window.MH_TR["ch00"]={"t": "\u05de\u05d4 \u05d6\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd", "l": [[5.0, "\u05e2\u05dc \u05e9\u05d5\u05dc\u05d7\u05df \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05de\u05d5\u05e0\u05d7\u05d9\u05dd \u05e9\u05e0\u05d9 \u05de\u05d5\u05d8\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4."], [8.4, "\u05d0\u05d5\u05ea\u05d5 \u05e7\u05d5\u05d8\u05e8, \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e8\u05da, \u05d5\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d1\u05d3\u05d9\u05d5\u05e7: \u05e4\u05dc\u05d3\u05ea 4140."], [14.8, "\u05d0\u05ea \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e8\u05d5\u05d8 \u05d5\u05dc\u05e7\u05d3\u05d5\u05d7 \u05d1\u05e7\u05dc\u05d5\u05ea."], [18.1, "\u05d4\u05e9\u05e0\u05d9 \u05e7\u05e9\u05d4 \u05db\u05dc \u05db\u05da, \u05e9\u05de\u05e7\u05d3\u05d7 \u05e8\u05d2\u05d9\u05dc \u05e0\u05e9\u05d7\u05e7 \u05e2\u05dc\u05d9\u05d5 \u05d1\u05dc\u05d9 \u05dc\u05d7\u05d3\u05d5\u05e8."], [22.7, "\u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05dc\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05d4\u05e8\u05db\u05d1 \u05d5\u05dc\u05d0 \u05d1\u05e6\u05d5\u05e8\u05d4, \u05d0\u05dc\u05d0 \u05d1\u05d4\u05d9\u05e1\u05d8\u05d5\u05e8\u05d9\u05d4: \u05de\u05d4 \u05e2\u05d1\u05e8 \u05e2\u05dc \u05db\u05dc \u05de\u05d5\u05d8 \u05d1\u05ea\u05e0\u05d5\u05e8."], [30.3, "\u05d5\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05e0\u05d5\u05e9\u05d0 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d6\u05d4: \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd."], [34.9, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d1\u05d5\u05e7\u05e8\u05d9\u05dd \u05e9\u05dc \u05de\u05ea\u05db\u05ea, \u05db\u05e9\u05d4\u05d9\u05d0 \u05db\u05dc \u05d4\u05d6\u05de\u05df \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7."], [41.0, "\u05d4\u05de\u05d8\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8: \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d7\u05d5\u05d6\u05e7, \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d5\u05e2\u05d5\u05d3."], [47.4, "\u05d1\u05e8\u05d5\u05d1 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d0\u05e8\u05ea \u05db\u05de\u05e2\u05d8 \u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4, \u05d5\u05d2\u05dd \u05d4\u05d4\u05e8\u05db\u05d1 \u05d4\u05db\u05d9\u05de\u05d9 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4."], [54.2, "\u05d9\u05e9 \u05d2\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d9\u05e1\u05d5\u05d3 \u05db\u05de\u05d5 \u05e4\u05d7\u05de\u05df \u05d0\u05d5 \u05d7\u05e0\u05e7\u05df, \u05d5\u05e2\u05dc\u05d9\u05d4\u05dd \u05e0\u05d3\u05d1\u05e8 \u05d1\u05d4\u05de\u05e9\u05da \u05d4\u05e7\u05d5\u05e8\u05e1."], [61.7, "\u05de\u05d4 \u05e9\u05de\u05e9\u05ea\u05e0\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9: \u05d0\u05d9\u05da \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd, \u05d5\u05d0\u05d9\u05dc\u05d5 \u05de\u05d1\u05e0\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05de\u05d4\u05dd."], [68.2, "\u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d6\u05d4 \u05dc\u05d0 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05df, \u05d0\u05d1\u05dc \u05de\u05e8\u05d2\u05d9\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d4\u05d9\u05d8\u05d1: \u05d1\u05db\u05dc\u05d9 \u05d4\u05d7\u05d9\u05ea\u05d5\u05da, \u05d1\u05de\u05db\u05d5\u05e0\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05d1\u05e9\u05d8\u05d7."], [77.5, "\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05e4\u05e9\u05d5\u05d8 \u05d0\u05d5 \u05de\u05e1\u05d5\u05d1\u05da, \u05e0\u05e9\u05e2\u05df \u05e2\u05dc \u05e9\u05dc\u05d5\u05e9\u05d4 \u05de\u05e9\u05ea\u05e0\u05d9\u05dd \u05d1\u05dc\u05d1\u05d3."], [82.8, "\u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4: \u05dc\u05d0\u05d9\u05d6\u05d4 \u05d7\u05d5\u05dd \u05de\u05d1\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7."], [87.4, "\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05d6\u05de\u05df: \u05db\u05de\u05d4 \u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d0\u05ea, \u05e2\u05d3 \u05e9\u05d4\u05d7\u05d5\u05dd \u05de\u05d2\u05d9\u05e2 \u05dc\u05db\u05dc \u05d4\u05e0\u05e4\u05d7 \u05d5\u05d4\u05de\u05d1\u05e0\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05d4\u05e9\u05ea\u05e0\u05d5\u05ea."], [96.3, "\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8: \u05dc\u05d0\u05d8 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8, \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05de\u05d9\u05dd."], [103.2, "\u05e0\u05d5\u05d7 \u05dc\u05e6\u05d9\u05d9\u05e8 \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea\u05dd \u05d1\u05d2\u05e8\u05e3 \u05d0\u05d7\u05d3: \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df."], [108.1, "\u05e2\u05dc\u05d9\u05d9\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05e7\u05d8\u05e2 \u05d9\u05e9\u05e8 \u05e9\u05dc \u05d4\u05d7\u05d6\u05e7\u05d4, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05d9\u05e8\u05d9\u05d3\u05d4, \u05de\u05d4\u05d9\u05e8\u05d4 \u05d0\u05d5 \u05d0\u05d9\u05d8\u05d9\u05ea."], [114.9, "\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05e0\u05dc\u05de\u05d3 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e6\u05dd \u05d2\u05e8\u05e3 \u05db\u05d6\u05d4, \u05e2\u05dd \u05de\u05e1\u05e4\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd."], [119.8, "\u05d5\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df \u05d1\u05d0\u05d7\u05d3 \u05d4\u05de\u05e9\u05ea\u05e0\u05d9\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05ea\u05ea \u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9."], [124.8, "\u05e0\u05d7\u05d6\u05d5\u05e8 \u05dc\u05e4\u05dc\u05d3\u05ea 4140, \u05e9\u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 \u05e0\u05e7\u05e8\u05d0\u05ea 42CrMo4."], [132.6, "\u05d1\u05de\u05e6\u05d1 \u05de\u05e8\u05d5\u05db\u05da \u05d4\u05d9\u05d0 \u05e8\u05db\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 200 \u05d1\u05e8\u05d9\u05e0\u05dc, \u05d5\u05e0\u05d5\u05d7\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."], [139.4, "\u05d0\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc-850 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05e2\u05e8\u05da \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05d1\u05e9\u05de\u05df, \u05d4\u05d9\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 55 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [148.5, "\u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d1\u05dc \u05d2\u05dd \u05e0\u05e9\u05d1\u05e8\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea \u05d1\u05de\u05db\u05d4 \u05d7\u05d6\u05e7\u05d4."], [153.7, "\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e9\u05dc\u05d1 \u05e9\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4: \u05d7\u05d9\u05de\u05d5\u05dd \u05d7\u05d5\u05d6\u05e8 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."], [161.5, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1-600 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d1\u05e2\u05e8\u05da 30 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05d1\u05ea\u05de\u05d5\u05e8\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e2\u05e9\u05d4 \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d5\u05d7, \u05d5\u05e2\u05d5\u05de\u05d3 \u05d1\u05de\u05db\u05d5\u05ea."], [171.9, "\u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4, \u05de\u05d5\u05e7\u05e9\u05d4 \u05d5\u05de\u05d5\u05e8\u05e4\u05d4, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e0\u05de\u05db\u05e8\u05ea \u05d2\u05dd \u05db\u05de\u05d5\u05d8 prehard, \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea."], [179.8, "\u05d0\u05d5\u05ea\u05d5 \u05d4\u05e8\u05db\u05d1, \u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4, \u05d5\u05e9\u05dc\u05d5\u05e9\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05ea\u05e0\u05d4\u05d2\u05d9\u05dd \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."], [185.7, "\u05d4\u05e1\u05d5\u05d3 \u05e0\u05de\u05e6\u05d0 \u05d1\u05ea\u05d5\u05da \u05d4\u05e4\u05dc\u05d3\u05d4: \u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7, \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05e9\u05dc \u05d4\u05d1\u05e8\u05d6\u05dc \u05de\u05e1\u05ea\u05d3\u05e8\u05d9\u05dd \u05de\u05d7\u05d3\u05e9, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd."], [194.4, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05dd \u05de\u05e1\u05ea\u05d3\u05e8\u05d9\u05dd \u05e9\u05d5\u05d1, \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05d9\u05d6\u05d4 \u05de\u05d1\u05e0\u05d4 \u05d9\u05d9\u05d5\u05d5\u05e6\u05e8."], [199.9, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05e0\u05d5\u05ea\u05df \u05de\u05d1\u05e0\u05d4 \u05e8\u05da. \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3 \u05dc\u05d5\u05db\u05d3 \u05d0\u05ea \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05e0\u05d5\u05ea\u05df \u05de\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05e9\u05e0\u05e7\u05e8\u05d0 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [208.9, "\u05d0\u05ea \u05db\u05dc \u05d6\u05d4 \u05e0\u05e4\u05e8\u05d8 \u05d1\u05e4\u05e8\u05e7\u05d9\u05dd 1 \u05d5-2, \u05e2\u05dd \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df \u05d5\u05e2\u05dd \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [215.7, "\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea \u05e9\u05dc\u05d0 \u05db\u05dc \u05de\u05ea\u05db\u05ea \u05de\u05d2\u05d9\u05d1\u05d4 \u05db\u05da. \u05d1\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05dc\u05de\u05e9\u05dc, \u05d4\u05d7\u05d5\u05d6\u05e7 \u05de\u05d2\u05d9\u05e2 \u05de\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05d7\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d6\u05d9\u05e7\u05d5\u05df."], [225.0, "\u05de\u05d4 \u05d1\u05e2\u05e6\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05d9\u05d2 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd? \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05e0\u05d3\u05de\u05d4."], [229.7, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05e2\u05de\u05d5\u05d3 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05db\u05de\u05d5 \u05d1\u05db\u05dc\u05d9\u05dd, \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d1\u05e4\u05d9\u05e0\u05d9\u05dd."], [236.6, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e2\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7, \u05db\u05d3\u05d9 \u05e9\u05d2\u05dc \u05d3\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05d9\u05d9\u05e9\u05d0 \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05e2\u05d5\u05de\u05e1."], [241.7, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05db\u05da, \u05db\u05d3\u05d9 \u05e9\u05d9\u05d4\u05d9\u05d4 \u05e7\u05dc \u05dc\u05e2\u05d1\u05d3, \u05dc\u05db\u05d5\u05e4\u05e3 \u05d0\u05d5 \u05dc\u05e2\u05e6\u05d1 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8."], [247.1, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05d1\u05d7\u05dc\u05e7 \u05de\u05e2\u05d9\u05d1\u05d5\u05d3, \u05de\u05e8\u05d9\u05ea\u05d5\u05da \u05d0\u05d5 \u05de\u05d9\u05d9\u05e9\u05d5\u05e8, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05ea\u05e2\u05d5\u05d5\u05ea \u05d0\u05d7\u05e8 \u05db\u05da."], [254.3, "\u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05e2\u05d3\u05df \u05d0\u05ea \u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."], [258.7, "\u05d0\u05d1\u05dc \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d9\u05e9 \u05de\u05d7\u05d9\u05e8: \u05db\u05db\u05dc \u05e9\u05d4\u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d9\u05d5\u05e8\u05d3\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05e4\u05d7\u05d5\u05ea \u05e1\u05dc\u05d7\u05e0\u05d9\u05ea \u05dc\u05de\u05db\u05d5\u05ea \u05d5\u05dc\u05d7\u05e8\u05d9\u05e6\u05d9\u05dd."], [267.4, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d8\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e4\u05e9\u05e8\u05d4: \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05e0\u05db\u05d5\u05e0\u05d4 \u05dc\u05ea\u05e4\u05e7\u05d9\u05d3, \u05d5\u05dc\u05d0 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea."], [274.7, "\u05d0\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05dc\u05e9\u05ea\u05d9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea."], [278.7, "\u05d1\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05de\u05d8\u05e4\u05dc\u05d9\u05dd \u05d1\u05db\u05dc \u05d4\u05e0\u05e4\u05d7 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7: \u05e8\u05d9\u05db\u05d5\u05da, \u05e0\u05e8\u05de\u05d5\u05dc, \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."], [286.9, "\u05d1\u05e9\u05e0\u05d9\u05d9\u05d4 \u05de\u05e7\u05e9\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05dc\u05d9\u05d1\u05d4 \u05e8\u05db\u05d4 \u05d5\u05e7\u05e9\u05d5\u05d7\u05d4."], [292.8, "\u05db\u05da \u05e9\u05df \u05e9\u05dc \u05d2\u05dc\u05d2\u05dc \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05de\u05d1\u05d7\u05d5\u05e5, \u05d5\u05dc\u05d0 \u05e0\u05e9\u05d1\u05e8\u05ea \u05de\u05d1\u05e4\u05e0\u05d9\u05dd."], [298.3, "\u05d7\u05dc\u05e7 \u05de\u05e9\u05d9\u05d8\u05d5\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e8\u05e7 \u05de\u05d7\u05de\u05de\u05d5\u05ea \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea, \u05db\u05de\u05d5 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d4\u05d1\u05d4."], [305.5, "\u05d5\u05d0\u05d7\u05e8\u05d5\u05ea \u05d2\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05dc\u05d4 \u05d9\u05e1\u05d5\u05d3: \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e4\u05d7\u05de\u05df, \u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d7\u05e0\u05e7\u05df."], [313.1, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e9\u05dc\u05d1 \u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d1\u05e1\u05d5\u05e3, \u05d0\u05dc\u05d0 \u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05e0\u05d5\u05df \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."], [318.2, "\u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd \u05e2\u05e6\u05de\u05d5 \u05de\u05d2\u05d9\u05e2 \u05db\u05d1\u05e8 \u05d1\u05de\u05e6\u05d1 \u05de\u05e1\u05d5\u05d9\u05dd: \u05de\u05e8\u05d5\u05db\u05da, \u05de\u05e0\u05d5\u05e8\u05de\u05dc, \u05d0\u05d5 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d5\u05de\u05d5\u05e8\u05e4\u05d4."], [326.0, "\u05d7\u05dc\u05e7 \u05d8\u05d9\u05e4\u05d5\u05e1\u05d9 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05e6\u05d1 \u05e8\u05da, \u05e9\u05d5\u05dc\u05d7\u05d9\u05dd \u05dc\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."], [333.4, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e8\u05d2\u05d9\u05e9\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d9\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05e1 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8, \u05d5\u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [340.9, "\u05e1\u05d3\u05e8 \u05d4\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2 \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d2\u05d9\u05e2 \u05dc\u05de\u05d9\u05d3\u05d4, \u05d5\u05e0\u05e7\u05d3\u05d9\u05e9 \u05dc\u05d5 \u05e4\u05e8\u05e7 \u05e9\u05dc\u05dd \u05d1\u05d4\u05de\u05e9\u05da."], [347.2, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05e7\u05e9\u05d4 \u05dc\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05dc\u05d5."], [350.9, "\u05d7\u05dc\u05e7 \u05e9\u05d8\u05d5\u05e4\u05dc \u05e0\u05db\u05d5\u05df \u05d5\u05d7\u05dc\u05e7 \u05e9\u05d8\u05d5\u05e4\u05dc \u05dc\u05d0 \u05e0\u05db\u05d5\u05df \u05e0\u05e8\u05d0\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05d0\u05d5\u05ea\u05d5 \u05d3\u05d1\u05e8."], [356.2, "\u05d4\u05d1\u05e2\u05d9\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d4\u05df \u05e2\u05d9\u05d5\u05d5\u05ea, \u05e1\u05d3\u05e7\u05d9\u05dd \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4, \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e8\u05db\u05d5\u05ea, \u05d5\u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e9\u05de\u05e9\u05d0\u05d9\u05e8 \u05e9\u05dd \u05e9\u05db\u05d1\u05d4 \u05e8\u05db\u05d4."], [365.5, "\u05d5\u05dc\u05db\u05df \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e1\u05de\u05d5\u05da \u05e2\u05dc \u05d4\u05de\u05e8\u05d0\u05d4: \u05e6\u05e8\u05d9\u05da \u05de\u05e4\u05e8\u05d8 \u05d1\u05e8\u05d5\u05e8 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d1\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05e1\u05d5\u05e3."], [374.1, "\u05d5\u05de\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8? \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d6\u05de\u05df \u05d4\u05ea\u05e0\u05d5\u05e8, \u05e1\u05d5\u05d2 \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05d1\u05d5, \u05d5\u05db\u05de\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05db\u05e0\u05e1\u05d9\u05dd \u05dc\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8."], [382.6, "\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea \u05d0\u05d5 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e0\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e8\u05d2\u05d9\u05dc, \u05d0\u05d1\u05dc \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d5\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [390.4, "\u05de\u05e2\u05d1\u05e8 \u05dc\u05d6\u05d4 \u05d9\u05e9 \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05d4 \u05d0\u05e6\u05dc \u05e7\u05d1\u05dc\u05df \u05d4\u05de\u05e9\u05e0\u05d4, \u05d9\u05d9\u05e9\u05d5\u05e8 \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea\u05d5, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea."], [398.1, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05e0\u05e2\u05e9\u05d4 \u05e2\u05dc \u05db\u05dc \u05d6\u05d4 \u05d7\u05e9\u05d1\u05d5\u05df \u05de\u05dc\u05d0, \u05e2\u05dd \u05d3\u05d5\u05d2\u05de\u05d0\u05d5\u05ea."], [403.0, "\u05d4\u05e7\u05d5\u05e8\u05e1 \u05d1\u05e0\u05d5\u05d9 \u05de\u05e9\u05e9 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea."], [405.3, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea: \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05de\u05d4 \u05d6\u05d5 \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4."], [411.8, "\u05d0\u05d7\u05e8 \u05db\u05da \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05d1\u05db\u05dc \u05d4\u05e0\u05e4\u05d7, \u05d0\u05d7\u05d3 \u05d0\u05d7\u05d3, \u05d5\u05e2\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [417.4, "\u05de\u05e9\u05dd \u05e0\u05de\u05e9\u05d9\u05da \u05dc\u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05dc\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05dc\u05e4\u05d9 \u05de\u05e9\u05e4\u05d7\u05ea \u05d7\u05d5\u05de\u05e8: \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05d0\u05dc \u05d7\u05dc\u05d3, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."], [427.8, "\u05d5\u05e0\u05e1\u05d9\u05d9\u05dd \u05d1\u05e6\u05d9\u05d5\u05d3 \u05d5\u05d1\u05ea\u05db\u05e0\u05d5\u05df, \u05d1\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d1\u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05d1\u05e2\u05dc\u05d5\u05d9\u05d5\u05ea."], [433.1, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05e9\u05dc \u05d4\u05de\u05ea\u05db\u05ea, \u05d1\u05e2\u05d6\u05e8\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d6\u05de\u05df \u05d5\u05e7\u05e6\u05d1 \u05e7\u05d9\u05e8\u05d5\u05e8."], [440.8, "\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea \u05e8\u05da, \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d5 \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d5\u05d7, \u05dc\u05e4\u05d9 \u05de\u05d4 \u05e9\u05e2\u05d1\u05e8 \u05e2\u05dc\u05d9\u05d5 \u05d1\u05ea\u05e0\u05d5\u05e8."], [447.7, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d9\u05db\u05e0\u05e1 \u05dc\u05ea\u05d5\u05da \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d4 \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."]]};
window.MH_TR["ch01"]={"t": "\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05e8\u05db\u05d4, \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d5 \u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d5\u05d7\u05d4."], [12.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d9\u05db\u05e0\u05e1 \u05dc\u05ea\u05d5\u05da \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05d4 \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4."], [17.6, "\u05d6\u05d4 \u05d4\u05d1\u05e1\u05d9\u05e1 \u05dc\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd: \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05d7\u05d9\u05de\u05d5\u05dd, \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d0\u05ea \u05d4\u05e8\u05d9\u05db\u05d5\u05da \u05d0\u05d5 \u05d0\u05ea \u05d4\u05e0\u05e8\u05de\u05d5\u05dc."], [26.2, "\u05de\u05ea\u05db\u05ea \u05de\u05d5\u05e6\u05e7\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05e9\u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05d1\u05e1\u05d3\u05e8 \u05e7\u05d1\u05d5\u05e2, \u05e9\u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05e2\u05e6\u05de\u05d5 \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1. \u05dc\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e1\u05e8\u05d9\u05d2 \u05d2\u05d1\u05d9\u05e9\u05d9."], [35.2, "\u05d1\u05d1\u05e8\u05d6\u05dc, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d4\u05e1\u05d9\u05d3\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05d9\u05d9\u05d4 \u05e2\u05dd \u05d0\u05d8\u05d5\u05dd \u05d1\u05db\u05dc \u05e4\u05d9\u05e0\u05d4, \u05d5\u05d0\u05d8\u05d5\u05dd \u05d0\u05d7\u05d3 \u05d1\u05de\u05e8\u05db\u05d6."], [42.7, "\u05d4\u05e1\u05d9\u05d3\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 BCC, \u05e7\u05d5\u05d1\u05d9\u05d9\u05d4 \u05de\u05de\u05d5\u05e8\u05db\u05d6\u05ea \u05d2\u05d5\u05e3."], [47.3, "\u05d0\u05d1\u05dc \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e9 \u05ea\u05db\u05d5\u05e0\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea: \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d4\u05d5\u05d0 \u05de\u05d7\u05dc\u05d9\u05e3 \u05d0\u05ea \u05d4\u05e1\u05d9\u05d3\u05d5\u05e8."], [52.9, "\u05d1-912 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05e7\u05d5\u05d1\u05d9\u05d9\u05d4 \u05e2\u05dd \u05d0\u05d8\u05d5\u05dd \u05d1\u05db\u05dc \u05e4\u05d9\u05e0\u05d4, \u05d5\u05d1\u05de\u05e8\u05db\u05d6 \u05db\u05dc \u05e4\u05d0\u05d4."], [60.1, "\u05d4\u05e1\u05d9\u05d3\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 FCC, \u05e7\u05d5\u05d1\u05d9\u05d9\u05d4 \u05de\u05de\u05d5\u05e8\u05db\u05d6\u05ea \u05e4\u05d0\u05d5\u05ea."], [64.8, "\u05d5\u05d1-1394 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d6\u05e8 \u05dc-BCC, \u05e2\u05d3 \u05e9\u05d4\u05d1\u05e8\u05d6\u05dc \u05e0\u05de\u05e1 \u05d1-1538 \u05de\u05e2\u05dc\u05d5\u05ea."], [74.0, "\u05d1\u05de\u05e2\u05d1\u05e8 \u05dc-FCC \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05e0\u05d0\u05e8\u05d6\u05d9\u05dd \u05e6\u05e4\u05d5\u05e3 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05d1\u05e8\u05d6\u05dc \u05d0\u05e4\u05d9\u05dc\u05d5 \u05de\u05ea\u05db\u05d5\u05d5\u05e5 \u05de\u05e2\u05d8, \u05dc\u05de\u05e8\u05d5\u05ea \u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05d7\u05de\u05dd."], [82.2, "\u05d5\u05e2\u05d5\u05d3 \u05e7\u05d5\u05d3\u05dd, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 770 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05de\u05d0\u05d1\u05d3\u05ea \u05d0\u05ea \u05d4\u05de\u05d2\u05e0\u05d8\u05d9\u05d5\u05ea \u05e9\u05dc\u05d4."], [88.3, "\u05e0\u05e4\u05d7\u05d9\u05dd \u05d5\u05ea\u05d9\u05e7\u05d9\u05dd \u05e0\u05d9\u05e6\u05dc\u05d5 \u05d0\u05ea \u05d6\u05d4: \u05de\u05d2\u05e0\u05d8 \u05e9\u05db\u05d1\u05e8 \u05dc\u05d0 \u05e0\u05de\u05e9\u05da \u05dc\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05df \u05dc\u05d4\u05dd \u05e9\u05d4\u05d5\u05d0 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [96.2, "\u05d0\u05d1\u05dc \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4 \u05dc\u05d0 \u05e1\u05d5\u05de\u05db\u05d9\u05dd \u05e2\u05dc \u05de\u05d2\u05e0\u05d8 \u05d5\u05dc\u05d0 \u05e2\u05dc \u05e6\u05d1\u05e2 \u05d4\u05d6\u05d5\u05d4\u05e8: \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05e6\u05de\u05d3\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd."], [103.0, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05d5\u05e1\u05d9\u05e3 \u05e4\u05d7\u05de\u05df. \u05d0\u05d8\u05d5\u05dd \u05d4\u05e4\u05d7\u05de\u05df \u05e7\u05d8\u05df \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d0\u05d8\u05d5\u05dd \u05d4\u05d1\u05e8\u05d6\u05dc, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e0\u05d3\u05d7\u05e7 \u05dc\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e9\u05d1\u05d9\u05df \u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd."], [111.3, "\u05d1\u05e1\u05e8\u05d9\u05d2 BCC \u05d4\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d4\u05de\u05d9\u05e1 \u05dc\u05db\u05dc \u05d4\u05d9\u05d5\u05ea\u05e8 0.022% \u05e4\u05d7\u05de\u05df."], [119.7, "\u05d1\u05e1\u05e8\u05d9\u05d2 FCC \u05d4\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05de\u05e1\u05d5\u05d2\u05dc \u05dc\u05d4\u05de\u05d9\u05e1 \u05e2\u05d3 2.14%, \u05db\u05de\u05e2\u05d8 \u05e4\u05d9 \u05de\u05d0\u05d4."], [127.6, "\u05dc\u05d1\u05e8\u05d6\u05dc BCC \u05e2\u05dd \u05de\u05e2\u05d8 \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e4\u05e8\u05d9\u05d8. \u05d4\u05d5\u05d0 \u05e8\u05da \u05d5\u05de\u05e9\u05d9\u05da."], [133.9, "\u05dc\u05d1\u05e8\u05d6\u05dc FCC \u05e2\u05dd \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05de\u05d5\u05de\u05e1 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8. \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05d4\u05d5\u05d0 \u05e7\u05d9\u05d9\u05dd \u05e8\u05e7 \u05d1\u05d7\u05d5\u05dd."], [141.4, "\u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05dc\u05d0 \u05e0\u05db\u05e0\u05e1 \u05de\u05ea\u05d7\u05d1\u05e8 \u05dc\u05d1\u05e8\u05d6\u05dc \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e6\u05de\u05e0\u05d8\u05d9\u05d8: \u05ea\u05e8\u05db\u05d5\u05d1\u05ea \u05e2\u05dd \u05db-7% \u05e4\u05d7\u05de\u05df, \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d0\u05d1\u05dc \u05e9\u05d1\u05d9\u05e8\u05d4."], [151.2, "\u05d0\u05ea \u05db\u05dc \u05d6\u05d4 \u05de\u05e1\u05db\u05de\u05d9\u05dd \u05d1\u05d2\u05e8\u05e3 \u05d0\u05d7\u05d3: \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df."], [155.9, "\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e4\u05e7\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05e0\u05db\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4. \u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d1\u05d2\u05e8\u05e3 \u05d0\u05d5\u05de\u05e8\u05ea \u05de\u05d4 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d1\u05e9\u05d9\u05d5\u05d5\u05d9 \u05de\u05e9\u05e7\u05dc."], [164.6, "\u05e0\u05ea\u05de\u05e7\u05d3 \u05d1\u05d7\u05dc\u05e7 \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 2% \u05e4\u05d7\u05de\u05df. \u05de\u05e2\u05d1\u05e8 \u05dc\u05d6\u05d4 \u05db\u05d1\u05e8 \u05de\u05d3\u05d5\u05d1\u05e8 \u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."], [172.0, "\u05d4\u05e7\u05d5 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05e7\u05d5 \u05d0\u05d5\u05e4\u05e7\u05d9 \u05d1-727 \u05de\u05e2\u05dc\u05d5\u05ea. \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 A1, \u05d5\u05de\u05ea\u05d7\u05ea\u05d9\u05d5 \u05d0\u05d9\u05df \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d1\u05db\u05dc\u05dc."], [180.7, "\u05d4\u05e7\u05d5 \u05d4\u05e9\u05e0\u05d9 \u05d9\u05d5\u05e8\u05d3 \u05de\u05e9\u05de\u05d0\u05dc, \u05de-912 \u05de\u05e2\u05dc\u05d5\u05ea. \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 A3, \u05d5\u05de\u05e2\u05dc\u05d9\u05d5 \u05db\u05d1\u05e8 \u05d0\u05d9\u05df \u05e4\u05e8\u05d9\u05d8, \u05e8\u05e7 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [190.3, "\u05d4\u05e7\u05d5 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05d9\u05de\u05d9\u05e0\u05d4, \u05d5\u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d5 Acm. \u05de\u05e2\u05dc\u05d9\u05d5 \u05db\u05dc \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05db\u05d1\u05e8 \u05d4\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [198.1, "\u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05e0\u05e4\u05d2\u05e9\u05d9\u05dd \u05d1\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea: 727 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5-0.76% \u05e4\u05d7\u05de\u05df."], [206.5, "\u05de\u05e2\u05dc \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd \u05d9\u05e9 \u05e9\u05d3\u05d4 \u05d0\u05d7\u05d3 \u05d2\u05d3\u05d5\u05dc \u05e9\u05dc \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d1\u05dc\u05d1\u05d3. \u05dc\u05e9\u05dd, \u05d0\u05d5 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e9\u05dd, \u05de\u05d1\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4."], [216.1, "\u05d5\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc-A1? \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd 0.76% \u05e4\u05d7\u05de\u05df, \u05e9\u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05dc\u05d0\u05d8, \u05d4\u05d5\u05e4\u05db\u05ea \u05db\u05d5\u05dc\u05d4 \u05dc\u05e4\u05e8\u05dc\u05d9\u05d8."], [225.1, "\u05e4\u05e8\u05dc\u05d9\u05d8 \u05d4\u05d5\u05d0 \u05dc\u05d0 \u05e4\u05d0\u05d6\u05d4 \u05d0\u05d7\u05ea, \u05d0\u05dc\u05d0 \u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e9\u05dc \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05dc\u05e1\u05d9\u05e8\u05d5\u05d2\u05d9\u05df, \u05db\u05de\u05d5 \u05d8\u05d1\u05d9\u05e2\u05ea \u05d0\u05e6\u05d1\u05e2."], [232.2, "\u05d4\u05e9\u05dd \u05d1\u05d0 \u05de\u05d4\u05d1\u05e8\u05e7 \u05d4\u05e4\u05e0\u05d9\u05e0\u05ea\u05d9 \u05e9\u05dc\u05d5, \u05db\u05e9\u05de\u05e1\u05ea\u05db\u05dc\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5 \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4."], [236.7, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d9\u05e9 \u05e4\u05e8\u05d9\u05d8 \u05d5\u05d2\u05dd \u05e4\u05e8\u05dc\u05d9\u05d8. \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d9\u05e9 \u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05e7\u05e6\u05ea \u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."], [246.7, "\u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d4\u05e4\u05dc\u05d3\u05d4 \u05d1\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05e9\u05dc\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."], [254.5, "\u05d1\u05d5\u05d0\u05d5 \u05e0\u05d7\u05de\u05dd \u05e4\u05dc\u05d3\u05ea 1045, \u05e2\u05dd 0.45% \u05e4\u05d7\u05de\u05df, \u05d5\u05e0\u05e2\u05e7\u05d5\u05d1 \u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4."], [261.9, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8 \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d4 \u05d4\u05d5\u05d0 \u05e7\u05e8\u05d5\u05d1 \u05dc-60% \u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d4\u05e9\u05d0\u05e8 \u05e4\u05e8\u05d9\u05d8."], [268.0, "\u05e2\u05d3 727 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4, \u05d5\u05d4\u05d7\u05d5\u05dd \u05e8\u05e7 \u05de\u05ea\u05e4\u05e9\u05d8 \u05d1\u05d7\u05dc\u05e7."], [275.0, "\u05d1-A1 \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8 \u05d4\u05d5\u05e4\u05da \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [278.4, "\u05d1\u05d9\u05df A1 \u05dc-A3, \u05e4\u05e8\u05d9\u05d8 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d4\u05d5\u05dc\u05da \u05d5\u05de\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [284.3, "\u05d5\u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 775 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e2\u05dc \u05e7\u05d5 A3, \u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05db\u05d1\u05e8 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [290.7, "\u05dc\u05de\u05e2\u05e9\u05d4 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e2\u05d5\u05d3 \u05e7\u05e6\u05ea \u05de\u05e2\u05dc \u05d6\u05d4, \u05db\u05de\u05d5 \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d1\u05e4\u05e8\u05e7 7."], [295.7, "\u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05ea\u05d0\u05e8\u05ea \u05e9\u05d9\u05d5\u05d5\u05d9 \u05de\u05e9\u05e7\u05dc, \u05db\u05dc\u05d5\u05de\u05e8 \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [301.2, "\u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d0\u05de\u05d9\u05ea\u05d9 \u05d4\u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05e7\u05d5\u05e8\u05d9\u05dd \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d2\u05d1\u05d5\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd Ac1 \u05d5-Ac3."], [309.0, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05dd \u05e7\u05d5\u05e8\u05d9\u05dd \u05e0\u05de\u05d5\u05da \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd Ar1 \u05d5-Ar3."], [315.5, "\u05d2\u05dd \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05d6\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d5\u05d9\u05dd: \u05de\u05e0\u05d2\u05df \u05d5\u05e0\u05d9\u05e7\u05dc \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd, \u05d5\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05e2\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd."], [323.7, "\u05dc\u05db\u05df \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05de\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4."], [328.6, "\u05dc\u05de\u05e9\u05dc, \u05d9\u05e6\u05e8\u05df \u05d0\u05d7\u05d3 \u05e0\u05d5\u05ea\u05df \u05dc\u05e4\u05dc\u05d3\u05ea C45, \u05d4\u05de\u05e7\u05d1\u05d9\u05dc\u05d4 \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9\u05ea, Ac1 \u05e9\u05dc 725 \u05de\u05e2\u05dc\u05d5\u05ea \u05d5-Ac3 \u05e9\u05dc 760."], [341.1, "\u05d6\u05d4 \u05e7\u05e6\u05ea \u05e4\u05d7\u05d5\u05ea \u05de\u05de\u05d4 \u05e9\u05e7\u05e8\u05d0\u05e0\u05d5 \u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4, \u05d1\u05d2\u05dc\u05dc \u05d4\u05de\u05e0\u05d2\u05df \u05e9\u05d1\u05d4."], [345.8, "\u05d5\u05d6\u05d4 \u05d7\u05e9\u05d5\u05d1: \u05d7\u05d9\u05de\u05d5\u05dd \u05e0\u05de\u05d5\u05da \u05de\u05d3\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8 \u05e4\u05e8\u05d9\u05d8 \u05e8\u05da, \u05d5\u05d6\u05d4 \u05de\u05e7\u05d5\u05e8 \u05dc\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e8\u05db\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [353.3, "\u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d6\u05d4 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7. \u05e6\u05e8\u05d9\u05da \u05d2\u05dd \u05d6\u05de\u05df."], [357.3, "\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05e7\u05d5\u05d3\u05dd \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05d1\u05d9\u05df \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05e6\u05e8\u05d9\u05da \u05d6\u05de\u05df \u05db\u05d3\u05d9 \u05dc\u05d4\u05ea\u05e4\u05d6\u05e8 \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3."], [364.4, "\u05d1\u05d4\u05ea\u05d7\u05dc\u05d4 \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05e2\u05d3\u05d9\u05e0\u05d9\u05dd, \u05d5\u05d6\u05d4 \u05de\u05e6\u05d5\u05d9\u05df."], [369.1, "\u05d0\u05d1\u05dc \u05d0\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d7\u05dd \u05de\u05d3\u05d9, \u05d0\u05d5 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d6\u05de\u05df \u05e8\u05d1 \u05de\u05d3\u05d9, \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05d5\u05d1\u05d5\u05dc\u05e2\u05d9\u05dd \u05d6\u05d4 \u05d0\u05ea \u05d6\u05d4."], [375.8, "\u05d2\u05e8\u05e2\u05d9\u05df \u05d2\u05e1 \u05e0\u05e9\u05d0\u05e8 \u05d2\u05e1 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05e6\u05d0 \u05e9\u05d1\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8. \u05dc\u05db\u05df \u05d9\u05e9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05db\u05d5\u05e0\u05d4, \u05d5\u05d6\u05de\u05df \u05e0\u05db\u05d5\u05df."], [385.9, "\u05de\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05d1\u05e9 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd?"], [388.0, "\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05d0\u05d5 \u05de\u05e1\u05d5\u05d1\u05da \u05d9\u05d5\u05e6\u05e8 \u05d4\u05d1\u05d3\u05dc\u05d9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d9\u05df \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05dc\u05dc\u05d9\u05d1\u05d4, \u05d5\u05d0\u05dc\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05e2\u05d5\u05d5\u05ea \u05d5\u05d0\u05e4\u05d9\u05dc\u05d5 \u05dc\u05e1\u05d3\u05d5\u05e7."], [397.7, "\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05d0\u05dc\u05d4, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd, \u05e2\u05dd \u05e2\u05e6\u05d9\u05e8\u05d5\u05ea \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd."], [404.2, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05e7\u05e9\u05e7\u05e9\u05d9\u05dd \u05e9\u05dc \u05ea\u05d7\u05de\u05d5\u05e6\u05ea, \u05d5\u05de\u05d5\u05e6\u05d9\u05d0 \u05e4\u05d7\u05de\u05df \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05db\u05da \u05e9\u05e0\u05e9\u05d0\u05e8\u05ea \u05e9\u05dd \u05e9\u05db\u05d1\u05d4 \u05e8\u05db\u05d4."], [411.6, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d7\u05dd \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5."], [415.4, "\u05d5\u05d1\u05de\u05e7\u05e8\u05d4 \u05d4\u05e7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d4\u05d9\u05ea\u05d5\u05da, \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05de\u05e1. \u05dc\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e9\u05e8\u05d9\u05e4\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d5\u05dc\u05da \u05dc\u05d2\u05e8\u05d5\u05d8\u05d0\u05d4."], [425.4, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05ea \u05e9\u05dc\u05d1 \u05d4\u05d7\u05d9\u05de\u05d5\u05dd?"], [427.7, "\u05db\u05dc \u05de\u05e2\u05dc\u05d4 \u05d5\u05db\u05dc \u05e9\u05e2\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05d5\u05dc\u05d5\u05ea \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d5\u05d6\u05de\u05df \u05ea\u05e0\u05d5\u05e8, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05d6\u05de\u05df \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8."], [435.7, "\u05db\u05d3\u05d9 \u05dc\u05de\u05e0\u05d5\u05e2 \u05e7\u05e9\u05e7\u05e9\u05d9\u05dd \u05d5\u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df \u05e6\u05e8\u05d9\u05da \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d5\u05db\u05dc \u05d0\u05d7\u05d3 \u05de\u05d4\u05dd \u05de\u05d5\u05e1\u05d9\u05e3 \u05e2\u05dc\u05d5\u05ea."], [444.5, "\u05d5\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd, \u05e9\u05e0\u05d3\u05e8\u05e9 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05de\u05d0\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05db\u05d5\u05dc\u05d5."], [451.7, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4, \u05d4\u05d1\u05e8\u05d6\u05dc \u05e2\u05d5\u05d1\u05e8 \u05de-BCC \u05dc-FCC, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05d5 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [460.9, "\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df \u05de\u05e8\u05d0\u05d4 \u05de\u05ea\u05d9 \u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4, \u05d5\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d4\u05d0\u05de\u05d9\u05ea\u05d9\u05d5\u05ea \u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e0\u05de\u05e6\u05d0\u05d5\u05ea \u05d1\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc\u05d4."], [469.0, "\u05d5\u05db\u05d3\u05d9 \u05dc\u05e7\u05d1\u05dc \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d8\u05d5\u05d1, \u05e6\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05e0\u05db\u05d5\u05e0\u05d4, \u05d0\u05ea \u05d4\u05d6\u05de\u05df \u05d4\u05e0\u05db\u05d5\u05df, \u05d5\u05d7\u05d9\u05de\u05d5\u05dd \u05d0\u05d7\u05d9\u05d3."], [475.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9: \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05de\u05e7\u05e8\u05e8\u05d9\u05dd, \u05d5\u05d0\u05d9\u05da \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4."]]};
window.MH_TR["ch02"]={"t": "\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05d7\u05d9\u05de\u05de\u05e0\u05d5 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4, \u05e2\u05d3 \u05e9\u05db\u05d5\u05dc\u05d4 \u05d4\u05e4\u05db\u05d4 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [9.8, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05de\u05d2\u05d9\u05e2 \u05d4\u05e8\u05d2\u05e2 \u05e9\u05e7\u05d5\u05d1\u05e2 \u05d4\u05db\u05d5\u05dc: \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [13.8, "\u05de\u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e8\u05db\u05d4, \u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [22.8, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05de\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d0\u05d5\u05d3, \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8. \u05d0\u05d6 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05dc\u05db\u05ea \u05d1\u05d3\u05d9\u05d5\u05e7 \u05dc\u05e4\u05d9 \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df, \u05e8\u05e7 \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d4\u05e4\u05d5\u05da."], [31.8, "\u05d1\u05e4\u05dc\u05d3\u05ea 1045, \u05de\u05ea\u05d7\u05ea \u05dc-A3 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05e4\u05e8\u05d9\u05d8, \u05e7\u05d5\u05d3\u05dd \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [40.1, "\u05e4\u05e8\u05d9\u05d8 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05db\u05d9\u05dc \u05e4\u05d7\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05e4\u05d7\u05de\u05df \u05e0\u05d3\u05d7\u05e7 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05e0\u05e9\u05d0\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05d4\u05d5\u05dc\u05da \u05d5\u05de\u05ea\u05e2\u05e9\u05e8."], [47.5, "\u05d1-A1 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05e0\u05e9\u05d0\u05e8, \u05e2\u05dd \u05d1\u05e2\u05e8\u05da 0.76% \u05e4\u05d7\u05de\u05df, \u05d4\u05d5\u05e4\u05da \u05db\u05d5\u05dc\u05d5 \u05dc\u05e4\u05e8\u05dc\u05d9\u05d8."], [55.4, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8 \u05d2\u05e1, \u05d5\u05d4\u05e4\u05dc\u05d3\u05d4 \u05e8\u05db\u05d4 \u05d5\u05e0\u05d5\u05d7\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3."], [61.7, "\u05db\u05d3\u05d9 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8, \u05d0\u05d8\u05d5\u05de\u05d9 \u05d4\u05e4\u05d7\u05de\u05df \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05e0\u05d3\u05d5\u05d3 \u05d5\u05dc\u05d4\u05ea\u05d0\u05e1\u05e3 \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05e9\u05dc \u05e6\u05de\u05e0\u05d8\u05d9\u05d8. \u05dc\u05e0\u05d3\u05d9\u05d3\u05d4 \u05d4\u05d6\u05d5 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4."], [70.5, "\u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05d6\u05de\u05df, \u05d5\u05d4\u05d9\u05d0 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05d7\u05d5\u05dd \u05d5\u05d0\u05d9\u05d8\u05d9\u05ea \u05d1\u05e7\u05d5\u05e8."], [75.5, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05dc\u05de\u05e9\u05dc \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05d6\u05de\u05df, \u05d5\u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05d9\u05d5\u05e6\u05d0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8: \u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df, \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."], [85.0, "\u05d5\u05d0\u05dd \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05db\u05dc \u05db\u05da \u05de\u05d4\u05e8 \u05e9\u05dc\u05e4\u05d7\u05de\u05df \u05d0\u05d9\u05df \u05d6\u05de\u05df \u05dc\u05d6\u05d5\u05d6 \u05d1\u05db\u05dc\u05dc? \u05d0\u05d6 \u05e0\u05d5\u05e6\u05e8 \u05de\u05e9\u05d4\u05d5 \u05d0\u05d7\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9."], [92.4, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05d1\u05d9\u05df \u05d0\u05ea \u05d6\u05d4 \u05d1\u05d5\u05e0\u05d9\u05dd \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea: \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea TTT, \u05d6\u05de\u05df, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d8\u05e8\u05e0\u05e1\u05e4\u05d5\u05e8\u05de\u05e6\u05d9\u05d4."], [100.7, "\u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05e9\u05dc \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05db\u05dc \u05d0\u05d7\u05ea \u05de\u05d4\u05e8 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05e8\u05ea, \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05e9\u05dd, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05ea\u05d9 \u05d4\u05de\u05d1\u05e0\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05e9\u05ea\u05e0\u05d5\u05ea \u05d5\u05de\u05ea\u05d9 \u05d4\u05d5\u05d0 \u05d2\u05d5\u05de\u05e8."], [111.2, "\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05e0\u05db\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05d1\u05e6\u05d9\u05e8 \u05d4\u05d0\u05d5\u05e4\u05e7\u05d9 \u05d4\u05d6\u05de\u05df, \u05d1\u05e1\u05d5\u05dc\u05dd \u05dc\u05d5\u05d2\u05e8\u05d9\u05ea\u05de\u05d9: \u05e9\u05e0\u05d9\u05d9\u05d4, \u05e2\u05e9\u05e8 \u05e9\u05e0\u05d9\u05d5\u05ea, \u05de\u05d0\u05d4 \u05e9\u05e0\u05d9\u05d5\u05ea."], [120.3, "\u05de\u05ea\u05e7\u05d1\u05dc\u05d5\u05ea \u05e9\u05ea\u05d9 \u05e2\u05e7\u05d5\u05de\u05d5\u05ea \u05d1\u05e6\u05d5\u05e8\u05ea \u05d4\u05d0\u05d5\u05ea C: \u05d0\u05d7\u05ea \u05dc\u05d4\u05ea\u05d7\u05dc\u05ea \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9, \u05d5\u05d0\u05d7\u05ea \u05dc\u05e1\u05d5\u05e4\u05d5."], [126.8, "\u05dc\u05d7\u05dc\u05e7 \u05d4\u05d1\u05d5\u05dc\u05d8 \u05e9\u05dc \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d4\u05d0\u05e3. \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd 0.76% \u05e4\u05d7\u05de\u05df \u05d4\u05d5\u05d0 \u05e0\u05de\u05e6\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 540 \u05de\u05e2\u05dc\u05d5\u05ea."], [136.9, "\u05dc\u05d9\u05d3 \u05d4\u05d0\u05e3 \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d4\u05db\u05d9 \u05de\u05d4\u05d9\u05e8: \u05d7\u05e6\u05d9 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05de\u05e9\u05ea\u05e0\u05d4 \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea \u05e1\u05e4\u05d5\u05e8\u05d5\u05ea."], [142.9, "\u05de\u05e2\u05dc \u05d4\u05d0\u05e3 \u05e0\u05d5\u05e6\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8: \u05d2\u05e1 \u05e7\u05e8\u05d5\u05d1 \u05dc-A1, \u05d5\u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8 \u05db\u05db\u05dc \u05e9\u05d9\u05d5\u05e8\u05d3\u05d9\u05dd \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d0\u05e3."], [150.4, "\u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05e3, \u05d5\u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 220 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e0\u05d5\u05e6\u05e8 \u05de\u05d1\u05e0\u05d4 \u05d0\u05d7\u05e8, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8."], [157.8, "\u05d2\u05dd \u05d1\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05d9\u05e9 \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d1\u05e9\u05db\u05d1\u05d5\u05ea \u05de\u05e1\u05d5\u05d3\u05e8\u05d5\u05ea, \u05d0\u05dc\u05d0 \u05db\u05de\u05d7\u05d8\u05d9\u05dd \u05d3\u05e7\u05d5\u05ea \u05e2\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd."], [165.7, "\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d5\u05d7, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05e8\u05d5\u05e6\u05d9\u05dd. \u05e2\u05dc \u05d6\u05d4 \u05e0\u05d3\u05d1\u05e8 \u05d1\u05e4\u05e8\u05e7 10, \u05d1\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2."], [174.2, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05de\u05e7\u05e8\u05d4 \u05d4\u05e7\u05d9\u05e6\u05d5\u05e0\u05d9: \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05db\u05da \u05e9\u05e2\u05d5\u05e7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05e3 \u05d5\u05dc\u05d0 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05e9\u05d5\u05dd \u05d3\u05d1\u05e8 \u05dc\u05e7\u05e8\u05d5\u05ea \u05d1\u05d3\u05e8\u05da."], [182.3, "\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05de\u05d2\u05d9\u05e2 \u05db\u05de\u05e2\u05d8 \u05e9\u05dc\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d5\u05e9\u05dd, \u05e4\u05ea\u05d0\u05d5\u05dd, \u05d4\u05d5\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d5 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d1\u05dc\u05d9 \u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4."], [191.3, "\u05d4\u05d0\u05d8\u05d5\u05de\u05d9\u05dd \u05d6\u05d6\u05d9\u05dd \u05d9\u05d7\u05d3, \u05db\u05de\u05d5 \u05d1\u05d2\u05d6\u05d9\u05e8\u05d4, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05e0\u05e9\u05d0\u05e8 \u05db\u05dc\u05d5\u05d0 \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05e8\u05d9\u05d2. \u05d6\u05d4 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [198.8, "\u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05db\u05dc\u05d5\u05d0 \u05de\u05d5\u05ea\u05d7 \u05d0\u05ea \u05d4\u05e1\u05e8\u05d9\u05d2, \u05d5\u05d4\u05d5\u05e4\u05da \u05d0\u05d5\u05ea\u05d5 \u05dc\u05e7\u05d5\u05d1\u05d9\u05d9\u05d4 \u05de\u05e2\u05d5\u05d5\u05ea\u05ea \u05d5\u05de\u05d5\u05d0\u05e8\u05db\u05ea. \u05d6\u05d5 \u05d4\u05e1\u05d9\u05d1\u05d4 \u05e9\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05db\u05dc \u05db\u05da \u05e7\u05e9\u05d4, \u05d5\u05d2\u05dd \u05e9\u05d1\u05d9\u05e8."], [208.3, "\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea Ms, \u05d5\u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea Mf."], [215.7, "\u05db\u05de\u05d4 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05d0\u05dc\u05d9\u05d4 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd, \u05d5\u05dc\u05d0 \u05d1\u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4."], [221.3, "\u05db\u05db\u05dc \u05e9\u05d9\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, Ms \u05d9\u05d5\u05e8\u05d3\u05ea. \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd 0.76% \u05e4\u05d7\u05de\u05df \u05d4\u05d9\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 220 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05e4\u05dc\u05d3\u05ea C45 \u05d1\u05e2\u05e8\u05da 305."], [235.3, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df Mf \u05e0\u05de\u05e6\u05d0\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d5\u05d0\u05d6 \u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e0\u05e9\u05d0\u05e8. \u05dc\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9, \u05d5\u05e0\u05d7\u05d6\u05d5\u05e8 \u05d0\u05dc\u05d9\u05d5 \u05d1\u05e4\u05e8\u05e7 10."], [247.4, "\u05db\u05de\u05d4 \u05e7\u05e9\u05d4 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8? \u05d6\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05db\u05de\u05e2\u05d8 \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df."], [252.0, "\u05e2\u05dd 0.4% \u05e4\u05d7\u05de\u05df \u05d4\u05d5\u05d0 \u05de\u05d2\u05d9\u05e2 \u05dc\u05d1\u05e2\u05e8\u05da 56 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05e2\u05dd 0.5%, \u05dc\u05d1\u05e2\u05e8\u05da 61."], [261.0, "\u05de\u05e2\u05dc \u05d1\u05e2\u05e8\u05da 0.7% \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05d1\u05e8 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e2\u05d5\u05dc\u05d4, \u05d5\u05e0\u05e2\u05e6\u05e8\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 65."], [268.2, "\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05dc\u05d0 \u05de\u05e2\u05dc\u05d9\u05dd \u05d0\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d4\u05dd \u05e2\u05d5\u05d6\u05e8\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d5, \u05d5\u05d6\u05d4 \u05d4\u05e0\u05d5\u05e9\u05d0 \u05e9\u05dc \u05d4\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."], [276.5, "\u05d1\u05e4\u05d5\u05e2\u05dc, \u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0 \u05de\u05e7\u05d5\u05e8\u05e8\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4 \u05d5\u05de\u05d5\u05d7\u05d6\u05e7\u05d9\u05dd \u05e9\u05dd. \u05d4\u05dd \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05e8\u05e6\u05d9\u05e4\u05d5\u05ea, \u05de\u05d4\u05d7\u05d5\u05dd \u05d5\u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."], [285.5, "\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea CCT, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e8\u05e6\u05d9\u05e3. \u05d4\u05d9\u05d0 \u05d3\u05d5\u05de\u05d4 \u05dc-TTT, \u05d0\u05d1\u05dc \u05d4\u05e2\u05e7\u05d5\u05de\u05d5\u05ea \u05d6\u05d6\u05d5\u05ea \u05de\u05e2\u05d8 \u05d9\u05de\u05d9\u05e0\u05d4 \u05d5\u05dc\u05de\u05d8\u05d4."], [294.8, "\u05e2\u05dc \u05d4\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d4 \u05de\u05e6\u05d9\u05d9\u05e8\u05d9\u05dd \u05e2\u05e7\u05d5\u05de\u05d5\u05ea \u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05d9\u05d6\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05db\u05dc \u05d0\u05d7\u05ea \u05d7\u05d5\u05e6\u05d4."], [300.2, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d7\u05d5\u05e6\u05d4 \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8 \u05de\u05d5\u05e7\u05d3\u05dd, \u05d5\u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05dc\u05d9\u05d8 \u05d2\u05e1 \u05d5\u05e8\u05da. \u05d6\u05d4 \u05e8\u05d9\u05db\u05d5\u05da."], [307.1, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df, \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8. \u05d6\u05d4 \u05e0\u05e8\u05de\u05d5\u05dc."], [312.5, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05de\u05d9\u05dd, \u05de\u05d4\u05d9\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05e2\u05e7\u05d5\u05e3 \u05d0\u05ea \u05d4\u05d0\u05e3, \u05e0\u05d5\u05ea\u05df \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d6\u05d5 \u05d4\u05e7\u05e9\u05d9\u05d4."], [319.9, "\u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05d0\u05d9\u05d8\u05d9 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05e2\u05d5\u05e7\u05e3 \u05d0\u05ea \u05d4\u05d0\u05e3 \u05e0\u05e7\u05e8\u05d0 \u05e7\u05e6\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05e7\u05e8\u05d9\u05d8\u05d9."], [326.6, "\u05d0\u05d1\u05dc \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8 \u05db\u05d5\u05dc\u05d5 \u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea. \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d4\u05db\u05d9 \u05de\u05d4\u05e8, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05d4\u05db\u05d9 \u05dc\u05d0\u05d8."], [334.5, "\u05d1\u05d7\u05dc\u05e7 \u05d3\u05e7 \u05d2\u05dd \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05d5\u05e7\u05e4\u05ea \u05d0\u05ea \u05d4\u05d0\u05e3, \u05d5\u05db\u05dc \u05d4\u05d7\u05ea\u05da \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [340.0, "\u05d1\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05dc\u05d5\u05dc\u05d4 \u05dc\u05e4\u05d2\u05d5\u05e2 \u05d1\u05d0\u05e3, \u05d5\u05dc\u05e6\u05d0\u05ea \u05e8\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [345.6, "\u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e4\u05e9\u05d5\u05d8\u05d4 \u05d4\u05d0\u05e3 \u05e7\u05e8\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e6\u05d9\u05e8 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05e6\u05e8\u05d9\u05da \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3. \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05db\u05de\u05d5 4340, \u05d4\u05d0\u05e3 \u05d6\u05d6 \u05d9\u05de\u05d9\u05e0\u05d4, \u05d5\u05de\u05e1\u05e4\u05d9\u05e7 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d1\u05d4\u05e8\u05d1\u05d4."], [359.3, "\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05e2\u05dc \u05d6\u05d4 \u05d4\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."], [365.8, "\u05de\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05d1\u05e9 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8?"], [367.9, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05dc\u05e9 \u05de\u05d3\u05d9, \u05de\u05e9\u05d0\u05d9\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8 \u05d0\u05d5 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05d1\u05de\u05e7\u05d5\u05dd \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e8\u05db\u05d5\u05ea."], [376.9, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9 \u05d5\u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05d9\u05d5\u05e6\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd: \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05db\u05d1\u05e8 \u05d4\u05ea\u05e7\u05e9\u05d5, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05d5\u05d3 \u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05ea \u05d5\u05de\u05e9\u05e0\u05d4 \u05de\u05d1\u05e0\u05d4."], [386.1, "\u05d5\u05d1\u05de\u05e2\u05d1\u05e8 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d2\u05dd \u05de\u05ea\u05e8\u05d7\u05d1\u05ea \u05de\u05e2\u05d8. \u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05d4\u05d6\u05d4 \u05de\u05e2\u05d5\u05d5\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05d1\u05de\u05e7\u05e8\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05e1\u05d5\u05d3\u05e7 \u05d0\u05d5\u05ea\u05dd, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d5\u05d1\u05e9\u05d9\u05e0\u05d5\u05d9\u05d9 \u05e2\u05d5\u05d1\u05d9."], [397.2, "\u05d5\u05e2\u05d5\u05d3 \u05d3\u05d1\u05e8: \u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05dc\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e2\u05d5\u05ea. \u05dc\u05db\u05df \u05de\u05e8\u05e4\u05d9\u05dd \u05db\u05de\u05d4 \u05e9\u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [407.4, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d0\u05ea \u05e9\u05dc\u05d1 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8?"], [409.7, "\u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d8\u05d5\u05d1 \u05e6\u05e8\u05d9\u05da \u05e2\u05e8\u05d1\u05d5\u05dc, \u05d1\u05e7\u05e8\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05ea\u05d7\u05d6\u05d5\u05e7\u05d4 \u05e9\u05dc \u05d4\u05e9\u05de\u05df \u05d0\u05d5 \u05e9\u05dc \u05d4\u05ea\u05de\u05d9\u05e1\u05d4."], [416.5, "\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d2\u05d6 \u05d1\u05dc\u05d7\u05e5, \u05d1\u05ea\u05d5\u05da \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05e0\u05d5\u05ea\u05df \u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05d5\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df, \u05d0\u05d1\u05dc \u05d4\u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8 \u05d1\u05d4\u05e8\u05d1\u05d4."], [424.5, "\u05d5\u05db\u05dc \u05d7\u05dc\u05e7 \u05e9\u05e0\u05e1\u05d3\u05e7 \u05d0\u05d5 \u05d4\u05ea\u05e2\u05d5\u05d5\u05ea \u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d9\u05e9\u05d5\u05e8, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e0\u05d5\u05e1\u05e3, \u05d0\u05d5 \u05d2\u05e8\u05d5\u05d8\u05d0\u05d4."], [431.4, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05de\u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05d1\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05dc\u05e4\u05d9 \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [436.9, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df \u05d0\u05d5 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3 \u05e0\u05d5\u05ea\u05df \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [446.6, "\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea TTT \u05d5-CCT \u05de\u05e8\u05d0\u05d5\u05ea \u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4 \u05db\u05de\u05d4 \u05de\u05d4\u05e8 \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05e8\u05e8, \u05d5\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df."], [455.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e8\u05d0\u05d4 \u05dc\u05de\u05d4 \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05de\u05ea\u05e7\u05e9\u05d4 \u05e2\u05d3 \u05d4\u05dc\u05d9\u05d1\u05d4: \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d5\u05dc \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4."]]};
window.MH_TR["ch03"]={"t": "\u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d5\u05dc \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05db\u05de\u05e2\u05d8 \u05e8\u05e7 \u05d1\u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df."], [10.5, "\u05d0\u05d1\u05dc \u05d1\u05de\u05e4\u05e2\u05dc \u05e9\u05d5\u05d0\u05dc\u05d9\u05dd \u05e9\u05ea\u05d9 \u05e9\u05d0\u05dc\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea: \u05db\u05de\u05d4 \u05e7\u05e9\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d4\u05d9\u05d4, \u05d5\u05e2\u05d3 \u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d5\u05d0 \u05d9\u05ea\u05e7\u05e9\u05d4."], [17.9, "\u05dc\u05e9\u05d0\u05dc\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05dc\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4. \u05d4\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e2\u05d5\u05e1\u05e7 \u05d1\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05df."], [26.8, "\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05ea\u05db\u05d5\u05e0\u05d4 \u05e9\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4: \u05db\u05de\u05d4 \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e0\u05d2\u05d3 \u05dc\u05d7\u05d3\u05d9\u05e8\u05d4, \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd."], [33.1, "\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea \u05e9\u05e4\u05dc\u05d3\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4 \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e4\u05d7\u05de\u05df: \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df, \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."], [41.9, "\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05db\u05d5\u05e0\u05d4 \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05db\u05d5\u05dc\u05d4: \u05db\u05de\u05d4 \u05e7\u05dc \u05dc\u05d4 \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d2\u05dd \u05db\u05e9\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05dc\u05d0 \u05de\u05d4\u05d9\u05e8 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3."], [50.0, "\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05ea\u05e7\u05e9\u05d4 \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d1, \u05d5\u05d2\u05dd \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05ea\u05d5\u05df \u05d9\u05d5\u05ea\u05e8, \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05d1\u05d2\u05d6."], [57.9, "\u05d5\u05d1\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea CCT \u05de\u05d4\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd, \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d4 \u05e9\u05d4\u05d0\u05e3 \u05e8\u05d7\u05d5\u05e7 \u05d9\u05de\u05d9\u05e0\u05d4, \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05d5\u05e7\u05e3 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e7\u05dc\u05d5\u05ea."], [67.3, "\u05db\u05e9\u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05de\u05d5\u05d8 \u05d7\u05dd, \u05d4\u05d7\u05d5\u05dd \u05d9\u05d5\u05e6\u05d0 \u05e8\u05e7 \u05d3\u05e8\u05da \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [71.6, "\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d4\u05db\u05d9 \u05de\u05d4\u05e8, \u05d5\u05db\u05db\u05dc \u05e9\u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d4 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d4\u05d7\u05d5\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05d1\u05d5\u05e8 \u05d3\u05e8\u05da \u05db\u05dc \u05d4\u05de\u05ea\u05db\u05ea \u05e9\u05de\u05e1\u05d1\u05d9\u05d1."], [81.2, "\u05db\u05db\u05dc \u05e9\u05d4\u05de\u05d5\u05d8 \u05e2\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e9\u05dc\u05d5 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8."], [85.7, "\u05d5\u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05de\u05d5\u05e0\u05d4: \u05de\u05d9\u05dd \u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05d7\u05d5\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05de\u05df, \u05d5\u05e9\u05de\u05df \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05d5\u05d5\u05d9\u05e8."], [93.9, "\u05dc\u05db\u05df \u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05e2\u05d3 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05d1\u05de\u05d5\u05d8 \u05d3\u05e7, \u05d5\u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d4 \u05d1\u05dc\u05d9\u05d1\u05d4 \u05e9\u05dc \u05de\u05d5\u05d8 \u05e2\u05d1\u05d4."], [101.7, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d5\u05d5\u05ea \u05d1\u05d9\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05e6\u05e8\u05d9\u05da \u05de\u05d1\u05d7\u05df \u05d0\u05d7\u05d3 \u05e7\u05d1\u05d5\u05e2, \u05d5\u05dc\u05d6\u05d4 \u05de\u05e9\u05de\u05e9 \u05de\u05d1\u05d7\u05df Jominy, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d2\u05dd \u05de\u05d1\u05d7\u05df \u05db\u05d9\u05d1\u05d5\u05d9 \u05e7\u05e6\u05d4."], [110.9, "\u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05de\u05d5\u05d8 \u05d1\u05e7\u05d5\u05d8\u05e8 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d5\u05d1\u05d0\u05d5\u05e8\u05da 100 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [117.9, "\u05ea\u05d5\u05da \u05e4\u05d7\u05d5\u05ea \u05de-5 \u05e9\u05e0\u05d9\u05d5\u05ea \u05de\u05e2\u05d1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05dc\u05de\u05ea\u05e7\u05df, \u05d5\u05de\u05ea\u05d9\u05d6\u05d9\u05dd \u05e1\u05d9\u05dc\u05d5\u05df \u05de\u05d9\u05dd \u05e2\u05dc \u05d4\u05e7\u05e6\u05d4 \u05d4\u05ea\u05d7\u05ea\u05d5\u05df \u05d1\u05dc\u05d1\u05d3, \u05d1\u05de\u05e9\u05da 10 \u05d3\u05e7\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea."], [126.1, "\u05d4\u05e7\u05e6\u05d4 \u05d4\u05d6\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05de\u05e2\u05dc\u05d9\u05d5 \u05de\u05ea\u05e7\u05e8\u05e8 \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d0\u05d8. \u05db\u05da \u05de\u05d5\u05d8 \u05d0\u05d7\u05d3 \u05de\u05db\u05d9\u05dc \u05d0\u05ea \u05db\u05dc \u05e7\u05e6\u05d1\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [135.9, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05d5\u05d8 \u05e9\u05e0\u05d9 \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05d1\u05e2\u05d5\u05de\u05e7 \u05e9\u05dc \u05db\u05de\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d9\u05d5\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df."], [145.4, "\u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05de\u05e9\u05d8\u05d7: \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 1.5 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05de\u05d4\u05e7\u05e6\u05d4, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d4 \u05e2\u05d5\u05d3 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d1\u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d1\u05d5\u05e2\u05d9\u05dd."], [155.1, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05e7\u05d5\u05de\u05ea Jominy: \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05e4\u05d9 \u05d4\u05de\u05e8\u05d7\u05e7 \u05de\u05d4\u05e7\u05e6\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8\u05e8."], [161.4, "\u05e0\u05e9\u05d5\u05d5\u05d4 \u05e9\u05dc\u05d5\u05e9 \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05db\u05de\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d3\u05d5\u05de\u05d4, \u05d1\u05d9\u05df 0.4% \u05dc-0.5%: \u05e4\u05dc\u05d3\u05ea \u05d4\u05e4\u05d7\u05de\u05df 1045, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea 4140 \u05d5-4340."], [176.7, "\u05d1\u05e7\u05e6\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8\u05e8 \u05e9\u05dc\u05d5\u05e9\u05ea\u05df \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05d3\u05d5\u05de\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 55 \u05e2\u05d3 60 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05db\u05d9 \u05d4\u05e4\u05d7\u05de\u05df \u05d3\u05d5\u05de\u05d4."], [185.0, "\u05d0\u05d1\u05dc \u05d1-1045 \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e6\u05d5\u05e0\u05d7\u05ea \u05de\u05d4\u05e8: \u05db\u05d1\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05db-6 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05d0\u05dc \u05de\u05ea\u05d7\u05ea \u05dc-40."], [193.7, "\u05d1-4140, \u05e2\u05dd \u05db\u05e8\u05d5\u05dd \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc\u05d0\u05d8: \u05d1-25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d4\u05d9\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 45."], [203.1, "\u05d5\u05d1-4340, \u05e2\u05dd \u05e0\u05d9\u05e7\u05dc, \u05db\u05e8\u05d5\u05dd \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05db\u05de\u05e2\u05d8 \u05e9\u05d8\u05d5\u05d7\u05d4, \u05d5\u05e0\u05e9\u05d0\u05e8\u05ea \u05de\u05e2\u05dc 50 \u05d2\u05dd \u05d1-25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [212.7, "\u05d4\u05d2\u05d5\u05d1\u05d4 \u05e9\u05dc \u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05d4\u05e9\u05d9\u05e4\u05d5\u05e2 \u05e9\u05dc\u05d4 \u05de\u05e8\u05d0\u05d4 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [219.8, "\u05dc\u05de\u05d4 \u05d6\u05d4 \u05e9\u05d9\u05de\u05d5\u05e9\u05d9? \u05db\u05d9 \u05db\u05dc \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e2\u05dc \u05de\u05d5\u05d8 Jominy \u05de\u05d9\u05d9\u05e6\u05d2\u05ea \u05e7\u05e6\u05d1 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05e1\u05d5\u05d9\u05dd."], [225.6, "\u05d5\u05d9\u05e9 \u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05d1\u05d9\u05df \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05e2\u05dc \u05d4\u05de\u05d5\u05d8 \u05dc\u05d1\u05d9\u05df \u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05d1\u05d7\u05dc\u05e7 \u05e2\u05d2\u05d5\u05dc: \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d7\u05e6\u05d9 \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05d5\u05d4\u05de\u05e8\u05db\u05d6, \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d5\u05dc\u05e4\u05d9 \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [236.6, "\u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05d6\u05d5\u05ea \u05de\u05e8\u05d0\u05e9, \u05d1\u05dc\u05d9 \u05dc\u05d7\u05ea\u05d5\u05da \u05d7\u05dc\u05e7, \u05d0\u05d9\u05d6\u05d5 \u05e7\u05e9\u05d9\u05d5\u05ea \u05ea\u05d4\u05d9\u05d4 \u05d1\u05ea\u05d5\u05db\u05d5."], [242.0, "\u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05de\u05d5\u05d8 1045 \u05d1\u05e7\u05d5\u05d8\u05e8 2 \u05d0\u05d9\u05e0\u05e5', \u05db-50 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05e9\u05de\u05d5\u05e7\u05e9\u05d4 \u05d1\u05e9\u05de\u05df, \u05de\u05d2\u05d9\u05e2 \u05d1\u05d7\u05e6\u05d9 \u05d4\u05e8\u05d3\u05d9\u05d5\u05e1 \u05e8\u05e7 \u05dc\u05d1\u05e2\u05e8\u05da 25 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [253.6, "\u05d5\u05d6\u05d5 \u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7, \u05e9\u05d1\u05e7\u05e6\u05d4 \u05e9\u05dc \u05de\u05d5\u05d8 Jominy \u05d4\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d9\u05d5\u05ea\u05e8 \u05de-55."], [260.1, "\u05de\u05d4 \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4? \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e9\u05de\u05d5\u05de\u05e1\u05d9\u05dd \u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [265.9, "\u05de\u05e0\u05d2\u05df, \u05db\u05e8\u05d5\u05dd, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05e0\u05d9\u05e7\u05dc \u05de\u05e2\u05db\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05ea\u05e4\u05e8\u05e7\u05d5\u05ea \u05e9\u05dc \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05dc\u05e4\u05e8\u05d9\u05d8 \u05d5\u05dc\u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d3\u05d5\u05d7\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05e3 \u05d9\u05de\u05d9\u05e0\u05d4."], [274.6, "\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d7\u05d6\u05e7 \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05d9\u05d7\u05e1 \u05dc\u05db\u05de\u05d5\u05ea \u05e9\u05dc\u05d5, \u05d5\u05d1\u05d5\u05e8\u05d5\u05df, \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05d6\u05e2\u05d9\u05e8\u05d5\u05ea \u05e9\u05dc \u05d0\u05dc\u05e4\u05d9\u05d5\u05ea \u05d4\u05d0\u05d7\u05d5\u05d6, \u05de\u05e2\u05dc\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [283.6, "\u05d2\u05dd \u05d2\u05e8\u05e2\u05d9\u05df \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d2\u05e1 \u05de\u05e2\u05dc\u05d4 \u05d0\u05d5\u05ea\u05d4, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05de\u05db\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05dc\u05d0 \u05de\u05d2\u05d3\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05d1\u05db\u05d5\u05d5\u05e0\u05d4."], [291.2, "\u05d5\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d6\u05db\u05d5\u05e8: \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05dc\u05d0 \u05de\u05e2\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea. \u05d4\u05dd \u05e8\u05e7 \u05de\u05d0\u05e4\u05e9\u05e8\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4 \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d1 \u05d9\u05d5\u05ea\u05e8."], [300.2, "\u05d2\u05dd \u05d1\u05ea\u05d5\u05da \u05d0\u05d5\u05ea\u05d5 \u05e1\u05d5\u05d2 \u05e4\u05dc\u05d3\u05d4 \u05d9\u05e9 \u05e4\u05d9\u05d6\u05d5\u05e8: \u05db\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05e2\u05dd \u05d4\u05e8\u05db\u05d1 \u05e7\u05e6\u05ea \u05e9\u05d5\u05e0\u05d4, \u05d1\u05ea\u05d5\u05da \u05d4\u05d8\u05d5\u05d5\u05d7 \u05e9\u05dc \u05d4\u05ea\u05e7\u05df."], [307.6, "\u05dc\u05db\u05df \u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05d2\u05d3\u05e8 \u05e4\u05e1 \u05e9\u05dc \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4, H-band \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea: \u05e2\u05e7\u05d5\u05de\u05d4 \u05e2\u05dc\u05d9\u05d5\u05e0\u05d4 \u05d5\u05e2\u05e7\u05d5\u05de\u05d4 \u05ea\u05d7\u05ea\u05d5\u05e0\u05d4, \u05d5\u05db\u05dc \u05d9\u05e6\u05d9\u05e7\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d9\u05e4\u05d5\u05dc \u05d1\u05d9\u05e0\u05d9\u05d4\u05df."], [318.7, "\u05d1-4140, \u05d1\u05de\u05e8\u05d7\u05e7 19 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05de\u05d4\u05e7\u05e6\u05d4, \u05d4\u05e4\u05e1 \u05e0\u05e2 \u05de\u05d1\u05e2\u05e8\u05da 39 \u05e2\u05d3 55 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [328.1, "\u05db\u05e9\u05d4\u05e2\u05d5\u05de\u05e7 \u05e7\u05e8\u05d9\u05d8\u05d9, \u05de\u05d6\u05de\u05d9\u05e0\u05d9\u05dd \u05e4\u05dc\u05d3\u05ea H, \u05dc\u05de\u05e9\u05dc 4140H, \u05e9\u05d1\u05d4 \u05d4\u05d9\u05e6\u05e8\u05df \u05de\u05d1\u05d8\u05d9\u05d7 \u05e2\u05e7\u05d5\u05de\u05ea Jominy \u05d1\u05ea\u05d5\u05da \u05d4\u05e4\u05e1, \u05d5\u05d9\u05e9 \u05d2\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05e4\u05e1 \u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8."], [340.8, "\u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05e9\u05d0\u05d5\u05dc \u05e7\u05d5\u05d3\u05dd: \u05d0\u05d9\u05e4\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d0\u05de\u05ea \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d7\u05d6\u05e7?"], [346.2, "\u05d1\u05d2\u05dc \u05e9\u05e2\u05d5\u05d1\u05d3 \u05d1\u05db\u05e4\u05d9\u05e4\u05d4 \u05d0\u05d5 \u05d1\u05e4\u05d9\u05ea\u05d5\u05dc, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05e0\u05de\u05e6\u05d0\u05d9\u05dd \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05d5\u05d1\u05d3\u05ea \u05e4\u05d7\u05d5\u05ea. \u05dc\u05db\u05df \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05e6\u05e8\u05d9\u05da \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e2\u05d3 \u05d4\u05dc\u05d9\u05d1\u05d4."], [356.9, "\u05d0\u05d1\u05dc \u05d1\u05d1\u05d5\u05e8\u05d2 \u05d0\u05d5 \u05d1\u05de\u05d5\u05d8 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05d1\u05de\u05e9\u05d9\u05db\u05d4, \u05db\u05dc \u05d4\u05d7\u05ea\u05da \u05e0\u05d5\u05e9\u05d0 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e1, \u05d5\u05e6\u05e8\u05d9\u05da \u05e4\u05dc\u05d3\u05d4 \u05e9\u05ea\u05ea\u05e7\u05e9\u05d4 \u05e2\u05d3 \u05d4\u05de\u05e8\u05db\u05d6."], [365.3, "\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05d9\u05e9\u05e8 \u05d1\u05d8\u05d1\u05dc\u05d4: \u05d1-42CrMo4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05d1\u05d7\u05d4, \u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05e9\u05d9\u05db\u05d4 \u05e2\u05d3 \u05e7\u05d5\u05d8\u05e8 16 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d4\u05d5\u05d0 1,100 \u05e2\u05d3 1,300 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."], [378.7, "\u05d5\u05d1\u05e7\u05d5\u05d8\u05e8 100 \u05e2\u05d3 160 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05e8\u05e7 \u05dc-800 \u05e2\u05d3 950."], [385.9, "\u05db\u05db\u05dc \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e6\u05e8\u05d9\u05da \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05db\u05d3\u05d9 \u05dc\u05e7\u05d1\u05dc \u05d0\u05ea \u05d0\u05d5\u05ea\u05df \u05ea\u05db\u05d5\u05e0\u05d5\u05ea."], [393.2, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05d4\u05d8\u05e2\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05e7\u05e9\u05d9\u05d5\u05ea \u05e8\u05e7 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05dc\u05d4\u05e0\u05d9\u05d7 \u05e9\u05d6\u05d5 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05db\u05dc \u05d4\u05d7\u05dc\u05e7."], [401.5, "\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05de\u05e8\u05d0\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e9\u05dc \u05d3\u05d2\u05d9\u05de\u05d4 \u05e7\u05d8\u05e0\u05d4. \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05de\u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05d9\u05d5\u05e6\u05d0 \u05d7\u05dc\u05e9 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05dc\u05d9\u05d1\u05d4."], [409.2, "\u05d5\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d9\u05ea\u05e8\u05d5\u05df: \u05dc\u05d9\u05d3 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d4\u05ea\u05d7\u05de\u05dd \u05de\u05ea\u05e7\u05e9\u05d4 \u05de\u05e2\u05e6\u05de\u05d5 \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."], [419.1, "\u05d5\u05d8\u05e2\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05ea: \u05dc\u05e7\u05e8\u05e8 \u05d1\u05de\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05db\u05d3\u05d9 \u05dc\u05e1\u05d7\u05d5\u05d8 \u05de\u05de\u05e0\u05d4 \u05e2\u05d5\u05d3 \u05e2\u05d5\u05de\u05e7. \u05d6\u05d4 \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd, \u05d5\u05e2\u05d3\u05d9\u05e3 \u05dc\u05d1\u05d7\u05d5\u05e8 \u05e4\u05dc\u05d3\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d5\u05dc\u05e7\u05e8\u05e8 \u05d1\u05e9\u05de\u05df."], [433.0, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e4\u05dc\u05d3\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d9\u05e7\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05db\u05dc \u05d9\u05e1\u05d5\u05d3 \u05e0\u05d5\u05e1\u05e3, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05e0\u05d9\u05e7\u05dc, \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05de\u05d7\u05d9\u05e8."], [442.0, "\u05e4\u05dc\u05d3\u05ea H \u05e2\u05dd \u05e4\u05e1 \u05de\u05d5\u05d1\u05d8\u05d7 \u05e2\u05d5\u05dc\u05d4 \u05e2\u05d5\u05d3, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05e9 \u05e2\u05dc\u05d9\u05d4 \u05db\u05de\u05d5\u05ea \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05d4."], [448.1, "\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d0\u05de\u05d9\u05ea\u05d9\u05ea \u05e9\u05dc \u05d4\u05dc\u05d9\u05d1\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05dc\u05d7\u05ea\u05d5\u05da \u05d7\u05dc\u05e7 \u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05d0\u05d5 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05dc\u05e1\u05d3\u05e8\u05d4 \u05d3\u05d2\u05d9\u05de\u05ea \u05d1\u05e7\u05e8\u05d4, \u05d5\u05d2\u05dd \u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4."], [455.4, "\u05d0\u05d1\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d3\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05d4\u05db\u05d9 \u05d4\u05e8\u05d1\u05d4: \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05e4\u05e1\u05dc\u05d9\u05dd \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d0\u05d5 \u05d2\u05e8\u05d5\u05e2 \u05de\u05d6\u05d4, \u05e0\u05db\u05e9\u05dc\u05d9\u05dd \u05d1\u05e9\u05d8\u05d7."], [464.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05db\u05de\u05d4 \u05e7\u05e9\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d5\u05ea, \u05d5\u05d4\u05d9\u05d0 \u05e0\u05e7\u05d1\u05e2\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05d9 \u05d4\u05e4\u05d7\u05de\u05df."], [472.0, "\u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7 \u05d4\u05d5\u05d0 \u05d9\u05ea\u05e7\u05e9\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05e0\u05e7\u05d1\u05e2\u05ea \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05d9 \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5 \u05d2\u05dd \u05dc\u05e4\u05d9 \u05d4\u05e7\u05d5\u05d8\u05e8 \u05d5\u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [482.2, "\u05de\u05d1\u05d7\u05df Jominy \u05de\u05d5\u05d3\u05d3 \u05d0\u05d5\u05ea\u05d4, \u05d5\u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e9\u05dc\u05d5 \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05dc\u05d7\u05d6\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d7\u05dc\u05e7 \u05d0\u05de\u05d9\u05ea\u05d9."], [488.6, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05d1\u05db\u05dc \u05d4\u05e0\u05e4\u05d7, \u05e2\u05dd \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e9\u05d1\u05d4\u05dd: \u05e8\u05d9\u05db\u05d5\u05da."]]};
window.MH_TR["ch04"]={"t": "\u05e8\u05d9\u05db\u05d5\u05da", "l": [[5.0, "\u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05e8\u05d0\u05d9\u05e0\u05d5 \u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8. \u05de\u05d4\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05e2\u05e6\u05de\u05dd, \u05d5\u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e9\u05d1\u05d4\u05dd \u05d4\u05d5\u05d0 \u05e8\u05d9\u05db\u05d5\u05da."], [14.3, "\u05e8\u05d9\u05db\u05d5\u05da, annealing \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05de\u05d8\u05e8\u05ea\u05d5 \u05dc\u05d4\u05e4\u05d5\u05da \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e8\u05db\u05d4, \u05d2\u05de\u05d9\u05e9\u05d4 \u05d5\u05e0\u05d5\u05d7\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4."], [22.1, "\u05de\u05e8\u05db\u05db\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9, \u05dc\u05e4\u05e0\u05d9 \u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8, \u05d5\u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8 \u05e9\u05d4\u05e7\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8."], [30.2, "\u05d9\u05e9 \u05db\u05de\u05d4 \u05e1\u05d5\u05d2\u05d9 \u05e8\u05d9\u05db\u05d5\u05da, \u05d5\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05d4\u05d5\u05d0 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [34.9, "\u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df, \u05e2\u05d3 \u05e9\u05db\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [40.7, "\u05d1\u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d6\u05de\u05df \u05e8\u05d1 \u05e1\u05d1\u05d9\u05d1 \u05d4\u05e7\u05d5 \u05d4\u05ea\u05d7\u05ea\u05d5\u05df, A1."], [46.0, "\u05d5\u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05ea\u05ea-\u05e7\u05e8\u05d9\u05d8\u05d9 \u05d5\u05e8\u05d9\u05db\u05d5\u05da \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05db\u05da \u05e9\u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d1\u05db\u05dc\u05dc."], [54.2, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de-0.8% \u05e4\u05d7\u05de\u05df, \u05db\u05de\u05d5 \u05e8\u05d5\u05d1 \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d5\u05ea."], [61.5, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05d1\u05e2\u05e8\u05da 50 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e2\u05dc Ac3, \u05d4\u05e7\u05d5 \u05e9\u05de\u05e2\u05dc\u05d9\u05d5 \u05db\u05dc \u05d4\u05e4\u05e8\u05d9\u05d8 \u05db\u05d1\u05e8 \u05d4\u05e4\u05da \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [68.8, "\u05d1\u05e4\u05dc\u05d3\u05ea 4140, \u05dc\u05de\u05e9\u05dc, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e8\u05d9\u05db\u05d5\u05da \u05d4\u05d9\u05d0 815 \u05e2\u05d3 870 \u05de\u05e2\u05dc\u05d5\u05ea."], [77.3, "\u05d5\u05d0\u05d6 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05db\u05d3\u05d9 \u05e9\u05d2\u05dd \u05d4\u05dc\u05d9\u05d1\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05ea\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4, \u05d5\u05e9\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d9\u05d4\u05d9\u05d4 \u05d0\u05d7\u05d9\u05d3."], [84.6, "\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2 \u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9, \u05d0\u05d1\u05dc \u05d4\u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05e9\u05dc \u05d9\u05e6\u05e8\u05df \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e7\u05d5\u05d1\u05e2\u05d5\u05ea."], [92.9, "\u05d4\u05e1\u05d5\u05d3 \u05e9\u05dc \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8: \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8."], [98.8, "\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e7\u05e6\u05d1 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05e9\u05e2\u05d4, \u05e2\u05d3 \u05e9\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05ea\u05d7\u05d5\u05dd \u05d4\u05d4\u05ea\u05de\u05e8\u05d4, \u05de\u05ea\u05d7\u05ea \u05dc-A1."], [105.9, "\u05de\u05e9\u05dd \u05db\u05d1\u05e8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d5\u05dc\u05e7\u05e8\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [109.6, "\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05d0\u05d9\u05d8\u05d9 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8 \u05d2\u05e1, \u05e2\u05dd \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05e4\u05e1\u05d9 \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05d5\u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05de\u05d1\u05d9\u05df \u05d4\u05de\u05d1\u05e0\u05d9\u05dd \u05e2\u05dd \u05e4\u05e1\u05d9\u05dd."], [119.1, "\u05e4\u05dc\u05d3\u05ea 4140 \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05e2\u05d3 \u05db-197 \u05d1\u05e8\u05d9\u05e0\u05dc, \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05e9\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4."], [129.3, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de-0.8% \u05e4\u05d7\u05de\u05df \u05d4\u05d7\u05d5\u05e7 \u05e9\u05d5\u05e0\u05d4: \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e8\u05e7 \u05de\u05e2\u05d8 \u05de\u05e2\u05dc Ac1, \u05d5\u05dc\u05d0 \u05de\u05e2\u05dc Acm."], [138.7, "\u05d0\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05de\u05e2\u05dc Acm \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8, \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05d4\u05e2\u05d5\u05d3\u05e3 \u05e0\u05d0\u05e1\u05e3 \u05e2\u05dc \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."], [145.6, "\u05d4\u05d5\u05d0 \u05d9\u05d5\u05e6\u05e8 \u05e9\u05dd \u05e8\u05e9\u05ea \u05e8\u05e6\u05d9\u05e4\u05d4 \u05e9\u05dc \u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05e9\u05d4\u05d5\u05e4\u05db\u05ea \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05e4\u05e8\u05d9\u05db\u05d4."], [150.5, "\u05db\u05e9\u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc-Acm, \u05d7\u05dc\u05e7 \u05de\u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05dc\u05d0 \u05de\u05ea\u05de\u05d5\u05e1\u05e1, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05e6\u05d5\u05e8\u05ea \u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d5\u05dc\u05d0 \u05db\u05e8\u05e9\u05ea."], [159.0, "\u05d4\u05e1\u05d5\u05d2 \u05d4\u05d1\u05d0 \u05d4\u05d5\u05d0 \u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd \u05e8\u05d9\u05db\u05d5\u05da \u05db\u05d3\u05d5\u05e8\u05d9."], [163.8, "\u05d1\u05e4\u05e8\u05dc\u05d9\u05d8 \u05e8\u05d2\u05d9\u05dc \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05d1\u05e0\u05d5\u05d9 \u05de\u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea, \u05db\u05de\u05d5 \u05d3\u05e4\u05d9\u05dd. \u05d1\u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05de\u05ea\u05e4\u05e8\u05e7\u05d5\u05ea \u05d5\u05d4\u05d5\u05e4\u05db\u05d5\u05ea \u05dc\u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea."], [173.9, "\u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05d9\u05d0 \u05e9\u05db\u05d3\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e2\u05dd \u05d4\u05e9\u05d8\u05d7 \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05e9\u05d5\u05d0\u05e3 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d4 \u05db\u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d5 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d6\u05de\u05df \u05d5\u05d7\u05d5\u05dd."], [182.5, "\u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea: \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05de\u05de\u05e9 \u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 700 \u05de\u05e2\u05dc\u05d5\u05ea."], [189.8, "\u05de\u05d7\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05dc\u05d9\u05dd, \u05de\u05e2\u05dc \u05d5\u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05d0\u05d5 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e2\u05d8 \u05de\u05e2\u05dc A1 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d0\u05d5\u05d3."], [198.3, "\u05d6\u05d4 \u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da, \u05e9\u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05de\u05e9\u05da \u05e2\u05e9\u05e8\u05d5\u05ea \u05e9\u05e2\u05d5\u05ea, \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05d4\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05d1\u05e4\u05dc\u05d3\u05d4."], [206.0, "\u05dc\u05de\u05d9 \u05d6\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd? \u05e7\u05d5\u05d3\u05dd \u05db\u05dc \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df, \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05ea \u05de\u05e1\u05d1\u05d9\u05dd 52100 \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd."], [214.4, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05db\u05d3\u05d5\u05e8\u05d9 \u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9 \u05d4\u05e0\u05d5\u05d7 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05e4\u05dc\u05d3\u05ea 52100 \u05de\u05d2\u05d9\u05e2\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da \u05dc\u05d1\u05e2\u05e8\u05da 183 \u05e2\u05d3 212 \u05d1\u05e8\u05d9\u05e0\u05dc."], [227.1, "\u05d5\u05d6\u05d4 \u05d2\u05dd \u05de\u05d1\u05e0\u05d4 \u05d4\u05ea\u05d7\u05dc\u05d4 \u05d8\u05d5\u05d1 \u05dc\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05db\u05d9 \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3."], [233.6, "\u05e9\u05d9\u05de\u05d5\u05e9 \u05d7\u05e9\u05d5\u05d1 \u05e0\u05d5\u05e1\u05e3 \u05d4\u05d5\u05d0 \u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8, \u05db\u05de\u05d5 \u05db\u05d1\u05d9\u05e9\u05d4 \u05e9\u05dc \u05e8\u05d0\u05e9\u05d9 \u05d1\u05e8\u05d2\u05d9\u05dd, \u05db\u05d9 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05db\u05d3\u05d5\u05e8\u05d9\u05ea \u05e0\u05de\u05ea\u05d7\u05ea \u05d1\u05dc\u05d9 \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7."], [241.9, "\u05d0\u05d1\u05dc \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de-0.4% \u05e4\u05d7\u05de\u05df, \u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05dc\u05d0 \u05d8\u05d5\u05d1\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9: \u05d4\u05d7\u05d5\u05de\u05e8 \u05e8\u05da \u05de\u05d3\u05d9, \u05e0\u05de\u05e8\u05d7, \u05d5\u05e0\u05d3\u05d1\u05e7 \u05dc\u05db\u05dc\u05d9."], [253.1, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05ea\u05d7\u05ea \u05dc-A1. \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8, \u05db\u05de\u05d5 \u05de\u05e9\u05d9\u05db\u05d4, \u05e2\u05e8\u05d2\u05d5\u05dc \u05d0\u05d5 \u05db\u05d9\u05e4\u05d5\u05e3, \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e0\u05de\u05ea\u05d7\u05d9\u05dd \u05d5\u05de\u05ea\u05de\u05dc\u05d0\u05d9\u05dd \u05e4\u05d2\u05de\u05d9\u05dd."], [263.0, "\u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05ea\u05e7\u05e9\u05d4 \u05de\u05d4\u05e2\u05d1\u05d5\u05d3\u05d4, \u05d5\u05d0\u05dd \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5, \u05d4\u05d5\u05d0 \u05e0\u05e1\u05d3\u05e7."], [267.9, "\u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 550 \u05e2\u05d3 700 \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05ea\u05d7\u05ea \u05dc-A1."], [275.5, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05e2\u05d2\u05d5\u05dc\u05d9\u05dd \u05d5\u05e0\u05e7\u05d9\u05d9\u05dd \u05de\u05e4\u05d2\u05de\u05d9\u05dd, \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d4\u05de\u05e2\u05d5\u05d5\u05ea\u05d9\u05dd. \u05dc\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05e8\u05d4-\u05e7\u05e8\u05d9\u05e1\u05d8\u05dc\u05d9\u05d6\u05e6\u05d9\u05d4."], [285.9, "\u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05d5\u05d6\u05e8\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05e8\u05db\u05d4, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05de\u05e9\u05d9\u05da \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d4. \u05d1\u05de\u05e9\u05d9\u05db\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05e9\u05dc \u05e4\u05d7 \u05d0\u05d5 \u05d1\u05de\u05e9\u05d9\u05db\u05ea \u05d7\u05d5\u05d8\u05d9\u05dd \u05d7\u05d5\u05d6\u05e8\u05d9\u05dd \u05e2\u05dc \u05d6\u05d4 \u05d1\u05d9\u05df \u05d4\u05e9\u05dc\u05d1\u05d9\u05dd."], [295.4, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df: \u05d0\u05d9\u05df \u05de\u05e2\u05d1\u05e8 \u05d3\u05e8\u05da \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05dc\u05db\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05e7\u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05e7\u05e9\u05e7\u05e9\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea."], [303.8, "\u05de\u05d4 \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d1\u05d1\u05d9\u05ea \u05d4\u05de\u05dc\u05d0\u05db\u05d4? \u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05e8\u05db\u05da \u05d1\u05db\u05dc\u05dc, \u05db\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05db\u05d1\u05e8 \u05de\u05e8\u05d5\u05db\u05da."], [310.8, "\u05d1\u05ea\u05e7\u05e0\u05d9\u05dd \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9\u05d9\u05dd, \u200e+A \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05de\u05e8\u05d5\u05db\u05da, \u05d5-\u200e+AC \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4, \u05db\u05dc\u05d5\u05de\u05e8 \u05e8\u05d9\u05db\u05d5\u05da \u05e2\u05dd \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05db\u05d3\u05d5\u05e8\u05d9\u05d9\u05dd."], [321.6, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05d5 \u05d1\u05d4\u05d6\u05de\u05e0\u05d4 \u05db\u05d3\u05d0\u05d9 \u05dc\u05db\u05ea\u05d5\u05d1 \u05d2\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9\u05ea, \u05dc\u05de\u05e9\u05dc: \u05de\u05e8\u05d5\u05db\u05da, \u05e2\u05d3 197 \u05d1\u05e8\u05d9\u05e0\u05dc."], [330.7, "\u05d5\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05e2\u05d1\u05d5\u05e8 \u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e7\u05e9\u05d9\u05d4, \u05de\u05e8\u05db\u05db\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05dc\u05d0 \u05d0\u05d7\u05e8\u05d9\u05d5."], [336.8, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05de\u05d7\u05d6\u05d5\u05e8 \u05d0\u05e8\u05d5\u05da \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05d5\u05de\u05ea\u05db\u05e1\u05d9\u05dd \u05d1\u05e7\u05e9\u05e7\u05e9\u05ea."], [346.7, "\u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df \u05dc\u05d0 \u05ea\u05ea\u05e7\u05e9\u05d4 \u05db\u05de\u05d5 \u05e9\u05e6\u05e8\u05d9\u05da \u05d0\u05d7\u05e8 \u05db\u05da, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3, \u05d0\u05d5 \u05dc\u05e8\u05db\u05da \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4."], [355.6, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df, \u05d5\u05d6\u05d4 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05e0\u05d5\u05e1\u05e4\u05d9\u05dd."], [363.9, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9, \u05dc\u05de\u05e9\u05dc \u05db\u05e9\u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05d5\u05e7\u05d3\u05dd, \u05e0\u05d5\u05ea\u05df \u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05e6\u05d9\u05e4\u05d9\u05e0\u05d5."], [371.4, "\u05d5\u05e9\u05ea\u05d9 \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05e9\u05db\u05d1\u05e8 \u05d4\u05d6\u05db\u05e8\u05e0\u05d5: \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e2\u05dc Acm \u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df, \u05d5\u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df \u05e9\u05e6\u05e8\u05d9\u05db\u05d4 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9."], [382.5, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d4\u05d6\u05de\u05df. \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05ea\u05d5\u05e4\u05e1 \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05e9\u05e2\u05d5\u05ea, \u05db\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05d0\u05d9\u05d8\u05d9 \u05e0\u05e2\u05e9\u05d4 \u05d1\u05ea\u05d5\u05db\u05d5."], [390.5, "\u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e0\u05de\u05e9\u05db\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d9\u05de\u05de\u05d4."], [395.8, "\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4 \u05d0\u05d5 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05e9\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df, \u05d9\u05e7\u05e8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8. \u05d5\u05d1\u05dc\u05e2\u05d3\u05d9\u05d4\u05dd \u05e6\u05e8\u05d9\u05da \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4."], [405.1, "\u05dc\u05db\u05df, \u05d0\u05dd \u05d0\u05e4\u05e9\u05e8, \u05d4\u05db\u05d9 \u05d6\u05d5\u05dc \u05dc\u05e7\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05de\u05e8 \u05db\u05d1\u05e8 \u05de\u05e8\u05d5\u05db\u05da \u05de\u05d4\u05d9\u05e6\u05e8\u05df, \u200e+A \u05d0\u05d5 \u200e+AC, \u05d5\u05dc\u05d0 \u05dc\u05e8\u05db\u05da \u05d1\u05e2\u05e6\u05de\u05da."], [414.5, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05d4\u05d5\u05d0 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e2\u05dc Ac3 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8 \u05d2\u05e1."], [423.3, "\u05e1\u05e4\u05e8\u05d5\u05d0\u05d9\u05d3\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05d0\u05ea \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05dc\u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea, \u05d5\u05e0\u05d5\u05ea\u05e0\u05ea \u05d0\u05ea \u05d4\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d5\u05dc\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8."], [433.5, "\u05e8\u05d9\u05db\u05d5\u05da \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd, \u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05de\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05d4\u05d2\u05de\u05d9\u05e9\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05e8."], [439.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05e0\u05e8\u05d0\u05d4 \u05d3\u05d5\u05de\u05d4, \u05d0\u05d1\u05dc \u05e0\u05d5\u05ea\u05df \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d0\u05d7\u05e8\u05ea: \u05e0\u05e8\u05de\u05d5\u05dc."]]};
window.MH_TR["ch05"]={"t": "\u05e0\u05e8\u05de\u05d5\u05dc", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e8\u05d0\u05d9\u05e0\u05d5 \u05e8\u05d9\u05db\u05d5\u05da. \u05e0\u05e8\u05de\u05d5\u05dc \u05e0\u05e8\u05d0\u05d4 \u05db\u05de\u05e2\u05d8 \u05d0\u05d5\u05ea\u05d5 \u05d4\u05d3\u05d1\u05e8, \u05d0\u05d1\u05dc \u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05e7\u05d8\u05df \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd \u05e0\u05d5\u05ea\u05df \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9."], [13.9, "\u05e0\u05e8\u05de\u05d5\u05dc, normalizing \u05d1\u05d0\u05e0\u05d2\u05dc\u05d9\u05ea, \u05e0\u05e7\u05e8\u05d0 \u05db\u05da \u05db\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d7\u05d6\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05de\u05d1\u05e0\u05d4 \u05e8\u05d2\u05d9\u05dc \u05d5\u05d0\u05d7\u05d9\u05d3, \u05d0\u05d7\u05e8\u05d9 \u05e9\u05ea\u05d4\u05dc\u05d9\u05da \u05e7\u05d5\u05d3\u05dd \u05e7\u05dc\u05e7\u05dc \u05d0\u05d5\u05ea\u05d5."], [23.1, "\u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05da \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5, \u05d1\u05de\u05d4 \u05d4\u05d5\u05d0 \u05e9\u05d5\u05e0\u05d4 \u05de\u05e8\u05d9\u05db\u05d5\u05da, \u05d5\u05de\u05ea\u05d9 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5: \u05d0\u05d7\u05e8\u05d9 \u05d7\u05d9\u05e9\u05d5\u05dc, \u05d0\u05d7\u05e8\u05d9 \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [32.1, "\u05d1\u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d1\u05e2\u05e8\u05da 30 \u05e2\u05d3 80 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df, Ac3, \u05e2\u05d3 \u05e9\u05db\u05d5\u05dc\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d0\u05d7\u05d9\u05d3."], [42.0, "\u05d1\u05e4\u05dc\u05d3\u05ea 4140, \u05dc\u05de\u05e9\u05dc, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05e0\u05d5\u05de\u05d9\u05e0\u05dc\u05d9\u05ea \u05d4\u05d9\u05d0 870 \u05de\u05e2\u05dc\u05d5\u05ea."], [49.6, "\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e2\u05d3 \u05e9\u05d2\u05dd \u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05d0\u05dc\u05d9\u05d4, \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05d1\u05e8\u05d9\u05db\u05d5\u05da."], [55.4, "\u05d5\u05d4\u05d4\u05d1\u05d3\u05dc \u05de\u05d2\u05d9\u05e2 \u05e2\u05db\u05e9\u05d9\u05d5: \u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d4\u05ea\u05e0\u05d5\u05e8, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e9\u05e7\u05d8."], [61.6, "\u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e7\u05e8\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05ea\u05d5\u05da \u05ea\u05e0\u05d5\u05e8 \u05db\u05d1\u05d5\u05d9, \u05d0\u05d1\u05dc \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d0\u05d8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05d8\u05d1\u05d9\u05dc\u05d4 \u05d1\u05de\u05d9\u05dd \u05d0\u05d5 \u05d1\u05e9\u05de\u05df."], [71.5, "\u05de\u05d4 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05e2\u05d5\u05e9\u05d4? \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05d6\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05ea\u05e4\u05e8\u05e7 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."], [79.2, "\u05e0\u05d5\u05e6\u05e8 \u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df, \u05e2\u05dd \u05de\u05e8\u05d5\u05d5\u05d7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05d9\u05df \u05e4\u05e1\u05d9 \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05d5\u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05d5\u05d0\u05d7\u05d9\u05d3\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [86.5, "\u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df \u05d5\u05d2\u05e8\u05e2\u05d9\u05df \u05e7\u05d8\u05df \u05e4\u05d9\u05e8\u05d5\u05e9\u05dd \u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da."], [92.5, "\u05d1\u05e4\u05dc\u05d3\u05ea 4140, \u05d1\u05de\u05d5\u05d8 \u05d1\u05e7\u05d5\u05d8\u05e8 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d0\u05d7\u05e8\u05d9 \u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d1\u05e2\u05e8\u05da 302 \u05d1\u05e8\u05d9\u05e0\u05dc \u05d5\u05d7\u05d5\u05d6\u05e7 \u05de\u05e9\u05d9\u05db\u05d4 \u05e9\u05dc \u05db-1,020 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc."], [104.9, "\u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0, \u05d0\u05d5\u05ea\u05d4 \u05e4\u05dc\u05d3\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05e8\u05e7 \u05dc\u05db-197 \u05d1\u05e8\u05d9\u05e0\u05dc."], [110.1, "\u05d5\u05e2\u05d5\u05d3 \u05d4\u05d1\u05d3\u05dc \u05d7\u05e9\u05d5\u05d1: \u05d1\u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05ea\u05e4\u05e0\u05d4 \u05de\u05d9\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05d4\u05d9\u05e8 \u05d5\u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0."], [117.9, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de-0.8% \u05e4\u05d7\u05de\u05df, \u05db\u05d0\u05df \u05d4\u05d7\u05d5\u05e7 \u05d4\u05e4\u05d5\u05da \u05de\u05e8\u05d9\u05db\u05d5\u05da: \u05de\u05e0\u05e8\u05de\u05dc\u05d9\u05dd \u05de\u05e2\u05dc Acm."], [125.9, "\u05d4\u05de\u05d8\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05dc\u05d4\u05de\u05d9\u05e1 \u05d0\u05ea \u05db\u05dc \u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05db\u05d5\u05dc\u05dc \u05d4\u05e8\u05e9\u05ea \u05e9\u05e0\u05d5\u05e6\u05e8\u05d4 \u05e2\u05dc \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d1\u05ea\u05d4\u05dc\u05d9\u05da \u05e7\u05d5\u05d3\u05dd."], [132.5, "\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d9\u05df \u05de\u05e1\u05e4\u05d9\u05e7 \u05d6\u05de\u05df \u05db\u05d3\u05d9 \u05e9\u05d4\u05e8\u05e9\u05ea \u05ea\u05d9\u05d5\u05d5\u05e6\u05e8 \u05de\u05d7\u05d3\u05e9, \u05d5\u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05e0\u05e9\u05d0\u05e8 \u05de\u05e4\u05d5\u05d6\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8."], [140.1, "\u05dc\u05db\u05df \u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d3\u05e8\u05da \u05d8\u05d5\u05d1\u05d4 \u05dc\u05e9\u05d1\u05d5\u05e8 \u05e8\u05e9\u05ea \u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05dc\u05e4\u05e0\u05d9 \u05e8\u05d9\u05db\u05d5\u05da \u05db\u05d3\u05d5\u05e8\u05d9 \u05d0\u05d5 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4."], [147.4, "\u05d9\u05e9 \u05dc\u05e0\u05e8\u05de\u05d5\u05dc \u05d7\u05d9\u05e1\u05e8\u05d5\u05df \u05d0\u05d7\u05d3: \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7."], [152.3, "\u05d7\u05dc\u05e7 \u05d3\u05e7 \u05de\u05ea\u05e7\u05e8\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05d4\u05e8, \u05d5\u05d9\u05d5\u05e6\u05d0 \u05d7\u05d6\u05e7 \u05d9\u05d5\u05ea\u05e8. \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e9\u05dc\u05d5 \u05e7\u05e8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05de\u05e6\u05d1 \u05e9\u05dc \u05e8\u05d9\u05db\u05d5\u05da."], [161.8, "\u05dc\u05db\u05df \u05d4\u05e2\u05e8\u05db\u05d9\u05dd \u05e9\u05dc 4140 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05e0\u05db\u05d5\u05e0\u05d9\u05dd \u05dc\u05de\u05d5\u05d8 \u05d1\u05e7\u05d5\u05d8\u05e8 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05dc\u05d0 \u05dc\u05db\u05dc \u05d7\u05dc\u05e7."], [170.1, "\u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05db\u05d1\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05e4\u05d9\u05dc\u05d5 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [177.9, "\u05d0\u05d6 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d9\u05d5\u05e6\u05d0\u05ea \u05e7\u05e9\u05d4 \u05d5\u05e4\u05e8\u05d9\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05e8\u05e6\u05d9\u05e0\u05d5, \u05d5\u05dc\u05db\u05df \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05de\u05e0\u05e8\u05de\u05dc\u05d9\u05dd \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e8\u05e4\u05d9\u05dd. \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05de\u05e0\u05e8\u05de\u05dc\u05d9\u05dd \u05d1\u05db\u05dc\u05dc."], [190.5, "\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d0\u05d7\u05e8\u05d9 \u05d7\u05d9\u05e9\u05d5\u05dc."], [194.2, "\u05d1\u05d7\u05d9\u05e9\u05d5\u05dc \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e2\u05dc 1,100 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05db\u05d6\u05d5 \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [204.3, "\u05d4\u05d7\u05d9\u05e9\u05d5\u05dc \u05d2\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3: \u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05d5\u05d7\u05dc\u05e7 \u05dc\u05d0\u05d8, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d4 \u05de\u05d2\u05d5\u05dc\u05d2\u05dc\u05ea \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e4\u05e1\u05d9\u05dd \u05e9\u05dc \u05e4\u05e8\u05d9\u05d8 \u05d5\u05e4\u05e8\u05dc\u05d9\u05d8."], [213.7, "\u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05d5\u05d7\u05e7 \u05d0\u05ea \u05db\u05dc \u05d6\u05d4. \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05e9\u05d5\u05d1 \u05d3\u05e8\u05da \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05e0\u05d1\u05e0\u05d9\u05ea \u05de\u05d7\u05d3\u05e9 \u05e2\u05dd \u05d2\u05e8\u05e2\u05d9\u05df \u05e2\u05d3\u05d9\u05df \u05d5\u05d0\u05d7\u05d9\u05d3."], [221.5, "\u05d5\u05de\u05d1\u05e0\u05d4 \u05d0\u05d7\u05d9\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d5 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05d2\u05d9\u05d1 \u05dc\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea."], [229.4, "\u05d2\u05dd \u05d1\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05d4\u05de\u05d1\u05e0\u05d4 \u05d2\u05e1 \u05d5\u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3, \u05db\u05d9 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05ea\u05e7\u05e8\u05e8\u05d4 \u05dc\u05d0\u05d8 \u05de\u05d4\u05de\u05e6\u05d1 \u05d4\u05e0\u05d5\u05d6\u05dc\u05d9, \u05d5\u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05e9\u05e4\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d0\u05d5\u05d3."], [238.2, "\u05d5\u05d2\u05dd \u05d1\u05e8\u05d9\u05ea\u05d5\u05da: \u05d4\u05ea\u05e4\u05e8 \u05e2\u05e6\u05de\u05d5 \u05d5\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3\u05d5, \u05e9\u05d4\u05ea\u05d7\u05de\u05dd \u05de\u05d0\u05d5\u05d3, \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05e2\u05dd \u05d2\u05e8\u05e2\u05d9\u05df \u05d2\u05e1."], [245.6, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05e8\u05d9\u05d8\u05d9\u05d9\u05dd, \u05db\u05de\u05d5 \u05e6\u05e0\u05e8\u05ea \u05d5\u05db\u05dc\u05d9 \u05dc\u05d7\u05e5, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e0\u05e8\u05de\u05dc\u05d9\u05dd \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05db\u05d3\u05d9 \u05dc\u05e2\u05d3\u05df \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05d1\u05db\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd."], [255.2, "\u05d6\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc \u05db\u05d1\u05d3, \u05db\u05d9 \u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05d5\u05d0 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea. \u05d1\u05e8\u05d5\u05d1 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05de\u05e1\u05ea\u05e4\u05e7\u05d9\u05dd \u05d1\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05e9\u05e0\u05db\u05d9\u05e8 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0."], [265.6, "\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05de\u05e4\u05ea\u05d9\u05e2\u05d4 \u05e8\u05d1\u05d9\u05dd: \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d3\u05dc\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05e0\u05e8\u05de\u05d5\u05dc \u05e0\u05d5\u05ea\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d8\u05d5\u05d1 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e8\u05d9\u05db\u05d5\u05da."], [273.0, "\u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da \u05e4\u05dc\u05d3\u05d4 \u05db\u05d6\u05d5 \u05e8\u05db\u05d4 \u05de\u05d3\u05d9, \u05d4\u05d9\u05d0 \u05e0\u05de\u05e8\u05d7\u05ea, \u05d5\u05e0\u05d5\u05e6\u05e8 \u05e7\u05e6\u05d4 \u05d1\u05e0\u05d5\u05d9 \u05e2\u05dc \u05d4\u05db\u05dc\u05d9. \u05d0\u05d7\u05e8\u05d9 \u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05d9\u05d0 \u05e7\u05e6\u05ea \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05e9\u05d1\u05d1 \u05e0\u05e9\u05d1\u05e8 \u05d1\u05e6\u05d5\u05e8\u05d4 \u05e0\u05e7\u05d9\u05d9\u05d4."], [283.9, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d4\u05d4\u05e4\u05da \u05e0\u05db\u05d5\u05df, \u05d5\u05e9\u05dd \u05e8\u05d9\u05db\u05d5\u05da \u05e0\u05d5\u05ea\u05df \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e0\u05d5\u05d7 \u05d9\u05d5\u05ea\u05e8."], [290.6, "\u05d1\u05ea\u05e7\u05e0\u05d9\u05dd \u05d4\u05d0\u05d9\u05e8\u05d5\u05e4\u05d9\u05d9\u05dd, \u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05e1\u05d5\u05de\u05df \u200e+N, \u05dc\u05de\u05e9\u05dc \u05d1\u05e4\u05dc\u05d3\u05ea \u05de\u05d1\u05e0\u05d9\u05dd \u200eS355J2+N."], [300.4, "\u05e4\u05d7 \u05db\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05d1\u05d5\u05e8 \u05e0\u05e8\u05de\u05d5\u05dc \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d0\u05d5 \u05d2\u05dc\u05d2\u05d5\u05dc \u05de\u05e0\u05e8\u05de\u05dc, \u05e9\u05d1\u05d5 \u05d4\u05d2\u05dc\u05d2\u05d5\u05dc \u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05e0\u05d5\u05ea\u05e0\u05ea \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d4\u05de\u05d1\u05e0\u05d4."], [308.9, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05de\u05e0\u05d5\u05e8\u05de\u05dc, \u05d5\u05d0\u05dd \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05e9\u05d5\u05d1\u05d5\u05ea, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d2\u05dd \u05d8\u05d5\u05d5\u05d7 \u05e7\u05e9\u05d9\u05d5\u05ea \u05d0\u05d5 \u05d7\u05d5\u05d6\u05e7."], [316.1, "\u05d5\u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d5\u05d0 \u05de\u05d7\u05d5\u05e9\u05dc, \u05db\u05d3\u05d0\u05d9 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05e0\u05e8\u05de\u05d5\u05dc \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05d1\u05e0\u05d4 \u05d9\u05d4\u05d9\u05d4 \u05d0\u05d7\u05d9\u05d3 \u05db\u05d1\u05e8 \u05de\u05d4\u05d4\u05ea\u05d7\u05dc\u05d4."], [323.7, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05db\u05e9\u05de\u05e2\u05e8\u05de\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05de\u05d5\u05d3 \u05d6\u05d4 \u05dc\u05d6\u05d4, \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d1\u05d0\u05de\u05e6\u05e2 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8, \u05d5\u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05de\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d1\u05d7\u05d5\u05e5."], [332.9, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05ea\u05db\u05d5\u05e4\u05e3 \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05dd \u05d7\u05de\u05d9\u05dd. \u05dc\u05db\u05df \u05ea\u05d5\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d0\u05e0\u05db\u05d9\u05ea, \u05d0\u05d5 \u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05e2\u05dc \u05ea\u05de\u05d9\u05db\u05d5\u05ea \u05e8\u05d1\u05d5\u05ea."], [341.9, "\u05d6\u05e8\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d7\u05d6\u05e7 \u05d0\u05d5 \u05e8\u05e6\u05e4\u05d4 \u05e7\u05e8\u05d4 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05e6\u05d3 \u05d0\u05d7\u05d3 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d6\u05d4 \u05d9\u05d5\u05e6\u05e8 \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [349.2, "\u05d2\u05dd \u05db\u05d0\u05df, \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e7\u05e9\u05e7\u05e9\u05ea, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05e4\u05d7\u05de\u05df."], [354.8, "\u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05e9\u05d5\u05db\u05d7\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05d4\u05df \u05d4\u05ea\u05e7\u05e9\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e4\u05e8\u05d9\u05da, \u05d0\u05d5 \u05d7\u05dc\u05e7 \u05e9\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e2\u05d1\u05d3."], [363.5, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e0\u05e8\u05de\u05d5\u05dc \u05d6\u05d5\u05dc \u05de\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0, \u05db\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05ea\u05e4\u05e0\u05d4 \u05de\u05d9\u05d3."], [368.8, "\u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05e0\u05e7\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05e9\u05e7\u05e9\u05ea, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d4\u05ea\u05d6\u05ea \u05d7\u05d5\u05dc \u05d0\u05d5 \u05db\u05d3\u05d5\u05e8\u05d9\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d9\u05d9\u05e9\u05e8 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05d4\u05ea\u05e2\u05e7\u05de\u05d5."], [376.7, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d9\u05e9 \u05e2\u05d5\u05d3 \u05de\u05d7\u05d6\u05d5\u05e8 \u05e9\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05ea\u05e0\u05d5\u05e8 \u05d2\u05d3\u05d5\u05dc \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05db\u05dc \u05d4\u05de\u05d1\u05e0\u05d4."], [384.7, "\u05d5\u05dc\u05db\u05df, \u05db\u05de\u05d5 \u05d1\u05e8\u05d9\u05db\u05d5\u05da, \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d4\u05db\u05d9 \u05d6\u05d5\u05dc \u05dc\u05e7\u05e0\u05d5\u05ea \u05d7\u05d5\u05de\u05e8 \u05e9\u05db\u05d1\u05e8 \u05de\u05e0\u05d5\u05e8\u05de\u05dc."], [391.5, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e0\u05e8\u05de\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e2\u05dc \u05d4\u05e7\u05d5 \u05d4\u05e2\u05dc\u05d9\u05d5\u05df \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e9\u05e7\u05d8."], [397.3, "\u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05e4\u05e8\u05dc\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df \u05d5\u05d2\u05e8\u05e2\u05d9\u05df \u05e7\u05d8\u05df \u05d5\u05d0\u05d7\u05d9\u05d3, \u05d5\u05e4\u05dc\u05d3\u05d4 \u05d7\u05d6\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05db\u05d5\u05da."], [403.9, "\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05d0\u05d7\u05e8\u05d9 \u05d7\u05d9\u05e9\u05d5\u05dc, \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05e8\u05d9\u05ea\u05d5\u05da, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05dc\u05e9\u05d1\u05d9\u05e8\u05ea \u05e8\u05e9\u05ea \u05e6\u05de\u05e0\u05d8\u05d9\u05d8. \u05d5\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d5\u05d1\u05e1\u05d5\u05d2 \u05d4\u05e4\u05dc\u05d3\u05d4."], [413.6, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d1\u05db\u05dc\u05dc, \u05d0\u05dc\u05d0 \u05e8\u05e7 \u05de\u05e9\u05d7\u05e8\u05e8 \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd: \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."]]};
window.MH_TR["ch06"]={"t": "\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd", "l": [[5.0, "\u05de\u05db\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4: \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d7\u05dc\u05e7, \u05d4\u05d5\u05d0 \u05d9\u05d5\u05e6\u05d0 \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05d0\u05d7\u05e8\u05d9 \u05e9\u05e9\u05d7\u05e8\u05e8\u05d5 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05de\u05dc\u05d7\u05e6\u05d9\u05d9\u05dd, \u05d0\u05d5 \u05d9\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9, \u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05e2\u05e7\u05d5\u05dd."], [13.4, "\u05d4\u05d0\u05e9\u05de\u05d9\u05dd \u05d4\u05dd \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd, \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05db\u05dc\u05d5\u05d0\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8."], [19.1, "\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e9\u05de\u05d8\u05e8\u05ea\u05d5 \u05d0\u05d7\u05ea: \u05dc\u05d4\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4."], [27.6, "\u05de\u05d0\u05de\u05e5 \u05e9\u05d9\u05d5\u05e8\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d0\u05de\u05e5 \u05e9\u05e7\u05d9\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7 \u05d2\u05dd \u05db\u05e9\u05d0\u05e3 \u05db\u05d5\u05d7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9 \u05dc\u05d0 \u05e4\u05d5\u05e2\u05dc \u05e2\u05dc\u05d9\u05d5."], [33.4, "\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05d0\u05d5\u05d6\u05e0\u05d9\u05dd: \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d0\u05d7\u05d3 \u05d9\u05e9 \u05de\u05ea\u05d9\u05d7\u05d4, \u05d5\u05d1\u05d0\u05d6\u05d5\u05e8 \u05d0\u05d7\u05e8 \u05d9\u05e9 \u05dc\u05d7\u05d9\u05e6\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05e9\u05d9\u05d5\u05d5\u05d9 \u05de\u05e9\u05e7\u05dc."], [42.0, "\u05d6\u05d4 \u05d3\u05d5\u05de\u05d4 \u05dc\u05e7\u05e4\u05d9\u05e5 \u05d3\u05e8\u05d5\u05da \u05e9\u05e0\u05ea\u05e4\u05e1 \u05d1\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8. \u05db\u05dc \u05e2\u05d5\u05d3 \u05dc\u05d0 \u05e0\u05d5\u05d2\u05e2\u05d9\u05dd, \u05d4\u05db\u05d5\u05dc \u05d9\u05e6\u05d9\u05d1."], [48.1, "\u05d0\u05d1\u05dc \u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8, \u05dc\u05de\u05e9\u05dc \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9, \u05d4\u05d0\u05d9\u05d6\u05d5\u05df \u05e0\u05e9\u05d1\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05db\u05d3\u05d9 \u05dc\u05de\u05e6\u05d5\u05d0 \u05d0\u05d9\u05d6\u05d5\u05df \u05d7\u05d3\u05e9."], [56.0, "\u05d5\u05de\u05d0\u05de\u05e5 \u05e9\u05d9\u05d5\u05e8\u05d9 \u05d1\u05de\u05ea\u05d9\u05d7\u05d4 \u05d2\u05dd \u05de\u05e6\u05d8\u05e8\u05e3 \u05dc\u05e2\u05d5\u05de\u05e1 \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d6\u05d4 \u05de\u05e7\u05e6\u05e8 \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d5\u05de\u05d2\u05d1\u05d9\u05e8 \u05e1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [64.4, "\u05de\u05d0\u05d9\u05e4\u05d4 \u05d4\u05dd \u05d1\u05d0\u05d9\u05dd? \u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e2\u05e6\u05de\u05d5."], [68.6, "\u05d1\u05d7\u05d9\u05ea\u05d5\u05da \u05db\u05d1\u05d3, \u05d4\u05db\u05dc\u05d9 \u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e2\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [75.3, "\u05d2\u05dd \u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd \u05de\u05d2\u05d9\u05e2 \u05e2\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd: \u05de\u05d5\u05d8\u05d5\u05ea \u05e9\u05e0\u05de\u05e9\u05db\u05d5 \u05d1\u05e7\u05d5\u05e8 \u05d0\u05d5 \u05d9\u05d5\u05e9\u05e8\u05d5 \u05d1\u05de\u05e4\u05e2\u05dc, \u05d5\u05dc\u05d5\u05d7\u05d5\u05ea \u05e9\u05e0\u05d7\u05ea\u05db\u05d5."], [82.9, "\u05d5\u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d7\u05d5\u05de\u05e8 \u05de\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05dc\u05de\u05e9\u05dc \u05db\u05d9\u05e1 \u05e2\u05de\u05d5\u05e7 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05dc\u05d5\u05d7, \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05e9\u05e0\u05d9."], [91.4, "\u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05e9\u05e0\u05d9, \u05d5\u05d4\u05d7\u05d6\u05e7 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d4\u05d5\u05d0 \u05e8\u05d9\u05ea\u05d5\u05da."], [95.2, "\u05d4\u05ea\u05e4\u05e8 \u05de\u05ea\u05de\u05e6\u05e7 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05d5\u05d0 \u05de\u05ea\u05db\u05d5\u05d5\u05e5. \u05d0\u05d1\u05dc \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05e7\u05e8\u05d4 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1 \u05de\u05d5\u05e0\u05e2\u05ea \u05de\u05de\u05e0\u05d5 \u05dc\u05d4\u05ea\u05db\u05d5\u05d5\u05e5."], [104.1, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05ea\u05e4\u05e8 \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d3 \u05dc\u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8, \u05d5\u05e8\u05d7\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8 \u05d9\u05e9 \u05dc\u05d7\u05d9\u05e6\u05d4."], [114.1, "\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05dc \u05d4\u05de\u05d1\u05e0\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05d4\u05dd \u05de\u05d2\u05d3\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da \u05d5\u05dc\u05e1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [122.4, "\u05dc\u05db\u05df \u05d1\u05e6\u05e0\u05e8\u05ea \u05d5\u05d1\u05db\u05dc\u05d9 \u05dc\u05d7\u05e5, \u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da."], [129.5, "\u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05e2\u05d9\u05e6\u05d5\u05d1 \u05d1\u05e7\u05d5\u05e8."], [133.1, "\u05db\u05e9\u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05d2\u05dc \u05e2\u05e7\u05d5\u05dd \u05d1\u05dc\u05d7\u05d9\u05e6\u05d4, \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d1\u05d5 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05e4\u05d5\u05db\u05d9\u05dd. \u05d4\u05d5\u05d0 \u05d9\u05e9\u05e8, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05db\u05dc \u05e2\u05d5\u05d3 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05dc\u05d0 \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd."], [142.1, "\u05d0\u05dd \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d0\u05d5 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05de\u05de\u05e0\u05d5 \u05d7\u05d5\u05de\u05e8, \u05d4\u05d5\u05d0 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d7\u05d6\u05d5\u05e8 \u05dc\u05e2\u05e7\u05de\u05d5\u05de\u05d9\u05d5\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea."], [148.4, "\u05d5\u05d2\u05dd \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e2\u05e6\u05de\u05d4 \u05d9\u05d5\u05e6\u05e8\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05d5\u05e2\u05dc\u05d9\u05d4 \u05e0\u05d3\u05d1\u05e8 \u05d1\u05e4\u05e8\u05e7\u05d9\u05dd \u05d4\u05d1\u05d0\u05d9\u05dd."], [155.0, "\u05d0\u05d9\u05da \u05d7\u05d5\u05dd \u05de\u05e9\u05d7\u05e8\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd? \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4, \u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc\u05d4 \u05d9\u05d5\u05e8\u05d3."], [160.9, "\u05db\u05dc \u05de\u05d0\u05de\u05e5 \u05e9\u05d2\u05d1\u05d5\u05d4 \u05de\u05d7\u05d5\u05d6\u05e7 \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d6\u05e8\u05d9\u05de\u05d4 \u05de\u05e7\u05d5\u05de\u05d9\u05ea \u05e7\u05d8\u05e0\u05d4, \u05d5\u05d4\u05d7\u05d5\u05de\u05e8 \u05e0\u05e8\u05d2\u05e2."], [168.2, "\u05d5\u05d1\u05d4\u05d7\u05d6\u05e7\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d4\u05d7\u05d5\u05de\u05e8 \u05d2\u05dd \u05d6\u05d5\u05d7\u05dc \u05dc\u05d0\u05d8, \u05d5\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05dc\u05e8\u05d3\u05ea."], [174.7, "\u05de\u05ea\u05d7\u05ea \u05dc\u05d1\u05e2\u05e8\u05da 260 \u05de\u05e2\u05dc\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e7\u05d5\u05e8\u05d4 \u05db\u05dc\u05d5\u05dd. \u05d1-540 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05e2\u05e8\u05da 90% \u05de\u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05db\u05d1\u05e8 \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd."], [184.8, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4, \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d5\u05d1\u05d0\u05d7\u05d9\u05d3\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05e6\u05de\u05d5 \u05dc\u05d0 \u05d9\u05d9\u05e6\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd."], [192.2, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05de\u05d5\u05db\u05d4, \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e0\u05e2\u05e9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1-550 \u05e2\u05d3 650 \u05de\u05e2\u05dc\u05d5\u05ea."], [201.6, "\u05d6\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05d5\u05dc\u05db\u05df \u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d4 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4."], [208.4, "\u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9."], [213.7, "\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d0\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e9\u05e7\u05d8, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05dc\u05d0\u05d8 \u05d5\u05d1\u05e7\u05e6\u05d1 \u05de\u05d1\u05d5\u05e7\u05e8."], [220.7, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05de\u05e8\u05d5\u05db\u05db\u05ea \u05d0\u05d5 \u05de\u05e0\u05d5\u05e8\u05de\u05dc\u05ea, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05ea\u05e0\u05d4. \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05e0\u05e9\u05d0\u05e8\u05d5\u05ea, \u05e8\u05e7 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d9\u05d5\u05e8\u05d3\u05d9\u05dd."], [229.0, "\u05d5\u05de\u05d4 \u05e2\u05dd \u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05d5\u05de\u05d5\u05e8\u05e4\u05d4? \u05db\u05d0\u05df \u05d9\u05e9 \u05db\u05dc\u05dc \u05d7\u05e9\u05d5\u05d1."], [233.7, "\u05e9\u05d7\u05e8\u05d5\u05e8 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d1\u05e2\u05e8\u05da 30 \u05e2\u05d3 50 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d0\u05d7\u05e8\u05d5\u05e0\u05d4."], [242.0, "\u05d0\u05d7\u05e8\u05ea \u05d6\u05d5 \u05d1\u05e2\u05e6\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e8\u05d3\u05ea."], [247.5, "\u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05d7\u05dc\u05e7 \u05e9\u05d4\u05d5\u05e8\u05e4\u05d4 \u05d1-600 \u05de\u05e2\u05dc\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05d1-550 \u05d1\u05e2\u05e8\u05da. \u05d0\u05d1\u05dc \u05d7\u05dc\u05e7 \u05e9\u05d4\u05d5\u05e8\u05e4\u05d4 \u05d1-200 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e9\u05d7\u05e8\u05e8 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05d0\u05d1\u05d3 \u05e7\u05e9\u05d9\u05d5\u05ea."], [261.1, "\u05d1\u05e8\u05d9\u05ea\u05d5\u05da \u05e9\u05dc \u05e6\u05e0\u05e8\u05ea \u05d5\u05db\u05dc\u05d9 \u05dc\u05d7\u05e5, \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e0\u05e7\u05e8\u05d0 PWHT, \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05d4\u05ea\u05e7\u05e0\u05d9\u05dd \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d3\u05d9\u05d5\u05e7."], [270.6, "\u05dc\u05e4\u05d9 ASME, \u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e8\u05d2\u05d9\u05dc\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d1-595 \u05e2\u05d3 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [280.9, "\u05d1\u05e6\u05e0\u05e8\u05ea \u05dc\u05e4\u05d9 B31.3, \u05d6\u05d4 \u05d7\u05d5\u05d1\u05d4 \u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05db\u05e9\u05d4\u05d3\u05d5\u05e4\u05df \u05e2\u05d1\u05d4 \u05de-19 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [289.2, "\u05d4\u05ea\u05e7\u05df \u05de\u05d2\u05d1\u05d9\u05dc \u05d2\u05dd \u05d0\u05ea \u05e7\u05e6\u05d1 \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05e2\u05dc 425 \u05de\u05e2\u05dc\u05d5\u05ea: \u05db\u05db\u05dc \u05e9\u05d4\u05d3\u05d5\u05e4\u05df \u05e2\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e6\u05e8\u05d9\u05da \u05dc\u05d7\u05de\u05dd \u05d5\u05dc\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8."], [299.7, "\u05d5\u05db\u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05db\u05e0\u05d9\u05e1 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05dc\u05ea\u05e0\u05d5\u05e8, \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05ea\u05e4\u05e8, \u05e2\u05dd \u05e9\u05de\u05d9\u05db\u05d5\u05ea \u05d7\u05d9\u05de\u05d5\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d5\u05ea \u05d5\u05e6\u05de\u05d3\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd \u05e9\u05de\u05ea\u05e2\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d7\u05d6\u05d5\u05e8."], [309.9, "\u05d4\u05e1\u05d3\u05e8 \u05d4\u05e0\u05db\u05d5\u05df \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3: \u05e7\u05d5\u05d3\u05dd \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05e1, \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8, \u05d0\u05d7\u05e8 \u05db\u05da \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d1\u05e1\u05d5\u05e3 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8."], [319.0, "\u05db\u05da \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05d5\u05dc\u05de\u05d9 \u05d5\u05de\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05e1 \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05db\u05d1\u05e8 \u05d1\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."], [326.9, "\u05d2\u05dd \u05d1\u05de\u05d1\u05e0\u05d4 \u05de\u05e8\u05d5\u05ea\u05da \u05e9\u05e6\u05e8\u05d9\u05da \u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d3\u05d5\u05d9\u05e7: \u05de\u05e8\u05ea\u05db\u05d9\u05dd, \u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e2\u05d1\u05d3\u05d9\u05dd."], [335.0, "\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d3\u05d0\u05d9 \u05dc\u05db\u05ea\u05d5\u05d1 \u05d0\u05ea \u05d6\u05d4 \u05d1\u05de\u05e4\u05d5\u05e8\u05e9, \u05dc\u05de\u05e9\u05dc: \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8, \u05e2\u05dd \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05d4\u05d6\u05de\u05df."], [343.5, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05d7\u05d9\u05de\u05d5\u05dd \u05d0\u05d5 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8\u05d9\u05dd \u05de\u05d3\u05d9 \u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05d2\u05dd \u05e2\u05d9\u05d5\u05d5\u05ea."], [351.3, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05dc\u05e9\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05e9\u05dc\u05d0 \u05e0\u05ea\u05de\u05da \u05d8\u05d5\u05d1 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05ea\u05db\u05d5\u05e4\u05e3 \u05de\u05d4\u05de\u05e9\u05e7\u05dc \u05e9\u05dc \u05e2\u05e6\u05de\u05d5."], [359.4, "\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05d1\u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5."], [365.1, "\u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e7\u05e9\u05e7\u05e9\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05de\u05d5\u05d2\u05de\u05e8\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05d4\u05d2\u05e0\u05d4 \u05d0\u05d5 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4."], [372.1, "\u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea \u05d6\u05d4 \u05e1\u05d9\u05e4\u05d5\u05e8 \u05d0\u05d7\u05e8 \u05dc\u05d2\u05de\u05e8\u05d9, \u05e2\u05dd \u05e1\u05db\u05e0\u05d5\u05ea \u05de\u05e9\u05dc\u05d5, \u05d5\u05e2\u05dc\u05d9\u05d4\u05df \u05e0\u05d3\u05d1\u05e8 \u05d1\u05e4\u05e8\u05e7 \u05e0\u05e4\u05e8\u05d3."], [380.4, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d6\u05de\u05df \u05d4\u05ea\u05e0\u05d5\u05e8, \u05db\u05d5\u05dc\u05dc \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd, \u05e9\u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e7\u05d7\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df \u05de\u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05e2\u05e6\u05de\u05d4."], [389.3, "\u05de\u05d1\u05e0\u05d4 \u05de\u05e8\u05d5\u05ea\u05da \u05d2\u05d3\u05d5\u05dc \u05e6\u05e8\u05d9\u05da \u05ea\u05e0\u05d5\u05e8 \u05d2\u05d3\u05d5\u05dc, \u05d0\u05d5 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e7\u05d5\u05de\u05d9 \u05e2\u05dd \u05e6\u05d9\u05d5\u05d3, \u05e6\u05de\u05d3\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd \u05d5\u05ea\u05d9\u05e2\u05d5\u05d3."], [396.6, "\u05d5\u05d2\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05e9\u05dc\u05d1 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e0\u05d5\u05e1\u05e3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e2\u05d5\u05dc\u05d9\u05dd \u05db\u05e1\u05e3."], [402.0, "\u05d0\u05d1\u05dc \u05d6\u05d4 \u05e2\u05d3\u05d9\u05d9\u05df \u05d6\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d7\u05dc\u05e7 \u05de\u05d3\u05d5\u05d9\u05e7 \u05e9\u05d4\u05ea\u05e2\u05e7\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05de\u05e8, \u05d0\u05d5 \u05de\u05de\u05d1\u05e0\u05d4 \u05de\u05e8\u05d5\u05ea\u05da \u05e9\u05e0\u05e1\u05d3\u05e7 \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea."], [410.3, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd \u05d1\u05d0\u05d9\u05dd \u05de\u05e2\u05d9\u05d1\u05d5\u05d3, \u05de\u05e8\u05d9\u05ea\u05d5\u05da, \u05de\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05de\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05d4\u05dd \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05dc\u05db\u05e9\u05dc\u05d9\u05dd."], [419.2, "\u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d4\u05d5\u05d0 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05ea\u05d7\u05ea \u05dc-A1, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 550 \u05e2\u05d3 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9, \u05d1\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05d1\u05e0\u05d4."], [430.2, "\u05d1\u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4, \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05d1\u05e2\u05d9\u05d1\u05d5\u05d3, \u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d9\u05df \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05e1 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05de\u05e8."], [438.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d2\u05d9\u05e2 \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d0\u05d7\u05e8: \u05d4\u05e7\u05e9\u05d9\u05d4."]]};
window.MH_TR["ch07"]={"t": "\u05d4\u05e7\u05e9\u05d9\u05d4: \u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8", "l": [[5.0, "\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d0\u05d7\u05e8. \u05d4\u05d9\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05e4\u05d5\u05da \u05e4\u05dc\u05d3\u05d4 \u05e8\u05db\u05d4 \u05dc\u05d7\u05d5\u05de\u05e8 \u05e7\u05e9\u05d4 \u05db\u05de\u05e2\u05d8 \u05e4\u05d9 \u05e9\u05dc\u05d5\u05e9\u05d4."], [14.0, "\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05e0\u05d5\u05d9\u05d4 \u05de\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd: \u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d4\u05d9\u05e8, \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."], [20.1, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05ea\u05de\u05e7\u05d3 \u05d1\u05e9\u05dc\u05d1 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df: \u05dc\u05d0\u05d9\u05d6\u05d5 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05d7\u05de\u05de\u05d9\u05dd, \u05d5\u05db\u05de\u05d4 \u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd. \u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05e0\u05e2\u05e1\u05d5\u05e7 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0, \u05d5\u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e9\u05d0\u05d7\u05e8\u05d9\u05d5."], [32.1, "\u05dc\u05de\u05d4 \u05e6\u05e8\u05d9\u05da \u05d3\u05d5\u05d5\u05e7\u05d0 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8? \u05db\u05d9 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05e8\u05e7 \u05de\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [37.1, "\u05db\u05dc \u05e4\u05e8\u05d9\u05d8 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d1\u05e8\u05d2\u05e2 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05e0\u05e9\u05d0\u05e8 \u05e4\u05e8\u05d9\u05d8 \u05e8\u05da \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [42.8, "\u05d5\u05d1\u05e0\u05d5\u05e1\u05e3, \u05d4\u05e4\u05d7\u05de\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8. \u05e8\u05e7 \u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05d4\u05ea\u05de\u05d5\u05e1\u05e1 \u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d5\u05e0\u05d5\u05ea\u05df \u05dc\u05d5 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea."], [51.2, "\u05dc\u05db\u05df \u05d4\u05de\u05d8\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d4\u05d9\u05d0 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d0\u05d7\u05d9\u05d3, \u05e2\u05dd \u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05d4\u05e0\u05db\u05d5\u05e0\u05d4, \u05d1\u05db\u05dc \u05e0\u05e4\u05d7 \u05d4\u05d7\u05dc\u05e7."], [58.6, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de-0.8% \u05e4\u05d7\u05de\u05df, \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 30 \u05e2\u05d3 50 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e2\u05dc Ac3."], [67.5, "\u05db\u05da \u05db\u05dc \u05d4\u05e4\u05e8\u05d9\u05d8 \u05d4\u05d5\u05e4\u05da \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05e2\u05d5\u05dc\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d4\u05e0\u05d3\u05e8\u05e9."], [72.4, "\u05d1\u05e4\u05dc\u05d3\u05ea 4140, \u05dc\u05de\u05e9\u05dc, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05e2\u05e8\u05da 830 \u05e2\u05d3 870 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d0\u05d7\u05e8\u05d9\u05d4 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df."], [83.2, "\u05d5\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d0\u05dd \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d3\u05d9, \u05d1\u05d9\u05df Ac1 \u05dc-Ac3? \u05d7\u05dc\u05e7 \u05de\u05d4\u05e4\u05e8\u05d9\u05d8 \u05dc\u05d0 \u05d4\u05d5\u05e4\u05da \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [91.3, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e2\u05dd \u05d0\u05d9\u05d9\u05dd \u05e9\u05dc \u05e4\u05e8\u05d9\u05d8 \u05e8\u05da, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d4\u05e6\u05e4\u05d5\u05d9."], [98.3, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de-0.8% \u05e4\u05d7\u05de\u05df, \u05d4\u05d7\u05d5\u05e7 \u05e9\u05d5\u05e0\u05d4: \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e8\u05e7 \u05dc\u05d1\u05e2\u05e8\u05da 30 \u05e2\u05d3 50 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05e2\u05dc Ac1, \u05d5\u05dc\u05d0 \u05de\u05e2\u05dc Acm."], [109.8, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e6\u05de\u05e0\u05d8\u05d9\u05d8 \u05e0\u05e9\u05d0\u05e8 \u05dc\u05d0 \u05de\u05d5\u05de\u05e1, \u05db\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [116.4, "\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05e8\u05d5\u05e6\u05d9\u05dd: \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d4\u05e7\u05e9\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."], [122.0, "\u05d5\u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e2\u05e6\u05de\u05d5 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05e2\u05e8\u05da \u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05e0\u05d3\u05e8\u05e9 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e7\u05e9\u05d4, \u05d1\u05dc\u05d9 \u05e2\u05d5\u05d3\u05e3."], [127.9, "\u05d0\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e2\u05dc Acm, \u05db\u05dc \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05de\u05d5\u05e1\u05e1, \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05d2\u05d3\u05dc, \u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e0\u05e9\u05d0\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05dc\u05d0 \u05d4\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05db\u05da \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e4\u05d7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05d9\u05d5\u05ea\u05e8 \u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [142.1, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05e1\u05d5\u05d2\u05e1\u05d2\u05d5\u05ea, \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e9\u05dc \u05d4\u05db\u05e8\u05d5\u05dd, \u05d4\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05d4\u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd \u05e8\u05e7 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."], [150.7, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05de\u05d5 D2 \u05d5-H13 \u05de\u05d5\u05e7\u05e9\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,000 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d0\u05e4\u05d9\u05dc\u05d5 \u05e7\u05e8\u05d5\u05d1 \u05dc-1,200."], [159.8, "\u05db\u05d0\u05df \u05ea\u05de\u05d9\u05d3 \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc \u05d9\u05e6\u05e8\u05df \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05d6\u05d4 \u05d1\u05e4\u05e8\u05e7 \u05e2\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd."], [166.8, "\u05d5\u05de\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9? \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05e9\u05dc \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d2\u05d3\u05dc."], [171.8, "\u05de\u05d2\u05e8\u05e2\u05d9\u05df \u05d2\u05e1 \u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d2\u05e1 \u05d5\u05e4\u05e8\u05d9\u05da, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05de\u05db\u05d5\u05ea."], [177.2, "\u05d4\u05e4\u05e8\u05e9\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05d2\u05d3\u05dc\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [183.0, "\u05d5\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d2\u05dd \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d5\u05de\u05ea\u05db\u05e1\u05d9\u05dd \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e7\u05e9\u05e7\u05e9\u05ea."], [190.1, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05d6\u05de\u05df. \u05d4\u05d6\u05de\u05df \u05d1\u05ea\u05e0\u05d5\u05e8 \u05de\u05d5\u05e8\u05db\u05d1 \u05de\u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd: \u05d4\u05d6\u05de\u05df \u05e2\u05d3 \u05e9\u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05d2\u05d9\u05e2 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05e2\u05e6\u05de\u05d5."], [200.0, "\u05d4\u05d7\u05d5\u05dd \u05e0\u05db\u05e0\u05e1 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05e0\u05d9\u05de\u05d4, \u05d5\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4, \u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [207.9, "\u05d4\u05ea\u05e0\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2 \u05d4\u05e8\u05d1\u05d4: \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d4\u05d7\u05d5\u05dd \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d7\u05dc\u05e7 \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d5 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d0\u05d8."], [216.9, "\u05d2\u05dd \u05d4\u05e2\u05d5\u05de\u05e1 \u05de\u05e9\u05e0\u05d4: \u05ea\u05e0\u05d5\u05e8 \u05de\u05dc\u05d0 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd \u05de\u05ea\u05d7\u05de\u05dd \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05dc\u05e7 \u05d1\u05d5\u05d3\u05d3."], [223.3, "\u05dc\u05db\u05df \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5, \u05d0\u05d5 \u05d1\u05d7\u05dc\u05e7 \u05dc\u05d3\u05d5\u05d2\u05de\u05d4 \u05e2\u05dd \u05e6\u05de\u05d3 \u05ea\u05e8\u05de\u05d9, \u05d5\u05dc\u05d0 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8."], [232.1, "\u05db\u05de\u05d4 \u05d6\u05de\u05df \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd? \u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2 \u05d0\u05d7\u05d3 \u05dc\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05e2\u05e8\u05da 1.2 \u05d3\u05e7\u05d5\u05ea \u05dc\u05db\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9, \u05d5\u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d1\u05e2\u05e8\u05da \u05d7\u05e6\u05d9 \u05de\u05d6\u05d4."], [243.0, "\u05db\u05dc\u05dc \u05e9\u05de\u05e8\u05e0\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05e9\u05de\u05d5\u05e4\u05d9\u05e2 \u05d1\u05d4\u05e8\u05d1\u05d4 \u05ea\u05e7\u05e0\u05d9\u05dd \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d4\u05d5\u05d0 \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9."], [250.8, "\u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e9\u05dc\u05d0 \u05d4\u05ea\u05de\u05d5\u05e1\u05e1\u05d5, \u05d5\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc\u05d0 \u05d4\u05e4\u05db\u05d5 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d4."], [258.6, "\u05d6\u05de\u05df \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9 \u05de\u05d2\u05d3\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05df \u05d5\u05de\u05d0\u05d1\u05d3 \u05e4\u05d7\u05de\u05df \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [263.5, "\u05dc\u05db\u05df \u05db\u05dc\u05dc\u05d9 \u05d4\u05d0\u05e6\u05d1\u05e2 \u05d4\u05dd \u05e8\u05e7 \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05ea\u05d7\u05dc\u05d4, \u05d5\u05d4\u05de\u05e4\u05e8\u05d8 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df \u05d0\u05d5 \u05e9\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7 \u05e7\u05d5\u05d1\u05e2."], [270.6, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05dc\u05d0 \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d4\u05e7\u05e8 \u05d9\u05e9\u05e8 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [277.6, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05dc\u05e9\u05dc\u05d1 \u05d1\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d1\u05e2\u05e8\u05da 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05d7\u05db\u05d9\u05dd \u05e9\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05ea\u05ea\u05d0\u05d6\u05df \u05d1\u05db\u05dc \u05d4\u05d7\u05dc\u05e7."], [285.6, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05dc\u05d1 \u05e9\u05e0\u05d9, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 850 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4."], [293.8, "\u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d4\u05de\u05d5\u05e7\u05d3\u05dd \u05de\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e4\u05e8\u05e9\u05d9 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d9\u05df \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05dc\u05e2\u05d1\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [302.8, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e8\u05d2\u05d9\u05dc, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05de\u05d4\u05e8."], [308.6, "\u05e9\u05db\u05d1\u05d4 \u05e9\u05d0\u05d9\u05d1\u05d3\u05d4 \u05e4\u05d7\u05de\u05df \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4, \u05d5\u05e0\u05e9\u05d0\u05e8\u05ea \u05e8\u05db\u05d4 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d5\u05e9\u05dc\u05dd."], [314.1, "\u05dc\u05db\u05df \u05de\u05e7\u05e9\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4, \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d5\u05d8\u05e4\u05d9\u05dd \u05d1\u05e8\u05d3\u05d9\u05d3 \u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3."], [323.7, "\u05d5\u05d0\u05dd \u05d0\u05d9\u05df \u05d1\u05e8\u05d9\u05e8\u05d4, \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8, \u05d5\u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [330.1, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05db\u05ea\u05de\u05d9\u05dd \u05e8\u05db\u05d9\u05dd: \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d3\u05d9, \u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05d2\u05e2\u05d5 \u05d6\u05d4 \u05d1\u05d6\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d4\u05e1\u05ea\u05d9\u05e8\u05d5 \u05d6\u05d4 \u05d0\u05ea \u05d6\u05d4."], [340.0, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d0\u05d5 \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9: \u05d2\u05e8\u05e2\u05d9\u05df \u05d2\u05e1, \u05e9\u05d1\u05d9\u05e8\u05d5\u05ea, \u05d5\u05d9\u05d5\u05ea\u05e8 \u05e1\u05d3\u05e7\u05d9\u05dd \u05d1\u05db\u05d9\u05d1\u05d5\u05d9."], [346.8, "\u05e7\u05dc\u05d9\u05e4\u05d4 \u05e8\u05db\u05d4: \u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e9\u05de\u05ea\u05d2\u05dc\u05d4 \u05e8\u05e7 \u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d0\u05d5 \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d7\u05e7 \u05de\u05d4\u05e8 \u05d1\u05e9\u05d9\u05e8\u05d5\u05ea."], [355.1, "\u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e2\u05dd \u05d7\u05ea\u05db\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05d5\u05d3\u05e7\u05d9\u05dd, \u05e9\u05de\u05d5\u05d1\u05d9\u05dc \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea."], [360.1, "\u05d5\u05d1\u05dc\u05d1\u05d5\u05dc \u05d1\u05d7\u05d5\u05de\u05e8: \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e9\u05d5\u05d9 \u05de\u05e4\u05dc\u05d3\u05d4 \u05d0\u05d7\u05e8\u05ea \u05de\u05d6\u05d5 \u05e9\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05dc\u05d0 \u05ea\u05ea\u05d0\u05d9\u05dd, \u05d5\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05e0\u05db\u05d5\u05e0\u05d4."], [369.3, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e1\u05d5\u05d2 \u05d4\u05ea\u05e0\u05d5\u05e8: \u05d5\u05d0\u05e7\u05d5\u05dd \u05d5\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4 \u05d9\u05e7\u05e8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8."], [376.2, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05de\u05d7\u05d6\u05d5\u05e8 \u05d0\u05e8\u05d5\u05da, \u05d5\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d5\u05e7\u05d3\u05dd \u05de\u05d5\u05e1\u05d9\u05e3 \u05e2\u05d5\u05d3 \u05e9\u05dc\u05d1\u05d9\u05dd."], [381.5, "\u05e1\u05d9\u05d3\u05d5\u05e8 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8, \u05de\u05ea\u05e7\u05e0\u05d9\u05dd \u05dc\u05ea\u05dc\u05d9\u05d4 \u05d5\u05dc\u05ea\u05de\u05d9\u05db\u05d4, \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05db\u05d5\u05dc\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d7\u05d9\u05e8."], [388.8, "\u05d5\u05db\u05e9\u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05dc\u05e7\u05d1\u05dc\u05df, \u05d9\u05e9 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d7\u05d9\u05e8 \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d8\u05e2\u05d9\u05e0\u05d4, \u05d5\u05dc\u05db\u05df \u05db\u05d3\u05d0\u05d9 \u05dc\u05e8\u05db\u05d6 \u05d7\u05dc\u05e7\u05d9\u05dd."], [396.4, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05db\u05d3\u05d9 \u05e9\u05db\u05dc \u05d4\u05e0\u05e4\u05d7 \u05d9\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d1\u05db\u05d9\u05d1\u05d5\u05d9."], [403.6, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05de-0.8% \u05e4\u05d7\u05de\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e2\u05dc Ac3, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05e2\u05d8 \u05de\u05e2\u05dc Ac1. \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05d4\u05d9\u05e6\u05e8\u05df."], [415.2, "\u05d4\u05d6\u05de\u05df \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d5\u05d1\u05e1\u05d5\u05d2 \u05d4\u05ea\u05e0\u05d5\u05e8: \u05de\u05e1\u05e4\u05d9\u05e7 \u05db\u05d3\u05d9 \u05e9\u05d4\u05db\u05d5\u05dc \u05d9\u05d4\u05e4\u05d5\u05da \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05dc\u05d0 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d6\u05d4."], [422.1, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d2\u05d9\u05e2 \u05dc\u05e8\u05d2\u05e2 \u05d4\u05e7\u05e8\u05d9\u05d8\u05d9 \u05e9\u05dc \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4: \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."]]};
window.MH_TR["ch08"]={"t": "\u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05d7\u05d9\u05de\u05de\u05e0\u05d5 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8. \u05e2\u05db\u05e9\u05d9\u05d5 \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05e8\u05e8 \u05d0\u05d5\u05ea\u05d5 \u05de\u05d4\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d9\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [14.1, "\u05d0\u05d1\u05dc \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9 \u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e1\u05d5\u05d3\u05e7 \u05d0\u05d5\u05ea\u05d5."], [18.9, "\u05dc\u05db\u05df \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05d9\u05d0 \u05ea\u05de\u05d9\u05d3 \u05d0\u05d9\u05d6\u05d5\u05df: \u05de\u05e1\u05e4\u05d9\u05e7 \u05de\u05d4\u05e8 \u05db\u05d3\u05d9 \u05dc\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea, \u05d5\u05dc\u05d0 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d6\u05d4."], [27.1, "\u05db\u05e9\u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05d7\u05dc\u05e7 \u05d7\u05dd \u05d1\u05e0\u05d5\u05d6\u05dc, \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05d1\u05d6\u05de\u05df. \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd."], [33.3, "\u05d1\u05e9\u05dc\u05d1 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05e0\u05d5\u05e6\u05e8\u05ea \u05e1\u05d1\u05d9\u05d1 \u05d4\u05d7\u05dc\u05e7 \u05e9\u05db\u05d1\u05d4 \u05e9\u05dc \u05d0\u05d3\u05d9\u05dd. \u05d4\u05d0\u05d3\u05d9\u05dd \u05de\u05d1\u05d5\u05d3\u05d3\u05d9\u05dd, \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d7\u05e1\u05d9\u05ea."], [40.9, "\u05db\u05e9\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05e1\u05e4\u05d9\u05e7, \u05e9\u05db\u05d1\u05ea \u05d4\u05d0\u05d3\u05d9\u05dd \u05e7\u05d5\u05e8\u05e1\u05ea, \u05d5\u05d4\u05e0\u05d5\u05d6\u05dc \u05e0\u05d5\u05d2\u05e2 \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05d1\u05d7\u05dc\u05e7 \u05d5\u05e8\u05d5\u05ea\u05d7 \u05e2\u05dc\u05d9\u05d5."], [48.5, "\u05d6\u05d4 \u05d4\u05e9\u05dc\u05d1 \u05d4\u05e9\u05e0\u05d9, \u05e9\u05dc\u05d1 \u05d4\u05e8\u05ea\u05d9\u05d7\u05d4, \u05d5\u05d4\u05d5\u05d0 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8."], [53.1, "\u05db\u05e9\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d9\u05d5\u05e8\u05d3\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05e8\u05ea\u05d9\u05d7\u05d4 \u05e9\u05dc \u05d4\u05e0\u05d5\u05d6\u05dc, \u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05e9\u05dc\u05d1 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9: \u05d4\u05e1\u05e2\u05d4, \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05d5\u05d1 \u05d0\u05d9\u05d8\u05d9."], [61.6, "\u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d8\u05d5\u05d1 \u05e0\u05d5\u05ea\u05df \u05e9\u05dc\u05d1 \u05d0\u05d3\u05d9\u05dd \u05e7\u05e6\u05e8, \u05e8\u05ea\u05d9\u05d7\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d5\u05ea, \u05d5\u05d4\u05e1\u05e2\u05d4 \u05d0\u05d9\u05d8\u05d9\u05ea \u05d1\u05d0\u05d6\u05d5\u05e8 \u05e9\u05d1\u05d5 \u05e0\u05d5\u05e6\u05e8 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05db\u05d3\u05d9 \u05dc\u05d4\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [73.7, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05e9\u05d5\u05d5\u05ea \u05d1\u05d9\u05df \u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05e1\u05e4\u05e8 \u05e9\u05e0\u05e7\u05e8\u05d0 \u05d7\u05d5\u05de\u05e8\u05ea \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d0\u05d5 \u05de\u05e1\u05e4\u05e8 H \u05e9\u05dc \u05d2\u05e8\u05d5\u05e1\u05de\u05df."], [82.1, "\u05e9\u05de\u05df \u05d1\u05dc\u05d9 \u05e2\u05e8\u05d1\u05d5\u05dc \u05e0\u05de\u05e6\u05d0 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 0.25 \u05e2\u05d3 0.3. \u05de\u05d9\u05dd \u05d1\u05dc\u05d9 \u05e2\u05e8\u05d1\u05d5\u05dc, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1."], [90.8, "\u05de\u05d9 \u05de\u05dc\u05d7 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc-2 \u05d5\u05d9\u05d5\u05ea\u05e8, \u05d5\u05e2\u05dd \u05e2\u05e8\u05d1\u05d5\u05dc \u05d7\u05d6\u05e7 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05dc-5."], [96.5, "\u05db\u05db\u05dc \u05e9\u05d4\u05de\u05e1\u05e4\u05e8 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e7\u05e9\u05d4 \u05dc\u05e2\u05d5\u05de\u05e7 \u05e8\u05d1 \u05d9\u05d5\u05ea\u05e8."], [103.0, "\u05d0\u05d1\u05dc \u05d2\u05dd \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d5\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd."], [108.1, "\u05de\u05d9\u05dd \u05d4\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d5\u05d4\u05d6\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d9\u05df \u05d4\u05e0\u05e4\u05d5\u05e6\u05d9\u05dd."], [112.7, "\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e6\u05d5\u05e8\u05d4 \u05e4\u05e9\u05d5\u05d8\u05d4."], [117.4, "\u05d0\u05d1\u05dc \u05d4\u05de\u05d9\u05dd \u05e8\u05d2\u05d9\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4. \u05d1\u05de\u05d9\u05dd \u05d7\u05de\u05d9\u05dd, \u05e9\u05db\u05d1\u05ea \u05d4\u05d0\u05d3\u05d9\u05dd \u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df, \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e0\u05d7\u05dc\u05e9 \u05de\u05d0\u05d5\u05d3."], [126.2, "\u05dc\u05de\u05e9\u05dc, \u05de\u05d9\u05dd \u05d1-32 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e2\u05e8\u05d1\u05d5\u05dc \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d1\u05e2\u05e8\u05da 1.1, \u05d5\u05d1\u05de\u05d9\u05dd \u05d1-55 \u05de\u05e2\u05dc\u05d5\u05ea \u05d6\u05d4 \u05d9\u05d5\u05e8\u05d3 \u05dc\u05d1\u05e2\u05e8\u05da 0.2, \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05de\u05df."], [138.9, "\u05de\u05d9 \u05de\u05dc\u05d7 \u05e9\u05d5\u05d1\u05e8\u05d9\u05dd \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05d0\u05d3\u05d9\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05dc\u05d4\u05dd \u05de\u05d4\u05d9\u05e8 \u05d5\u05d0\u05d7\u05d9\u05d3 \u05d9\u05d5\u05ea\u05e8. \u05d0\u05d1\u05dc \u05d4\u05dd \u05de\u05d2\u05d1\u05d9\u05e8\u05d9\u05dd \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05d8\u05d5\u05e3 \u05d0\u05d7\u05e8\u05d9\u05d4\u05dd \u05d4\u05d9\u05d8\u05d1."], [150.6, "\u05e9\u05de\u05df \u05de\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d9\u05dd, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e9\u05dc\u05d1 \u05d4\u05e8\u05ea\u05d9\u05d7\u05d4 \u05d5\u05d1\u05e9\u05dc\u05d1 \u05d4\u05d4\u05e1\u05e2\u05d4."], [156.4, "\u05d4\u05d4\u05e1\u05e2\u05d4 \u05d4\u05d0\u05d9\u05d8\u05d9\u05ea \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05e7\u05d8\u05d9\u05e0\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05e9\u05de\u05df \u05d4\u05d5\u05d0 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d4\u05de\u05e7\u05d5\u05d1\u05dc\u05ea \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea."], [165.7, "\u05d9\u05e9 \u05e9\u05de\u05e0\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05d9\u05d5\u05ea \u05e9\u05d5\u05e0\u05d5\u05ea: \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd, \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05d9\u05dd \u05d5\u05de\u05d4\u05d9\u05e8\u05d9\u05dd, \u05e2\u05dd \u05ea\u05d5\u05e1\u05e4\u05d9\u05dd \u05e9\u05de\u05e7\u05e6\u05e8\u05d9\u05dd \u05d0\u05ea \u05e9\u05dc\u05d1 \u05d4\u05d0\u05d3\u05d9\u05dd."], [173.6, "\u05d0\u05d1\u05dc \u05e9\u05de\u05df \u05d7\u05dd \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05d3\u05dc\u05e7. \u05e6\u05e8\u05d9\u05da \u05d0\u05de\u05d1\u05d8 \u05d1\u05e0\u05e4\u05d7 \u05de\u05e1\u05e4\u05d9\u05e7, \u05d1\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e9\u05de\u05df, \u05d5\u05de\u05db\u05e1\u05d4 \u05dc\u05db\u05d9\u05d1\u05d5\u05d9 \u05d0\u05e9."], [182.3, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df \u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05d8\u05d5\u05e3 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4."], [187.7, "\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05d4\u05d5\u05d0 \u05ea\u05de\u05d9\u05e1\u05d4 \u05e9\u05dc \u05de\u05d9\u05dd \u05d5\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05de\u05d9\u05d5\u05d7\u05d3, \u05d5\u05e0\u05d5\u05ea\u05df \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d9\u05df \u05de\u05d9\u05dd \u05dc\u05e9\u05de\u05df."], [193.5, "\u05d4\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05de\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05de\u05d9\u05dd \u05e7\u05e8\u05d9\u05dd, \u05d0\u05d1\u05dc \u05dc\u05d9\u05d3 \u05d4\u05d7\u05dc\u05e7 \u05d4\u05d7\u05dd \u05d4\u05d5\u05d0 \u05d9\u05d5\u05e6\u05d0 \u05de\u05d4\u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc\u05d9\u05d5 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4."], [200.9, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05de\u05d0\u05d8\u05d4 \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05de\u05d5\u05e0\u05e2\u05ea \u05d0\u05ea \u05d4\u05e7\u05e4\u05d9\u05e6\u05d5\u05ea \u05d4\u05d7\u05d3\u05d5\u05ea \u05e9\u05dc \u05de\u05d9\u05dd \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd."], [206.3, "\u05d0\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05d3\u05e8\u05da \u05d4\u05e8\u05d9\u05db\u05d5\u05d6, \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05d4\u05e2\u05e8\u05d1\u05d5\u05dc. \u05e8\u05d9\u05db\u05d5\u05d6 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8."], [214.4, "\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05dc\u05d0 \u05e0\u05d3\u05dc\u05e7 \u05db\u05de\u05d5 \u05e9\u05de\u05df, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05e8\u05d9\u05db\u05d5\u05d6 \u05e9\u05dc\u05d5 \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e8\u05e4\u05e8\u05e7\u05d8\u05d5\u05de\u05d8\u05e8."], [222.4, "\u05d0\u05de\u05d1\u05d8 \u05e9\u05dc \u05de\u05dc\u05d7 \u05de\u05d5\u05ea\u05da \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05dc \u05de\u05d0\u05d5\u05ea \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e9\u05de\u05e9 \u05dc\u05e9\u05d9\u05d8\u05d5\u05ea \u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea \u05e9\u05e0\u05db\u05d9\u05e8 \u05d1\u05e4\u05e8\u05e7 10."], [230.2, "\u05d5\u05d1\u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d2\u05d6, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d7\u05e0\u05e7\u05df, \u05d1\u05dc\u05d7\u05e5 \u05e9\u05dc \u05db\u05de\u05d4 \u05d1\u05e8 \u05d5\u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 20 \u05d1\u05e8."], [237.9, "\u05d4\u05dc\u05d9\u05d5\u05dd \u05de\u05e7\u05e8\u05e8 \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05e0\u05e7\u05df, \u05d0\u05d1\u05dc \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8."], [242.0, "\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d2\u05d6 \u05e0\u05e7\u05d9, \u05d1\u05dc\u05d9 \u05e9\u05de\u05df \u05d5\u05d1\u05dc\u05d9 \u05e9\u05d8\u05d9\u05e4\u05d4, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3."], [247.6, "\u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd."], [255.2, "\u05e2\u05e8\u05d1\u05d5\u05dc \u05e9\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05e9\u05d5\u05d1 \u05db\u05de\u05e2\u05d8 \u05db\u05de\u05d5 \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05e9\u05dc\u05d5."], [259.5, "\u05e2\u05e8\u05d1\u05d5\u05dc \u05e9\u05d5\u05d1\u05e8 \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05d0\u05d3\u05d9\u05dd, \u05de\u05e1\u05dc\u05e7 \u05d1\u05d5\u05e2\u05d5\u05ea, \u05d5\u05de\u05d1\u05d9\u05d0 \u05e0\u05d5\u05d6\u05dc \u05e7\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [265.3, "\u05d1\u05dc\u05d9 \u05e2\u05e8\u05d1\u05d5\u05dc, \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05db\u05d9\u05e1\u05d9\u05dd \u05e9\u05dc \u05d0\u05d3\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc \u05d1\u05d7\u05d5\u05e8\u05d9\u05dd \u05e2\u05d9\u05d5\u05d5\u05e8\u05d9\u05dd \u05d5\u05d1\u05e9\u05e7\u05e2\u05d9\u05dd, \u05d5\u05e9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05db\u05ea\u05de\u05d9\u05dd \u05e8\u05db\u05d9\u05dd."], [273.9, "\u05d2\u05dd \u05d4\u05db\u05d9\u05d5\u05d5\u05df \u05d7\u05e9\u05d5\u05d1: \u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05d0\u05e0\u05db\u05d9\u05ea, \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05e6\u05d9\u05e8 \u05e9\u05dc\u05d5, \u05d5\u05dc\u05d0 \u05e2\u05dc \u05d4\u05e6\u05d3."], [280.3, "\u05db\u05da \u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea."], [285.9, "\u05d0\u05d9\u05da \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd? \u05d4\u05db\u05dc\u05dc: \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05e2\u05d3\u05d9\u05df \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05de\u05e7\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05e2\u05d5\u05de\u05e7 \u05d4\u05e0\u05d3\u05e8\u05e9."], [293.8, "\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e6\u05e8\u05d9\u05db\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05d9\u05dd, \u05de\u05d9 \u05de\u05dc\u05d7 \u05d0\u05d5 \u05e4\u05d5\u05dc\u05d9\u05de\u05e8. \u05e4\u05dc\u05d3\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05e1\u05ea\u05e4\u05e7\u05ea \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05e4\u05d5\u05dc\u05d9\u05de\u05e8."], [302.3, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05e1\u05d5\u05d2\u05e1\u05d2\u05d5\u05ea \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d2\u05dd \u05d1\u05d2\u05d6 \u05d0\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05dc\u05e4\u05d9 \u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd."], [308.0, "\u05d5\u05d1\u05d7\u05dc\u05e7 \u05e2\u05dd \u05e6\u05d5\u05e8\u05d4 \u05de\u05e1\u05d5\u05d1\u05db\u05ea, \u05d7\u05d5\u05e8\u05d9\u05dd \u05d5\u05e4\u05d9\u05e0\u05d5\u05ea, \u05e2\u05d3\u05d9\u05e3 \u05d0\u05de\u05e6\u05e2\u05d9 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8."], [317.0, "\u05de\u05d4 \u05de\u05e9\u05ea\u05d1\u05e9? \u05e1\u05d3\u05e7\u05d9\u05dd: \u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05d6\u05e7 \u05de\u05d3\u05d9 \u05dc\u05e4\u05dc\u05d3\u05d4, \u05d0\u05d5 \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d5\u05d7\u05ea\u05db\u05d9\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3\u05d9\u05dd."], [325.0, "\u05db\u05ea\u05de\u05d9\u05dd \u05e8\u05db\u05d9\u05dd: \u05db\u05d9\u05e1\u05d9 \u05d0\u05d3\u05d9\u05dd, \u05e2\u05e8\u05d1\u05d5\u05dc \u05d7\u05dc\u05e9, \u05d0\u05d5 \u05de\u05d9\u05dd \u05e9\u05d4\u05ea\u05d7\u05de\u05de\u05d5."], [330.6, "\u05e2\u05d9\u05d5\u05d5\u05ea: \u05d7\u05dc\u05e7 \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05d0\u05de\u05d1\u05d8 \u05d1\u05d6\u05d5\u05d5\u05d9\u05ea, \u05d0\u05d5 \u05e9\u05e6\u05d3 \u05d0\u05d7\u05d3 \u05e9\u05dc\u05d5 \u05de\u05ea\u05e7\u05e8\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [337.4, "\u05e9\u05e8\u05d9\u05e4\u05d4: \u05e9\u05de\u05df \u05e9\u05d4\u05ea\u05d7\u05de\u05dd \u05de\u05e2\u05d1\u05e8 \u05dc\u05d2\u05d1\u05d5\u05dc, \u05d0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05de\u05d3\u05d9 \u05d1\u05d0\u05de\u05d1\u05d8 \u05e7\u05d8\u05df \u05de\u05d3\u05d9."], [344.0, "\u05d5\u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d6\u05d5\u05d4\u05dd: \u05de\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05e9\u05de\u05df \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e8\u05ea\u05d9\u05d7\u05d4 \u05e4\u05ea\u05d0\u05d5\u05de\u05d9\u05ea \u05d5\u05dc\u05e1\u05d3\u05e7\u05d9\u05dd, \u05d5\u05e9\u05de\u05df \u05d9\u05e9\u05df \u05de\u05d0\u05d1\u05d3 \u05de\u05d4\u05d9\u05db\u05d5\u05dc\u05ea \u05e9\u05dc\u05d5."], [353.3, "\u05d5\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d2\u05d6 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05d4\u05d9\u05e7\u05e8 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05d7\u05d5\u05e1\u05da \u05e9\u05d8\u05d9\u05e4\u05d4 \u05d5\u05d9\u05d9\u05e9\u05d5\u05e8."], [361.2, "\u05d1\u05e9\u05de\u05df \u05d9\u05e9 \u05e2\u05dc\u05d5\u05d9\u05d5\u05ea \u05e9\u05dc \u05e9\u05d8\u05d9\u05e4\u05d4, \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d0\u05e9, \u05d4\u05d7\u05dc\u05e4\u05d4 \u05d5\u05e1\u05d9\u05dc\u05d5\u05e7 \u05e9\u05dc \u05d4\u05e9\u05de\u05df."], [367.0, "\u05d1\u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05e6\u05e8\u05d9\u05da \u05d1\u05e7\u05e8\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4 \u05e9\u05dc \u05d4\u05e8\u05d9\u05db\u05d5\u05d6."], [370.3, "\u05d5\u05d4\u05e2\u05dc\u05d5\u05ea \u05d4\u05e0\u05e1\u05ea\u05e8\u05ea \u05d4\u05d9\u05d0 \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea: \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05d6\u05e7 \u05de\u05d3\u05d9 \u05e2\u05d5\u05dc\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [380.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd: \u05d0\u05d3\u05d9\u05dd, \u05e8\u05ea\u05d9\u05d7\u05d4 \u05d5\u05d4\u05e1\u05e2\u05d4, \u05d5\u05d4\u05e8\u05ea\u05d9\u05d7\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05de\u05d4\u05d9\u05e8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [389.3, "\u05d7\u05d5\u05de\u05e8\u05ea \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d5\u05dc\u05d4 \u05de\u05e9\u05de\u05df, \u05d3\u05e8\u05da \u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05d5\u05de\u05d9\u05dd, \u05d5\u05e2\u05d3 \u05de\u05d9 \u05de\u05dc\u05d7, \u05d5\u05e2\u05e8\u05d1\u05d5\u05dc \u05de\u05e2\u05dc\u05d4 \u05d0\u05d5\u05ea\u05d4 \u05e2\u05d5\u05d3."], [397.0, "\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05ea \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05e2\u05d3\u05d9\u05df \u05d1\u05d9\u05d5\u05ea\u05e8 \u05e9\u05e2\u05d3\u05d9\u05d9\u05df \u05de\u05e7\u05e9\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05e0\u05d9\u05e7\u05d9\u05d5\u05df \u05d5\u05e2\u05e8\u05d1\u05d5\u05dc."], [405.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e9\u05dc\u05d1 \u05e9\u05d1\u05dc\u05e2\u05d3\u05d9\u05d5 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d8\u05e8\u05d9 \u05e4\u05e9\u05d5\u05d8 \u05e4\u05e8\u05d9\u05da \u05de\u05d3\u05d9: \u05d4\u05e8\u05e4\u05d9\u05d4."]]};
window.MH_TR["ch09"]={"t": "\u05d4\u05e8\u05e4\u05d9\u05d4", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05e7\u05d9\u05e8\u05e8\u05e0\u05d5 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d5\u05e7\u05d9\u05d1\u05dc\u05e0\u05d5 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d1\u05dc \u05d2\u05dd \u05e4\u05e8\u05d9\u05da, \u05d5\u05de\u05dc\u05d0 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e4\u05e0\u05d9\u05de\u05d9\u05d9\u05dd."], [13.9, "\u05d7\u05dc\u05e7 \u05db\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05e2\u05dc \u05d4\u05de\u05d3\u05e3, \u05e2\u05d5\u05d3 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05db\u05e0\u05e1 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4."], [18.2, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d7\u05d3\u05e9 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05ea\u05d7\u05ea \u05dc-Ac1, \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8. \u05d4\u05d9\u05d0 \u05de\u05d5\u05d5\u05ea\u05e8\u05ea \u05e2\u05dc \u05e7\u05e6\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea."], [29.0, "\u05d1\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d4\u05d8\u05e8\u05d9, \u05d4\u05e4\u05d7\u05de\u05df \u05db\u05dc\u05d5\u05d0 \u05d1\u05ea\u05d5\u05da \u05e1\u05e8\u05d9\u05d2 \u05d4\u05d1\u05e8\u05d6\u05dc \u05d5\u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05d5\u05ea\u05d5. \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05de\u05e7\u05d5\u05e8 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05d2\u05dd \u05de\u05e7\u05d5\u05e8 \u05d4\u05e4\u05e8\u05d9\u05db\u05d5\u05ea."], [38.8, "\u05d1\u05d7\u05d9\u05de\u05d5\u05dd, \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05e6\u05d0\u05ea \u05de\u05d4\u05e1\u05e8\u05d9\u05d2 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05dc \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd."], [44.8, "\u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 200 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d9\u05d5\u05e8\u05d3\u05ea, \u05d0\u05d1\u05dc \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd."], [52.6, "\u05d1\u05d9\u05df 200 \u05dc-300 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05de\u05ea\u05e4\u05e8\u05e7."], [57.4, "\u05de\u05e2\u05dc 300 \u05de\u05e2\u05dc\u05d5\u05ea \u05e0\u05d5\u05e6\u05e8 \u05e6\u05de\u05e0\u05d8\u05d9\u05d8, \u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05d1\u05d4\u05d3\u05e8\u05d2\u05d4."], [64.4, "\u05db\u05db\u05dc \u05e9\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e2\u05d5\u05dc\u05d4, \u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e0\u05e2\u05e9\u05d9\u05ea \u05e8\u05db\u05d4 \u05d5\u05de\u05e9\u05d9\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8. \u05d5\u05d6\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05de\u05d4 \u05e9\u05d0\u05e0\u05d7\u05e0\u05d5 \u05de\u05db\u05d5\u05d5\u05e0\u05d9\u05dd."], [72.2, "\u05d4\u05db\u05dc\u05d9 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e2\u05e7\u05d5\u05de\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4: \u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05e4\u05d5\u05e0\u05e7\u05e6\u05d9\u05d4 \u05e9\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d1\u05d6\u05de\u05df \u05d4\u05d7\u05d6\u05e7\u05d4 \u05e7\u05d1\u05d5\u05e2."], [80.6, "\u05dc\u05d3\u05d5\u05d2\u05de\u05d4, 4140 \u05e9\u05d4\u05d5\u05e7\u05e9\u05ea\u05d4 \u05d1\u05e9\u05de\u05df \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d1\u05e2\u05e8\u05da 55 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1-200 \u05de\u05e2\u05dc\u05d5\u05ea,"], [90.1, "\u05dc\u05d1\u05e2\u05e8\u05da 45 \u05d1-425 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05d1\u05e2\u05e8\u05da 30 \u05d1-650 \u05de\u05e2\u05dc\u05d5\u05ea."], [98.0, "\u05d4\u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05d4\u05d5\u05dc\u05db\u05ea \u05d1\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05d4\u05e4\u05d5\u05da: \u05db\u05db\u05dc \u05e9\u05de\u05e8\u05e4\u05d9\u05dd \u05d7\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d7\u05dc\u05e7 \u05e1\u05d5\u05e4\u05d2 \u05d9\u05d5\u05ea\u05e8 \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05e0\u05e9\u05d1\u05e8."], [105.9, "\u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05e9\u05d5\u05e0\u05d4 \u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4, \u05d5\u05dc\u05db\u05df \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05de\u05d2\u05d9\u05dc\u05d9\u05d5\u05df \u05d4\u05e0\u05ea\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df, \u05d5\u05dc\u05d0 \u05de\u05d4\u05d6\u05d9\u05db\u05e8\u05d5\u05df."], [113.3, "\u05d1\u05e4\u05d5\u05e2\u05dc \u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05ea\u05d7\u05d5\u05de\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd."], [116.7, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05d9\u05df 150 \u05dc-250 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc 58 \u05e2\u05d3 62 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C. \u05db\u05db\u05d4 \u05de\u05e8\u05e4\u05d9\u05dd \u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05de\u05e1\u05d1\u05d9\u05dd."], [129.1, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05d1\u05d9\u05df 350 \u05dc-500 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e0\u05d5\u05ea\u05e0\u05ea \u05d1\u05e2\u05e8\u05da 40 \u05e2\u05d3 50, \u05e2\u05dd \u05d2\u05de\u05d9\u05e9\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4. \u05db\u05db\u05d4 \u05de\u05e8\u05e4\u05d9\u05dd \u05e7\u05e4\u05d9\u05e6\u05d9\u05dd."], [139.4, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05d9\u05df 500 \u05dc-650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e0\u05d5\u05ea\u05e0\u05ea 25 \u05e2\u05d3 40 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C \u05e2\u05dd \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4. \u05dc\u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \"\u05e9\u05d9\u05e4\u05d5\u05e8\"."], [152.9, "\u05e6\u05d9\u05e8\u05d9\u05dd, \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05d1\u05e8\u05d2\u05d9\u05dd \u05d7\u05d6\u05e7\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e9\u05d9\u05e4\u05d5\u05e8. \u05d5-4140 \u05e9\u05e7\u05d5\u05e0\u05d9\u05dd \"\u05de\u05e9\u05d5\u05e4\u05e8\", \u05d1\u05d1\u05e2\u05e8\u05da 28 \u05e2\u05d3 32 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05db\u05d1\u05e8 \u05e2\u05d1\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e6\u05dc \u05d4\u05e1\u05e4\u05e7."], [168.4, "\u05d1\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d7\u05e9\u05d5\u05d1\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d6\u05de\u05df."], [172.4, "\u05dc\u05e4\u05d9 \u05d4\u05e4\u05e8\u05de\u05d8\u05e8 \u05e9\u05dc \u05d4\u05d5\u05dc\u05d5\u05de\u05d5\u05df \u05d5\u05d2'\u05d0\u05e4\u05d4, \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05dc\u05d4\u05d0\u05e8\u05d9\u05da \u05d0\u05ea \u05d4\u05d6\u05de\u05df \u05e4\u05d9 10 \u05e9\u05e7\u05d5\u05dc \u05d1\u05e2\u05e8\u05da \u05dc\u05d4\u05e2\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05db-40 \u05de\u05e2\u05dc\u05d5\u05ea."], [183.0, "\u05db\u05dc\u05d5\u05de\u05e8, \u05e9\u05e2\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05d1\u05ea\u05e0\u05d5\u05e8 \u05dc\u05d0 \u05ea\u05e6\u05d9\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4."], [188.3, "\u05db\u05dc\u05dc \u05d0\u05e6\u05d1\u05e2 \u05dc\u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4: \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9, \u05d5\u05dc\u05d0 \u05e4\u05d7\u05d5\u05ea \u05de\u05e9\u05e2\u05ea\u05d9\u05d9\u05dd, \u05de\u05d4\u05e8\u05d2\u05e2 \u05e9\u05d4\u05dc\u05d9\u05d1\u05d4 \u05d4\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [198.0, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [202.2, "\u05de\u05ea\u05d9 \u05de\u05e8\u05e4\u05d9\u05dd? \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [205.2, "\u05de\u05d7\u05db\u05d9\u05dd \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d9\u05ea\u05e7\u05e8\u05e8 \u05dc\u05d1\u05e2\u05e8\u05da 50 \u05e2\u05d3 70 \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05e9\u05db\u05de\u05e2\u05d8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d2\u05e2\u05ea \u05d1\u05d5, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d9\u05e1\u05d9\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8."], [214.2, "\u05d5\u05d0\u05d6 \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05dc\u05ea\u05e0\u05d5\u05e8 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4. \u05dc\u05d0 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05dc\u05dc\u05d9\u05dc\u05d4 \u05e2\u05dc \u05d4\u05e8\u05e6\u05e4\u05d4, \u05db\u05d9 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e1\u05d3\u05d5\u05e7 \u05d0\u05d5\u05ea\u05d5."], [222.3, "\u05d2\u05dd \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d1\u05dc\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05e1\u05d5\u05db\u05e0\u05d5\u05ea, \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dd \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea."], [229.8, "\u05d9\u05e9 \u05e9\u05e0\u05d9 \u05ea\u05d7\u05d5\u05de\u05d9\u05dd \u05e9\u05d1\u05d4\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d3\u05d5\u05d5\u05e7\u05d0 \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d7\u05d5\u05ea."], [234.1, "\u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d1\u05d9\u05df 250 \u05dc-400 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05e2\u05e8\u05da, \u05d5\u05e0\u05e7\u05e8\u05d0 \"\u05e4\u05e8\u05d9\u05db\u05d5\u05ea 350\". \u05d4\u05d5\u05d0 \u05e0\u05d5\u05e6\u05e8 \u05de\u05d4\u05e8, \u05ea\u05d5\u05da \u05e9\u05e2\u05d4."], [243.3, "\u05dc\u05db\u05df \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea, \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d0 \u05de\u05e8\u05e4\u05d9\u05dd \u05d1\u05ea\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4."], [247.7, "\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05e4\u05e8\u05d9\u05db\u05d5\u05ea \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d1\u05d9\u05df 375 \u05dc-575 \u05de\u05e2\u05dc\u05d5\u05ea. \u05d4\u05d9\u05d0 \u05de\u05ea\u05e4\u05ea\u05d7\u05ea \u05dc\u05d0\u05d8, \u05d1\u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d0\u05d5 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d3\u05e8\u05da \u05d4\u05ea\u05d7\u05d5\u05dd, \u05dc\u05de\u05e9\u05dc \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd."], [261.7, "\u05d4\u05d2\u05d5\u05e8\u05dd \u05d4\u05d5\u05d0 \u05d6\u05d9\u05d4\u05d5\u05de\u05d9\u05dd \u05db\u05de\u05d5 \u05d6\u05e8\u05d7\u05df, \u05d1\u05d3\u05d9\u05dc \u05d5\u05d0\u05e0\u05d8\u05d9\u05de\u05d5\u05df, \u05e9\u05e0\u05d0\u05e1\u05e4\u05d9\u05dd \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd. \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd-\u05e0\u05d9\u05e7\u05dc \u05e8\u05d2\u05d9\u05e9\u05d5\u05ea \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05e7\u05d8\u05e0\u05d4 \u05e9\u05dc \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05de\u05e7\u05d8\u05d9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05d1\u05e2\u05d9\u05d4."], [274.6, "\u05d0\u05ea \u05d4\u05e1\u05d5\u05d2 \u05d4\u05d6\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05d8\u05dc: \u05de\u05e8\u05e4\u05d9\u05dd \u05e9\u05d5\u05d1 \u05de\u05e2\u05dc 600 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8 \u05d3\u05e8\u05da \u05d4\u05ea\u05d7\u05d5\u05dd."], [282.1, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05e1\u05d5\u05d2\u05e1\u05d2\u05d5\u05ea, \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e0\u05e9\u05d0\u05e8 \u05d4\u05e8\u05d1\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9."], [287.2, "\u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05d6\u05d4 \u05de\u05ea\u05e4\u05e8\u05e7, \u05d5\u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05d0\u05d7\u05e8\u05d9\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d7\u05d3\u05e9, \u05d8\u05e8\u05d9 \u05d5\u05e4\u05e8\u05d9\u05da."], [295.8, "\u05d0\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d4\u05d7\u05d3\u05e9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05e9\u05d5\u05d1. \u05dc\u05db\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05de\u05d5 H13 \u05d5-D2 \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05e9\u05ea\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d5\u05ea."], [305.0, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05db\u05de\u05d5 M2 \u05de\u05e8\u05e4\u05d9\u05dd \u05e9\u05dc\u05d5\u05e9 \u05e4\u05e2\u05de\u05d9\u05dd, \u05db\u05dc \u05e4\u05e2\u05dd \u05e9\u05e2\u05ea\u05d9\u05d9\u05dd, \u05d1\u05d1\u05e2\u05e8\u05da 550 \u05de\u05e2\u05dc\u05d5\u05ea."], [314.2, "\u05d5\u05d1\u05d9\u05df \u05d4\u05e8\u05e4\u05d9\u05d4 \u05dc\u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8. \u05d1\u05dc\u05d9 \u05d6\u05d4 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05dc\u05d0 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d1\u05d0\u05d4 \u05dc\u05d0 \u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4."], [324.5, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc\u05d4 \u05d4\u05e2\u05e7\u05d5\u05de\u05d4 \u05d2\u05dd \u05e0\u05e8\u05d0\u05d9\u05ea \u05d0\u05d7\u05e8\u05ea: \u05e1\u05d1\u05d9\u05d1 500 \u05e2\u05d3 550 \u05de\u05e2\u05dc\u05d5\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05d5\u05dc\u05d4 \u05e9\u05d5\u05d1, \u05d1\u05d2\u05dc\u05dc \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e9\u05dc \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d5\u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df. \u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05e9\u05e0\u05d9\u05ea."], [339.3, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea."], [342.2, "\u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e7\u05e9\u05d4 \u05de\u05d3\u05d9, \u05de\u05e8\u05e4\u05d9\u05dd \u05e9\u05d5\u05d1 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d2\u05d1\u05d5\u05d4\u05d4. \u05d6\u05d4 \u05ea\u05d9\u05e7\u05d5\u05df \u05d6\u05d5\u05dc \u05d5\u05e4\u05e9\u05d5\u05d8."], [349.2, "\u05d0\u05dd \u05d4\u05d5\u05d0 \u05e8\u05da \u05de\u05d3\u05d9, \u05d4\u05e8\u05e4\u05d9\u05d4 \u05dc\u05d0 \u05ea\u05e2\u05d6\u05d5\u05e8, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05e8\u05e7 \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05e7\u05e9\u05d9\u05d5\u05ea. \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05de\u05d7\u05d3\u05e9, \u05d5\u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05e9\u05d5\u05d1."], [357.3, "\u05d5\u05e6\u05d1\u05e2\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05e6\u05d4\u05d5\u05d1 \u05e7\u05e9 \u05d0\u05d5 \u05db\u05d7\u05d5\u05dc, \u05d4\u05dd \u05e8\u05e7 \u05e9\u05db\u05d1\u05ea \u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05d3\u05e7\u05d4. \u05d4\u05dd \u05dc\u05d0 \u05de\u05d7\u05dc\u05d9\u05e4\u05d9\u05dd \u05e6\u05de\u05d3 \u05ea\u05e8\u05de\u05d9 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea."], [369.0, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d4\u05e8\u05e4\u05d9\u05d4?"], [370.8, "\u05de\u05e1\u05e4\u05e8 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d5\u05ea: \u05db\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d3 \u05de\u05d7\u05d6\u05d5\u05e8 \u05ea\u05e0\u05d5\u05e8, \u05e2\u05dd \u05d7\u05d9\u05de\u05d5\u05dd, \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8. \u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05e9\u05d5\u05dc\u05e9\u05ea \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05ea\u05e4\u05d5\u05e1 \u05d9\u05d5\u05dd \u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc\u05dd."], [381.7, "\u05e2\u05d5\u05d1\u05d9 \u05d5\u05de\u05e9\u05e7\u05dc: \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05e6\u05e8\u05d9\u05da \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05ea\u05d5\u05e4\u05e1 \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df."], [388.5, "\u05ea\u05d7\u05d5\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05e6\u05e8: \u05d3\u05e8\u05d9\u05e9\u05d4 \u05e9\u05dc 2 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C \u05d1\u05de\u05e7\u05d5\u05dd 4 \u05d0\u05d5 5 \u05de\u05d7\u05d9\u05d9\u05d1\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea, \u05de\u05d3\u05d9\u05d3\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea."], [398.4, "\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4: \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05d2\u05d6 \u05de\u05d2\u05df \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9\u05d9\u05dd, \u05d0\u05d1\u05dc \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [406.6, "\u05d5\u05d4\u05d9\u05e7\u05e8 \u05de\u05db\u05d5\u05dc\u05dd \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05e9\u05d9\u05e6\u05d0 \u05e8\u05da \u05de\u05d3\u05d9, \u05db\u05d9 \u05d0\u05d6 \u05de\u05e9\u05dc\u05de\u05d9\u05dd \u05e9\u05d5\u05d1 \u05e2\u05dc \u05db\u05dc \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [413.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05d7\u05d6\u05d9\u05e8\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d1\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05e7\u05e6\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea."], [420.1, "\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05dc\u05e4\u05d9 \u05e2\u05e7\u05d5\u05de\u05ea \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d4\u05d6\u05de\u05df \u05e8\u05e7 \u05de\u05e9\u05dc\u05d9\u05dd."], [426.4, "\u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05e0\u05d6\u05d4\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05d5\u05de\u05d9 \u05d4\u05e4\u05e8\u05d9\u05db\u05d5\u05ea, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05e8\u05e4\u05d9\u05dd \u05e4\u05e2\u05de\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9."], [433.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9 \u05e9\u05de\u05e1\u05dc\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9."]]};
window.MH_TR["ch10"]={"t": "\u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9", "l": [[5.0, "\u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05e8\u05d2\u05d9\u05dc, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05dc\u05d9\u05d1\u05d4. \u05d4\u05d7\u05d5\u05e5 \u05db\u05d1\u05e8 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d5\u05de\u05ea\u05e8\u05d7\u05d1, \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05d3\u05d9\u05d9\u05df \u05d7\u05de\u05d4."], [14.4, "\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e7\u05d5\u05e8 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9 \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [18.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd \u05dc\u05e9\u05dc\u05d5\u05d8 \u05d1\u05d6\u05d4: \u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9."], [26.0, "\u05e0\u05d7\u05d6\u05d5\u05e8 \u05dc\u05e2\u05e7\u05d5\u05de\u05ea \u05d4-TTT. \u05d4\u05d0\u05e3 \u05e9\u05dc \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8 \u05e7\u05d5\u05d1\u05e2 \u05db\u05de\u05d4 \u05d6\u05de\u05df \u05d9\u05e9 \u05dc\u05e0\u05d5, \u05d5\u05e7\u05d5 Ms \u05de\u05e1\u05de\u05df \u05d0\u05d9\u05e4\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [35.1, "\u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05e8\u05d2\u05d9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05e6\u05d5\u05dc\u05dc \u05d3\u05e8\u05da Ms, \u05d5\u05d4\u05d7\u05d5\u05e5 \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05d7\u05d5\u05e6\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d6\u05de\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd."], [42.0, "\u05e9\u05ea\u05d9 \u05d4\u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d5\u05ea \u05e2\u05d5\u05e6\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05de\u05d1\u05d8 \u05d7\u05dd, \u05de\u05e2\u05dc Ms. \u05d5\u05de\u05e9\u05dd \u05d4\u05d3\u05e8\u05db\u05d9\u05dd \u05e9\u05dc\u05d4\u05df \u05e0\u05e4\u05e8\u05d3\u05d5\u05ea."], [50.3, "\u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05e0\u05e7\u05e8\u05d0 \u05d2\u05dd \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d3\u05d5\u05e8\u05d2. \u05de\u05db\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d0\u05d5 \u05e9\u05de\u05df \u05d7\u05dd, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e7\u05e6\u05ea \u05de\u05e2\u05dc Ms."], [59.6, "\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e9\u05dd \u05e8\u05e7 \u05e2\u05d3 \u05e9\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e9\u05ea\u05d5\u05d5\u05d4 \u05d1\u05db\u05dc \u05d4\u05d7\u05ea\u05da, \u05d5\u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7 \u05d6\u05de\u05df \u05db\u05d3\u05d9 \u05e9\u05d9\u05d9\u05d5\u05d5\u05e6\u05e8 \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8."], [66.7, "\u05d5\u05d0\u05d6 \u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd \u05dc\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8. \u05d4\u05d7\u05d5\u05e5 \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05d7\u05d5\u05e6\u05d9\u05dd \u05d0\u05ea Ms \u05db\u05de\u05e2\u05d8 \u05d1\u05d9\u05d7\u05d3, \u05d5\u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05d6\u05de\u05df."], [76.3, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d0\u05d5\u05ea\u05d5 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05e1\u05d3\u05e7\u05d9\u05dd."], [82.8, "\u05d0\u05d7\u05e8\u05d9 \u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05e2\u05d3\u05d9\u05d9\u05df \u05e6\u05e8\u05d9\u05da \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4, \u05db\u05de\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd."], [87.5, "\u05d2\u05e8\u05e1\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df \u05d7\u05dd, \u05d1\u05e2\u05e8\u05da 100 \u05e2\u05d3 190 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05db\u05de\u05d5 \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d5\u05de\u05e1\u05d1\u05d9\u05dd."], [97.6, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d8\u05d5\u05d1\u05d4, \u05db\u05de\u05d5 4140, 4340 \u05d5-52100."], [106.6, "\u05d1\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e4\u05e9\u05d5\u05d8\u05d4 \u05d4\u05d0\u05de\u05d1\u05d8 \u05d4\u05d7\u05dd \u05d0\u05d9\u05d8\u05d9 \u05de\u05d3\u05d9, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d9\u05e4\u05d2\u05d5\u05e9 \u05d0\u05ea \u05d4\u05d0\u05e3 \u05e9\u05dc \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d9\u05d2\u05d9\u05e2 \u05dc-Ms."], [115.0, "\u05d2\u05dd \u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05de\u05d3\u05d9 \u05dc\u05d0 \u05d9\u05e1\u05e4\u05d9\u05e7 \u05dc\u05d4\u05ea\u05e7\u05e8\u05e8 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05d1\u05d6\u05de\u05df."], [119.7, "\u05dc\u05db\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d5\u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd, \u05e9\u05d1\u05d4\u05dd \u05db\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea \u05e2\u05d5\u05dc\u05d4 \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4."], [126.8, "\u05d1\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05de\u05db\u05d1\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d7\u05dd, \u05d1\u05e2\u05e8\u05da 260 \u05e2\u05d3 370 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d2\u05dd \u05db\u05df \u05de\u05e2\u05dc Ms."], [135.8, "\u05d0\u05d1\u05dc \u05d4\u05e4\u05e2\u05dd \u05dc\u05d0 \u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd: \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05d0\u05de\u05d1\u05d8 \u05e2\u05d3 \u05e9\u05db\u05dc \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05d5\u05e4\u05da \u05dc\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8."], [142.8, "\u05d6\u05d4 \u05dc\u05d5\u05e7\u05d7 \u05de\u05d3\u05e7\u05d5\u05ea \u05e1\u05e4\u05d5\u05e8\u05d5\u05ea \u05d5\u05e2\u05d3 \u05e9\u05e2\u05d4 \u05d5\u05d9\u05d5\u05ea\u05e8, \u05dc\u05e4\u05d9 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d5\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [148.3, "\u05d0\u05d9\u05df \u05db\u05d0\u05df \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05dc\u05db\u05df \u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4."], [151.9, "\u05db\u05db\u05dc \u05e9\u05d4\u05d0\u05de\u05d1\u05d8 \u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8."], [157.1, "\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05ea \u05d4\u05d9\u05d0 35 \u05e2\u05d3 55 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [162.6, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05e9\u05dc \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8: \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d9\u05d7 \u05d5\u05de\u05e9\u05d9\u05da \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05d5\u05e8\u05e4\u05d4, \u05d5\u05e2\u05de\u05d9\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d4\u05dc\u05dd."], [170.6, "\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05db\u05d9 \u05d4\u05d4\u05ea\u05de\u05e8\u05d4 \u05de\u05ea\u05e8\u05d7\u05e9\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05d9\u05d3\u05d4 \u05d1\u05db\u05dc \u05d4\u05d7\u05dc\u05e7."], [176.4, "\u05d5\u05d0\u05d9\u05df \u05db\u05d0\u05df \u05e1\u05d3\u05e7\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05d2\u05dd \u05dc\u05d0 \u05e4\u05e8\u05d9\u05db\u05d5\u05ea \u05d4\u05e8\u05e4\u05d9\u05d4."], [180.3, "\u05dc\u05db\u05df \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05e0\u05e4\u05d5\u05e5 \u05d1\u05e7\u05e4\u05d9\u05e6\u05d9\u05dd \u05e9\u05d8\u05d5\u05d7\u05d9\u05dd, \u05e7\u05dc\u05d9\u05e4\u05e1\u05d9\u05dd, \u05d3\u05d9\u05e1\u05e7\u05d9\u05d5\u05ea \u05e7\u05e4\u05d9\u05e6\u05d9\u05d5\u05ea \u05d5\u05dc\u05d4\u05d1\u05d9\u05dd."], [188.1, "\u05d4\u05de\u05d2\u05d1\u05dc\u05d4 \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d1\u05d9."], [190.5, "\u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d5\u05d0 \u05e4\u05d5\u05d2\u05e9 \u05d0\u05ea \u05d4\u05d0\u05e3 \u05e9\u05dc \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d4\u05d0\u05de\u05d1\u05d8 \u05d4\u05d7\u05dd \u05de\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8."], [198.3, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d6\u05d4 \u05d0\u05d5\u05de\u05e8 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05d5\u05de\u05e2\u05dc \u05d1\u05e2\u05e8\u05da 13 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e6\u05e8\u05d9\u05da \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3."], [208.1, "\u05d5\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9, \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05d9\u05d5\u05e6\u05e8 \u05d0\u05ea \u05d4-ADI, \u05e9\u05e0\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d5 \u05d1\u05e4\u05e8\u05e7 19."], [216.0, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05d1\u05e2\u05d9\u05d4 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea: \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9."], [219.7, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05d1\u05e9\u05db\u05d1\u05d5\u05ea \u05de\u05d5\u05e6\u05de\u05e0\u05d8\u05d5\u05ea, Mf \u05d9\u05d5\u05e8\u05d3\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."], [227.4, "\u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7 \u05dc\u05d4\u05e4\u05d5\u05da, \u05d5\u05e0\u05e9\u05d0\u05e8 \u05d1\u05d7\u05dc\u05e7 \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d4\u05ea\u05e7\u05e8\u05e8."], [233.4, "\u05d4\u05d5\u05d0 \u05e8\u05da, \u05d5\u05de\u05d5\u05e8\u05d9\u05d3 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea."], [236.1, "\u05d5\u05d2\u05e8\u05d5\u05e2 \u05de\u05d6\u05d4: \u05e2\u05dd \u05d4\u05d6\u05de\u05df, \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05d5 \u05d1\u05e7\u05d5\u05e8, \u05d4\u05d5\u05d0 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d5\u05de\u05ea\u05e0\u05e4\u05d7. \u05de\u05d9\u05d3\u05d4 \u05e9\u05e0\u05d1\u05d3\u05e7\u05d4 \u05d5\u05e2\u05d1\u05e8\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e6\u05d0\u05ea \u05de\u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1 \u05d0\u05d7\u05e8\u05d9 \u05db\u05de\u05d4 \u05d7\u05d5\u05d3\u05e9\u05d9\u05dd."], [248.3, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05d5\u05d0 \u05dc\u05d4\u05de\u05e9\u05d9\u05da \u05dc\u05e7\u05e8\u05e8, \u05de\u05ea\u05d7\u05ea \u05dc\u05d0\u05e4\u05e1."], [252.4, "\u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05de\u05d9\u05e0\u05d5\u05e1 70 \u05e2\u05d3 \u05de\u05d9\u05e0\u05d5\u05e1 80 \u05de\u05e2\u05dc\u05d5\u05ea \u05d1\u05e7\u05e8\u05d7 \u05d9\u05d1\u05e9, \u05d0\u05d5 \u05dc\u05de\u05d9\u05e0\u05d5\u05e1 196 \u05d1\u05d7\u05e0\u05e7\u05df \u05e0\u05d5\u05d6\u05dc\u05d9."], [262.5, "\u05e9\u05dd \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05de\u05de\u05e9\u05d9\u05da \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [266.7, "\u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4. \u05d0\u05dd \u05de\u05d7\u05db\u05d9\u05dd, \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05de\u05ea\u05d9\u05d9\u05e6\u05d1 \u05d5\u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e4\u05d5\u05da \u05d0\u05d5\u05ea\u05d5."], [274.6, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea, \u05db\u05d9 \u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d8\u05e8\u05d9 \u05d5\u05e4\u05e8\u05d9\u05da."], [279.9, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05e9\u05e2\u05dc\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7, \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d5\u05e7\u05e6\u05e8\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [286.7, "\u05de\u05ea\u05d9 \u05e6\u05e8\u05d9\u05da \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9? \u05db\u05e9\u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e7\u05e8\u05d9\u05d8\u05d9\u05ea: \u05de\u05d3\u05d9 \u05d1\u05d3\u05d9\u05e7\u05d4, \u05de\u05e1\u05d1\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea."], [295.0, "\u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05d5\u05e6\u05de\u05e0\u05d8\u05d9\u05dd, \u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05db\u05de\u05d5 AMS 2759/7 \u05de\u05d2\u05d1\u05d9\u05dc\u05d9\u05dd \u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9."], [304.6, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d1\u05d7\u05e0\u05e7\u05df \u05e0\u05d5\u05d6\u05dc\u05d9 \u05e0\u05d7\u05e9\u05d1 \u05d2\u05dd \u05de\u05e9\u05e4\u05e8 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05dc\u05e9\u05d7\u05d9\u05e7\u05d4. \u05e0\u05e8\u05d7\u05d9\u05d1 \u05e2\u05dc \u05d6\u05d4 \u05d1\u05e4\u05e8\u05e7 15."], [313.1, "\u05d5\u05d0\u05ea \u05db\u05de\u05d5\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05d3\u05d9\u05e4\u05e8\u05e7\u05e6\u05d9\u05d4 \u05e9\u05dc \u05e7\u05e8\u05e0\u05d9 \u05e8\u05e0\u05d8\u05d2\u05df."], [318.2, "\u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d9\u05dd \u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05dc\u05db\u05dc \u05e2\u05d5\u05d1\u05d9, \u05d0\u05d1\u05dc \u05de\u05e2\u05d5\u05d5\u05ea\u05d9\u05dd \u05d4\u05db\u05d9 \u05d4\u05e8\u05d1\u05d4."], [324.2, "\u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05e0\u05d5\u05ea\u05df \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05e6\u05e8\u05d9\u05da \u05d4\u05e8\u05e4\u05d9\u05d4."], [329.7, "\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05e0\u05d5\u05ea\u05df \u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05e7\u05e9\u05d9\u05d7 \u05d1\u05dc\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd."], [335.5, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"], [336.7, "\u05d0\u05de\u05d1\u05d8\u05d9 \u05de\u05dc\u05d7: \u05e6\u05e8\u05d9\u05da \u05de\u05ea\u05e7\u05df \u05d9\u05d9\u05e2\u05d5\u05d3\u05d9, \u05e9\u05d8\u05d9\u05e4\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05d1\u05e4\u05e1\u05d5\u05dc\u05ea, \u05d5\u05dc\u05d0 \u05db\u05dc \u05de\u05e4\u05e2\u05dc \u05de\u05d7\u05d6\u05d9\u05e7 \u05d0\u05d5\u05ea\u05dd."], [344.8, "\u05d6\u05de\u05df \u05d1\u05d0\u05de\u05d1\u05d8: \u05d1\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05d4\u05d7\u05dc\u05e7 \u05ea\u05d5\u05e4\u05e1 \u05d0\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05e2\u05d3 \u05e9\u05d4\u05d4\u05ea\u05de\u05e8\u05d4 \u05e0\u05d2\u05de\u05e8\u05ea. \u05de\u05e6\u05d3 \u05e9\u05e0\u05d9 \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d6\u05d4 \u05d9\u05d5\u05e6\u05d0 \u05d6\u05d5\u05dc \u05de\u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."], [356.1, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9: \u05e2\u05d5\u05d3 \u05e9\u05dc\u05d1, \u05e2\u05d5\u05d3 \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05d1\u05d3\u05d9\u05e7\u05ea \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9 \u05d1\u05e8\u05e0\u05d8\u05d2\u05df \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3."], [363.6, "\u05d0\u05d1\u05dc \u05d4\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d1\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05d1\u05d4\u05e9\u05d7\u05d6\u05d4: \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea, \u05e4\u05d7\u05d5\u05ea \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [370.7, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05de\u05e8\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05de\u05e9\u05d5\u05d5\u05d4 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05de\u05e7\u05d8\u05d9\u05df \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd."], [377.6, "\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2 \u05d4\u05d5\u05e4\u05da \u05d4\u05db\u05dc \u05dc\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05d1\u05d0\u05de\u05d1\u05d8 \u05d7\u05dd, \u05d1\u05dc\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4, \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd."], [383.8, "\u05d5\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05ea-\u05d0\u05e4\u05e1\u05d9 \u05de\u05e1\u05dc\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9, \u05db\u05e9\u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e7\u05e8\u05d9\u05d8\u05d9\u05ea."], [389.3, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d5\u05d1\u05dc\u05d4\u05d1\u05d4, \u05e9\u05de\u05e7\u05e9\u05d4 \u05e8\u05e7 \u05d0\u05ea \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05e6\u05e8\u05d9\u05da."]]};
window.MH_TR["ch11"]={"t": "\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d5\u05d1\u05dc\u05d4\u05d1\u05d4", "l": [[5.0, "\u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5 \u05d4\u05e7\u05e9\u05d9\u05e0\u05d5 \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7. \u05d0\u05d1\u05dc \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05e8\u05e7 \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e7\u05e9\u05d9\u05dd \u05dc\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d5\u05dc\u05d9\u05d1\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d4 \u05e9\u05e1\u05d5\u05e4\u05d2\u05ea \u05de\u05db\u05d5\u05ea."], [14.0, "\u05d2\u05dc \u05e2\u05dd \u05de\u05e1\u05d1\u05d9\u05dd, \u05e9\u05d9\u05e0\u05d9 \u05d2\u05dc\u05d2\u05dc, \u05de\u05e1\u05d9\u05dc\u05d4 \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d4: \u05e8\u05e7 \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05e2\u05d5\u05d1\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d4."], [21.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05ea\u05d9 \u05e9\u05d9\u05d8\u05d5\u05ea \u05e9\u05de\u05d7\u05de\u05de\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7: \u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d5\u05dc\u05d4\u05d1\u05d4."], [28.0, "\u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4, \u05e1\u05dc\u05d9\u05dc \u05e0\u05d7\u05d5\u05e9\u05ea \u05de\u05e7\u05d9\u05e3 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d5\u05e2\u05d5\u05d1\u05e8 \u05d1\u05d5 \u05d6\u05e8\u05dd \u05d7\u05d9\u05dc\u05d5\u05e4\u05d9\u05df \u05d1\u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."], [35.1, "\u05d4\u05e9\u05d3\u05d4 \u05d4\u05de\u05d2\u05e0\u05d8\u05d9 \u05e9\u05dc \u05d4\u05e1\u05dc\u05d9\u05dc \u05de\u05e9\u05e8\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d6\u05e8\u05de\u05d9\u05dd \u05de\u05e2\u05d2\u05dc\u05d9\u05d9\u05dd, \u05d6\u05e8\u05de\u05d9 \u05de\u05e2\u05e8\u05d1\u05d5\u05dc\u05ea, \u05d5\u05d4\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05de\u05d1\u05e4\u05e0\u05d9\u05dd."], [43.0, "\u05d4\u05d6\u05e8\u05de\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05de\u05ea\u05e8\u05db\u05d6\u05d9\u05dd \u05dc\u05d9\u05d3 \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. \u05d6\u05d5 \u05ea\u05d5\u05e4\u05e2\u05ea \u05d4\u05e2\u05d5\u05e8."], [47.8, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05de\u05ea\u05d7\u05de\u05de\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05ea\u05d5\u05da \u05e9\u05e0\u05d9\u05d5\u05ea \u05e1\u05e4\u05d5\u05e8\u05d5\u05ea, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d4 \u05dc\u05d4\u05ea\u05d7\u05de\u05dd."], [54.1, "\u05de\u05d9\u05d3 \u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05e7\u05dc\u05d7\u05ea \u05e9\u05dc \u05de\u05d9\u05dd \u05d0\u05d5 \u05e4\u05d5\u05dc\u05d9\u05de\u05e8 \u05de\u05db\u05d1\u05d4 \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [60.6, "\u05d5\u05d4\u05e1\u05dc\u05d9\u05dc \u05e2\u05e6\u05de\u05d5? \u05e6\u05d9\u05e0\u05d5\u05e8 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d7\u05dc\u05d5\u05dc, \u05e9\u05de\u05d9\u05dd \u05e7\u05e8\u05d9\u05dd \u05d6\u05d5\u05e8\u05de\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d5."], [66.6, "\u05de\u05d4 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7? \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d4\u05ea\u05d3\u05d9\u05e8\u05d5\u05ea."], [70.2, "\u05db\u05db\u05dc \u05e9\u05d4\u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d6\u05e8\u05dd \u05e0\u05e6\u05de\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."], [76.7, "\u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, 1 \u05e2\u05d3 10 \u05e7\u05d9\u05dc\u05d5\u05d4\u05e8\u05e5, \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05e2\u05de\u05d5\u05e7\u05d5\u05ea. \u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4, 100 \u05e2\u05d3 500 \u05e7\u05d9\u05dc\u05d5\u05d4\u05e8\u05e5, \u05dc\u05e9\u05db\u05d1\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea."], [88.5, "\u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05d4\u05d0\u05d5\u05e4\u05d9\u05d9\u05e0\u05d9\u05d5\u05ea \u05d4\u05df \u05d1\u05d9\u05df \u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05dc\u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [93.1, "\u05d2\u05dd \u05d4\u05d4\u05e1\u05e4\u05e7 \u05d5\u05d6\u05de\u05df \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05e9\u05e4\u05d9\u05e2\u05d9\u05dd: \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df, \u05d9\u05d5\u05ea\u05e8 \u05d7\u05d5\u05dd \u05d6\u05d5\u05e8\u05dd \u05e4\u05e0\u05d9\u05de\u05d4, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."], [101.4, "\u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3."], [103.9, "\u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d4\u05e1\u05dc\u05d9\u05dc \u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d4\u05d7\u05dc\u05e7 \u05de\u05e1\u05ea\u05d5\u05d1\u05d1 \u05d1\u05ea\u05d5\u05db\u05d5, \u05d5\u05d0\u05d6 \u05de\u05db\u05d1\u05d9\u05dd \u05d4\u05db\u05dc \u05d9\u05d7\u05d3."], [112.0, "\u05d1\u05e1\u05e8\u05d9\u05e7\u05d4, \u05e1\u05dc\u05d9\u05dc \u05e7\u05e6\u05e8 \u05e0\u05e2 \u05dc\u05d0\u05d5\u05e8\u05da \u05d4\u05d2\u05dc, \u05d5\u05de\u05e7\u05dc\u05d7\u05ea \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e6\u05de\u05d5\u05d3\u05d4 \u05d0\u05dc\u05d9\u05d5 \u05de\u05d0\u05d7\u05d5\u05e8. \u05db\u05da \u05de\u05e7\u05e9\u05d9\u05dd \u05d2\u05dc\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd."], [120.9, "\u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d0\u05ea \u05db\u05dc \u05d4\u05d4\u05d9\u05e7\u05e3 \u05d1\u05d1\u05ea \u05d0\u05d7\u05ea, \u05d0\u05d5 \u05e9\u05df \u05d0\u05d7\u05e8\u05d9 \u05e9\u05df."], [127.4, "\u05d0\u05d9\u05dc\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea? \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9, \u05d1\u05e2\u05e8\u05da 0.35 \u05e2\u05d3 0.55 \u05d0\u05d7\u05d5\u05d6, \u05db\u05de\u05d5 1045, 4140 \u05d5-4340."], [141.4, "\u05d4\u05e4\u05d7\u05de\u05df \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. \u05d1-1045 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d1\u05e2\u05e8\u05da 50 \u05e2\u05d3 58 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [150.3, "\u05d2\u05dd \u05de\u05d1\u05e0\u05d4 \u05d4\u05de\u05d5\u05e6\u05d0 \u05d7\u05e9\u05d5\u05d1: \u05e4\u05dc\u05d3\u05d4 \u05de\u05e9\u05d5\u05e4\u05e8\u05ea, \u05e2\u05dd \u05de\u05d1\u05e0\u05d4 \u05e2\u05d3\u05d9\u05df \u05d5\u05d0\u05d7\u05d9\u05d3, \u05de\u05d2\u05d9\u05d1\u05d4 \u05d4\u05db\u05d9 \u05d8\u05d5\u05d1."], [157.1, "\u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05e7\u05e6\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05d0\u05d9\u05df \u05d4\u05e8\u05d1\u05d4 \u05d6\u05de\u05df \u05dc\u05d4\u05ea\u05de\u05d5\u05e1\u05e1. \u05dc\u05db\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d0\u05e9\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8."], [165.7, "\u05d5\u05db\u05e9\u05d4\u05db\u05dc \u05e0\u05e2\u05e9\u05d4 \u05e0\u05db\u05d5\u05df, \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e7\u05e9\u05d9\u05dd \u05de\u05e2\u05dc \u05dc\u05d9\u05d1\u05d4 \u05de\u05e9\u05d5\u05e4\u05e8\u05ea \u05d5\u05e7\u05e9\u05d9\u05d7\u05d4."], [172.5, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05d4\u05d5\u05d0 \u05de\u05d0\u05de\u05e6\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4."], [175.3, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05e9\u05d4\u05e4\u05db\u05d4 \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05de\u05ea\u05e0\u05e4\u05d7\u05ea, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05d0\u05d5\u05ea\u05d4. \u05db\u05da \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05de\u05e6\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4."], [183.2, "\u05de\u05d0\u05de\u05e6\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4 \u05de\u05e2\u05db\u05d1\u05d9\u05dd \u05e1\u05d3\u05e7\u05d9 \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea. \u05dc\u05db\u05df \u05d2\u05dc\u05d9\u05dd \u05d5\u05d2\u05dc\u05d9 \u05d0\u05e8\u05db\u05d5\u05d1\u05d4 \u05e9\u05d4\u05d5\u05e7\u05e9\u05d5 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df."], [192.2, "\u05d0\u05d1\u05dc \u05de\u05ea\u05d7\u05ea \u05dc\u05e9\u05db\u05d1\u05d4, \u05d1\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05e2\u05d1\u05e8, \u05d9\u05e9 \u05de\u05d0\u05de\u05e6\u05d9 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05de\u05d0\u05d6\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd. \u05dc\u05db\u05df \u05dc\u05d0 \u05de\u05e1\u05d9\u05d9\u05de\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d4\u05e2\u05d5\u05de\u05e1 \u05de\u05e8\u05d5\u05db\u05d6."], [203.0, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4, \u05d5\u05d4\u05d5\u05d5\u05ea\u05d9\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d9\u05d0 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05dc\u05d4\u05d1\u05d4."], [207.8, "\u05de\u05d1\u05e2\u05e8 \u05e9\u05dc \u05d7\u05de\u05e6\u05df \u05d5\u05d0\u05e6\u05d8\u05d9\u05dc\u05df, \u05d0\u05d5 \u05d2\u05d6 \u05d0\u05d7\u05e8, \u05de\u05d7\u05de\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9\u05d5 \u05de\u05e7\u05dc\u05d7\u05ea \u05e9\u05dc \u05de\u05d9\u05dd \u05d0\u05d5 \u05e4\u05d5\u05dc\u05d9\u05de\u05e8."], [217.0, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05de\u05dd \u05e0\u05e7\u05d5\u05d3\u05d4 \u05d0\u05d7\u05ea, \u05dc\u05e1\u05e8\u05d5\u05e7 \u05dc\u05d0\u05d5\u05e8\u05da \u05de\u05e9\u05d8\u05d7, \u05d0\u05d5 \u05dc\u05e1\u05d5\u05d1\u05d1 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05de\u05d5\u05dc \u05d4\u05de\u05d1\u05e2\u05e8."], [223.4, "\u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05d1\u05dc\u05d4\u05d1\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05de\u05d5\u05e7\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4."], [227.5, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df: \u05e6\u05d9\u05d5\u05d3 \u05d6\u05d5\u05dc \u05d5\u05e0\u05d9\u05d9\u05d3, \u05e9\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05d5 \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05e2\u05e0\u05e7\u05d9\u05d9\u05dd, \u05de\u05e1\u05d9\u05dc\u05d5\u05ea \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea."], [235.9, "\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05e4\u05d7\u05d5\u05ea \u05e9\u05dc\u05d9\u05d8\u05d4. \u05d4\u05e2\u05d5\u05de\u05e7 \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05ea\u05dc\u05d5\u05d9\u05d9\u05dd \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea, \u05d1\u05de\u05e8\u05d7\u05e7 \u05e9\u05dc \u05d4\u05de\u05d1\u05e2\u05e8, \u05d5\u05d1\u05de\u05e4\u05e2\u05d9\u05dc."], [244.3, "\u05de\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05d1\u05e9?"], [245.9, "\u05d7\u05d5\u05e8\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e6\u05d9 \u05e9\u05d2\u05dd \u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05de\u05e9\u05d1\u05e9\u05d9\u05dd \u05d0\u05ea \u05d6\u05e8\u05de\u05d9 \u05d4\u05d7\u05d9\u05de\u05d5\u05dd. \u05d4\u05e4\u05d9\u05e0\u05d5\u05ea \u05de\u05ea\u05d7\u05de\u05de\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9, \u05d5\u05e9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e1\u05d3\u05e7\u05d9\u05dd."], [254.7, "\u05dc\u05db\u05df \u05de\u05e2\u05d2\u05dc\u05d9\u05dd \u05e4\u05d9\u05e0\u05d5\u05ea, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05e8\u05d7\u05e7 \u05d1\u05d9\u05df \u05e7\u05e6\u05d4 \u05d4\u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05d9\u05df \u05d7\u05d5\u05e8\u05d9\u05dd \u05d5\u05db\u05ea\u05e4\u05d9\u05d9\u05dd."], [260.6, "\u05d1\u05e1\u05d5\u05e3 \u05de\u05e1\u05dc\u05d5\u05dc \u05e1\u05e8\u05d9\u05e7\u05d4, \u05d0\u05d5 \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05e9\u05ea\u05d9 \u05e9\u05db\u05d1\u05d5\u05ea \u05e0\u05e4\u05d2\u05e9\u05d5\u05ea, \u05e0\u05d5\u05e6\u05e8 \u05e4\u05e1 \u05e8\u05da \u05e9\u05d4\u05d5\u05e8\u05e4\u05d4 \u05de\u05d7\u05d3\u05e9."], [268.0, "\u05d5\u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d0\u05d5 \u05d1\u05e1\u05dc\u05d9\u05dc \u05e2\u05e6\u05de\u05d5. \u05e2\u05d9\u05db\u05d5\u05d1 \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d5\u05d0 \u05d0\u05d7\u05ea \u05d4\u05e1\u05d9\u05d1\u05d5\u05ea \u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [277.9, "\u05d0\u05d9\u05da \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d6\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8?"], [280.0, "\u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d0\u05ea \u05d0\u05d6\u05d5\u05e8 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d5\u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9."], [286.0, "\u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05e2\u05d5\u05de\u05e7 \u05e9\u05d1\u05d5 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc-80 \u05d0\u05d7\u05d5\u05d6 \u05de\u05e7\u05e9\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9\u05ea, \u05dc\u05e4\u05d9 ISO 18203."], [295.9, "\u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc \u05d7\u05dc\u05e7 \u05dc\u05d3\u05d5\u05d2\u05de\u05d4: \u05d7\u05d5\u05ea\u05db\u05d9\u05dd, \u05de\u05dc\u05d8\u05e9\u05d9\u05dd, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05de\u05d9\u05e7\u05e8\u05d5-\u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05e0\u05d9\u05de\u05d4."], [303.9, "\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4: \u05de\u05d4\u05d9\u05e8\u05d4, \u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05d5\u05d7\u05d5\u05d6\u05e8\u05ea \u05e2\u05dc \u05e2\u05e6\u05de\u05d4, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05e1\u05dc\u05d9\u05dc \u05dc\u05db\u05dc \u05d7\u05dc\u05e7."], [310.1, "\u05dc\u05d4\u05d1\u05d4: \u05d2\u05de\u05d9\u05e9\u05d4 \u05d5\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d4\u05ea\u05d7\u05dc\u05d4, \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d0\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4."], [317.2, "\u05d5\u05e9\u05ea\u05d9\u05d4\u05df \u05de\u05e2\u05d5\u05d5\u05ea\u05d5\u05ea \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05de\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e9\u05dc \u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05db\u05d9 \u05e8\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05ea \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9."], [325.0, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"], [326.3, "\u05d4\u05e1\u05dc\u05d9\u05dc: \u05dc\u05db\u05dc \u05e6\u05d5\u05e8\u05ea \u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05e1\u05dc\u05d9\u05dc \u05de\u05e9\u05dc\u05d5, \u05e9\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d5\u05d1\u05d5\u05e0\u05d9\u05dd. \u05d1\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea, \u05d4\u05e1\u05dc\u05d9\u05dc \u05d4\u05d5\u05d0 \u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e2\u05dc\u05d5\u05ea."], [336.0, "\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05d5\u05e8\u05e1\u05ea: \u05db\u05d3\u05d9 \u05dc\u05d0\u05e9\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d7\u05dc\u05e7 \u05d0\u05de\u05d9\u05ea\u05d9, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05d9\u05e7\u05e8 \u05d6\u05d4 \u05de\u05d7\u05d9\u05e8 \u05de\u05e9\u05de\u05e2\u05d5\u05ea\u05d9."], [344.0, "\u05d2\u05d0\u05d5\u05de\u05d8\u05e8\u05d9\u05d4 \u05de\u05e1\u05d5\u05d1\u05db\u05ea: \u05d7\u05d5\u05e8\u05d9\u05dd, \u05d7\u05e8\u05d9\u05e6\u05d9\u05dd \u05d5\u05db\u05ea\u05e4\u05d9\u05d9\u05dd \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05db\u05d9\u05d5\u05d5\u05e0\u05d5\u05df \u05d5\u05e0\u05d9\u05e1\u05d5\u05d9\u05d9\u05dd."], [350.1, "\u05d5\u05d1\u05dc\u05d4\u05d1\u05d4 \u05d4\u05e6\u05d9\u05d5\u05d3 \u05d6\u05d5\u05dc, \u05d0\u05d1\u05dc \u05e9\u05e2\u05d5\u05ea \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d5\u05d4\u05d1\u05e7\u05e8\u05d4 \u05d9\u05e7\u05e8\u05d5\u05ea."], [355.7, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d5\u05dc\u05d4\u05d1\u05d4 \u05de\u05e7\u05e9\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d5\u05ea \u05dc\u05d9\u05d1\u05d4 \u05e7\u05e9\u05d9\u05d7\u05d4."], [362.3, "\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d4\u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7, \u05d5\u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05dc\u05d7\u05d9\u05e6\u05d4 \u05de\u05e9\u05e4\u05e8\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [369.6, "\u05d4\u05dc\u05d4\u05d1\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05dc\u05db\u05de\u05d5\u05d9\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea."], [373.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05db\u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05db\u05da \u05d2\u05dd \u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea."]]};
window.MH_TR["ch12"]={"t": "\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d5\u05e7\u05e8\u05d1\u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd \u05d4\u05e7\u05e9\u05d9\u05e0\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9. \u05d0\u05d1\u05dc \u05de\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05e2\u05dd \u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05e9\u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4?"], [14.4, "\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d4 \u05e4\u05d7\u05de\u05df, \u05e8\u05e7 \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [17.6, "\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4. \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05e9\u05db\u05d1\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d4 \u05d1\u05e4\u05d7\u05de\u05df \u05e9\u05de\u05ea\u05e7\u05e9\u05d4, \u05de\u05e2\u05dc \u05dc\u05d9\u05d1\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05e7\u05e9\u05d9\u05d7\u05d4 \u05d5\u05d7\u05d6\u05e7\u05d4."], [27.6, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1-925 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e2\u05e9\u05d9\u05e8\u05d4 \u05d1\u05e4\u05d7\u05de\u05df."], [35.0, "\u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6, \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05de\u05d2\u05d6\u05d9\u05dd \u05db\u05de\u05d5 \u05de\u05ea\u05d0\u05df \u05d0\u05d5 \u05e4\u05e8\u05d5\u05e4\u05d0\u05df, \u05d5\u05de\u05d1\u05e7\u05e8\u05d9\u05dd \u05d1\u05d4 \u05d0\u05ea \u05e4\u05d5\u05d8\u05e0\u05e6\u05d9\u05d0\u05dc \u05d4\u05e4\u05d7\u05de\u05df."], [42.9, "\u05d4\u05e4\u05d7\u05de\u05df \u05d7\u05d5\u05d3\u05e8 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05e0\u05d9\u05de\u05d4 \u05d1\u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05de\u05e4\u05dc: \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d1\u05d7\u05d5\u05e5, \u05d5\u05e4\u05d7\u05d5\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05dc\u05d9\u05d1\u05d4."], [52.1, "\u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05db\u05d5\u05d5\u05e0\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 0.7 \u05e2\u05d3 0.8 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df. \u05d9\u05d5\u05ea\u05e8 \u05de\u05d6\u05d4 \u05db\u05d1\u05e8 \u05dc\u05d0 \u05de\u05d5\u05e1\u05d9\u05e3 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05d9\u05db\u05d5\u05dc \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05d5\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9."], [64.7, "\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05db\u05d1\u05d9\u05dd, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e9\u05de\u05df, \u05d5\u05de\u05e8\u05e4\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 180 \u05de\u05e2\u05dc\u05d5\u05ea."], [72.5, "\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc-57 \u05e2\u05d3 63 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05e9\u05d9\u05d7\u05d4."], [79.8, "\u05db\u05de\u05d4 \u05d6\u05de\u05df \u05d6\u05d4 \u05dc\u05d5\u05e7\u05d7? \u05d4\u05e2\u05d5\u05de\u05e7 \u05d2\u05d3\u05dc \u05dc\u05e4\u05d9 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05d4\u05e8\u05d9\u05d1\u05d5\u05e2\u05d9 \u05e9\u05dc \u05d4\u05d6\u05de\u05df."], [85.3, "\u05db\u05dc\u05d5\u05de\u05e8, \u05db\u05d3\u05d9 \u05dc\u05d4\u05db\u05e4\u05d9\u05dc \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05e6\u05e8\u05d9\u05da \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d6\u05de\u05df."], [89.6, "\u05d1-925 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05db\u05d1\u05d4 \u05e9\u05dc \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d0\u05d7\u05d3 \u05dc\u05d5\u05e7\u05d7\u05ea \u05d1\u05e2\u05e8\u05da \u05e9\u05e2\u05ea\u05d9\u05d9\u05dd, \u05d5\u05e9\u05db\u05d1\u05d4 \u05e9\u05dc 4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc-36 \u05e9\u05e2\u05d5\u05ea."], [100.0, "\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e7\u05e6\u05e8\u05ea \u05d0\u05ea \u05d4\u05d6\u05de\u05df, \u05d5\u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05e2\u05d3 1,050 \u05de\u05e2\u05dc\u05d5\u05ea. \u05d0\u05d1\u05dc \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05d2\u05d3\u05dc."], [110.0, "\u05dc\u05db\u05df \u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d5\u05d0 \u05d4\u05d2\u05d5\u05e8\u05dd \u05d4\u05d2\u05d3\u05d5\u05dc \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05de\u05d7\u05d9\u05e8."], [114.7, "\u05d0\u05d9\u05da \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7?"], [116.6, "\u05dc\u05e4\u05d9 ISO 2639, \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05d4\u05d5\u05d0 \u05d4\u05de\u05e8\u05d7\u05e7 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e2\u05d3 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc-550 \u05d5\u05d9\u05e7\u05e8\u05e1."], [127.5, "\u05d1\u05ea\u05e7\u05e0\u05d9\u05dd \u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9\u05d9\u05dd \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05e2\u05d3 50 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05e9\u05d6\u05d4 \u05d1\u05e2\u05e8\u05da 513 \u05d5\u05d9\u05e7\u05e8\u05e1. \u05dc\u05db\u05df \u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7 \u05d9\u05e7\u05d1\u05dc \u05e9\u05dd \u05e2\u05d5\u05de\u05e7 \u05e7\u05e6\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d2\u05d3\u05d5\u05dc."], [138.6, "\u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05db\u05d5\u05dc\u05dc, \u05e2\u05d3 \u05e9\u05d4\u05e4\u05d7\u05de\u05df \u05d7\u05d5\u05d6\u05e8 \u05dc\u05e8\u05de\u05d4 \u05e9\u05dc \u05d4\u05dc\u05d9\u05d1\u05d4, \u05d2\u05d3\u05d5\u05dc \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05d0\u05d7\u05d3 \u05d5\u05d7\u05e6\u05d9."], [145.7, "\u05d5\u05d7\u05e9\u05d5\u05d1: \u05d0\u05ea \u05d4\u05e2\u05d5\u05de\u05e7 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e1\u05d5\u05e4\u05d9. \u05d0\u05dd \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc, \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05dc\u05e2\u05d5\u05de\u05e7 \u05e9\u05de\u05d6\u05de\u05d9\u05e0\u05d9\u05dd."], [155.1, "\u05d0\u05d9\u05dc\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea? \u05e4\u05dc\u05d3\u05d5\u05ea \u05d3\u05dc\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05d1\u05e2\u05e8\u05da 0.15 \u05e2\u05d3 0.25 \u05d0\u05d7\u05d5\u05d6."], [163.7, "\u05d1\u05d0\u05e8\u05e6\u05d5\u05ea \u05d4\u05d1\u05e8\u05d9\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 8620. \u05d1\u05d0\u05d9\u05e8\u05d5\u05e4\u05d4 16MnCr5 \u05d5-20MnCr5, \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05d1\u05d3\u05d9\u05dd 18CrNiMo7-6."], [178.3, "\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d0\u05d1\u05dc \u05d4\u05d9\u05d0 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05d5\u05d0\u05ea \u05d4\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d7\u05ea\u05db\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd."], [186.5, "\u05dc\u05db\u05df \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05dc\u05e4\u05d9 \u05d2\u05d5\u05d3\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d5\u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05de\u05e1 \u05e2\u05dc \u05d4\u05dc\u05d9\u05d1\u05d4."], [191.7, "\u05d5\u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9: \u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05d1\u05ea\u05d9\u05d1\u05d5\u05ea \u05d4\u05d9\u05dc\u05d5\u05db\u05d9\u05dd."], [196.3, "\u05e7\u05e8\u05d1\u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6, \u05e9\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05dc\u05d4 \u05d0\u05de\u05d5\u05e0\u05d9\u05d4."], [201.5, "\u05d4\u05d0\u05de\u05d5\u05e0\u05d9\u05d4 \u05de\u05ea\u05e4\u05e8\u05e7\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05d7\u05e0\u05e7\u05df \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05d4\u05e4\u05d7\u05de\u05df."], [207.2, "\u05d4\u05d9\u05d0 \u05e0\u05e2\u05e9\u05d9\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d1\u05e2\u05e8\u05da 790 \u05e2\u05d3 845 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05d9\u05d5\u05ea\u05e8."], [215.6, "\u05dc\u05db\u05df \u05d4\u05e9\u05db\u05d1\u05d4 \u05e8\u05d3\u05d5\u05d3\u05d4 \u05d9\u05d5\u05ea\u05e8: \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 0.075 \u05dc-0.75 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [224.2, "\u05d4\u05d7\u05e0\u05e7\u05df \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d9\u05db\u05d5\u05dc\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05e9\u05dc \u05d4\u05e9\u05db\u05d1\u05d4. \u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05db\u05d1\u05d5\u05ea \u05d1\u05e9\u05de\u05df \u05d2\u05dd \u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e4\u05e9\u05d5\u05d8\u05d4, \u05d5\u05dc\u05e7\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea."], [232.8, "\u05d4\u05d9\u05d0 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05e1\u05d3\u05e8\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea: \u05d1\u05e8\u05d2\u05d9\u05dd, \u05e4\u05d9\u05e0\u05d9\u05dd \u05d5\u05d7\u05dc\u05e7\u05d9 \u05de\u05e0\u05d2\u05e0\u05d5\u05e0\u05d9\u05dd."], [238.8, "\u05d5\u05d4\u05d9\u05d0 \u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05dc\u05d7\u05d9\u05e6\u05d4 \u05d1\u05e9\u05db\u05d1\u05d4, \u05d5\u05d6\u05d4 \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05de\u05d2\u05e2."], [244.8, "\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05d8\u05d7 \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d1\u05dc \u05e4\u05d7\u05de\u05df: \u05d4\u05d1\u05e8\u05d2\u05d4 \u05e9\u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e7\u05e9\u05d9\u05d7\u05d4, \u05de\u05e7\u05d5\u05dd \u05dc\u05e8\u05d9\u05ea\u05d5\u05da, \u05d0\u05d5 \u05d0\u05d6\u05d5\u05e8 \u05e9\u05e2\u05d5\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05e2\u05d1\u05d3."], [254.2, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05de\u05d5\u05db\u05e8\u05ea \u05d4\u05d9\u05d0 \u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05d7\u05d5\u05e9\u05ea. \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea \u05d7\u05d5\u05e1\u05de\u05ea \u05d0\u05ea \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05de\u05e6\u05d5\u05e4\u05d4 \u05dc\u05d0 \u05de\u05ea\u05e4\u05d7\u05de\u05df."], [261.9, "\u05e9\u05d9\u05d8\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05e6\u05d1\u05e2 \u05de\u05d9\u05e1\u05d5\u05da, \u05e9\u05de\u05d5\u05e8\u05d7\u05d9\u05dd \u05e2\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [267.1, "\u05d5\u05d9\u05e9 \u05d3\u05e8\u05da \u05e9\u05dc\u05d9\u05e9\u05d9\u05ea: \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05d1\u05d0\u05d6\u05d5\u05e8, \u05de\u05e6\u05de\u05e0\u05d8\u05d9\u05dd, \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05de\u05e7\u05e9\u05d9\u05dd."], [276.4, "\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05d1\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05dc\u05d5 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05de\u05e6\u05de\u05e0\u05d8\u05d9\u05dd \u05d5\u05d0\u05d9\u05dc\u05d5 \u05dc\u05d0."], [281.3, "\u05de\u05d9\u05e1\u05d5\u05da \u05d4\u05d5\u05d0 \u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05d4\u05d5\u05d0 \u05de\u05d5\u05e1\u05d9\u05e3 \u05d4\u05e8\u05d1\u05d4 \u05dc\u05e2\u05dc\u05d5\u05ea."], [287.4, "\u05de\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05d1\u05e9?"], [289.1, "\u05e4\u05d7\u05de\u05df \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05e9\u05d0\u05d9\u05e8 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9, \u05d5\u05de\u05d5\u05e8\u05d9\u05d3 \u05e7\u05e9\u05d9\u05d5\u05ea."], [294.5, "\u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 \u05e0\u05d5\u05e6\u05e8 \u05d7\u05de\u05e6\u05d5\u05df \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd, \u05e9\u05de\u05d7\u05dc\u05d9\u05e9 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df \u05d0\u05ea \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05d6\u05d5."], [303.8, "\u05d4\u05d7\u05dc\u05e7 \u05e2\u05d5\u05d1\u05e8 \u05d7\u05d9\u05de\u05d5\u05dd \u05d0\u05e8\u05d5\u05da \u05d5\u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea. \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4."], [310.1, "\u05d5\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d2\u05e8\u05e1\u05d9\u05d1\u05d9\u05ea \u05de\u05d3\u05d9 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e9\u05e8\u05d5\u05e3 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d0\u05d5 \u05dc\u05d4\u05d5\u05e8\u05d9\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05de\u05d4\u05e9\u05db\u05d1\u05d4."], [316.7, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"], [318.0, "\u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4: \u05e4\u05d9 \u05e9\u05e0\u05d9\u05d9\u05dd \u05e2\u05d5\u05de\u05e7 \u05d6\u05d4 \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d6\u05de\u05df \u05d1\u05ea\u05e0\u05d5\u05e8."], [323.3, "\u05de\u05d9\u05e1\u05d5\u05da: \u05e0\u05d7\u05d5\u05e9\u05ea \u05d0\u05d5 \u05e6\u05d1\u05e2, \u05d5\u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3 \u05dc\u05d4\u05e1\u05e8\u05d4."], [328.0, "\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc: \u05e2\u05dc \u05d7\u05dc\u05e7 \u05e7\u05e9\u05d4, \u05d5\u05d1\u05d6\u05d4\u05d9\u05e8\u05d5\u05ea."], [332.6, "\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea: \u05d3\u05d2\u05d9\u05de\u05ea \u05e2\u05d3\u05d5\u05ea \u05e9\u05e0\u05d7\u05ea\u05db\u05ea \u05d5\u05e0\u05de\u05d3\u05d3\u05ea \u05d1\u05db\u05dc \u05e2\u05d5\u05de\u05e1."], [338.2, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e4\u05d7\u05de\u05df \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d3\u05dc\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05d0\u05d6 \u05de\u05db\u05d1\u05d9\u05dd \u05d5\u05de\u05e8\u05e4\u05d9\u05dd."], [346.5, "\u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05e0\u05de\u05d3\u05d3 \u05e2\u05d3 550 \u05d5\u05d9\u05e7\u05e8\u05e1, \u05d5\u05d4\u05d6\u05de\u05df \u05d2\u05d3\u05dc \u05d1\u05e8\u05d9\u05d1\u05d5\u05e2 \u05e9\u05dc \u05d4\u05e2\u05d5\u05de\u05e7."], [353.8, "\u05e7\u05e8\u05d1\u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d2\u05dd \u05d7\u05e0\u05e7\u05df, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d5\u05dc\u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d9\u05d5\u05ea\u05e8."], [359.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d5\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05dc\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."]]};
window.MH_TR["ch13"]={"t": "\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d5\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4", "l": [[5.0, "\u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d5\u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05d2\u05d9\u05e2\u05d4 \u05de\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8: \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05de\u05db\u05d1\u05d9\u05dd. \u05d5\u05d1\u05db\u05d9\u05d1\u05d5\u05d9 \u05d9\u05e9 \u05e2\u05d9\u05d5\u05d5\u05ea."], [14.2, "\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d0\u05d7\u05e8\u05ea: \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d7\u05e0\u05e7\u05df \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05dc\u05d9 \u05dc\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05d1\u05dc\u05d9 \u05dc\u05db\u05d1\u05d5\u05ea."], [22.6, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4, \u05d5\u05d2\u05dd \u05d0\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4, \u05d4\u05d2\u05e8\u05e1\u05d4 \u05d4\u05e7\u05e6\u05e8\u05d4 \u05e9\u05dc\u05d4."], [33.9, "\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d9\u05df 495 \u05dc-565 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05dc \u05d0\u05de\u05d5\u05e0\u05d9\u05d4."], [42.5, "\u05d4\u05d0\u05de\u05d5\u05e0\u05d9\u05d4 \u05de\u05ea\u05e4\u05e8\u05e7\u05ea \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d4\u05d7\u05e0\u05e7\u05df \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d4 \u05d1\u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4."], [47.8, "\u05e9\u05dd \u05d4\u05d5\u05d0 \u05e0\u05e7\u05e9\u05e8 \u05dc\u05db\u05e8\u05d5\u05dd, \u05dc\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05dc\u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05d5\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05d5\u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [55.6, "\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d5\u05d4\u05e4\u05dc\u05d3\u05d4 \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8. \u05d0\u05d9\u05df \u05e9\u05d9\u05e0\u05d5\u05d9 \u05e4\u05d0\u05d6\u05d4 \u05d5\u05d0\u05d9\u05df \u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df \u05e2\u05d9\u05d5\u05d5\u05ea."], [64.4, "\u05d4\u05d7\u05dc\u05e7 \u05d2\u05d3\u05dc \u05e8\u05e7 \u05d1\u05db\u05de\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd, \u05d5\u05d1\u05e6\u05d5\u05e8\u05d4 \u05e6\u05e4\u05d5\u05d9\u05d4. \u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05dc\u05de\u05d9\u05d3\u05d4 \u05e1\u05d5\u05e4\u05d9\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [72.1, "\u05d5\u05d1\u05e7\u05e8\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4: \u05d1\u05e2\u05e8\u05da \u05d7\u05de\u05e9 \u05de\u05e2\u05dc\u05d5\u05ea \u05dc\u05db\u05dc \u05db\u05d9\u05d5\u05d5\u05df \u05de\u05d4\u05e2\u05e8\u05da \u05e9\u05e0\u05e7\u05d1\u05e2."], [78.5, "\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05d6\u05d4 \u05d0\u05d9\u05d8\u05d9. \u05de\u05d7\u05d6\u05d5\u05e8 \u05e0\u05de\u05e9\u05da \u05d1\u05d9\u05df 10 \u05dc-130 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05d0 \u05e2\u05de\u05d5\u05e7\u05d4 \u05de\u05d7\u05e6\u05d9 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [88.1, "\u05d1\u05d7\u05ea\u05da \u05de\u05ea\u05d7\u05ea \u05dc\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4 \u05e8\u05d5\u05d0\u05d9\u05dd \u05e9\u05e0\u05d9 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd."], [91.7, "\u05dc\u05de\u05e2\u05dc\u05d4, \u05e9\u05db\u05d1\u05ea \u05d4\u05ea\u05e8\u05db\u05d5\u05d1\u05ea. \u05e7\u05d5\u05e8\u05d0\u05d9\u05dd \u05dc\u05d4 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4, \u05db\u05d9 \u05d0\u05d7\u05e8\u05d9 \u05d0\u05d9\u05db\u05d5\u05dc \u05d1\u05e0\u05d9\u05d8\u05dc \u05d4\u05d9\u05d0 \u05e0\u05e9\u05d0\u05e8\u05ea \u05dc\u05d1\u05e0\u05d4."], [99.4, "\u05d4\u05d9\u05d0 \u05e2\u05e9\u05d5\u05d9\u05d4 \u05de\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9 \u05d1\u05e8\u05d6\u05dc, \u05d0\u05e4\u05e1\u05d9\u05dc\u05d5\u05df \u05d5\u05d2\u05de\u05d0 \u05e4\u05e8\u05d9\u05d9\u05dd, \u05d5\u05e2\u05d5\u05d1\u05d9\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc 5 \u05e2\u05d3 30 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."], [106.7, "\u05de\u05ea\u05d7\u05ea\u05d9\u05d4 \u05d0\u05d6\u05d5\u05e8 \u05d4\u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4: \u05d7\u05e0\u05e7\u05df \u05de\u05d5\u05de\u05e1 \u05d5\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d0\u05ea \u05e8\u05d5\u05d1 \u05d4\u05e2\u05d5\u05de\u05e7 \u05e9\u05dc \u05d4\u05e9\u05db\u05d1\u05d4."], [114.2, "\u05d4\u05d7\u05e0\u05e7\u05df \u05de\u05e8\u05d7\u05d9\u05d1 \u05d0\u05ea \u05d4\u05e1\u05e8\u05d9\u05d2 \u05d1\u05e9\u05db\u05d1\u05d4, \u05d5\u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d4 \u05de\u05d0\u05de\u05e6\u05d9 \u05dc\u05d7\u05d9\u05e6\u05d4. \u05dc\u05db\u05df \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05e9\u05e4\u05e8\u05ea \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [123.1, "\u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc\u05d4 \u05d2\u05dd \u05d1\u05d7\u05d5\u05dd, \u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4."], [128.6, "\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d1\u05d2\u05dc\u05d9 \u05d0\u05e8\u05db\u05d5\u05d1\u05d4, \u05d1\u05d1\u05e8\u05d2\u05d9\u05dd \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05d6\u05e8\u05e7\u05d4 \u05d5\u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea."], [136.4, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d5\u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d0\u05d1\u05dc \u05e4\u05e8\u05d9\u05db\u05d4. \u05e9\u05db\u05d1\u05d4 \u05e2\u05d1\u05d4 \u05de\u05d3\u05d9 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05ea\u05e7\u05dc\u05e3."], [145.0, "\u05dc\u05db\u05df \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4."], [147.9, "\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d3\u05d5-\u05e9\u05dc\u05d1\u05d9\u05ea, \u05d0\u05d7\u05e8\u05d9 \u05e9\u05dc\u05d1 \u05e8\u05d0\u05e9\u05d5\u05df \u05e7\u05e6\u05e8 \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05e4\u05d5\u05d8\u05e0\u05e6\u05d9\u05d0\u05dc \u05d4\u05d7\u05e0\u05e7\u05df, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05d3\u05e7\u05d4."], [156.2, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05e2\u05d5\u05de\u05e1 \u05de\u05d2\u05e2 \u05db\u05d1\u05d3, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d9\u05d8\u05d5\u05e9."], [162.1, "\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d3\u05d9\u05e8 \u05e2\u05d5\u05d1\u05d9 \u05de\u05e7\u05e1\u05d9\u05de\u05dc\u05d9 \u05dc\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4, \u05d0\u05d5 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05e9\u05dc\u05d0 \u05ea\u05d4\u05d9\u05d4 \u05d1\u05db\u05dc\u05dc."], [168.4, "\u05d5\u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05d2\u05d3\u05d9\u05e8\u05d9\u05dd \u05dc\u05e4\u05d9 \u05e7\u05e9\u05d9\u05d5\u05ea: \u05e2\u05d3 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1-50 \u05d5\u05d9\u05e7\u05e8\u05e1 \u05de\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4."], [177.6, "\u05d0\u05d9\u05dc\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea? \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e9\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9\u05dd."], [182.2, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05db\u05de\u05d5 \u05e0\u05d9\u05d8\u05e8\u05dc\u05d5\u05d9, \u05de\u05d2\u05d9\u05e2\u05d5\u05ea \u05dc\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd-\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05db\u05de\u05d5 4140 \u05d5-4340 \u05e0\u05d5\u05ea\u05e0\u05d5\u05ea \u05e9\u05db\u05d1\u05d4 \u05e4\u05d7\u05d5\u05ea \u05e7\u05e9\u05d4, \u05d0\u05d1\u05dc \u05e4\u05d7\u05d5\u05ea \u05e4\u05e8\u05d9\u05db\u05d4."], [195.8, "\u05d2\u05dd \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05db\u05de\u05d5 H11 \u05d5-D2 \u05de\u05d2\u05d9\u05d1\u05d5\u05ea \u05d4\u05d9\u05d8\u05d1 \u05dc\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4."], [202.0, "\u05d5\u05d1\u05de\u05e4\u05e8\u05d8 AMS 2759/6 \u05d9\u05e9 \u05e4\u05e8\u05de\u05d8\u05e8\u05d9\u05dd \u05de\u05d5\u05db\u05e0\u05d9\u05dd \u05dc\u05e0\u05d9\u05d8\u05e8\u05dc\u05d5\u05d9, \u05dc-4140, \u05dc-4340 \u05d5\u05dc-H11."], [215.1, "\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df \u05e4\u05e9\u05d5\u05d8\u05d4 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6: \u05d4\u05e9\u05db\u05d1\u05d4 \u05d9\u05d5\u05e6\u05d0\u05ea \u05e4\u05e8\u05d9\u05db\u05d4 \u05d5\u05de\u05ea\u05e7\u05dc\u05e4\u05ea."], [222.0, "\u05dc\u05e4\u05e0\u05d9 \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05e7\u05e9\u05d9\u05dd \u05d5\u05de\u05e8\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05dc\u05e4\u05d7\u05d5\u05ea \u05d1-30 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4. \u05d0\u05d7\u05e8\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4 \u05ea\u05ea\u05e8\u05db\u05da \u05d1\u05ea\u05e0\u05d5\u05e8."], [233.4, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05e8\u05d5\u05dd-\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05ea\u05dc\u05d5\u05d9\u05d4 \u05d1\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4: \u05dc\u05d9\u05d1\u05d4 \u05e8\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e9\u05db\u05d1\u05d4 \u05e8\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8."], [241.7, "\u05d5\u05e2\u05d5\u05d3 \u05d3\u05d1\u05e8: \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05e1 \u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05dc\u05d2\u05de\u05e8. \u05db\u05da \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05d9\u05d6\u05d5\u05d6 \u05d1\u05ea\u05e0\u05d5\u05e8."], [251.2, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05e4\u05dc\u05d6\u05de\u05d4, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d9\u05d5\u05e0\u05d9\u05ea."], [256.9, "\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05e9\u05d1\u05d9\u05dd \u05d1\u05ea\u05d0 \u05d5\u05d0\u05e7\u05d5\u05dd \u05e2\u05dd \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea \u05e9\u05dc \u05d7\u05e0\u05e7\u05df \u05d5\u05de\u05d9\u05de\u05df, \u05d5\u05de\u05ea\u05d7 \u05d7\u05e9\u05de\u05dc\u05d9 \u05d9\u05d5\u05e6\u05e8 \u05e1\u05d1\u05d9\u05d1\u05dd \u05d6\u05d5\u05d4\u05e8 \u05e1\u05d2\u05d5\u05dc."], [264.6, "\u05d4\u05e4\u05dc\u05d6\u05de\u05d4 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e9\u05dc\u05d9\u05d8\u05d4 \u05de\u05d3\u05d5\u05d9\u05e7\u05ea: \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05d1\u05dc \u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4, \u05d0\u05d5 \u05dc\u05d5\u05d5\u05ea\u05e8 \u05e2\u05dc\u05d9\u05d4 \u05dc\u05d2\u05de\u05e8\u05d9."], [270.9, "\u05d4\u05d9\u05d0 \u05d2\u05dd \u05e9\u05d5\u05d1\u05e8\u05ea \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e4\u05e1\u05d9\u05d1\u05d9\u05ea \u05e9\u05dc \u05e4\u05dc\u05d3\u05ea \u05d0\u05dc-\u05d7\u05dc\u05d3, \u05d5\u05dc\u05db\u05df \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05e9\u05dc \u05d0\u05dc-\u05d7\u05dc\u05d3."], [278.4, "\u05d1\u05d0\u05dc-\u05d7\u05dc\u05d3 \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 450 \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d9\u05e6\u05d5\u05e8 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd \u05e9\u05e4\u05d5\u05d2\u05e2\u05d9\u05dd \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [287.8, "\u05d4\u05de\u05d9\u05e1\u05d5\u05da \u05e4\u05e9\u05d5\u05d8: \u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d1\u05db\u05d9\u05e1\u05d5\u05d9 \u05de\u05ea\u05db\u05ea\u05d9, \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05d5 \u05e9\u05d5\u05d1."], [293.5, "\u05d5\u05d2\u05dd \u05d1\u05d2\u05d6 \u05d9\u05e9 \u05e9\u05ea\u05d9 \u05d3\u05e8\u05db\u05d9\u05dd: \u05dc\u05de\u05e1\u05da \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8, \u05d0\u05d5 \u05dc\u05d1\u05e6\u05e2 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05dc\u05db\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d5\u05dc\u05d4\u05e9\u05d7\u05d9\u05d6 \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05de\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da."], [303.0, "\u05d4\u05d7\u05d9\u05e1\u05e8\u05d5\u05df: \u05d4\u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8."], [306.4, "\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d7\u05e0\u05e7\u05df, \u05d5\u05d2\u05dd \u05e7\u05e6\u05ea \u05e4\u05d7\u05de\u05df."], [311.5, "\u05d4\u05d9\u05d0 \u05e0\u05e2\u05e9\u05d9\u05ea \u05e1\u05d1\u05d9\u05d1 565 \u05e2\u05d3 580 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1\u05d6\u05de\u05df \u05e7\u05e6\u05e8: \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e9\u05e2\u05d4 \u05e2\u05d3 \u05e9\u05e2\u05ea\u05d9\u05d9\u05dd."], [321.4, "\u05d4\u05de\u05d8\u05e8\u05d4 \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9\u05ea \u05d4\u05d9\u05d0 \u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4 \u05d8\u05d5\u05d1\u05d4, \u05d5\u05dc\u05d0 \u05d0\u05d6\u05d5\u05e8 \u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4 \u05e2\u05de\u05d5\u05e7."], [326.4, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05de\u05e9\u05e4\u05e8\u05ea \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d1\u05d4\u05d9\u05d3\u05d1\u05e7\u05d5\u05ea \u05d5\u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05d2\u05dd \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [333.0, "\u05d5\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc: \u05d4\u05d9\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05d2\u05dd \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05e4\u05e9\u05d5\u05d8\u05d5\u05ea \u05d5\u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."], [340.0, "\u05d9\u05e9 \u05d2\u05dd \u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 \u05d5\u05d1\u05e4\u05dc\u05d6\u05de\u05d4. \u05d1\u05e4\u05dc\u05d6\u05de\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d5\u05d3 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d0\u05d6 \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05e2\u05d5\u05d3 \u05d9\u05d5\u05ea\u05e8."], [349.5, "\u05d4\u05d2\u05e8\u05e1\u05d4 \u05d4\u05de\u05d5\u05db\u05e8\u05ea \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05e0\u05e7\u05e8\u05d0\u05ea \u05d8\u05e0\u05d9\u05e4\u05e8, \u05d0\u05d5 \u05d8\u05d5\u05e4\u05d8\u05e8\u05d9\u05d9\u05d3."], [354.3, "\u05d1\u05d2\u05e8\u05e1\u05ea QPQ \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d4 \u05e2\u05d5\u05d3 \u05e9\u05e0\u05d9 \u05e9\u05dc\u05d1\u05d9\u05dd."], [358.3, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05d7\u05de\u05e6\u05df \u05d1\u05db-400 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e9\u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05d4 \u05e9\u05d7\u05d5\u05e8\u05d4 \u05e9\u05dc \u05de\u05d2\u05e0\u05d8\u05d9\u05d8."], [367.2, "\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05dc\u05d8\u05e9\u05d9\u05dd, \u05d5\u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05e9\u05d5\u05d1 \u05d1\u05d0\u05de\u05d1\u05d8 \u05d4\u05de\u05d7\u05de\u05e6\u05df. \u05e9\u05db\u05d1\u05ea \u05d4\u05ea\u05d7\u05de\u05d5\u05e6\u05ea \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05e9\u05dc\u05d5\u05e9\u05d4 \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05de\u05d9\u05e7\u05e8\u05d5\u05df."], [375.3, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4: \u05d2\u05d9\u05de\u05d5\u05e8 \u05e9\u05d7\u05d5\u05e8, \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05e9\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4 \u05de\u05e6\u05d9\u05e4\u05d5\u05d9\u05d9\u05dd \u05d2\u05dc\u05d5\u05d5\u05e0\u05d9\u05d9\u05dd. \u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d1\u05de\u05d5\u05d8\u05d5\u05ea \u05e9\u05dc \u05d1\u05d5\u05db\u05e0\u05d5\u05ea \u05d4\u05d9\u05d3\u05e8\u05d0\u05d5\u05dc\u05d9\u05d5\u05ea."], [386.2, "\u05de\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e9\u05ea\u05d1\u05e9?"], [387.9, "\u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4 \u05e2\u05d1\u05d4 \u05de\u05d3\u05d9 \u05de\u05ea\u05e7\u05dc\u05e4\u05ea \u05ea\u05d7\u05ea \u05e2\u05d5\u05de\u05e1."], [391.8, "\u05dc\u05d9\u05d1\u05d4 \u05e9\u05d4\u05d5\u05e8\u05e4\u05ea\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05de\u05d3\u05d9 \u05de\u05ea\u05e8\u05db\u05db\u05ea \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05e9\u05db\u05d1\u05d4 \u05de\u05d0\u05d1\u05d3\u05ea \u05d0\u05ea \u05d4\u05ea\u05de\u05d9\u05db\u05d4 \u05e9\u05dc\u05d4."], [398.5, "\u05d5\u05e9\u05de\u05df \u05d0\u05d5 \u05dc\u05db\u05dc\u05d5\u05da \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05db\u05ea\u05de\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e2\u05d1\u05e8\u05d5 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4. \u05dc\u05db\u05df \u05e0\u05d9\u05e7\u05d5\u05d9 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d7\u05d5\u05d1\u05d4."], [407.8, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8?"], [409.0, "\u05d6\u05de\u05df: \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05ea\u05e4\u05d5\u05e1 \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8 \u05db\u05de\u05d4 \u05d9\u05de\u05d9\u05dd."], [413.7, "\u05de\u05d9\u05e1\u05d5\u05da: \u05d1\u05d2\u05d6 \u05e6\u05e8\u05d9\u05da \u05e6\u05d1\u05e2 \u05d0\u05d5 \u05e6\u05d9\u05e4\u05d5\u05d9, \u05d5\u05d1\u05e4\u05dc\u05d6\u05de\u05d4 \u05db\u05d9\u05e1\u05d5\u05d9\u05d9\u05dd \u05de\u05db\u05e0\u05d9\u05d9\u05dd."], [419.6, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4: \u05d3\u05e8\u05d9\u05e9\u05d4 \u05dc\u05d4\u05e1\u05d9\u05e8 \u05d0\u05d5\u05ea\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 \u05dc\u05d9\u05d8\u05d5\u05e9."], [425.1, "\u05d5-QPQ: \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd, \u05dc\u05d9\u05d8\u05d5\u05e9 \u05d1\u05d0\u05de\u05e6\u05e2, \u05d5\u05d0\u05de\u05d1\u05d8\u05d9 \u05de\u05dc\u05d7 \u05e9\u05e6\u05e8\u05d9\u05da \u05dc\u05d8\u05e4\u05dc \u05d1\u05d4\u05dd. \u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05d5\u05d0 \u05d7\u05d5\u05e1\u05da \u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05e4\u05e8\u05d3."], [435.0, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05db\u05e0\u05d9\u05e1\u05d4 \u05d7\u05e0\u05e7\u05df \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05dc\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05dc\u05db\u05df \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."], [442.8, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05e2\u05de\u05d9\u05d3\u05d4, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05e9\u05dc\u05d5\u05d8 \u05d1\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc\u05d4."], [447.6, "\u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05e7\u05e9\u05d9\u05dd \u05d5\u05de\u05e8\u05e4\u05d9\u05dd, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4."], [453.9, "\u05e0\u05d9\u05d8\u05e8\u05d5\u05e7\u05e8\u05d1\u05d5\u05e8\u05e6\u05d9\u05d4 \u05d5-QPQ \u05e7\u05e6\u05e8\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8, \u05de\u05ea\u05d0\u05d9\u05de\u05d5\u05ea \u05d2\u05dd \u05dc\u05e4\u05dc\u05d3\u05ea \u05e4\u05d7\u05de\u05df, \u05d5\u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [461.3, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0: \u05e9\u05d9\u05d8\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea \u05dc\u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7: \u05dc\u05d9\u05d9\u05d6\u05e8, \u05d0\u05dc\u05d5\u05de\u05ea \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d5\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2."]]};
window.MH_TR["ch14"]={"t": "\u05dc\u05d9\u05d9\u05d6\u05e8, \u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d5\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7\u05d9\u05dd \u05d4\u05e7\u05d5\u05d3\u05de\u05d9\u05dd \u05d4\u05db\u05e8\u05e0\u05d5 \u05d0\u05ea \u05e9\u05d9\u05d8\u05d5\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05dc\u05d5\u05e9 \u05e9\u05d9\u05d8\u05d5\u05ea \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea."], [12.4, "\u05e9\u05ea\u05d9\u05d9\u05dd \u05de\u05d4\u05df \u05de\u05d7\u05de\u05de\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d5\u05d1\u05d3\u05d9\u05d5\u05e7: \u05e7\u05e8\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd."], [19.7, "\u05d5\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2, \u05de\u05d7\u05d3\u05d9\u05e8\u05d4 \u05d1\u05d5\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05d4 \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05e9\u05d9\u05d8\u05d4 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05e2\u05d3 \u05e2\u05db\u05e9\u05d9\u05d5."], [28.6, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8. \u05e7\u05e8\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d7\u05d6\u05e7\u05d4 \u05e0\u05e2\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05de\u05d7\u05de\u05de\u05ea \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05de\u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [38.1, "\u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05e0\u05de\u05e9\u05da \u05e9\u05d1\u05e8\u05d9\u05e8 \u05e9\u05e0\u05d9\u05d9\u05d4, \u05d5\u05dc\u05db\u05df \u05e8\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05e2\u05dc\u05d9\u05d5\u05e0\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e0\u05e9\u05d0\u05e8\u05ea \u05e7\u05e8\u05d4."], [45.9, "\u05d1\u05e8\u05d2\u05e2 \u05e9\u05d4\u05e7\u05e8\u05df \u05de\u05de\u05e9\u05d9\u05db\u05d4 \u05d4\u05dc\u05d0\u05d4, \u05d4\u05de\u05ea\u05db\u05ea \u05d4\u05e7\u05e8\u05d4 \u05e9\u05de\u05ea\u05d7\u05ea \u05de\u05d5\u05e9\u05db\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05dd \u05de\u05d4\u05e8 \u05de\u05d0\u05d5\u05d3."], [52.3, "\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05e6\u05de\u05d9: \u05d0\u05d9\u05df \u05de\u05d9\u05dd, \u05d0\u05d9\u05df \u05e9\u05de\u05df \u05d5\u05d0\u05d9\u05df \u05e4\u05d5\u05dc\u05d9\u05de\u05e8. \u05d4\u05d7\u05dc\u05e7 \u05de\u05db\u05d1\u05d4 \u05d0\u05ea \u05e2\u05e6\u05de\u05d5, \u05d5\u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [61.4, "\u05d4\u05d9\u05d5\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9 \u05d3\u05d9\u05d5\u05d3\u05d4 \u05d1\u05d4\u05e1\u05e4\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05e9\u05de\u05de\u05d9\u05e8\u05d9\u05dd \u05d7\u05e9\u05de\u05dc \u05dc\u05d0\u05d5\u05e8 \u05d1\u05d9\u05e2\u05d9\u05dc\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4."], [68.1, "\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05dc\u05d9\u05d9\u05d6\u05e8\u05d9\u05dd \u05de\u05d5\u05e8\u05d7\u05d9\u05dd \u05e6\u05d9\u05e4\u05d5\u05d9 \u05db\u05d4\u05d4, \u05db\u05d3\u05d9 \u05e9\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d9\u05d1\u05dc\u05e2\u05d5 \u05d9\u05d5\u05ea\u05e8 \u05d0\u05d5\u05e8 \u05d5\u05dc\u05d0 \u05d9\u05d7\u05d6\u05d9\u05e8\u05d5 \u05d0\u05d5\u05ea\u05d5."], [75.7, "\u05e2\u05d5\u05de\u05e7 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d4\u05d5\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 0.1 \u05dc-1.5 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc-2.5 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [85.4, "\u05d4\u05e2\u05d5\u05de\u05e7 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d4\u05e1\u05e4\u05e7, \u05d1\u05e8\u05d5\u05d7\u05d1 \u05d4\u05e7\u05e8\u05df \u05d5\u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05ea\u05e0\u05d5\u05e2\u05d4: \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d7\u05d5\u05dd \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8."], [93.3, "\u05d4\u05d9\u05ea\u05e8\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc \u05d4\u05d5\u05d0 \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea: \u05d4\u05d7\u05d5\u05dd \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05d7\u05dc\u05e7 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e9\u05d0\u05e8 \u05db\u05de\u05e2\u05d8 \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05d5\u05ea \u05e9\u05dc\u05d5."], [102.1, "\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05d7\u05d6\u05d4 \u05e1\u05d5\u05e4\u05d9\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d7\u05e1\u05d5\u05da \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."], [108.5, "\u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05e0\u05e9\u05d7\u05e7, \u05dc\u05de\u05e9\u05dc \u05d0\u05ea \u05d4\u05e7\u05e6\u05d4 \u05e9\u05dc \u05db\u05dc\u05d9 \u05db\u05d9\u05e4\u05d5\u05e3, \u05d0\u05d5 \u05d0\u05ea \u05d4\u05d6\u05d9\u05d6\u05d9\u05dd \u05e9\u05dc \u05d2\u05dc \u05d6\u05d9\u05d6\u05d9\u05dd."], [116.5, "\u05d0\u05d1\u05dc \u05d9\u05e9 \u05de\u05d2\u05d1\u05dc\u05d4: \u05d4\u05e7\u05e8\u05df \u05e8\u05d7\u05d1\u05d4 \u05e8\u05e7 \u05db\u05de\u05d4 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8\u05d9\u05dd, \u05d5\u05db\u05d3\u05d9 \u05dc\u05db\u05e1\u05d5\u05ea \u05e9\u05d8\u05d7 \u05e8\u05d7\u05d1 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d1\u05de\u05e1\u05dc\u05d5\u05dc\u05d9\u05dd \u05e6\u05de\u05d5\u05d3\u05d9\u05dd."], [124.4, "\u05db\u05e9\u05de\u05e1\u05dc\u05d5\u05dc \u05d7\u05d3\u05e9 \u05e2\u05d5\u05d1\u05e8 \u05dc\u05d9\u05d3 \u05de\u05e1\u05dc\u05d5\u05dc \u05e9\u05db\u05d1\u05e8 \u05d4\u05d5\u05e7\u05e9\u05d4, \u05d4\u05d5\u05d0 \u05de\u05d7\u05de\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e9\u05d5\u05d1 \u05d5\u05de\u05e8\u05db\u05da \u05e8\u05e6\u05d5\u05e2\u05d4 \u05e6\u05e8\u05d4, \u05d5\u05d0\u05ea \u05d6\u05d4 \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05de\u05e8\u05d0\u05e9."], [134.1, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e9\u05e0\u05d9\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd. \u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05d3\u05d5\u05de\u05d4: \u05e7\u05e8\u05df \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05de\u05d7\u05de\u05de\u05ea \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05db\u05d1\u05d4 \u05d0\u05ea \u05e2\u05e6\u05de\u05d5."], [144.5, "\u05d4\u05d4\u05d1\u05d3\u05dc \u05d4\u05d5\u05d0 \u05e9\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05ea\u05d1\u05e6\u05e2 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05db\u05d9 \u05de\u05d5\u05dc\u05e7\u05d5\u05dc\u05d5\u05ea \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05de\u05e4\u05d6\u05e8\u05d5\u05ea \u05d0\u05ea \u05d4\u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd."], [151.0, "\u05e1\u05dc\u05d9\u05dc\u05d9\u05dd \u05de\u05d2\u05e0\u05d8\u05d9\u05d9\u05dd \u05de\u05e1\u05d9\u05d8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e8\u05df \u05d1\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05e2\u05e6\u05d5\u05de\u05d4, \u05d5\u05d4\u05d9\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05e1\u05e8\u05d5\u05e7 \u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05de\u05d4, \u05d0\u05d5 \u05db\u05de\u05d4 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05d1\u05d5 \u05d6\u05de\u05e0\u05d9\u05ea."], [159.9, "\u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9, \u05d5\u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05e9\u05d5\u05de\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05d7\u05de\u05e6\u05d5\u05df."], [165.4, "\u05d4\u05de\u05d2\u05d1\u05dc\u05d4 \u05d4\u05d9\u05d0 \u05ea\u05d0 \u05d4\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd: \u05d4\u05d7\u05dc\u05e7 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05db\u05e0\u05e1 \u05dc\u05ea\u05d0, \u05d5\u05db\u05dc \u05de\u05d7\u05d6\u05d5\u05e8 \u05db\u05d5\u05dc\u05dc \u05e9\u05d0\u05d9\u05d1\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8."], [172.9, "\u05d0\u05d9\u05da \u05d6\u05d4 \u05e2\u05d5\u05de\u05d3 \u05de\u05d5\u05dc \u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4? \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05e6\u05e8\u05d9\u05da \u05e1\u05dc\u05d9\u05dc \u05e9\u05de\u05d5\u05ea\u05d0\u05dd \u05dc\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d5\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d2\u05dd \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e8\u05d9\u05e1\u05d5\u05e1."], [181.5, "\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05dc\u05d0 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05e1\u05dc\u05d9\u05dc \u05d5\u05dc\u05d0 \u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05de\u05d9\u05dd, \u05d5\u05de\u05ea\u05d0\u05d9\u05de\u05d9\u05dd \u05dc\u05e6\u05d5\u05e8\u05d5\u05ea \u05de\u05d5\u05e8\u05db\u05d1\u05d5\u05ea \u05d5\u05dc\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd."], [188.9, "\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e2\u05dc \u05e9\u05d8\u05d7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05d5\u05de\u05d2\u05d9\u05e2\u05d4 \u05e2\u05de\u05d5\u05e7 \u05d9\u05d5\u05ea\u05e8."], [193.4, "\u05dc\u05db\u05df \u05dc\u05d9\u05d9\u05d6\u05e8 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05e9\u05db\u05d1\u05d4 \u05e8\u05d3\u05d5\u05d3\u05d4 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7\u05ea \u05e2\u05dd \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05e2\u05d9\u05d5\u05d5\u05ea, \u05d5\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05dc\u05e9\u05db\u05d1\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05e9\u05d5\u05d8\u05d9\u05dd."], [202.1, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea, \u05e9\u05e2\u05d5\u05d1\u05d3\u05ea \u05d0\u05d7\u05e8\u05ea \u05dc\u05d2\u05de\u05e8\u05d9: \u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2."], [207.2, "\u05db\u05de\u05d5 \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d5\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4, \u05de\u05d7\u05d3\u05d9\u05e8\u05d9\u05dd \u05d9\u05e1\u05d5\u05d3 \u05dc\u05ea\u05d5\u05da \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d1\u05d3\u05d9\u05e4\u05d5\u05d6\u05d9\u05d4. \u05d4\u05e4\u05e2\u05dd \u05d4\u05d9\u05e1\u05d5\u05d3 \u05d4\u05d5\u05d0 \u05d1\u05d5\u05e8."], [215.8, "\u05d4\u05d1\u05d5\u05e8 \u05de\u05ea\u05d7\u05d1\u05e8 \u05e2\u05dd \u05d4\u05d1\u05e8\u05d6\u05dc, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05ea\u05e8\u05db\u05d5\u05d1\u05ea \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3: \u05d1\u05d5\u05e8\u05d9\u05d3 \u05d1\u05e8\u05d6\u05dc."], [221.4, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05d0\u05d1\u05e7\u05d4: \u05d0\u05d5\u05e8\u05d6\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e7\u05d5\u05e4\u05e1\u05d4 \u05e2\u05dd \u05d0\u05d1\u05e7\u05d4 \u05e9\u05de\u05db\u05d9\u05dc\u05d4 \u05d1\u05d5\u05e8, \u05d5\u05e1\u05d5\u05d2\u05e8\u05d9\u05dd."], [228.4, "\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05d1\u05de\u05e9\u05d7\u05d4 \u05e9\u05de\u05d5\u05e8\u05d7\u05d9\u05dd \u05e8\u05e7 \u05e2\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05e8\u05e6\u05d5\u05d9, \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d0\u05d5 \u05d1\u05d2\u05d6."], [234.4, "\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d3\u05d5\u05e8\u05e9 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 800 \u05dc-1,050 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d6\u05de\u05df \u05d0\u05e8\u05d5\u05da: \u05de\u05e9\u05dc\u05d5\u05e9 \u05e9\u05e2\u05d5\u05ea \u05d5\u05e2\u05d3 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d7\u05e6\u05d9 \u05d9\u05d5\u05dd."], [245.3, "\u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05d5\u05e6\u05e8\u05d5\u05ea \u05e9\u05ea\u05d9 \u05e9\u05db\u05d1\u05d5\u05ea."], [248.2, "\u05d1\u05d7\u05d5\u05e5, \u05d0\u05d9\u05e4\u05d4 \u05e9\u05d9\u05e9 \u05d4\u05db\u05d9 \u05d4\u05e8\u05d1\u05d4 \u05d1\u05d5\u05e8, \u05e0\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05ea FeB. \u05d5\u05de\u05ea\u05d7\u05ea\u05d9\u05d4 \u05e0\u05d5\u05e6\u05e8\u05ea \u05e9\u05db\u05d1\u05ea Fe2B."], [257.2, "\u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4 \u05d4\u05e9\u05db\u05d1\u05d4 \u05e0\u05e8\u05d0\u05d9\u05ea \u05db\u05de\u05d5 \u05e9\u05d9\u05e0\u05d9 \u05de\u05e1\u05d5\u05e8 \u05e9\u05e0\u05e0\u05e2\u05e6\u05d5\u05ea \u05dc\u05ea\u05d5\u05da \u05d4\u05de\u05ea\u05db\u05ea. \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05e2\u05d5\u05d6\u05e8\u05ea \u05dc\u05d4 \u05dc\u05d4\u05d9\u05d0\u05d7\u05d6 \u05d1\u05d1\u05e1\u05d9\u05e1."], [266.0, "\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05dc \u05e9\u05db\u05d1\u05ea \u05d4\u05d1\u05d5\u05e8\u05d9\u05d3 \u05d4\u05d9\u05d0 \u05d1\u05e2\u05e8\u05da 1,400 \u05e2\u05d3 2,000 \u05d5\u05d9\u05e7\u05e8\u05e1. \u05dc\u05e9\u05dd \u05d4\u05e9\u05d5\u05d5\u05d0\u05d4, \u05e9\u05db\u05d1\u05ea \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d1\u05e2\u05e8\u05da 700."], [275.7, "\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4 \u05e7\u05d8\u05df: \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05e9\u05e8\u05d5\u05ea \u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d1\u05e2\u05e8\u05da 250."], [283.7, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d2\u05d3\u05dc\u05d4 \u05dc\u05e4\u05d9 \u05e9\u05d5\u05e8\u05e9 \u05d4\u05d6\u05de\u05df, \u05db\u05de\u05d5 \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4: \u05db\u05d3\u05d9 \u05dc\u05d4\u05db\u05e4\u05d9\u05dc \u05d0\u05ea \u05d4\u05e2\u05d5\u05d1\u05d9, \u05e6\u05e8\u05d9\u05da \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d6\u05de\u05df."], [291.2, "\u05e8\u05d5\u05e6\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05d0\u05d7\u05ea \u05d1\u05dc\u05d1\u05d3, \u05e9\u05dc Fe2B. \u05e9\u05db\u05d1\u05ea FeB \u05e9\u05d1\u05d9\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d1\u05d2\u05d1\u05d5\u05dc \u05e9\u05d1\u05d9\u05df \u05e9\u05ea\u05d9 \u05d4\u05e9\u05db\u05d1\u05d5\u05ea \u05e0\u05d5\u05d8\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05d5\u05e6\u05e8 \u05e1\u05d3\u05e7\u05d9\u05dd."], [301.2, "\u05db\u05d3\u05d9 \u05dc\u05de\u05e0\u05d5\u05e2 \u05d0\u05ea FeB, \u05e9\u05d5\u05dc\u05d8\u05d9\u05dd \u05d1\u05db\u05de\u05d5\u05ea \u05d4\u05d1\u05d5\u05e8 \u05d1\u05d0\u05d1\u05e7\u05d4 \u05d5\u05d1\u05d6\u05de\u05df \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [307.8, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05e6\u05e2 \u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2 \u05e2\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df, \u05e4\u05dc\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3 \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."], [316.6, "\u05dc\u05d0 \u05de\u05d5\u05de\u05dc\u05e5 \u05dc\u05d1\u05e6\u05e2 \u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d0\u05d5 \u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05d5\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc \u05e2\u05dd \u05d2\u05d5\u05e4\u05e8\u05d9\u05ea \u05d0\u05d5 \u05e2\u05d5\u05e4\u05e8\u05ea."], [325.1, "\u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05ea\u05d1\u05e6\u05e2 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05dc\u05db\u05df \u05d0\u05d7\u05e8\u05d9\u05d5 \u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4: \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05de\u05dc\u05d7, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e8\u05e4\u05d9\u05d4."], [334.8, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e0\u05d5\u05b9\u05d7\u05d5\u05b9\u05ea \u05d1\u05de\u05d9\u05d5\u05d7\u05d3, \u05db\u05d9 \u05d4\u05df \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05db\u05d1\u05e8 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2."], [341.3, "\u05d4\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd: \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05dc\u05e9\u05d9\u05d7\u05d5\u05dc \u05d5\u05dc\u05db\u05d1\u05d9\u05e9\u05d4, \u05d7\u05dc\u05e7\u05d9 \u05de\u05e9\u05d0\u05d1\u05d5\u05ea, \u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd, \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d7\u05e7\u05dc\u05d0\u05d5\u05ea \u05d5\u05d1\u05e0\u05e4\u05d8 \u05d5\u05d2\u05d6, \u05e9\u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05de\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d0\u05d1\u05e8\u05e1\u05d9\u05d1\u05d9\u05ea."], [353.1, "\u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05e8\u05d0\u05e9\u05d5\u05e0\u05d4 \u05d1\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2 \u05d4\u05d9\u05d0 \u05e9\u05d9\u05e0\u05d5\u05d9 \u05de\u05d9\u05d3\u05d5\u05ea: \u05d4\u05e9\u05db\u05d1\u05d4 \u05d1\u05d5\u05dc\u05d8\u05ea \u05de\u05e2\u05dc \u05d4\u05de\u05d9\u05d3\u05d4 \u05d4\u05de\u05e7\u05d5\u05e8\u05d9\u05ea, \u05d1\u05e2\u05e8\u05da 20 \u05e2\u05d3 25 \u05d0\u05d7\u05d5\u05d6 \u05de\u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4."], [363.1, "\u05d5\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d4\u05e9\u05d7\u05d9\u05d6 \u05d0\u05d5\u05ea\u05d4, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3. \u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05e8\u05d0\u05e9, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05e8\u05e7 \u05dc\u05d9\u05d8\u05d5\u05e9."], [371.7, "\u05d4\u05e9\u05db\u05d1\u05d4 \u05d2\u05dd \u05e8\u05d2\u05d9\u05e9\u05d4 \u05dc\u05de\u05db\u05d5\u05ea \u05d5\u05dc\u05d4\u05dc\u05dd \u05ea\u05e8\u05de\u05d9, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05db\u05d5\u05ea \u05d7\u05d6\u05e7\u05d5\u05ea."], [378.7, "\u05d1\u05dc\u05d9\u05d9\u05d6\u05e8, \u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05de\u05dc\u05d5\u05db\u05dc\u05db\u05d9\u05dd: \u05e9\u05d5\u05de\u05df, \u05d7\u05dc\u05d5\u05d3\u05d4 \u05d0\u05d5 \u05dc\u05db\u05dc\u05d5\u05da \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e2\u05d5\u05de\u05e7 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3."], [387.2, "\u05d5\u05d1\u05de\u05e1\u05dc\u05d5\u05dc\u05d9\u05dd \u05e6\u05de\u05d5\u05d3\u05d9\u05dd, \u05d0\u05d6\u05d5\u05e8\u05d9 \u05d4\u05e8\u05d9\u05db\u05d5\u05da \u05e9\u05d1\u05d9\u05df \u05d4\u05de\u05e1\u05dc\u05d5\u05dc\u05d9\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05ea\u05d7\u05dc\u05d4 \u05e9\u05dc \u05e1\u05d3\u05e7 \u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [395.0, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05d1\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d9\u05e7\u05e8\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d0\u05d6 \u05de\u05e9\u05dc\u05de\u05d9\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05e2\u05dc \u05d6\u05de\u05df \u05de\u05db\u05d5\u05e0\u05d4 \u05d5\u05e2\u05dc \u05ea\u05db\u05e0\u05d5\u05ea."], [403.7, "\u05db\u05dc \u05d7\u05dc\u05e7 \u05d7\u05d3\u05e9 \u05d3\u05d5\u05e8\u05e9 \u05de\u05e1\u05dc\u05d5\u05dc, \u05de\u05ea\u05e7\u05df \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05db\u05d9\u05d5\u05dc. \u05d1\u05db\u05de\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4, \u05d4\u05d4\u05db\u05e0\u05d4 \u05d4\u05d9\u05d0 \u05e8\u05d5\u05d1 \u05d4\u05de\u05d7\u05d9\u05e8."], [411.7, "\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05d0\u05ea \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05d5\u05d6\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05db\u05e1\u05d5\u05ea \u05d0\u05ea \u05d4\u05d4\u05e4\u05e8\u05e9."], [419.5, "\u05d1\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2, \u05d4\u05d0\u05d1\u05e7\u05d4 \u05d6\u05d5\u05dc\u05d4, \u05d0\u05d1\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05d5\u05e8\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3\u05d9\u05d9\u05dd: \u05d0\u05e8\u05d9\u05d6\u05d4, \u05e4\u05e8\u05d9\u05e7\u05d4 \u05d5\u05e0\u05d9\u05e7\u05d5\u05d9."], [427.6, "\u05d5\u05d0\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d0\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2, \u05d6\u05d4 \u05e2\u05d5\u05d3 \u05de\u05d7\u05d6\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05e2\u05d5\u05d3 \u05e2\u05dc\u05d5\u05ea."], [434.6, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05e7\u05e8\u05df \u05d0\u05dc\u05e7\u05d8\u05e8\u05d5\u05e0\u05d9\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05db\u05d1\u05d4 \u05d0\u05ea \u05e2\u05e6\u05de\u05d5, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."], [442.8, "\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2 \u05de\u05d7\u05d3\u05d9\u05e8 \u05d1\u05d5\u05e8 \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05d5\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3, \u05e9\u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e9\u05d7\u05d9\u05e7\u05d4 \u05e7\u05e9\u05d4. \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05db\u05e0\u05df \u05de\u05e8\u05d0\u05e9 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea."], [451.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd: \u05d0\u05d9\u05da \u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05df, \u05d5\u05dc\u05de\u05d4 \u05d4\u05df \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05db\u05de\u05d4 \u05d4\u05e8\u05e4\u05d9\u05d5\u05ea."]]};
window.MH_TR["ch15"]={"t": "\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd", "l": [[5.0, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05d4\u05df \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05d4\u05df \u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05d1\u05dc\u05d8\u05d9\u05dd, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea, \u05e1\u05db\u05d9\u05e0\u05d9\u05dd \u05d5\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da."], [12.2, "\u05d9\u05e9 \u05d1\u05d4\u05df \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d5\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea, \u05d5\u05dc\u05db\u05df \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc\u05d4\u05df \u05e9\u05d5\u05e0\u05d4 \u05de\u05d6\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."], [19.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05da \u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05e8\u05d1\u05e2 \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05e0\u05e4\u05d5\u05e6\u05d5\u05ea: A2, D2, H13 \u05d5-M2."], [31.0, "\u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05d9\u05e9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea, \u05d5\u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05d4 \u05de\u05e1\u05d5\u05de\u05e0\u05ea \u05d1\u05d0\u05d5\u05ea."], [36.1, "\u05d4\u05d0\u05d5\u05ea A \u05de\u05e1\u05de\u05e0\u05ea \u05e4\u05dc\u05d3\u05d4 \u05e9\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05d4\u05d0\u05d5\u05ea O \u05e4\u05dc\u05d3\u05d4 \u05e9\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05e9\u05de\u05df."], [43.6, "\u05d4\u05d0\u05d5\u05ea D \u05de\u05e1\u05de\u05e0\u05ea \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df \u05d5\u05db\u05e8\u05d5\u05dd, \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e7\u05e8."], [49.6, "\u05d4\u05d0\u05d5\u05ea H \u05de\u05e1\u05de\u05e0\u05ea \u05e4\u05dc\u05d3\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d7\u05d5\u05dd, \u05db\u05de\u05d5 \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d7\u05d9\u05e9\u05d5\u05dc."], [56.2, "\u05d5\u05d4\u05d0\u05d5\u05ea M \u05de\u05e1\u05de\u05e0\u05ea \u05e4\u05dc\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05e2\u05dd \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05dc\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da."], [61.6, "\u05d4\u05de\u05e1\u05e4\u05e8 \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d0\u05d5\u05ea \u05d4\u05d5\u05d0 \u05e8\u05e7 \u05de\u05e1\u05e4\u05e8 \u05e1\u05d9\u05d3\u05d5\u05e8\u05d9 \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e9\u05e4\u05d7\u05d4."], [66.2, "\u05d0\u05ea \u05e4\u05dc\u05d3\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd, \u05db\u05d9 \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d7\u05d5\u05dd \u05dc\u05d0\u05d8."], [72.5, "\u05e7\u05d5\u05d3\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05e7\u05d3\u05dd \u05d7\u05d9\u05de\u05d5\u05dd, \u05de\u05d7\u05db\u05d9\u05dd \u05e9\u05db\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d9\u05ea\u05d0\u05d6\u05df, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05e2\u05d5\u05dc\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [81.2, "\u05db\u05da \u05d4\u05d4\u05d1\u05d3\u05dc \u05d1\u05d9\u05df \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05dc\u05dc\u05d9\u05d1\u05d4 \u05e7\u05d8\u05df, \u05d5\u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05e1\u05d3\u05e7\u05d9\u05dd."], [87.1, "\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d5\u05ea: \u05d1\u05e2\u05e8\u05da \u05d1\u05d9\u05df 950 \u05dc-1,230 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05e4\u05dc\u05d3\u05d4."], [95.0, "\u05d1\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd, \u05d5\u05d4\u05e4\u05d7\u05de\u05df \u05d5\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [101.4, "\u05d0\u05d1\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05e4\u05d7\u05de\u05df \u05d1\u05e7\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4\u05dd: \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d1\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d0\u05d5 \u05d1\u05e2\u05d8\u05d9\u05e4\u05d4 \u05e9\u05dc \u05e0\u05d9\u05d9\u05e8 \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4."], [111.1, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e7\u05e8. A2 \u05d4\u05d9\u05d0 \u05e4\u05dc\u05d3\u05d4 \u05db\u05dc\u05dc\u05d9\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [118.1, "\u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 950 \u05e2\u05d3 980 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [124.3, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc-60 \u05e2\u05d3 62 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e9\u05dc\u05d4 \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3."], [131.3, "\u05d1-D2 \u05d9\u05e9 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d5\u05db\u05e8\u05d5\u05dd, \u05d5\u05d1\u05ea\u05d5\u05db\u05d4 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd, \u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."], [139.8, "\u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,010 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d2\u05dd \u05d4\u05d9\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8."], [145.2, "\u05db\u05d0\u05df \u05d9\u05e9 \u05d1\u05d7\u05d9\u05e8\u05d4: \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 200 \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05d1\u05e2\u05e8\u05da 61 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [153.0, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 510 \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05e0\u05e6\u05dc\u05ea \u05d0\u05ea \u05d4\u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d4\u05de\u05e9\u05e0\u05d9\u05ea \u05d5\u05de\u05e4\u05e8\u05e7\u05ea \u05d0\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9."], [161.1, "\u05d4\u05d9\u05d0 \u05d7\u05d5\u05d1\u05d4 \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d9\u05e2\u05d1\u05d5\u05e8 \u05d0\u05d7\u05e8 \u05db\u05da \u05e6\u05d9\u05e4\u05d5\u05d9 \u05d0\u05d5 \u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4."], [167.3, "H13 \u05d4\u05d9\u05d0 \u05e4\u05dc\u05d3\u05d4 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d7\u05d5\u05dd, \u05e2\u05dd \u05db\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd, \u05d5\u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df \u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd."], [174.6, "\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d1\u05dc\u05d7\u05e5 \u05e9\u05dc \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e9\u05d9\u05d7\u05d5\u05dc \u05d5\u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d7\u05d9\u05e9\u05d5\u05dc."], [181.2, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e9\u05e0\u05d9 \u05e9\u05dc\u05d1\u05d9 \u05e7\u05d3\u05dd \u05d7\u05d9\u05de\u05d5\u05dd, \u05d5\u05d0\u05d6 \u05de\u05e7\u05e9\u05d9\u05dd \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,010 \u05e2\u05d3 1,030 \u05de\u05e2\u05dc\u05d5\u05ea."], [188.9, "\u05d1\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d3\u05d9 \u05e4\u05d5\u05d2\u05e2 \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d4\u05dc\u05dd, \u05d5\u05dc\u05db\u05df \u05e6\u05e8\u05d9\u05da \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d4\u05d9\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7."], [195.8, "\u05de\u05e8\u05e4\u05d9\u05dd \u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05e2\u05de\u05d9\u05d9\u05dd, \u05d1\u05d9\u05df 540 \u05dc-650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc-44 \u05e2\u05d3 52 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [205.8, "\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e7\u05e8, \u05db\u05d9 \u05ea\u05d1\u05e0\u05d9\u05ea \u05d7\u05de\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05e1\u05d3\u05e7\u05d9\u05dd \u05de\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05ea\u05e8\u05de\u05d9\u05ea."], [215.3, "M2 \u05d4\u05d9\u05d0 \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05de\u05d4\u05d9\u05e8\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05de\u05e0\u05d4 \u05de\u05e7\u05d3\u05d7\u05d9\u05dd, \u05db\u05e8\u05e1\u05d5\u05de\u05d9\u05dd \u05d5\u05de\u05d1\u05dc\u05d8\u05d9\u05dd."], [222.8, "\u05d9\u05e9 \u05d1\u05d4 \u05d8\u05d5\u05e0\u05d2\u05e1\u05d8\u05df, \u05de\u05d5\u05dc\u05d9\u05d1\u05d3\u05df, \u05db\u05e8\u05d5\u05dd \u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd, \u05e9\u05d9\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [229.3, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05de\u05d9\u05e1 \u05de\u05e1\u05e4\u05d9\u05e7 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd, \u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05d4\u05ea\u05db\u05d4: \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,190 \u05e2\u05d3 1,230 \u05de\u05e2\u05dc\u05d5\u05ea."], [238.1, "\u05de\u05e2\u05d8 \u05de\u05d3\u05d9 \u05d7\u05d5\u05dd, \u05d5\u05d4\u05db\u05dc\u05d9 \u05dc\u05d0 \u05d9\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05e9\u05d4\u05d5\u05d0 \u05de\u05ea\u05d7\u05de\u05dd \u05d1\u05d7\u05d9\u05ea\u05d5\u05da. \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9, \u05d5\u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05d1\u05d9\u05df \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05ea\u05da."], [247.5, "\u05dc\u05db\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd: \u05e9\u05e0\u05d9 \u05e7\u05d3\u05de\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd, \u05d5\u05d0\u05d6 \u05e2\u05dc\u05d9\u05d9\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d5\u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4."], [255.7, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e8\u05e4\u05d9\u05dd \u05e9\u05dc\u05d5\u05e9 \u05e4\u05e2\u05de\u05d9\u05dd, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 550 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc-63 \u05e2\u05d3 65 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C."], [265.5, "\u05d4\u05d9\u05d5\u05dd \u05e8\u05d5\u05d1 \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05de\u05d5\u05e7\u05e9\u05d5\u05ea \u05d1\u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd."], [269.6, "\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d9\u05df \u05d7\u05de\u05e6\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05d5\u05de\u05d1\u05e8\u05d9\u05e7\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05e7\u05e9\u05e7\u05e9\u05ea \u05d5\u05d1\u05dc\u05d9 \u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df."], [277.2, "\u05d0\u05ea \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d2\u05d6 \u05d7\u05e0\u05e7\u05df \u05d1\u05dc\u05d7\u05e5, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 2 \u05dc-10 \u05d1\u05e8."], [283.0, "\u05de\u05d0\u05d5\u05d5\u05e8\u05e8 \u05d7\u05d6\u05e7 \u05de\u05e1\u05d5\u05d1\u05d1 \u05d0\u05ea \u05d4\u05d2\u05d6, \u05d5\u05d0\u05ea \u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05dc\u05e4\u05d9 \u05d4\u05dc\u05d7\u05e5 \u05d5\u05de\u05d4\u05d9\u05e8\u05d5\u05ea \u05d4\u05de\u05d0\u05d5\u05d5\u05e8\u05e8."], [289.8, "\u05d2\u05d6 \u05de\u05e7\u05e8\u05e8 \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df. \u05d0\u05d1\u05dc \u05d6\u05d4 \u05e2\u05d5\u05d1\u05d3 \u05e8\u05e7 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05e7\u05dc\u05d5\u05ea, \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd."], [299.5, "\u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05dc\u05d0\u05d8, \u05d5\u05e6\u05e8\u05d9\u05da \u05dc\u05d5\u05d5\u05d3\u05d0 \u05e9\u05d4\u05dc\u05d7\u05e5 \u05de\u05e1\u05e4\u05d9\u05e7."], [306.5, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d9\u05e9 \u05d1\u05e4\u05dc\u05d3\u05ea \u05d4\u05db\u05dc\u05d9\u05dd \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9."], [313.9, "\u05dc\u05db\u05df \u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3, \u05d1\u05e8\u05d2\u05e2 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e7\u05e8\u05e8 \u05dc\u05d1\u05e2\u05e8\u05da 50 \u05de\u05e2\u05dc\u05d5\u05ea."], [319.4, "\u05d0\u05dd \u05de\u05d7\u05db\u05d9\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05de\u05e2\u05e6\u05de\u05d5, \u05d1\u05d2\u05dc\u05dc \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05d1\u05d5."], [324.8, "\u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d2\u05d1\u05d5\u05d4\u05d4, \u05d7\u05dc\u05e7 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d7\u05d3\u05e9 \u05d1\u05d6\u05de\u05df \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8."], [331.3, "\u05d0\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d4\u05d7\u05d3\u05e9 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05e9\u05d5\u05d1, \u05d5\u05dc\u05db\u05df \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e9\u05ea\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9 \u05d4\u05e8\u05e4\u05d9\u05d5\u05ea, \u05d5\u05d1\u05d9\u05df \u05db\u05dc \u05d0\u05d7\u05ea \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05e2\u05d3 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."], [340.7, "\u05db\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05de\u05e9\u05db\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05e9\u05e2\u05ea\u05d9\u05d9\u05dd, \u05d0\u05d5 \u05d1\u05e2\u05e8\u05da \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9."], [347.7, "\u05d3\u05e8\u05da \u05e0\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05d9\u05e4\u05d8\u05e8 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05d4\u05d9\u05d0 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d1\u05d7\u05e0\u05e7\u05df \u05e0\u05d5\u05d6\u05dc\u05d9, \u05e2\u05d3 \u05de\u05d9\u05e0\u05d5\u05e1 196 \u05de\u05e2\u05dc\u05d5\u05ea."], [355.8, "\u05d1\u05e7\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05e8\u05d5\u05d1 \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d4\u05e9\u05d9\u05d5\u05e8\u05d9 \u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05d4\u05d9\u05e6\u05d9\u05d1\u05d5\u05ea \u05d1\u05de\u05d9\u05d3\u05d5\u05ea \u05de\u05e9\u05ea\u05e4\u05e8\u05ea."], [362.4, "\u05de\u05d7\u05e7\u05e8\u05d9\u05dd \u05de\u05e8\u05d0\u05d9\u05dd \u05d2\u05dd \u05e9\u05d9\u05e4\u05d5\u05e8 \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4, \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05de\u05d5 D2."], [368.4, "\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d5\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d8, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05d2\u05e8\u05d5\u05dd \u05dc\u05d4\u05dc\u05dd \u05ea\u05e8\u05de\u05d9."], [372.8, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d4\u05e2\u05de\u05d5\u05e7 \u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea, \u05db\u05d9 \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d4\u05d7\u05d3\u05e9 \u05e9\u05d1\u05d9\u05e8."], [378.9, "\u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05e9\u05d0\u05d9\u05e8 \u05e9\u05db\u05d1\u05d4 \u05e8\u05db\u05d4, \u05e9\u05e0\u05e9\u05d7\u05e7\u05ea \u05de\u05d4\u05e8."], [383.8, "\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9, \u05d0\u05d5 \u05d1\u05dc\u05d9 \u05e7\u05d3\u05dd \u05d7\u05d9\u05de\u05d5\u05dd, \u05d2\u05d5\u05e8\u05dd \u05dc\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05dc\u05e1\u05d3\u05e7\u05d9\u05dd."], [389.6, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05d5\u05dc\u05d4\u05e8\u05d1\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d3\u05d5\u05d5\u05e7\u05d0 \u05d9\u05d5\u05e8\u05d3\u05ea."], [396.6, "\u05d5\u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea \u05d5\u05d7\u05d5\u05e8\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d9\u05dd \u05dc\u05d3\u05d5\u05e4\u05df \u05d4\u05dd \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05d4\u05e1\u05d3\u05e7\u05d9\u05dd \u05d1\u05db\u05d9\u05d1\u05d5\u05d9."], [402.8, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d9\u05e7\u05e8, \u05d5\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d0\u05e8\u05d5\u05da, \u05e2\u05dd \u05e7\u05d3\u05de\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05db\u05de\u05d4 \u05d4\u05e8\u05e4\u05d9\u05d5\u05ea."], [411.3, "\u05db\u05dc \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05e2\u05d5\u05d3 \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05e9\u05dc\u05d5\u05e9 \u05d4\u05e8\u05e4\u05d9\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d5\u05ea \u05dc\u05d4\u05db\u05e4\u05d9\u05dc \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [418.5, "\u05d1\u05e4\u05dc\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d4\u05d1\u05e7\u05e8\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05ea, \u05d5\u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8."], [425.2, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d4\u05d5\u05d0 \u05e2\u05d5\u05d3 \u05e9\u05dc\u05d1, \u05d5\u05e2\u05d5\u05d3 \u05d4\u05e8\u05e4\u05d9\u05d4 \u05d0\u05d7\u05e8\u05d9\u05d5."], [429.3, "\u05d0\u05d1\u05dc \u05db\u05dc\u05d9 \u05e9\u05d4\u05d5\u05e7\u05e9\u05d4 \u05e0\u05db\u05d5\u05df \u05de\u05d7\u05d6\u05d9\u05e7 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df, \u05d5\u05d6\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05de\u05db\u05e1\u05d4 \u05d0\u05ea \u05d4\u05d4\u05e4\u05e8\u05e9."], [435.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05e9\u05dc\u05d1\u05d9\u05dd, \u05d5\u05de\u05d2\u05d9\u05e0\u05d9\u05dd \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05d0\u05d9\u05d1\u05d5\u05d3 \u05e4\u05d7\u05de\u05df."], [442.4, "\u05dc\u05db\u05dc \u05e4\u05dc\u05d3\u05d4 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05e9\u05dc\u05d4: A2 \u05d5-D2 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05e7\u05e8, H13 \u05dc\u05e2\u05d1\u05d5\u05d3\u05d4 \u05d1\u05d7\u05d5\u05dd, \u05d5-M2 \u05dc\u05d7\u05d9\u05ea\u05d5\u05da."], [453.0, "\u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05e9\u05ea\u05d9\u05d9\u05dd \u05d0\u05d5 \u05e9\u05dc\u05d5\u05e9 \u05e4\u05e2\u05de\u05d9\u05dd, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7."], [459.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3: \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea, \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df."]]};
window.MH_TR["ch16"]={"t": "\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3", "l": [[5.0, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3 \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea 10.5 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd. \u05d4\u05db\u05e8\u05d5\u05dd \u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05db\u05d1\u05d4 \u05d3\u05e7\u05d4 \u05e9\u05de\u05d2\u05d9\u05e0\u05d4 \u05de\u05e4\u05e0\u05d9 \u05d7\u05dc\u05d5\u05d3\u05d4."], [13.8, "\u05d0\u05d1\u05dc \u05dc\u05d0 \u05db\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc \u05d7\u05dc\u05d3 \u05de\u05d2\u05d9\u05d1\u05d5\u05ea \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e6\u05d5\u05e8\u05d4. \u05dc\u05d7\u05dc\u05e7\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05dc\u05d7\u05dc\u05e7\u05df \u05dc\u05d0."], [21.9, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05dc\u05d5\u05e9 \u05de\u05e9\u05e4\u05d7\u05d5\u05ea: \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea, \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea, \u05d5\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df."], [30.2, "\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea, \u05db\u05de\u05d5 304 \u05d5-316, \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05db\u05e8\u05d5\u05dd \u05d5\u05e0\u05d9\u05e7\u05dc, \u05d5\u05d4\u05de\u05d1\u05e0\u05d4 \u05e9\u05dc\u05d4\u05df \u05e0\u05e9\u05d0\u05e8 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d2\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."], [41.1, "\u05d0\u05d9\u05df \u05d1\u05d4\u05df \u05de\u05e2\u05d1\u05e8 \u05e4\u05d0\u05d6\u05d4 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8, \u05d5\u05dc\u05db\u05df \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d0\u05d5\u05ea\u05df \u05d1\u05db\u05d9\u05d1\u05d5\u05d9. \u05de\u05d7\u05d6\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05e8\u05e7 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e7\u05e8."], [48.9, "\u05d2\u05dd \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05e4\u05e8\u05d9\u05d8\u05d9\u05d5\u05ea, \u05db\u05de\u05d5 430, \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05db\u05d9\u05d1\u05d5\u05d9."], [54.5, "\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea, \u05db\u05de\u05d5 420 \u05d5-440C, \u05de\u05db\u05d9\u05dc\u05d5\u05ea \u05d9\u05d5\u05ea\u05e8 \u05e4\u05d7\u05de\u05df \u05d5\u05e4\u05d7\u05d5\u05ea \u05e0\u05d9\u05e7\u05dc, \u05d5\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4."], [65.3, "\u05d5\u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df, \u05db\u05de\u05d5 17-4, \u05de\u05e7\u05d1\u05dc\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d4\u05df \u05de\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d1\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05ea\u05d5\u05df."], [75.0, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea. \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9 \u05e9\u05dc\u05d4\u05df \u05e0\u05e7\u05e8\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4."], [80.2, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 1,050 \u05e2\u05d3 1,150 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05d1\u05d4 \u05db\u05dc \u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05de\u05d5\u05e1\u05e1 \u05d1\u05ea\u05d5\u05da \u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8."], [89.0, "\u05d5\u05d0\u05d6 \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8, \u05d1\u05de\u05d9\u05dd \u05d0\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d7\u05d6\u05e7, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05d7\u05de\u05df \u05d9\u05d9\u05e9\u05d0\u05e8 \u05de\u05d5\u05de\u05e1."], [95.3, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05e8\u05db\u05da \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e7\u05e8, \u05d5\u05de\u05d7\u05d6\u05d9\u05e8 \u05dc\u05d4 \u05d0\u05ea \u05d4\u05d2\u05de\u05d9\u05e9\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [103.0, "\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e7\u05e8 \u05de\u05d7\u05d6\u05e7 \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7 \u05de\u05d4\u05e1\u05d5\u05d2\u05d9\u05dd \u05d2\u05dd \u05d4\u05d5\u05e4\u05da \u05d0\u05d5\u05ea\u05d4 \u05dc\u05e7\u05e6\u05ea \u05de\u05d2\u05e0\u05d8\u05d9\u05ea. \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d1\u05d8\u05dc \u05d0\u05ea \u05d6\u05d4."], [111.1, "\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d2\u05dd \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d6\u05d4\u05e8 \u05de\u05d4\u05ea\u05d7\u05d5\u05dd \u05e9\u05e0\u05e8\u05d0\u05d4 \u05e2\u05db\u05e9\u05d9\u05d5."], [118.7, "\u05d1\u05d9\u05df \u05d1\u05e2\u05e8\u05da 450 \u05dc-850 \u05de\u05e2\u05dc\u05d5\u05ea \u05e7\u05d5\u05e8\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05ea \u05d3\u05d1\u05e8 \u05de\u05e1\u05d5\u05db\u05df."], [126.5, "\u05d4\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05d7\u05d1\u05e8 \u05e2\u05dd \u05d4\u05db\u05e8\u05d5\u05dd, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd."], [131.8, "\u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05dc\u05d9\u05d3 \u05d4\u05d2\u05d1\u05d5\u05dc \u05de\u05d0\u05d1\u05d3 \u05db\u05e8\u05d5\u05dd, \u05d5\u05e9\u05dd \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05de\u05d2\u05d9\u05e0\u05d4 \u05db\u05d1\u05e8 \u05dc\u05d0 \u05e0\u05d5\u05e6\u05e8\u05ea."], [137.5, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05d9\u05d0 \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd, \u05d2\u05dd \u05db\u05e9\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e0\u05e8\u05d0\u05d9\u05dd \u05ea\u05e7\u05d9\u05e0\u05d9\u05dd."], [143.2, "\u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4 \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d3\u05d9, \u05d1\u05d4\u05d7\u05d6\u05e7\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05d1\u05ea\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4, \u05d5\u05d2\u05dd \u05dc\u05d9\u05d3 \u05e8\u05d9\u05ea\u05d5\u05db\u05d9\u05dd."], [149.0, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df: \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8, \u05d0\u05d5 \u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05de\u05e2\u05d8 \u05e4\u05d7\u05de\u05df, \u05db\u05de\u05d5 304L \u05d5-316L. \u05d5\u05d0\u05dd \u05d6\u05d4 \u05db\u05d1\u05e8 \u05e7\u05e8\u05d4, \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d7\u05d3\u05e9 \u05de\u05ea\u05e7\u05df \u05d0\u05ea \u05d6\u05d4."], [161.9, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea. \u05d1-420 \u05d9\u05e9 \u05d1\u05e2\u05e8\u05da 0.3 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df, \u05d5\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05dc\u05e1\u05db\u05d9\u05e0\u05d9\u05dd, \u05dc\u05db\u05dc\u05d9\u05dd \u05db\u05d9\u05e8\u05d5\u05e8\u05d2\u05d9\u05d9\u05dd \u05d5\u05dc\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7."], [174.2, "\u05d1-440C \u05d9\u05e9 \u05d1\u05e2\u05e8\u05da \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df \u05d0\u05d7\u05d3, \u05d5\u05d4\u05d9\u05d0 \u05d4\u05e7\u05e9\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d9\u05df \u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05d0\u05dc \u05d7\u05dc\u05d3 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea."], [182.5, "\u05d4\u05d9\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc-58 \u05e2\u05d3 60 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05de\u05e9\u05de\u05e9\u05ea \u05dc\u05de\u05e1\u05d1\u05d9\u05dd, \u05dc\u05e9\u05e1\u05ea\u05d5\u05de\u05d9\u05dd \u05d5\u05dc\u05db\u05dc\u05d9 \u05d7\u05d9\u05ea\u05d5\u05da."], [190.1, "\u05de\u05e7\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,010 \u05e2\u05d3 1,065 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05db\u05d1\u05d9\u05dd \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05d2\u05d6 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd."], [198.7, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e0\u05e9\u05d0\u05e8 \u05d1\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4."], [206.6, "\u05d6\u05de\u05df \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e7\u05e4\u05d9\u05d3\u05d9\u05dd \u05d2\u05dd \u05e2\u05dc \u05d6\u05d4."], [213.8, "\u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d5\u05ea \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea \u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 150 \u05e2\u05d3 370 \u05de\u05e2\u05dc\u05d5\u05ea."], [223.8, "\u05d9\u05e9 \u05ea\u05d7\u05d5\u05dd \u05e9\u05d0\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e8\u05e4\u05d5\u05ea \u05d1\u05d5: \u05d1\u05e2\u05e8\u05da \u05d1\u05d9\u05df 425 \u05dc-565 \u05de\u05e2\u05dc\u05d5\u05ea."], [231.5, "\u05d1\u05ea\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4 \u05d9\u05d5\u05e8\u05d3\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d4\u05dc\u05dd, \u05d5\u05d9\u05d5\u05e8\u05d3\u05ea \u05d2\u05dd \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05db\u05d9 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9 \u05db\u05e8\u05d5\u05dd."], [238.8, "\u05de\u05d9 \u05e9\u05e6\u05e8\u05d9\u05da \u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05de\u05e8\u05e4\u05d4 \u05de\u05e2\u05dc \u05d4\u05ea\u05d7\u05d5\u05dd \u05d4\u05d6\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 600 \u05e2\u05d3 675 \u05de\u05e2\u05dc\u05d5\u05ea."], [247.3, "\u05d1\u05e4\u05dc\u05d3\u05d4 17-4 \u05d9\u05e9 \u05d1\u05e2\u05e8\u05da 17 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd, 4 \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d9\u05e7\u05dc, \u05d5\u05d2\u05dd \u05e0\u05d7\u05d5\u05e9\u05ea."], [254.5, "\u05d4\u05d9\u05d0 \u05de\u05d2\u05d9\u05e2\u05d4 \u05de\u05d4\u05de\u05e4\u05e2\u05dc \u05d1\u05de\u05e6\u05d1 \u05e9\u05e0\u05e7\u05e8\u05d0 \u05de\u05e6\u05d1 A: \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 1,040 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8."], [262.5, "\u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4 \u05d4\u05de\u05d1\u05e0\u05d4 \u05db\u05d1\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9, \u05d0\u05d1\u05dc \u05e2\u05d5\u05d3 \u05dc\u05d0 \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d4\u05de\u05dc\u05d0, \u05d5\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e9\u05d1\u05d1\u05d9\u05dd."], [269.4, "\u05dc\u05d0 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d7\u05dc\u05e7 \u05d1\u05de\u05e6\u05d1 A, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8 \u05d1\u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da."], [275.0, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d6\u05d9\u05e7\u05d5\u05df: \u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05ea\u05d5\u05df, \u05d1\u05d9\u05df 480 \u05dc-620 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05de\u05e9\u05da \u05e9\u05e2\u05d4 \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2 \u05e9\u05e2\u05d5\u05ea."], [284.9, "\u05d1\u05d6\u05de\u05df \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05e2\u05e9\u05d9\u05e8\u05d9\u05dd \u05d1\u05e0\u05d7\u05d5\u05e9\u05ea, \u05e9\u05d7\u05d5\u05e1\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e2\u05d4 \u05d1\u05e1\u05e8\u05d9\u05d2 \u05d5\u05de\u05d7\u05d6\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e4\u05dc\u05d3\u05d4."], [293.7, "\u05e9\u05dd \u05d4\u05de\u05e6\u05d1 \u05de\u05d2\u05d9\u05e2 \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05d1\u05de\u05e2\u05dc\u05d5\u05ea \u05e4\u05e8\u05e0\u05d4\u05d9\u05d9\u05d8."], [298.1, "H900 \u05d4\u05d5\u05d0 \u05d6\u05d9\u05e7\u05d5\u05df \u05e9\u05dc \u05e9\u05e2\u05d4 \u05d1-482 \u05de\u05e2\u05dc\u05d5\u05ea. \u05d4\u05d5\u05d0 \u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d1\u05e2\u05e8\u05da 44 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d0\u05d1\u05dc \u05d0\u05ea \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d4\u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05d4\u05dc\u05dd."], [311.5, "H1025 \u05d4\u05d5\u05d0 \u05d0\u05e8\u05d1\u05e2 \u05e9\u05e2\u05d5\u05ea \u05d1-552 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e0\u05d5\u05ea\u05df \u05d1\u05e2\u05e8\u05da 38 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05e2\u05dd \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d4\u05dc\u05dd."], [322.1, "H1150 \u05d4\u05d5\u05d0 \u05d0\u05e8\u05d1\u05e2 \u05e9\u05e2\u05d5\u05ea \u05d1-621 \u05de\u05e2\u05dc\u05d5\u05ea. \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc\u05d1\u05e2\u05e8\u05da 33, \u05d0\u05d1\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d4\u05db\u05d9 \u05e7\u05e9\u05d5\u05d7\u05d4."], [333.1, "\u05d1\u05d6\u05d9\u05e7\u05d5\u05df \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05db\u05d5\u05d5\u05e5 \u05de\u05e2\u05d8: \u05d1\u05e2\u05e8\u05da 0.05 \u05d0\u05d7\u05d5\u05d6 \u05d1-H900, \u05d5-0.1 \u05d0\u05d7\u05d5\u05d6 \u05d1-H1150."], [343.0, "\u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df \u05d5\u05e6\u05e4\u05d5\u05d9, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e2\u05d1\u05d3 \u05db\u05de\u05e2\u05d8 \u05dc\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df."], [350.0, "\u05d1\u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05e0\u05e7\u05d9\u05d9\u05dd \u05de\u05e9\u05de\u05df \u05d5\u05de\u05dc\u05db\u05dc\u05d5\u05da \u05dc\u05e4\u05e0\u05d9 \u05d4\u05db\u05e0\u05d9\u05e1\u05d4 \u05dc\u05ea\u05e0\u05d5\u05e8."], [358.0, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05e7\u05e9\u05e7\u05e9\u05ea \u05e9\u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5\u05dc\u05db\u05df \u05de\u05e2\u05d3\u05d9\u05e4\u05d9\u05dd \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4."], [366.3, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4: \u05d8\u05d1\u05d9\u05dc\u05d4 \u05d1\u05d7\u05d5\u05de\u05e6\u05d4 \u05e9\u05de\u05e0\u05e7\u05d4 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d5\u05de\u05d7\u05d6\u05e7\u05ea \u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d4\u05d4\u05d2\u05e0\u05d4."], [375.5, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05d0\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da \u05d1\u05dc\u05d9 \u05ea\u05db\u05e0\u05d5\u05df, \u05d2\u05d5\u05e8\u05de\u05d9\u05dd \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05d2\u05e8\u05d9\u05dd."], [382.6, "\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05ea \u05d1\u05ea\u05d7\u05d5\u05dd \u05d4\u05d0\u05e1\u05d5\u05e8 \u05d2\u05d5\u05e8\u05de\u05ea \u05dc\u05e9\u05d1\u05d9\u05e8\u05d5\u05ea \u05d5\u05dc\u05d7\u05dc\u05d5\u05d3\u05d4."], [388.1, "\u05d1-440C, \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05e4\u05d5\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05d0\u05d7\u05e8 \u05db\u05da, \u05d5\u05dc\u05e9\u05e0\u05d5\u05ea \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05e9\u05dc \u05de\u05e1\u05d1\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd."], [397.1, "\u05d5\u05d7\u05dc\u05e7 \u05de-17-4 \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05de\u05e6\u05d1 A, \u05d0\u05d5 \u05e7\u05d9\u05d1\u05dc \u05d6\u05d9\u05e7\u05d5\u05df \u05dc\u05d0 \u05e0\u05db\u05d5\u05df, \u05e2\u05dc\u05d5\u05dc \u05dc\u05d4\u05d9\u05e9\u05d1\u05e8 \u05d1\u05e9\u05d1\u05e8 \u05e4\u05e8\u05d9\u05da."], [405.6, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3 \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d2\u05d9\u05e0\u05d4, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e7\u05d1\u05dc \u05e7\u05e9\u05e7\u05e9\u05ea."], [414.3, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d3\u05d5\u05e8\u05e9 \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d6\u05d4 \u05de\u05e1\u05d5\u05d1\u05da."], [420.6, "\u05d1-440C \u05d9\u05e9 \u05d4\u05e7\u05e9\u05d9\u05d4, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4: \u05e9\u05dc\u05d5\u05e9\u05d4 \u05e9\u05dc\u05d1\u05d9\u05dd \u05e0\u05e4\u05e8\u05d3\u05d9\u05dd."], [428.0, "\u05d5\u05e4\u05e1\u05d9\u05d1\u05e6\u05d9\u05d4 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d4\u05df \u05e2\u05d5\u05d3 \u05e9\u05dc\u05d1\u05d9\u05dd, \u05d5\u05e2\u05d5\u05d3 \u05de\u05d7\u05d9\u05e8."], [432.9, "\u05d1-17-4 \u05d4\u05d7\u05d9\u05e1\u05db\u05d5\u05df \u05d2\u05d3\u05d5\u05dc: \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05e6\u05d1 \u05e8\u05da \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d6\u05d9\u05e7\u05d5\u05df \u05d0\u05d7\u05d3, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05db\u05de\u05e2\u05d8 \u05d1\u05dc\u05d9 \u05e2\u05d9\u05d5\u05d5\u05ea."], [443.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8\u05d9\u05d5\u05ea \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05db\u05d9\u05d1\u05d5\u05d9. \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d4\u05df \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8."], [451.5, "\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8\u05d9\u05d5\u05ea \u05de\u05e7\u05e9\u05d9\u05dd \u05d5\u05de\u05e8\u05e4\u05d9\u05dd \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05de\u05e8\u05e4\u05d9\u05dd \u05d1\u05d9\u05df 425 \u05dc-565 \u05de\u05e2\u05dc\u05d5\u05ea."], [461.4, "\u05d5\u05d0\u05ea 17-4 \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05d1\u05de\u05e6\u05d1 A, \u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05d0\u05ea \u05de\u05e6\u05d1 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05dc\u05e4\u05d9 \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d4\u05e7\u05e9\u05d9\u05d7\u05d5\u05ea \u05d4\u05d3\u05e8\u05d5\u05e9\u05d9\u05dd."], [469.2, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd: \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df."]]};
window.MH_TR["ch17"]={"t": "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd", "l": [[5.0, "\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4. \u05d0\u05d9\u05df \u05d1\u05d5 \u05de\u05e2\u05d1\u05e8 \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05d5\u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05d5\u05dc\u05db\u05df \u05db\u05d9\u05d1\u05d5\u05d9 \u05dc\u05d1\u05d3 \u05dc\u05d0 \u05de\u05e7\u05e9\u05d4 \u05d0\u05d5\u05ea\u05d5."], [13.5, "\u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d5 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d1\u05d3\u05e8\u05da \u05d0\u05d7\u05e8\u05ea, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d6\u05d9\u05e7\u05d5\u05df."], [18.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05ea \u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05e9\u05dc\u05d1\u05d9\u05dd: \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df. \u05e0\u05db\u05d9\u05e8 \u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05e6\u05d1\u05d9\u05dd T4, T6, T73 \u05d5-T651."], [32.3, "\u05dc\u05d0 \u05db\u05dc \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d2\u05d9\u05d1\u05d5\u05ea \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."], [35.9, "\u05e1\u05d3\u05e8\u05d5\u05ea 2000, 6000 \u05d5-7000 \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df. \u05d9\u05e9 \u05d1\u05d4\u05df \u05e0\u05d7\u05d5\u05e9\u05ea, \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd \u05d5\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df, \u05d0\u05d5 \u05d0\u05d1\u05e5."], [45.4, "\u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d4\u05df 6061 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05db\u05dc\u05dc\u05d9\u05d9\u05dd, \u05d5-7075 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4, \u05db\u05de\u05d5 \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4."], [54.2, "\u05e1\u05d3\u05e8\u05d5\u05ea 1000, 3000 \u05d5-5000 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df. \u05de\u05d7\u05d6\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05e8\u05e7 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05e7\u05d5\u05e8, \u05d5\u05d4\u05de\u05e6\u05d1 \u05e9\u05dc\u05d4\u05df \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea H."], [65.2, "\u05d1\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e9\u05de\u05ea\u05e7\u05e9\u05d5\u05ea \u05d1\u05d6\u05d9\u05e7\u05d5\u05df, \u05d4\u05de\u05e6\u05d1 \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea T, \u05d5\u05d4\u05e1\u05e4\u05e8\u05d4 \u05e9\u05d0\u05d7\u05e8\u05d9\u05d4 \u05de\u05ea\u05d0\u05e8\u05ea \u05d0\u05ea \u05e1\u05d3\u05e8 \u05d4\u05e9\u05dc\u05d1\u05d9\u05dd."], [73.6, "\u05d4\u05e2\u05d9\u05e7\u05e8\u05d5\u05df \u05e4\u05e9\u05d5\u05d8. \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd \u05dc\u05d2\u05de\u05e8\u05d9 \u05d1\u05ea\u05d5\u05da \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd."], [80.4, "\u05d0\u05dd \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05de\u05d4\u05e8, \u05d4\u05dd \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05db\u05dc\u05d5\u05d0\u05d9\u05dd \u05d1\u05ea\u05d5\u05db\u05d5, \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05de\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d7\u05d6\u05d9\u05e7 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8."], [87.4, "\u05d6\u05d4 \u05de\u05e6\u05d1 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1, \u05e9\u05e0\u05e7\u05e8\u05d0 \u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d5\u05e6\u05e7\u05d4 \u05e2\u05dc \u05e8\u05d5\u05d5\u05d9\u05d4."], [91.9, "\u05e2\u05dd \u05d4\u05d6\u05de\u05df, \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05de\u05ea\u05e7\u05d1\u05e6\u05d9\u05dd \u05dc\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05de\u05d0\u05d5\u05d3, \u05e9\u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd \u05d1\u05db\u05dc \u05d4\u05de\u05ea\u05db\u05ea."], [98.1, "\u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05d7\u05d5\u05e1\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e2\u05d4 \u05d1\u05e1\u05e8\u05d9\u05d2, \u05d5\u05db\u05da \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05d7\u05d6\u05e7."], [103.8, "\u05db\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05ea\u05d1\u05e6\u05e2 \u05d1\u05de\u05e6\u05d1 \u05de\u05d5\u05e6\u05e7. \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e0\u05de\u05e1, \u05d5\u05dc\u05d0 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05e9\u05dc\u05d5."], [110.8, "\u05d4\u05e9\u05dc\u05d1 \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4. \u05d1-6061 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 530 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d1-7075 \u05dc\u05d1\u05e2\u05e8\u05da 480 \u05de\u05e2\u05dc\u05d5\u05ea."], [122.4, "\u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05e2\u05d5\u05d1\u05d9, \u05de\u05db\u05de\u05d4 \u05d3\u05e7\u05d5\u05ea \u05dc\u05dc\u05d5\u05d7 \u05d3\u05e7 \u05d5\u05e2\u05d3 \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea \u05dc\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4."], [129.1, "\u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d3\u05e8\u05d9\u05dd \u05d1\u05e1\u05dc\u05d9\u05dd \u05e2\u05dd \u05e8\u05d5\u05d5\u05d7\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05dd \u05d9\u05d2\u05d9\u05e2 \u05dc\u05db\u05dc \u05de\u05e9\u05d8\u05d7 \u05d1\u05d0\u05d5\u05e4\u05df \u05e9\u05d5\u05d5\u05d4."], [135.3, "\u05d7\u05dc\u05d5\u05df \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e6\u05e8 \u05de\u05d0\u05d5\u05d3. \u05e7\u05e6\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d5, \u05dc\u05d0 \u05db\u05dc \u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05de\u05ea\u05de\u05d5\u05e1\u05e1\u05d9\u05dd, \u05d5\u05d4\u05d7\u05d5\u05d6\u05e7 \u05d1\u05e1\u05d5\u05e3 \u05e0\u05de\u05d5\u05da."], [143.2, "\u05e7\u05e6\u05ea \u05de\u05e2\u05dc\u05d9\u05d5, \u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05e9\u05d1\u05d9\u05df \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05de\u05ea\u05d7\u05d9\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05ea\u05da. \u05d6\u05d4 \u05e0\u05d6\u05e7 \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05e7\u05df, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05e4\u05e1\u05dc."], [151.9, "\u05dc\u05db\u05df \u05d1\u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e6\u05e8\u05d9\u05db\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d0\u05d7\u05d9\u05d3\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d1\u05e2\u05e8\u05da \u05e4\u05dc\u05d5\u05e1 \u05de\u05d9\u05e0\u05d5\u05e1 5.5 \u05de\u05e2\u05dc\u05d5\u05ea."], [160.2, "\u05d4\u05e9\u05dc\u05d1 \u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05db\u05d9\u05d1\u05d5\u05d9, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05d9\u05dd."], [163.9, "\u05de\u05d9\u05db\u05dc \u05d4\u05de\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc, \u05e2\u05dd \u05e2\u05e8\u05d1\u05d5\u05dc, \u05db\u05d3\u05d9 \u05e9\u05d4\u05de\u05d9\u05dd \u05dc\u05d0 \u05d9\u05ea\u05d7\u05de\u05de\u05d5 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9 \u05db\u05e9\u05d4\u05e1\u05dc \u05e0\u05db\u05e0\u05e1."], [170.9, "\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df \u05d4\u05d6\u05de\u05df \u05de\u05e4\u05ea\u05d9\u05d7\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d5\u05e2\u05d3 \u05d4\u05db\u05e0\u05d9\u05e1\u05d4 \u05dc\u05de\u05d9\u05dd \u05de\u05d5\u05d2\u05d1\u05dc \u05dc\u05e9\u05e0\u05d9\u05d5\u05ea \u05e1\u05e4\u05d5\u05e8\u05d5\u05ea."], [179.1, "\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d1\u05e8 \u05d1\u05d7\u05de\u05e9 \u05e2\u05d3 \u05e2\u05e9\u05e8 \u05e9\u05e0\u05d9\u05d5\u05ea \u05d1\u05dc\u05d1\u05d3, \u05d5\u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05d1\u05e2\u05e8\u05da \u05d7\u05de\u05e9 \u05e2\u05e9\u05e8\u05d4 \u05e9\u05e0\u05d9\u05d5\u05ea."], [186.8, "\u05d0\u05dd \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d0\u05d9\u05d8\u05d9 \u05de\u05d3\u05d9, \u05d7\u05dc\u05e7 \u05de\u05d4\u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05de\u05d4\u05ea\u05de\u05d9\u05e1\u05d4 \u05de\u05d5\u05e7\u05d3\u05dd \u05de\u05d3\u05d9, \u05d5\u05d4\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05d9\u05d5\u05e8\u05d3\u05d9\u05dd."], [194.9, "\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05de\u05d4\u05d9\u05e8 \u05d2\u05dd \u05de\u05e2\u05d5\u05d5\u05ea \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05d5\u05de\u05e9\u05d0\u05d9\u05e8 \u05d1\u05d4\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd."], [200.3, "\u05db\u05d3\u05d9 \u05dc\u05d4\u05e7\u05d8\u05d9\u05df \u05d0\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea, \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05de\u05d9\u05dd \u05d7\u05de\u05d9\u05dd \u05d0\u05d5 \u05d1\u05ea\u05de\u05d9\u05e1\u05ea \u05e4\u05d5\u05dc\u05d9\u05de\u05e8, \u05e9\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05e7\u05e6\u05ea \u05dc\u05d0\u05d8 \u05d9\u05d5\u05ea\u05e8."], [208.2, "\u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05e2\u05d3\u05d9\u05d9\u05df \u05e8\u05da \u05d9\u05d7\u05e1\u05d9\u05ea. \u05d4\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4 \u05de\u05e1\u05d5\u05de\u05df \u05d1\u05d0\u05d5\u05ea W, \u05d5\u05d4\u05d5\u05d0 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1."], [216.4, "\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05ea\u05d7\u05d9\u05dc \u05de\u05e2\u05e6\u05de\u05d5, \u05d5\u05d6\u05d4 \u05e0\u05e7\u05e8\u05d0 \u05d6\u05d9\u05e7\u05d5\u05df \u05d8\u05d1\u05e2\u05d9."], [222.4, "\u05d0\u05d7\u05e8\u05d9 \u05db\u05de\u05d4 \u05d9\u05de\u05d9\u05dd \u05d4\u05d7\u05d5\u05d6\u05e7 \u05de\u05ea\u05d9\u05d9\u05e6\u05d1, \u05d5\u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05e6\u05d1 T4."], [227.6, "\u05d1\u05d2\u05dc\u05dc \u05d6\u05d4 \u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05d5\u05de\u05e2\u05e6\u05d1\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05db\u05dc \u05e2\u05d5\u05d3 \u05d4\u05dd \u05e8\u05db\u05d9\u05dd."], [233.5, "\u05d5\u05de\u05e1\u05de\u05e8\u05d5\u05ea \u05de-2024 \u05e9\u05d5\u05de\u05e8\u05d9\u05dd \u05d1\u05de\u05e7\u05e4\u05d9\u05d0, \u05db\u05d3\u05d9 \u05dc\u05e2\u05db\u05d1 \u05d0\u05ea \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05e2\u05d3 \u05d4\u05d4\u05ea\u05e7\u05e0\u05d4."], [239.7, "\u05d1-7075 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05d4\u05d8\u05d1\u05e2\u05d9 \u05dc\u05d0 \u05e0\u05e2\u05e6\u05e8, \u05d5\u05dc\u05db\u05df \u05ea\u05de\u05d9\u05d3 \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05dc\u05d4 \u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9."], [247.8, "\u05d1\u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05de\u05ea\u05d5\u05e0\u05d4, \u05d5\u05de\u05d0\u05d9\u05e6\u05d9\u05dd \u05d0\u05ea \u05d4\u05d9\u05d5\u05d5\u05e6\u05e8\u05d5\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd."], [254.1, "\u05d0\u05ea 6061 \u05de\u05d6\u05e7\u05e0\u05d9\u05dd \u05d1\u05e2\u05e8\u05da 18 \u05e9\u05e2\u05d5\u05ea \u05d1-160 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d0\u05ea 7075 \u05d1\u05e2\u05e8\u05da 24 \u05e9\u05e2\u05d5\u05ea \u05d1-120 \u05de\u05e2\u05dc\u05d5\u05ea."], [267.0, "\u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 T6, \u05e9\u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [271.0, "\u05d1\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc\u05d9\u05dd \u05de\u05e9\u05d5\u05d7\u05dc\u05d9\u05dd, \u05db\u05de\u05d5 6063, \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05e7 \u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9 \u05d9\u05e9\u05e8 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e9\u05d9\u05d7\u05d5\u05dc. \u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 T5."], [280.9, "\u05d1\u05d6\u05de\u05df \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e2\u05d5\u05dc\u05d4, \u05de\u05d2\u05d9\u05e2 \u05dc\u05e9\u05d9\u05d0, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d9\u05d5\u05e8\u05d3 \u05d0\u05dd \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd."], [287.4, "\u05d6\u05d9\u05e7\u05d5\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05e0\u05e7\u05e8\u05d0 \u05d6\u05d9\u05e7\u05d5\u05df \u05d7\u05e1\u05e8, \u05d5\u05d6\u05d9\u05e7\u05d5\u05df \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9 \u05e0\u05e7\u05e8\u05d0 \u05d6\u05d9\u05e7\u05d5\u05df \u05d9\u05ea\u05e8."], [294.3, "\u05d1\u05d6\u05d9\u05e7\u05d5\u05df \u05d9\u05ea\u05e8 \u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d2\u05d3\u05dc\u05d9\u05dd \u05d5\u05de\u05ea\u05e8\u05d7\u05e7\u05d9\u05dd \u05d6\u05d4 \u05de\u05d6\u05d4, \u05d5\u05d4\u05d7\u05d5\u05d6\u05e7 \u05d9\u05d5\u05e8\u05d3."], [300.2, "\u05d0\u05d1\u05dc \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05db\u05d5\u05d5\u05e0\u05d4 \u05d6\u05d9\u05e7\u05d5\u05df \u05d9\u05ea\u05e8. \u05d6\u05d4 \u05d4\u05de\u05e6\u05d1 T73."], [306.0, "\u05d1-7075 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e9\u05e0\u05d9 \u05e9\u05dc\u05d1\u05d9\u05dd: \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 105 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d9\u05d5\u05dd \u05d5\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 165 \u05de\u05e2\u05dc\u05d5\u05ea."], [317.5, "\u05d4\u05d7\u05d5\u05d6\u05e7 \u05d9\u05d5\u05e8\u05d3 \u05d1\u05db\u05e2\u05e9\u05e8\u05d4 \u05e2\u05d3 \u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d0\u05d7\u05d5\u05d6 \u05dc\u05e2\u05d5\u05de\u05ea T6."], [322.4, "\u05d0\u05d1\u05dc \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e1\u05d3\u05d9\u05e7\u05d4 \u05de\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4 \u05ea\u05d7\u05ea \u05de\u05d0\u05de\u05e5 \u05e2\u05d5\u05dc\u05d4 \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05db\u05df T73 \u05e0\u05e4\u05d5\u05e5 \u05d1\u05d7\u05dc\u05e7\u05d9 \u05ea\u05e2\u05d5\u05e4\u05d4 \u05e2\u05d1\u05d9\u05dd."], [331.4, "\u05d5\u05de\u05d4 \u05d6\u05d4 T651? \u05d4\u05e1\u05e4\u05e8\u05d5\u05ea 51 \u05d0\u05d5\u05de\u05e8\u05d5\u05ea \u05e9\u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05dc\u05e4\u05e0\u05d9 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df, \u05de\u05d5\u05ea\u05d7\u05d9\u05dd \u05d0\u05ea \u05d4\u05dc\u05d5\u05d7."], [340.1, "\u05de\u05d5\u05ea\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d9\u05df \u05d0\u05d7\u05d5\u05d6 \u05d5\u05d7\u05e6\u05d9 \u05dc\u05e9\u05dc\u05d5\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6\u05d9\u05dd, \u05d5\u05d4\u05de\u05ea\u05d9\u05d7\u05d4 \u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05e9\u05d0\u05d9\u05e8."], [347.7, "\u05d1\u05d2\u05dc\u05dc \u05d6\u05d4 \u05dc\u05d5\u05d7 T651 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05db\u05e9\u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05de\u05de\u05e0\u05d5 \u05d7\u05dc\u05e7\u05d9\u05dd."], [353.6, "\u05d5\u05d1-2024 \u05e0\u05e4\u05d5\u05e5 \u05d4\u05de\u05e6\u05d1 T3, \u05db\u05dc\u05d5\u05de\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc \u05d1\u05e7\u05d5\u05e8 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df \u05d8\u05d1\u05e2\u05d9."], [362.2, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05e6\u05d1 O, \u05e9\u05d4\u05d5\u05d0 \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0. \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d1\u05e2\u05e8\u05da 415 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8."], [370.7, "\u05d1\u05de\u05e6\u05d1 O \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d4\u05db\u05d9 \u05e8\u05da, \u05d5\u05e7\u05dc \u05dc\u05e2\u05e6\u05d1 \u05d5\u05dc\u05db\u05d5\u05e4\u05e3 \u05d0\u05d5\u05ea\u05d5."], [375.5, "\u05d0\u05d7\u05e8 \u05db\u05da \u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05ea \u05dc\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df."], [379.8, "\u05d4\u05ea\u05db\u05d4 \u05d1\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d1\u05d2\u05dc\u05dc \u05d7\u05d5\u05dd \u05d9\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05d4\u05e0\u05d6\u05e7 \u05d4\u05d2\u05e8\u05d5\u05e2 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d0\u05d9\u05df \u05dc\u05d4 \u05ea\u05d9\u05e7\u05d5\u05df."], [386.3, "\u05d4\u05e9\u05d4\u05d9\u05d4 \u05d0\u05e8\u05d5\u05db\u05d4 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05d7\u05d5\u05d6\u05e7 \u05e0\u05de\u05d5\u05da, \u05d5\u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [392.1, "\u05e2\u05d9\u05d5\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d7\u05d9\u05d9\u05d1 \u05d9\u05d9\u05e9\u05d5\u05e8, \u05d5\u05d4\u05d9\u05d9\u05e9\u05d5\u05e8 \u05de\u05d5\u05e1\u05d9\u05e3 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [397.2, "\u05d6\u05d9\u05e7\u05d5\u05df \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05e0\u05d5\u05ea\u05df \u05d6\u05d9\u05e7\u05d5\u05df \u05d9\u05ea\u05e8 \u05d1\u05dc\u05d9 \u05db\u05d5\u05d5\u05e0\u05d4, \u05d5\u05d7\u05d5\u05d6\u05e7 \u05e0\u05de\u05d5\u05da."], [403.4, "\u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e8\u05d5\u05ea\u05db\u05d9\u05dd \u05de\u05d0\u05d1\u05d3\u05d9\u05dd \u05d7\u05d5\u05d6\u05e7 \u05dc\u05d9\u05d3 \u05d4\u05e8\u05d9\u05ea\u05d5\u05da, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05ea\u05ea \u05dc\u05d4\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05d7\u05d3\u05e9."], [410.5, "\u05db\u05d3\u05d9 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05e9\u05d4\u05de\u05e6\u05d1 \u05e0\u05db\u05d5\u05df, \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05d7\u05e9\u05de\u05dc\u05d9\u05ea. \u05dc\u05db\u05dc \u05de\u05e6\u05d1 \u05d9\u05e9 \u05d8\u05d5\u05d5\u05d7 \u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05de\u05e9\u05dc\u05d5."], [418.5, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e7\u05d5\u05d3\u05dd \u05db\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8. \u05d4\u05d5\u05d0 \u05e6\u05e8\u05d9\u05da \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05d9\u05d3\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05d1\u05e7\u05e8\u05d4 \u05dc\u05e4\u05d9 \u05ea\u05e7\u05df, \u05d5\u05d6\u05d4 \u05d9\u05e7\u05e8 \u05d1\u05d4\u05e7\u05de\u05d4 \u05d5\u05d1\u05ea\u05d7\u05d6\u05d5\u05e7\u05d4."], [427.6, "\u05de\u05d9\u05db\u05dc \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05d9\u05d9\u05d1 \u05dc\u05d4\u05d9\u05d5\u05ea \u05e6\u05de\u05d5\u05d3 \u05dc\u05ea\u05e0\u05d5\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05ea\u05d7\u05ea\u05d9\u05ea \u05e0\u05e4\u05ea\u05d7\u05ea, \u05e9\u05de\u05e4\u05d9\u05dc\u05d4 \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05e9\u05e8 \u05dc\u05de\u05d9\u05dd."], [436.3, "\u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9 \u05dc\u05d5\u05e7\u05d7 \u05e2\u05d3 \u05d9\u05d5\u05dd \u05e9\u05dc\u05dd, \u05d5-T73 \u05d0\u05e4\u05d9\u05dc\u05d5 \u05d9\u05d5\u05ea\u05e8."], [442.1, "\u05d2\u05dd \u05d9\u05d9\u05e9\u05d5\u05e8 \u05d5\u05de\u05ea\u05d9\u05d7\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d4\u05dd \u05e2\u05d5\u05d3 \u05e2\u05d1\u05d5\u05d3\u05d4."], [446.2, "\u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05dc\u05db\u05dc \u05d0\u05e6\u05d5\u05d5\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05e2\u05d5\u05d3 \u05e2\u05dc\u05d5\u05ea."], [451.2, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05d6\u05d9\u05e7\u05d5\u05df, \u05dc\u05d0 \u05d1\u05db\u05d9\u05d1\u05d5\u05d9."], [455.8, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d1\u05d7\u05dc\u05d5\u05df \u05e6\u05e8, \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d4\u05d9\u05e8 \u05de\u05d0\u05d5\u05d3, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d6\u05d9\u05e7\u05d5\u05df \u05d8\u05d1\u05e2\u05d9 \u05dc-T4, \u05d0\u05d5 \u05d6\u05d9\u05e7\u05d5\u05df \u05de\u05dc\u05d0\u05db\u05d5\u05ea\u05d9 \u05dc-T6."], [464.8, "T73 \u05de\u05d5\u05d5\u05ea\u05e8 \u05e2\u05dc \u05e7\u05e6\u05ea \u05d7\u05d5\u05d6\u05e7 \u05d1\u05e9\u05d1\u05d9\u05dc \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05d5-T651 \u05e2\u05d5\u05d1\u05e8 \u05de\u05ea\u05d9\u05d7\u05d4 \u05e9\u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [474.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05dc\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05d5\u05dc\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc."]]};
window.MH_TR["ch18"]={"t": "\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05db\u05d9\u05e8 \u05e9\u05dc\u05d5\u05e9 \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e9\u05dc \u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05de\u05d9\u05d5\u05d7\u05d3\u05d9\u05dd: \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc."], [12.8, "\u05db\u05d5\u05dc\u05dd \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d4\u05dd \u05de\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05db\u05de\u05d5 \u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d0\u05d1\u05dc \u05dc\u05db\u05dc \u05d0\u05d7\u05d3 \u05d9\u05e9 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05e9\u05dc\u05d5."], [19.8, "\u05d5\u05d1\u05db\u05d5\u05dc\u05dd, \u05d8\u05e2\u05d5\u05ea \u05e7\u05d8\u05e0\u05d4 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05db\u05e1\u05e3."], [24.9, "\u05e0\u05ea\u05d7\u05d9\u05dc \u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd. \u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d9\u05e9 \u05e9\u05e0\u05d9 \u05de\u05d1\u05e0\u05d9\u05dd: \u05d0\u05dc\u05e4\u05d0 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d5\u05d1\u05d8\u05d0 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4."], [33.4, "\u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 Ti-6Al-4V, \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05d2\u05dd Grade 5. \u05d9\u05e9 \u05d1\u05d4 \u05e9\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d5\u05d0\u05e8\u05d1\u05e2\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05d5\u05e0\u05d3\u05d9\u05d5\u05dd."], [43.1, "\u05d4\u05d9\u05d0 \u05dc\u05d1\u05d3\u05d4 \u05de\u05d4\u05d5\u05d5\u05d4 \u05d1\u05e2\u05e8\u05da \u05de\u05d7\u05e6\u05d9\u05ea \u05de\u05db\u05dc \u05d4\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e9\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d5 \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05d4."], [48.3, "\u05d4\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05de\u05d9\u05d9\u05e6\u05d1 \u05d0\u05ea \u05d0\u05dc\u05e4\u05d0, \u05d5\u05d4\u05d5\u05d5\u05e0\u05d3\u05d9\u05d5\u05dd \u05de\u05d9\u05d9\u05e6\u05d1 \u05d0\u05ea \u05d1\u05d8\u05d0, \u05d5\u05dc\u05db\u05df \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8 \u05d9\u05e9 \u05d1\u05d4 \u05d0\u05ea \u05e9\u05e0\u05d9 \u05d4\u05de\u05d1\u05e0\u05d9\u05dd \u05d9\u05d7\u05d3."], [57.0, "\u05de\u05e2\u05dc \u05db-995 \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05dc \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d1\u05d8\u05d0. \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05e7\u05e8\u05d0\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05dc\u05d1\u05d8\u05d0."], [66.5, "\u05db\u05de\u05e2\u05d8 \u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9 \u05d4\u05d7\u05d5\u05dd \u05e9\u05dc \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05e2\u05e9\u05d9\u05dd \u05de\u05ea\u05d7\u05ea \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d6\u05d5, \u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05de\u05d1\u05e0\u05d4 \u05e2\u05d3\u05d9\u05df \u05d5\u05e2\u05dc \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d8\u05d5\u05d1\u05d4."], [74.4, "\u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4, \u05d1\u05d7\u05dc\u05dc, \u05d5\u05d1\u05e9\u05ea\u05dc\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd, \u05db\u05d9 \u05d4\u05d9\u05d0 \u05d7\u05d6\u05e7\u05d4, \u05e7\u05dc\u05d4 \u05d5\u05e2\u05de\u05d9\u05d3\u05d4 \u05d1\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4."], [82.1, "\u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d9\u05e9 \u05e9\u05dc\u05d5\u05e9\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc\u05d9\u05dd \u05e2\u05d9\u05e7\u05e8\u05d9\u05d9\u05dd."], [85.2, "\u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d1\u05d9\u05df 480 \u05dc-650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d0\u05d7\u05e8\u05d9 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05db\u05d1\u05d3 \u05d0\u05d5 \u05e8\u05d9\u05ea\u05d5\u05da."], [94.6, "\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05e8\u05d9\u05db\u05d5\u05da, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 700 \u05e2\u05d3 790 \u05de\u05e2\u05dc\u05d5\u05ea. \u05d1\u05e8\u05d5\u05d1 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2 \u05de\u05d4\u05e1\u05e4\u05e7 \u05db\u05d1\u05e8 \u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4."], [103.9, "\u05d4\u05e9\u05dc\u05d9\u05e9\u05d9 \u05d4\u05d5\u05d0 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df, \u05e9\u05de\u05e2\u05dc\u05d4 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7."], [108.7, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05db-40 \u05de\u05e2\u05dc\u05d5\u05ea \u05de\u05ea\u05d7\u05ea \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 950 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05db\u05d1\u05d9\u05dd \u05d1\u05de\u05d9\u05dd."], [116.8, "\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d6\u05e7\u05e0\u05d9\u05dd \u05d1\u05d9\u05df 480 \u05dc-600 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05de\u05e9\u05da \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea."], [123.2, "\u05d4\u05d7\u05d5\u05d6\u05e7 \u05e2\u05d5\u05dc\u05d4 \u05d1\u05e2\u05e8\u05da \u05d1\u05d7\u05de\u05d9\u05e9\u05d4 \u05e2\u05e9\u05e8 \u05d0\u05d7\u05d5\u05d6, \u05d0\u05d1\u05dc \u05e8\u05e7 \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d9\u05d7\u05e1\u05d9\u05ea. \u05d1\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4, \u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05dc\u05d0\u05d8 \u05de\u05d3\u05d9 \u05d5\u05dc\u05d0 \u05de\u05ea\u05d7\u05d6\u05e7\u05ea."], [134.0, "\u05db\u05e9\u05e6\u05e8\u05d9\u05da \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d4\u05ea\u05e4\u05e9\u05d8\u05d5\u05ea \u05e1\u05d3\u05e7\u05d9\u05dd, \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05d9\u05db\u05d5\u05da \u05db\u05e4\u05d5\u05dc, \u05d0\u05d5 \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05dc\u05d1\u05d8\u05d0."], [143.1, "\u05d4\u05d1\u05e2\u05d9\u05d4 \u05d4\u05d2\u05d3\u05d5\u05dc\u05d4 \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05d9\u05d0 \u05e9\u05d1\u05d7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05e1\u05d5\u05e4\u05d2 \u05d7\u05de\u05e6\u05df, \u05d7\u05e0\u05e7\u05df \u05d5\u05de\u05d9\u05de\u05df \u05de\u05d4\u05e1\u05d1\u05d9\u05d1\u05d4."], [149.3, "\u05d4\u05d7\u05de\u05e6\u05df \u05d7\u05d5\u05d3\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d9\u05d5\u05e6\u05e8 \u05e9\u05db\u05d1\u05d4 \u05e7\u05e9\u05d4 \u05d5\u05e9\u05d1\u05d9\u05e8\u05d4 \u05e9\u05e0\u05e7\u05e8\u05d0\u05ea \u05e9\u05db\u05d1\u05ea \u05d0\u05dc\u05e4\u05d0."], [155.6, "\u05d1\u05e9\u05db\u05d1\u05d4 \u05d4\u05d6\u05d5 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e1\u05d3\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd, \u05d5\u05d4\u05dd \u05de\u05e7\u05e6\u05e8\u05d9\u05dd \u05de\u05d0\u05d5\u05d3 \u05d0\u05ea \u05d7\u05d9\u05d9 \u05d4\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7."], [161.9, "\u05dc\u05db\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05e8\u05e7 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05e2\u05de\u05d5\u05e7 \u05d0\u05d5 \u05d1\u05d0\u05e8\u05d2\u05d5\u05df, \u05d5\u05dc\u05e2\u05d5\u05dc\u05dd \u05dc\u05d0 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d0\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e2\u05dd \u05de\u05d9\u05de\u05df."], [169.5, "\u05d4\u05de\u05d9\u05de\u05df \u05d2\u05d5\u05e8\u05dd \u05dc\u05e9\u05d1\u05d9\u05e8\u05d5\u05ea \u05de\u05d9\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05d4\u05d5\u05d0 \u05de\u05d5\u05d2\u05d1\u05dc \u05d1\u05de\u05e4\u05e8\u05d8."], [174.4, "\u05d5\u05d0\u05dd \u05d1\u05db\u05dc \u05d6\u05d0\u05ea \u05e0\u05d5\u05e6\u05e8\u05d4 \u05e9\u05db\u05d1\u05ea \u05d0\u05dc\u05e4\u05d0, \u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9 \u05d0\u05d5 \u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05db\u05d9\u05de\u05d9."], [180.4, "\u05d5\u05d2\u05dd \u05d4\u05e0\u05d9\u05e7\u05d5\u05d9 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d7\u05e9\u05d5\u05d1. \u05d8\u05d1\u05d9\u05e2\u05d5\u05ea \u05d0\u05e6\u05d1\u05e2 \u05d5\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05e9\u05dc \u05e0\u05d5\u05d6\u05dc \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05dc\u05d5\u05dc\u05d5\u05ea \u05dc\u05d6\u05d4\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [188.5, "\u05e2\u05db\u05e9\u05d9\u05d5 \u05dc\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd. \u05d4\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d4\u05d9\u05d0 C17200, \u05e2\u05dd \u05db\u05e9\u05e0\u05d9 \u05d0\u05d7\u05d5\u05d6 \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd."], [196.5, "\u05d4\u05d9\u05d0 \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05de\u05d1\u05d9\u05df \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05d4\u05e0\u05d7\u05d5\u05e9\u05ea, \u05d5\u05e2\u05d3\u05d9\u05d9\u05df \u05de\u05d5\u05dc\u05d9\u05db\u05d4 \u05d7\u05e9\u05de\u05dc \u05d5\u05d7\u05d5\u05dd \u05d4\u05d9\u05d8\u05d1."], [202.9, "\u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05de\u05e0\u05d4 \u05e7\u05e4\u05d9\u05e6\u05d9\u05dd, \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05d7\u05e9\u05de\u05dc\u05d9\u05d9\u05dd, \u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05dc\u05d4\u05d6\u05e8\u05e7\u05ea \u05e4\u05dc\u05e1\u05d8\u05d9\u05e7, \u05d5\u05db\u05dc\u05d9\u05dd \u05e9\u05dc\u05d0 \u05de\u05e2\u05dc\u05d9\u05dd \u05e0\u05d9\u05e6\u05d5\u05e6\u05d5\u05ea."], [210.4, "\u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05de\u05d2\u05d9\u05e2 \u05de\u05d4\u05d9\u05e6\u05e8\u05df \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 790 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05d4\u05d9\u05e8."], [219.2, "\u05d1\u05de\u05e6\u05d1 \u05d4\u05d6\u05d4 \u05d4\u05d5\u05d0 \u05e8\u05da, \u05d5\u05e7\u05dc \u05dc\u05e2\u05d1\u05d3 \u05d5\u05dc\u05e2\u05e6\u05d1 \u05d0\u05d5\u05ea\u05d5. \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05de\u05d6\u05e7\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05e9\u05e2\u05ea\u05d9\u05d9\u05dd \u05e2\u05d3 \u05e9\u05dc\u05d5\u05e9 \u05e9\u05e2\u05d5\u05ea, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 315 \u05de\u05e2\u05dc\u05d5\u05ea."], [230.3, "\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d6\u05d9\u05e7\u05d5\u05df \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d7\u05d3\u05e8, \u05d5\u05dc\u05db\u05df \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d0\u05d7\u05e1\u05df \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05e6\u05d1 \u05d4\u05e8\u05da \u05d6\u05de\u05df \u05e8\u05d1."], [238.0, "\u05d1\u05d6\u05d9\u05e7\u05d5\u05df, \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05d5\u05dc\u05d4 \u05dc\u05d1\u05e2\u05e8\u05da 38 \u05e2\u05d3 41 \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc C, \u05d5\u05d2\u05dd \u05d4\u05de\u05d5\u05dc\u05d9\u05db\u05d5\u05ea \u05de\u05e9\u05ea\u05e4\u05e8\u05ea."], [246.0, "\u05d1\u05d6\u05de\u05df \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05d7\u05de\u05e6\u05e0\u05d9\u05dd, \u05d2\u05dd \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d5\u05dc\u05db\u05df \u05de\u05e0\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [253.4, "\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d3\u05e2\u05ea \u05e9\u05d0\u05d1\u05e7 \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05e8\u05e2\u05d9\u05dc. \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d5\u05dc\u05d9\u05d8\u05d5\u05e9 \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05d9\u05e0\u05d9\u05e7\u05d4 \u05d5\u05d0\u05de\u05e6\u05e2\u05d9 \u05de\u05d9\u05d2\u05d5\u05df, \u05dc\u05e4\u05d9 \u05d4\u05d5\u05e8\u05d0\u05d5\u05ea \u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [262.2, "\u05d4\u05e7\u05d1\u05d5\u05e6\u05d4 \u05d4\u05e9\u05dc\u05d9\u05e9\u05d9\u05ea \u05d4\u05d9\u05d0 \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc, \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05e0\u05d9\u05e7\u05dc. \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05d0\u05d9\u05e0\u05e7\u05d5\u05e0\u05dc 718."], [270.9, "\u05d9\u05e9 \u05d1\u05d4 \u05d1\u05e2\u05e8\u05da \u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d9\u05e7\u05dc, \u05ea\u05e9\u05e2\u05d4 \u05e2\u05e9\u05e8 \u05d0\u05d7\u05d5\u05d6 \u05db\u05e8\u05d5\u05dd, \u05d5\u05d7\u05de\u05d9\u05e9\u05d4 \u05d0\u05d7\u05d5\u05d6 \u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd."], [277.1, "\u05d4\u05d9\u05d0 \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05e2\u05d3 \u05db-650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05d4 \u05d1\u05de\u05e0\u05d5\u05e2\u05d9 \u05e1\u05d9\u05dc\u05d5\u05df, \u05d1\u05d8\u05d5\u05e8\u05d1\u05d9\u05e0\u05d5\u05ea \u05d5\u05d1\u05d1\u05e8\u05d2\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4."], [287.1, "\u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc\u05d4 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d6\u05e2\u05d9\u05e8\u05d9\u05dd \u05e9\u05dc \u05e0\u05d9\u05e7\u05dc \u05d5\u05e0\u05d9\u05d5\u05d1\u05d9\u05d5\u05dd, \u05e9\u05e0\u05e7\u05e8\u05d0\u05d9\u05dd gamma prime \u05d5-gamma double prime."], [295.0, "\u05e7\u05d5\u05d3\u05dd \u05e2\u05d5\u05e9\u05d9\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 980 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8."], [301.5, "\u05d0\u05d7\u05e8 \u05db\u05da \u05de\u05d1\u05e6\u05e2\u05d9\u05dd \u05d6\u05d9\u05e7\u05d5\u05df \u05db\u05e4\u05d5\u05dc: \u05e9\u05de\u05d5\u05e0\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d1-720 \u05de\u05e2\u05dc\u05d5\u05ea, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05dc-620 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e9\u05dd \u05de\u05de\u05e9\u05d9\u05db\u05d9\u05dd \u05e2\u05d3 \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05e8\u05d4 \u05e9\u05e2\u05d5\u05ea \u05d1\u05e1\u05da \u05d4\u05db\u05d5\u05dc."], [313.5, "\u05d4\u05d7\u05dc\u05e7\u05d9\u05e7\u05d9\u05dd \u05d1-718 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8, \u05d5\u05d6\u05d4 \u05d9\u05ea\u05e8\u05d5\u05df. \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05ea\u05da \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05d1\u05dc\u05d9 \u05e9\u05d9\u05d9\u05e1\u05d3\u05e7, \u05d5\u05e8\u05e7 \u05d0\u05d7\u05e8 \u05db\u05da \u05dc\u05d7\u05d6\u05e7 \u05d0\u05d5\u05ea\u05d5."], [324.3, "\u05d2\u05dd \u05db\u05d0\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd, \u05db\u05d3\u05d9 \u05dc\u05e9\u05de\u05d5\u05e8 \u05e2\u05dc \u05e4\u05e0\u05d9 \u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9\u05d9\u05dd."], [329.5, "\u05d1\u05d8\u05d1\u05dc\u05d4 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05d0\u05d5\u05ea \u05d0\u05ea \u05d4\u05d4\u05d1\u05d3\u05dc\u05d9\u05dd \u05d1\u05d9\u05df \u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd."], [333.4, "\u05d1\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05d4\u05e2\u05d9\u05e7\u05e8\u05d9. \u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd, \u05d6\u05de\u05df \u05d4\u05d6\u05d9\u05e7\u05d5\u05df \u05d5\u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea. \u05d5\u05d1-718, \u05d3\u05d9\u05d5\u05e7 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05d6\u05de\u05df \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05d4\u05d0\u05e8\u05d5\u05da."], [346.1, "\u05e9\u05db\u05d1\u05ea \u05d0\u05dc\u05e4\u05d0 \u05e9\u05dc\u05d0 \u05d4\u05d5\u05e1\u05e8\u05d4 \u05de\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d4\u05d9\u05d0 \u05e1\u05d9\u05d1\u05d4 \u05e0\u05e4\u05d5\u05e6\u05d4 \u05dc\u05e9\u05d1\u05e8 \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [351.5, "\u05d7\u05d9\u05de\u05d5\u05dd \u05e9\u05dc \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05de\u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05dc\u05d1\u05d8\u05d0, \u05d1\u05d8\u05e2\u05d5\u05ea, \u05de\u05d2\u05d3\u05d9\u05dc \u05d0\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d5\u05e4\u05d5\u05d2\u05e2 \u05d1\u05de\u05e9\u05d9\u05db\u05d5\u05ea."], [359.0, "\u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd, \u05d6\u05d9\u05e7\u05d5\u05df \u05d0\u05e8\u05d5\u05da \u05d0\u05d5 \u05d7\u05dd \u05de\u05d3\u05d9 \u05d2\u05d5\u05e8\u05dd \u05dc\u05d6\u05d9\u05e7\u05d5\u05df \u05d9\u05ea\u05e8, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea."], [366.3, "\u05d5\u05d1-718, \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05ea\u05de\u05d9\u05e1\u05d4 \u05dc\u05d0 \u05e0\u05db\u05d5\u05e0\u05d4 \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4, \u05d5\u05e4\u05d5\u05d2\u05e2\u05ea \u05d1\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d1\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d6\u05d7\u05d9\u05dc\u05d4."], [374.4, "\u05d1\u05db\u05dc \u05e9\u05dc\u05d5\u05e9\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd, \u05dc\u05db\u05dc\u05d5\u05da \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05d6\u05d4\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05dc\u05db\u05df \u05de\u05e0\u05e7\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1 \u05dc\u05e4\u05e0\u05d9 \u05db\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc."], [383.9, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd \u05de\u05ea\u05e7\u05d3\u05de\u05d9\u05dd, \u05d5\u05d1\u05e7\u05e8\u05d4 \u05d4\u05d3\u05d5\u05e7\u05d4 \u05e2\u05dc \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [391.6, "\u05d6\u05d9\u05e7\u05d5\u05df \u05e9\u05dc 718 \u05dc\u05d5\u05e7\u05d7 \u05e9\u05de\u05d5\u05e0\u05d4 \u05e2\u05e9\u05e8\u05d4 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05e2\u05d5\u05d3 \u05d6\u05de\u05df \u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05e7\u05d9\u05e8\u05d5\u05e8."], [397.7, "\u05d4\u05e1\u05e8\u05ea \u05e9\u05db\u05d1\u05ea \u05d0\u05dc\u05e4\u05d0 \u05d1\u05db\u05e8\u05e1\u05d5\u05dd \u05db\u05d9\u05de\u05d9 \u05d4\u05d9\u05d0 \u05e9\u05dc\u05d1 \u05e0\u05d5\u05e1\u05e3, \u05d5\u05d3\u05d5\u05e8\u05e9\u05ea \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05d1\u05ea\u05db\u05e0\u05d5\u05df."], [404.2, "\u05d1\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd, \u05d0\u05de\u05e6\u05e2\u05d9 \u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05d5\u05d4\u05e0\u05d9\u05e7\u05d5\u05d9 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e2\u05dc\u05d5\u05ea."], [409.4, "\u05d5\u05d1\u05db\u05dc \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05d4\u05d0\u05dc\u05d4 \u05e0\u05d3\u05e8\u05e9\u05d5\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05d1\u05e7\u05e8\u05d4 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05de\u05ea\u05d9\u05d7\u05d4 \u05dc\u05db\u05dc \u05de\u05e0\u05d4."], [417.2, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05e8\u05e7 \u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d0\u05d5 \u05d1\u05d0\u05e8\u05d2\u05d5\u05df, \u05d5\u05e0\u05d6\u05d4\u05e8\u05d9\u05dd \u05de\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8 \u05dc\u05d1\u05d8\u05d0 \u05d5\u05de\u05e9\u05db\u05d1\u05ea \u05d0\u05dc\u05e4\u05d0."], [426.2, "\u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd \u05de\u05e7\u05d1\u05dc\u05ea \u05d6\u05d9\u05e7\u05d5\u05df \u05e7\u05e6\u05e8 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05d5\u05d3\u05d5\u05e8\u05e9\u05ea \u05d4\u05e7\u05e4\u05d3\u05d4 \u05e2\u05dc \u05d1\u05d8\u05d9\u05d7\u05d5\u05ea."], [432.6, "\u05d5\u05d0\u05d9\u05e0\u05e7\u05d5\u05e0\u05dc 718 \u05de\u05e7\u05d1\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05ea\u05de\u05d9\u05e1\u05d4 \u05d5\u05d6\u05d9\u05e7\u05d5\u05df \u05db\u05e4\u05d5\u05dc \u05d0\u05e8\u05d5\u05da, \u05e9\u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05dc\u05d5 \u05d7\u05d5\u05d6\u05e7 \u05d2\u05d1\u05d5\u05d4 \u05d1\u05d7\u05d5\u05dd."], [440.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7: \u05e8\u05d9\u05db\u05d5\u05da, \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d5-ADI."]]};
window.MH_TR["ch19"]={"t": "\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7: \u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05d1\u05e8\u05d6\u05dc \u05e2\u05dd \u05d4\u05e8\u05d1\u05d4 \u05e4\u05d7\u05de\u05df, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 2.5 \u05dc-4 \u05d0\u05d7\u05d5\u05d6."], [14.0, "\u05e8\u05d5\u05d1 \u05d4\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05dc\u05d0 \u05e2\u05d5\u05d1\u05e8\u05d5\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05db\u05dc\u05dc. \u05d0\u05d1\u05dc \u05db\u05e9\u05e6\u05e8\u05d9\u05da, \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05e9\u05e0\u05d4 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4, \u05d5\u05e6\u05d5\u05e8\u05ea \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05e0\u05e9\u05d0\u05e8\u05ea \u05db\u05de\u05d5 \u05e9\u05e0\u05d5\u05e6\u05e8\u05d4 \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4."], [24.2, "\u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d4\u05e1\u05d5\u05d2\u05d9\u05dd \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7, \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05e8\u05d9\u05db\u05d5\u05da \u05d5\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d0\u05ea ADI."], [32.7, "\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05d0\u05e4\u05d5\u05e8, \u05d4\u05e4\u05d7\u05de\u05df \u05e0\u05de\u05e6\u05d0 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e4\u05ea\u05d9\u05ea\u05d9 \u05d2\u05e8\u05e4\u05d9\u05d8. \u05d4\u05d5\u05d0 \u05d6\u05d5\u05dc, \u05e0\u05d5\u05d7 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05d1\u05d5\u05dc\u05e2 \u05e8\u05e2\u05d9\u05d3\u05d5\u05ea."], [40.8, "\u05dc\u05db\u05df \u05e2\u05d5\u05e9\u05d9\u05dd \u05de\u05de\u05e0\u05d5 \u05d2\u05d5\u05e4\u05d9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea, \u05d1\u05e1\u05d9\u05e1\u05d9\u05dd \u05d5\u05d1\u05dc\u05d5\u05e7\u05d9\u05dd \u05e9\u05dc \u05de\u05e0\u05d5\u05e2\u05d9\u05dd."], [45.7, "\u05d0\u05d1\u05dc \u05d4\u05e4\u05ea\u05d9\u05ea\u05d9\u05dd \u05de\u05ea\u05e0\u05d4\u05d2\u05d9\u05dd \u05db\u05de\u05d5 \u05e1\u05d3\u05e7\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05e9\u05d1\u05d9\u05e8 \u05d5\u05d7\u05dc\u05e9 \u05d9\u05d7\u05e1\u05d9\u05ea \u05d1\u05de\u05ea\u05d9\u05d7\u05d4."], [52.0, "\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e0\u05ea\u05da \u05de\u05d2\u05e0\u05d6\u05d9\u05d5\u05dd, \u05d5\u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05e6\u05d5\u05e8\u05ea \u05db\u05d3\u05d5\u05e8\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd."], [59.0, "\u05d4\u05db\u05d3\u05d5\u05e8\u05d9\u05dd \u05dc\u05d0 \u05de\u05e8\u05db\u05d6\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05db\u05de\u05d5 \u05d4\u05e4\u05ea\u05d9\u05ea\u05d9\u05dd, \u05d5\u05dc\u05db\u05df \u05d4\u05d5\u05d0 \u05d7\u05d6\u05e7 \u05d5\u05de\u05e9\u05d9\u05da \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05e7\u05e8\u05d5\u05d1 \u05d1\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05dc\u05e4\u05dc\u05d3\u05d4."], [67.5, "\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05dc\u05d1\u05df \u05d0\u05d9\u05df \u05d2\u05e8\u05e4\u05d9\u05d8: \u05d4\u05e4\u05d7\u05de\u05df \u05e7\u05e9\u05d5\u05e8 \u05d1\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd. \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05d5\u05e9\u05d1\u05d9\u05e8, \u05d5\u05de\u05e9\u05de\u05e9 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e2\u05de\u05d9\u05d3\u05d9\u05dd \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."], [77.4, "\u05e1\u05d1\u05d9\u05d1 \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8 \u05d9\u05e9 \u05de\u05d8\u05e8\u05d9\u05e6\u05d4, \u05e4\u05e8\u05d9\u05d8\u05d9\u05ea, \u05e4\u05e8\u05dc\u05d9\u05d8\u05d9\u05ea \u05d0\u05d5 \u05ea\u05e2\u05e8\u05d5\u05d1\u05ea \u05e9\u05dc\u05d4\u05df, \u05d5\u05d0\u05d5\u05ea\u05d4 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05de\u05e9\u05e0\u05d4."], [86.0, "\u05d9\u05e6\u05d9\u05e7\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05d1\u05d0\u05d5\u05e4\u05df \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3: \u05d4\u05d3\u05e4\u05e0\u05d5\u05ea \u05d4\u05d3\u05e7\u05d5\u05ea \u05de\u05ea\u05e7\u05e8\u05e8\u05d5\u05ea \u05de\u05d4\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d4\u05e2\u05d1\u05d9\u05dd \u05dc\u05d0\u05d8. \u05db\u05da \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d1\u05d4 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05d9\u05d5\u05e8\u05d9\u05d9\u05dd."], [96.4, "\u05db\u05e9\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d7\u05d5\u05de\u05e8 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05e9\u05d1\u05d1\u05d9, \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6 \u05d5\u05de\u05ea\u05e2\u05d5\u05d5\u05ea."], [103.1, "\u05dc\u05db\u05df \u05d1\u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05de\u05d3\u05d5\u05d9\u05e7\u05d5\u05ea, \u05db\u05de\u05d5 \u05d2\u05d5\u05e4\u05d9 \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05d1\u05e1\u05d9\u05e1\u05d9\u05dd, \u05e2\u05d5\u05e9\u05d9\u05dd \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e1\u05d5\u05e4\u05d9."], [110.6, "\u05d1\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05d0\u05e4\u05d5\u05e8 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05d9\u05d0 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d9\u05df 510 \u05dc-650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05dc\u05e4\u05d9 \u05d4\u05d4\u05e8\u05db\u05d1. \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05dc\u05d0 \u05de\u05e1\u05d2\u05e1\u05d2\u05ea, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 550."], [123.5, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d8, \u05d1\u05db-100 \u05de\u05e2\u05dc\u05d5\u05ea \u05dc\u05e9\u05e2\u05d4, \u05d5\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d1\u05e2\u05e8\u05da \u05e9\u05e2\u05d4 \u05dc\u05db\u05dc 25 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e2\u05d5\u05d1\u05d9."], [130.8, "\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d7\u05e9\u05d5\u05d1 \u05dc\u05d0 \u05e4\u05d7\u05d5\u05ea: \u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05dc\u05e4\u05d7\u05d5\u05ea \u05e2\u05d3 \u05db-300 \u05de\u05e2\u05dc\u05d5\u05ea. \u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd."], [140.1, "\u05e4\u05e2\u05dd \u05d4\u05e9\u05d0\u05d9\u05e8\u05d5 \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05d7\u05d5\u05d3\u05e9\u05d9\u05dd \u05db\u05d3\u05d9 \u05e9\u05d9\u05ea\u05d9\u05d9\u05e6\u05d1\u05d5 \u05de\u05e2\u05e6\u05de\u05df, \u05d0\u05d1\u05dc \u05de\u05d7\u05e7\u05e8\u05d9\u05dd \u05d4\u05e8\u05d0\u05d5 \u05e9\u05d6\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05e9\u05d7\u05e8\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd."], [148.3, "\u05db\u05e9\u05d4\u05d9\u05e6\u05d9\u05e7\u05d4 \u05e7\u05e9\u05d4 \u05de\u05d3\u05d9 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3, \u05e2\u05d5\u05e9\u05d9\u05dd \u05e8\u05d9\u05db\u05d5\u05da. \u05d4\u05de\u05d8\u05e8\u05d4: \u05dc\u05e4\u05e8\u05e7 \u05d0\u05ea \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8, \u05db\u05da \u05e9\u05ea\u05d9\u05e9\u05d0\u05e8 \u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e9\u05dc \u05e4\u05e8\u05d9\u05d8 \u05e8\u05da."], [157.5, "\u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05ea\u05ea-\u05e7\u05e8\u05d9\u05d8\u05d9 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05db-700 \u05e2\u05d3 760 \u05de\u05e2\u05dc\u05d5\u05ea, \u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05e9\u05e2\u05d4 \u05e2\u05d3 \u05d0\u05e8\u05d1\u05e2 \u05e9\u05e2\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d1\u05ea\u05e0\u05d5\u05e8."], [167.1, "\u05d1\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05de\u05e2\u05dc \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05de\u05e2\u05d1\u05e8, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 870 \u05e2\u05d3 900 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05dc\u05d0\u05d8 \u05de\u05d0\u05d5\u05d3, \u05d1\u05e2\u05e8\u05da 55 \u05de\u05e2\u05dc\u05d5\u05ea \u05dc\u05e9\u05e2\u05d4."], [178.7, "\u05d0\u05dd \u05d9\u05e9 \u05d1\u05d9\u05e6\u05d9\u05e7\u05d4 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05e9\u05d4\u05ea\u05e7\u05e8\u05e8\u05d5 \u05de\u05d4\u05e8, \u05e2\u05d5\u05e9\u05d9\u05dd \u05e8\u05d9\u05db\u05d5\u05da \u05d2\u05e8\u05e4\u05d9\u05d8\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d1\u05db-900 \u05e2\u05d3 950 \u05de\u05e2\u05dc\u05d5\u05ea."], [189.6, "\u05d4\u05d7\u05d5\u05dd \u05de\u05e4\u05e8\u05e7 \u05d0\u05ea \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05dc\u05d2\u05e8\u05e4\u05d9\u05d8 \u05d5\u05dc\u05d1\u05e8\u05d6\u05dc. \u05d0\u05d1\u05dc \u05db\u05e8\u05d5\u05dd, \u05d0\u05e4\u05d9\u05dc\u05d5 \u05e8\u05d1\u05e2 \u05d0\u05d7\u05d5\u05d6, \u05d9\u05d5\u05e6\u05e8 \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05d9\u05e6\u05d9\u05d1\u05d9\u05dd \u05e9\u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05de\u05ea\u05e4\u05e8\u05e7\u05d9\u05dd."], [199.6, "\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05e9\u05dc \u05d4\u05e8\u05d9\u05db\u05d5\u05da: \u05e7\u05e9\u05d9\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05e7\u05dc \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d1\u05d1\u05e8\u05d6\u05dc \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05d2\u05dd \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8."], [208.5, "\u05d1\u05e0\u05e8\u05de\u05d5\u05dc \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05db-870 \u05e2\u05d3 900 \u05de\u05e2\u05dc\u05d5\u05ea \u05d5\u05de\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8. \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e4\u05e8\u05dc\u05d9\u05d8\u05d9\u05ea, \u05e2\u05dd \u05d7\u05d5\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [219.1, "\u05d0\u05e4\u05e9\u05e8 \u05d2\u05dd \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05db\u05de\u05d5 \u05e4\u05dc\u05d3\u05d4: \u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05db-840 \u05e2\u05d3 900 \u05de\u05e2\u05dc\u05d5\u05ea, \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05d4\u05e8\u05e4\u05d9\u05d4."], [229.2, "\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05d4\u05d5\u05d0 \u05e1\u05d3\u05e7\u05d9\u05dd. \u05dc\u05db\u05df \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d8 \u05e2\u05d3 \u05d1\u05e2\u05e8\u05da 650 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05e8\u05e7 \u05de\u05e9\u05dd \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8. \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05de\u05e1\u05d5\u05d1\u05db\u05d5\u05ea \u05de\u05db\u05d1\u05d9\u05dd \u05d1\u05e9\u05de\u05df \u05d7\u05dd, 80 \u05e2\u05d3 100 \u05de\u05e2\u05dc\u05d5\u05ea."], [242.4, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05e4\u05d9 \u05d7\u05de\u05d9\u05e9\u05d4 \u05de\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e4\u05e8\u05dc\u05d9\u05d8\u05d9\u05ea."], [249.6, "\u05d1\u05e4\u05d5\u05e2\u05dc, \u05e0\u05e4\u05d5\u05e5 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d4\u05d1\u05d4, \u05dc\u05de\u05e9\u05dc \u05d1\u05de\u05e1\u05d9\u05dc\u05d5\u05ea \u05e9\u05dc \u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d5\u05d1\u05e9\u05e8\u05d5\u05d5\u05dc\u05d9 \u05e6\u05d9\u05dc\u05d9\u05e0\u05d3\u05e8."], [259.3, "\u05d4\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d6\u05d5 \u05e2\u05d5\u05d1\u05d3\u05ea \u05d8\u05d5\u05d1 \u05e8\u05e7 \u05d1\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e4\u05e8\u05dc\u05d9\u05d8\u05d9\u05ea. \u05d1\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05e4\u05e8\u05d9\u05d8\u05d9\u05ea \u05d0\u05d9\u05df \u05de\u05e1\u05e4\u05d9\u05e7 \u05e4\u05d7\u05de\u05df \u05de\u05d5\u05de\u05e1, \u05d5\u05dc\u05db\u05df \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e2\u05d5\u05dc\u05d4."], [269.4, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5 \u05e0\u05db\u05d9\u05e8 \u05d0\u05ea ADI: \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05e9\u05e2\u05d1\u05e8 \u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2."], [275.6, "\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea 850 \u05e2\u05d3 950 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05de\u05db\u05d1\u05d9\u05dd \u05de\u05d4\u05e8 \u05dc\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05d7\u05dd, \u05d1\u05d9\u05df 230 \u05dc-400 \u05de\u05e2\u05dc\u05d5\u05ea."], [287.1, "\u05de\u05d7\u05d6\u05d9\u05e7\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8 \u05e9\u05e2\u05d4 \u05e2\u05d3 \u05db\u05de\u05d4 \u05e9\u05e2\u05d5\u05ea, \u05e2\u05d3 \u05e9\u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4 \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05d0\u05d5\u05e1\u05e4\u05e8\u05d9\u05d8: \u05e4\u05e8\u05d9\u05d8 \u05de\u05d7\u05d8\u05e0\u05d9 \u05d5\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e2\u05e9\u05d9\u05e8 \u05d1\u05e4\u05d7\u05de\u05df."], [296.0, "\u05d1\u05d2\u05dc\u05dc \u05d4\u05e1\u05d9\u05dc\u05d9\u05e7\u05d5\u05df \u05d4\u05d2\u05d1\u05d5\u05d4 \u05d1\u05d1\u05e8\u05d6\u05dc, \u05dc\u05d0 \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05db\u05de\u05d5 \u05d1\u05d1\u05d9\u05d9\u05e0\u05d9\u05d8 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4. \u05d6\u05d4 \u05de\u05d4 \u05e9\u05e0\u05d5\u05ea\u05df \u05d0\u05ea \u05d4\u05ea\u05db\u05d5\u05e0\u05d5\u05ea \u05d4\u05de\u05d9\u05d5\u05d7\u05d3\u05d5\u05ea \u05e9\u05dc ADI."], [305.1, "\u05d4\u05de\u05d1\u05e0\u05d4 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05d0\u05de\u05d1\u05d8 \u05e2\u05e6\u05de\u05d5, \u05d5\u05dc\u05db\u05df \u05d0\u05d9\u05df \u05e6\u05d5\u05e8\u05da \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d6\u05d4, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df."], [311.3, "\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05ea \u05d4\u05d0\u05de\u05d1\u05d8 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05ea \u05d4\u05d3\u05e8\u05d2\u05d4: \u05d0\u05de\u05d1\u05d8 \u05d7\u05dd \u05e0\u05d5\u05ea\u05df \u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d5\u05e7\u05e9\u05d9\u05d7\u05d5\u05ea, \u05d5\u05d0\u05de\u05d1\u05d8 \u05e7\u05e8 \u05e0\u05d5\u05ea\u05df \u05d7\u05d5\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d9\u05d5\u05ea."], [320.8, "\u05d4\u05d3\u05e8\u05d2\u05d5\u05ea \u05d1\u05ea\u05e7\u05df ISO 17804 \u05e0\u05e2\u05d5\u05ea \u05d1\u05d9\u05df 800 \u05dc-1,400 \u05de\u05d2\u05d4 \u05e4\u05e1\u05e7\u05dc \u05d7\u05d5\u05d6\u05e7 \u05de\u05e9\u05d9\u05db\u05d4, \u05d5\u05d1\u05ea\u05e7\u05df \u05d4\u05d0\u05de\u05e8\u05d9\u05e7\u05d0\u05d9 \u05e2\u05d3 1,600."], [333.1, "\u05d4\u05d7\u05d5\u05d6\u05e7 \u05db\u05e4\u05d5\u05dc \u05de\u05d6\u05d4 \u05e9\u05dc \u05d1\u05e8\u05d6\u05dc \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05e8\u05d2\u05d9\u05dc, \u05d5\u05d4\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d1\u05db\u05d7\u05de\u05d9\u05e9\u05d9\u05dd \u05d0\u05d7\u05d5\u05d6."], [339.9, "\u05d4\u05d5\u05d0 \u05d2\u05dd \u05e7\u05dc \u05de\u05e4\u05dc\u05d3\u05d4 \u05d1\u05db\u05e2\u05e9\u05e8\u05d4 \u05d0\u05d7\u05d5\u05d6, \u05d5\u05dc\u05db\u05df \u05de\u05d7\u05dc\u05d9\u05e3 \u05e4\u05dc\u05d3\u05d4 \u05de\u05d7\u05d5\u05e9\u05dc\u05ea \u05d1\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd, \u05d1\u05d6\u05e8\u05d5\u05e2\u05d5\u05ea \u05de\u05ea\u05dc\u05d4 \u05d5\u05d1\u05de\u05db\u05d5\u05e0\u05d5\u05ea \u05d7\u05e7\u05dc\u05d0\u05d9\u05d5\u05ea."], [349.0, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4 \u05dc\u05e2\u05d9\u05d1\u05d5\u05d3. \u05dc\u05db\u05df \u05de\u05e2\u05d1\u05d3\u05d9\u05dd \u05db\u05de\u05e2\u05d8 \u05d4\u05db\u05d5\u05dc \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d0\u05d5\u05e1\u05d8\u05de\u05e4\u05e8\u05d9\u05e0\u05d2, \u05d5\u05d0\u05d7\u05e8 \u05db\u05da \u05e2\u05d5\u05e9\u05d9\u05dd \u05e8\u05e7 \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05de\u05e8."], [358.5, "\u05d4\u05d7\u05dc\u05e7 \u05d2\u05dd \u05d2\u05d3\u05dc \u05de\u05e2\u05d8 \u05d1\u05d8\u05d9\u05e4\u05d5\u05dc. \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e6\u05e4\u05d5\u05d9 \u05d5\u05d7\u05d5\u05d6\u05e8 \u05e2\u05dc \u05e2\u05e6\u05de\u05d5, \u05d5\u05dc\u05db\u05df \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df \u05db\u05d1\u05e8 \u05d1\u05ea\u05db\u05e0\u05d5\u05df."], [367.1, "\u05e7\u05d9\u05e8\u05d5\u05e8 \u05de\u05d4\u05d9\u05e8 \u05de\u05d3\u05d9 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d9\u05d5\u05e6\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3."], [374.5, "\u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05de\u05d3\u05d9 \u05de\u05e4\u05e8\u05e7\u05ea \u05d0\u05ea \u05d4\u05e4\u05e8\u05dc\u05d9\u05d8, \u05d5\u05d4\u05d7\u05d5\u05d6\u05e7 \u05d5\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05d9\u05dd."], [381.7, "\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05dc\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd \u05d4\u05d3\u05e8\u05d2\u05ea\u05d9 \u05e1\u05d5\u05d3\u05e7 \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d1\u05de\u05e2\u05d1\u05e8\u05d9\u05dd \u05d1\u05d9\u05df \u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05dc\u05e2\u05d1\u05d5\u05ea."], [388.7, "ADI \u05e8\u05d2\u05d9\u05e9 \u05dc\u05d6\u05de\u05df \u05d1\u05d0\u05de\u05d1\u05d8: \u05d6\u05de\u05df \u05e7\u05e6\u05e8 \u05de\u05d3\u05d9 \u05de\u05e9\u05d0\u05d9\u05e8 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05dc\u05d0 \u05d9\u05e6\u05d9\u05d1 \u05e9\u05d4\u05d5\u05e4\u05da \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8. \u05d6\u05de\u05df \u05d0\u05e8\u05d5\u05da \u05de\u05d3\u05d9 \u05de\u05e4\u05e8\u05e7 \u05d0\u05d5\u05ea\u05d5 \u05dc\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd. \u05d1\u05e9\u05e0\u05d9 \u05d4\u05de\u05e7\u05e8\u05d9\u05dd \u05d4\u05de\u05e9\u05d9\u05db\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea."], [402.4, "\u05d5\u05d2\u05dd \u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05d5\u05e9\u05dc\u05dd \u05dc\u05d0 \u05de\u05ea\u05e7\u05df \u05d9\u05e6\u05d9\u05e7\u05d4 \u05d2\u05e8\u05d5\u05e2\u05d4: \u05e0\u05e7\u05d1\u05d5\u05d1\u05d9\u05d5\u05ea, \u05de\u05e2\u05d8 \u05db\u05d3\u05d5\u05e8\u05d9 \u05d2\u05e8\u05e4\u05d9\u05d8 \u05d0\u05d5 \u05d4\u05e8\u05db\u05d1 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05e0\u05e9\u05d0\u05e8\u05d9\u05dd \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8."], [412.7, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d6\u05d5\u05dc\u05d4 \u05d9\u05d7\u05e1\u05d9\u05ea, \u05d0\u05d1\u05dc \u05d9\u05e6\u05d9\u05e7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d5\u05ea \u05ea\u05d5\u05e4\u05e1\u05d5\u05ea \u05ea\u05e0\u05d5\u05e8 \u05e9\u05dc\u05dd, \u05d5\u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05e7\u05d9\u05e8\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9 \u05e9\u05dc \u05e9\u05e2\u05d5\u05ea \u05e8\u05d1\u05d5\u05ea."], [422.3, "\u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05d5\u05e8\u05d9\u05db\u05d5\u05da \u05d2\u05e8\u05e4\u05d9\u05d8\u05d9\u05d6\u05e6\u05d9\u05d4 \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8."], [428.2, "ADI \u05d3\u05d5\u05e8\u05e9 \u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d1\u05e7\u05e8\u05d4 \u05e6\u05de\u05d5\u05d3\u05d4 \u05e2\u05dc \u05d4\u05d6\u05de\u05df \u05d5\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05d1\u05e8\u05d6\u05dc \u05d1\u05e1\u05d9\u05e1 \u05d0\u05d9\u05db\u05d5\u05ea\u05d9 \u05de\u05d1\u05d9\u05ea \u05d4\u05d9\u05e6\u05d9\u05e7\u05d4."], [435.8, "\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d9\u05e7\u05e8, \u05d5\u05dc\u05db\u05df \u05d7\u05e9\u05d5\u05d1 \u05dc\u05ea\u05db\u05e0\u05df \u05d0\u05ea \u05e1\u05d3\u05e8 \u05d4\u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05de\u05e8\u05d0\u05e9."], [441.2, "\u05d5\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, ADI \u05de\u05d7\u05dc\u05d9\u05e3 \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05de\u05d7\u05d5\u05e9\u05dc\u05ea, \u05d5\u05d1\u05e1\u05da \u05d4\u05db\u05d5\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d5\u05e6\u05d0 \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."], [449.4, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05de\u05e7\u05d1\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e8\u05e7 \u05db\u05e9\u05e6\u05e8\u05d9\u05da, \u05d5\u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05e9\u05e0\u05d4 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d0\u05ea \u05d4\u05de\u05d8\u05e8\u05d9\u05e6\u05d4, \u05d5\u05dc\u05d0 \u05d0\u05ea \u05e6\u05d5\u05e8\u05ea \u05d4\u05d2\u05e8\u05e4\u05d9\u05d8."], [458.4, "\u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05d9\u05d9\u05e6\u05d1\u05ea \u05de\u05d9\u05d3\u05d5\u05ea, \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05e9\u05e4\u05e8 \u05d0\u05ea \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05d5\u05d4\u05e7\u05e9\u05d9\u05d9\u05ea \u05e9\u05d8\u05d7 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4."], [466.3, "\u05d5\u05d0\u05d9\u05dc\u05d5 ADI \u05d4\u05d5\u05e4\u05da \u05d1\u05e8\u05d6\u05dc \u05e0\u05d5\u05d3\u05d5\u05dc\u05e8\u05d9 \u05dc\u05d7\u05d5\u05de\u05e8 \u05d7\u05d6\u05e7 \u05d5\u05e7\u05e9\u05d9\u05d7, \u05e9\u05de\u05ea\u05d7\u05e8\u05d4 \u05d1\u05e4\u05dc\u05d3\u05d4."], [472.8, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05dc\u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05d5\u05d0\u05d5\u05d5\u05d9\u05e8\u05d5\u05ea: \u05d0\u05d5\u05d5\u05d9\u05e8, \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05d5\u05d0\u05e7\u05d5\u05dd \u05d5\u05de\u05dc\u05d7, \u05d5\u05d2\u05dd \u05d4\u05e4\u05d7\u05ea\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05e1\u05d9\u05d3\u05d5\u05e8 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8."]]};
window.MH_TR["ch20"]={"t": "\u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05d5\u05d0\u05d5\u05d5\u05d9\u05e8\u05d5\u05ea", "l": [[5.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05dc \u05d4\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05e7\u05d5\u05e8\u05d4: \u05d4\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05e1\u05d1\u05d9\u05d1 \u05d4\u05d7\u05dc\u05e7."], [12.3, "\u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4, \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e9\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05de\u05d2\u05d9\u05d1\u05d9\u05dd \u05e2\u05dd \u05d4\u05d2\u05d6 \u05e9\u05e1\u05d1\u05d9\u05d1\u05dd. \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e7\u05d5\u05d1\u05e2\u05ea \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7 \u05d9\u05d9\u05e6\u05d0 \u05e0\u05e7\u05d9, \u05de\u05d7\u05d5\u05de\u05e6\u05df, \u05d0\u05d5 \u05d1\u05dc\u05d9 \u05e4\u05d7\u05de\u05df \u05d1\u05e9\u05db\u05d1\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea."], [23.6, "\u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05e1\u05d5\u05d2\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8\u05d9\u05dd, \u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea, \u05d5\u05d0\u05e7\u05d5\u05dd \u05d5\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d0\u05d9\u05da \u05de\u05e1\u05d3\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8."], [33.9, "\u05d4\u05ea\u05e0\u05d5\u05e8 \u05d4\u05e0\u05e4\u05d5\u05e5 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d5\u05d0 \u05ea\u05e0\u05d5\u05e8 \u05ea\u05d0: \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05de\u05e0\u05d4 \u05e9\u05dc \u05d7\u05dc\u05e7\u05d9\u05dd, \u05de\u05d7\u05de\u05de\u05d9\u05dd, \u05d5\u05de\u05d5\u05e6\u05d9\u05d0\u05d9\u05dd."], [40.8, "\u05d1\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e9\u05d5\u05dc\u05d1, \u05d4\u05d0\u05de\u05d1\u05d8 \u05e9\u05dc \u05d4\u05e9\u05de\u05df \u05e0\u05de\u05e6\u05d0 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05dc\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05dc\u05d9 \u05dc\u05e4\u05d2\u05d5\u05e9 \u05d0\u05d5\u05d5\u05d9\u05e8."], [48.7, "\u05d1\u05ea\u05e0\u05d5\u05e8 \u05d1\u05d5\u05e8, \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05ea\u05dc\u05d9\u05dd \u05d0\u05e0\u05db\u05d9\u05ea \u05de\u05dc\u05de\u05e2\u05dc\u05d4. \u05db\u05da \u05de\u05d8\u05e4\u05dc\u05d9\u05dd \u05d1\u05e6\u05d9\u05e8\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd, \u05d1\u05dc\u05d9 \u05e9\u05d9\u05ea\u05db\u05d5\u05e4\u05e4\u05d5 \u05de\u05d4\u05de\u05e9\u05e7\u05dc \u05e9\u05dc \u05e2\u05e6\u05de\u05dd."], [57.5, "\u05d1\u05d9\u05d9\u05e6\u05d5\u05e8 \u05e1\u05d3\u05e8\u05ea\u05d9 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8 \u05e8\u05e6\u05d9\u05e3: \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e2\u05d9\u05dd \u05e2\u05dc \u05de\u05e1\u05d5\u05e2 \u05d3\u05e8\u05da \u05d0\u05d6\u05d5\u05e8\u05d9 \u05d7\u05d9\u05de\u05d5\u05dd, \u05d4\u05d7\u05d6\u05e7\u05d4 \u05d5\u05db\u05d9\u05d1\u05d5\u05d9."], [65.9, "\u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4, \u05d4\u05d7\u05d5\u05dd \u05e2\u05d5\u05d1\u05e8 \u05d1\u05e2\u05d9\u05e7\u05e8 \u05d1\u05e7\u05e8\u05d9\u05e0\u05d4. \u05d1\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4, \u05e6\u05e8\u05d9\u05da \u05de\u05d0\u05d5\u05d5\u05e8\u05e8 \u05e9\u05de\u05e1\u05d7\u05e8\u05e8 \u05d0\u05ea \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8, \u05d0\u05d7\u05e8\u05ea \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3."], [77.5, "\u05d4\u05d3\u05e8\u05da \u05d4\u05e4\u05e9\u05d5\u05d8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05dc\u05d7\u05de\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8. \u05d0\u05d1\u05dc \u05d1\u05d7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4, \u05d4\u05d7\u05de\u05e6\u05df \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05e2\u05dc \u05d4\u05e4\u05dc\u05d3\u05d4 \u05e7\u05e9\u05e7\u05e9\u05ea."], [85.6, "\u05d5\u05e7\u05d5\u05e8\u05d4 \u05d3\u05d1\u05e8 \u05e0\u05d5\u05e1\u05e3: \u05d4\u05e4\u05d7\u05de\u05df \u05d1\u05e9\u05db\u05d1\u05d4 \u05d4\u05d7\u05d9\u05e6\u05d5\u05e0\u05d9\u05ea \u05de\u05d2\u05d9\u05d1 \u05e2\u05dd \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05d5\u05d9\u05d5\u05e6\u05d0 \u05db\u05d2\u05d6, \u05d5\u05e4\u05d7\u05de\u05df \u05de\u05ea\u05d5\u05da \u05d4\u05d7\u05dc\u05e7 \u05e0\u05d5\u05d3\u05d3 \u05d4\u05d7\u05d5\u05e6\u05d4 \u05d1\u05de\u05e7\u05d5\u05de\u05d5. \u05d6\u05d5 \u05d4\u05e4\u05d7\u05ea\u05ea \u05e4\u05d7\u05de\u05df."], [97.1, "\u05d4\u05ea\u05d5\u05e4\u05e2\u05d4 \u05de\u05ea\u05d7\u05d9\u05dc\u05d4 \u05d1\u05e2\u05e8\u05da \u05de-700 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d5\u05d2\u05d3\u05dc\u05d4 \u05e2\u05dd \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d5\u05e2\u05dd \u05d4\u05d6\u05de\u05df \u05d1\u05ea\u05e0\u05d5\u05e8."], [103.4, "\u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05e4\u05d7\u05de\u05df \u05dc\u05d0 \u05de\u05ea\u05e7\u05e9\u05d4 \u05d1\u05db\u05d9\u05d1\u05d5\u05d9. \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e7\u05dc\u05d9\u05e4\u05d4 \u05e8\u05db\u05d4 \u05de\u05e2\u05dc \u05dc\u05d9\u05d1\u05d4 \u05e7\u05e9\u05d4, \u05d5\u05e2\u05de\u05d9\u05d3\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d4 \u05d1\u05e9\u05d7\u05d9\u05e7\u05d4 \u05d5\u05d1\u05e2\u05d9\u05d9\u05e4\u05d5\u05ea."], [112.3, "\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4, \u05e2\u05dc \u05d7\u05ea\u05da \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d0\u05d5 \u05d1\u05de\u05d3\u05d9\u05d3\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05e0\u05d9\u05de\u05d4."], [118.9, "\u05db\u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8, \u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05d5\u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d1\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc. \u05dc\u05db\u05df \u05de\u05e7\u05d5\u05d1\u05dc \u05dc\u05e2\u05e9\u05d5\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e1\u05d5\u05e4\u05d9."], [129.0, "\u05d1\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05e9\u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4, \u05e2\u05d5\u05d8\u05e4\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05d1\u05e8\u05d3\u05d9\u05d3 \u05e9\u05dc \u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4. \u05d4\u05e8\u05d3\u05d9\u05d3 \u05e7\u05d5\u05e9\u05e8 \u05d0\u05ea \u05d4\u05d7\u05de\u05e6\u05df \u05e9\u05e0\u05e9\u05d0\u05e8 \u05d1\u05e4\u05e0\u05d9\u05dd."], [139.6, "\u05d4\u05e4\u05ea\u05e8\u05d5\u05df \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9 \u05d4\u05d5\u05d0 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea. \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d4\u05d9\u05d0 \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05d0\u05e0\u05d3\u05d5\u05ea\u05e8\u05de\u05d9\u05ea."], [145.9, "\u05de\u05d9\u05d9\u05e6\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d2\u05e0\u05e8\u05d8\u05d5\u05e8, \u05de\u05d2\u05d6 \u05d8\u05d1\u05e2\u05d9 \u05d5\u05d0\u05d5\u05d5\u05d9\u05e8, \u05e9\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05de\u05e2\u05dc \u05d6\u05e8\u05d6 \u05e9\u05dc \u05e0\u05d9\u05e7\u05dc, \u05d1\u05e2\u05e8\u05da \u05d1-1,040 \u05de\u05e2\u05dc\u05d5\u05ea."], [154.3, "\u05d4\u05d4\u05e8\u05db\u05d1 \u05d1\u05e7\u05d9\u05e8\u05d5\u05d1: 40 \u05d0\u05d7\u05d5\u05d6 \u05de\u05d9\u05de\u05df, 40 \u05d0\u05d7\u05d5\u05d6 \u05d7\u05e0\u05e7\u05df \u05d5-20 \u05d0\u05d7\u05d5\u05d6 \u05e4\u05d7\u05de\u05df \u05d7\u05d3 \u05d7\u05de\u05e6\u05e0\u05d9."], [161.7, "\u05d4\u05de\u05d5\u05e9\u05d2 \u05d4\u05d7\u05e9\u05d5\u05d1 \u05d4\u05d5\u05d0 \u05e4\u05d5\u05d8\u05e0\u05e6\u05d9\u05d0\u05dc \u05e4\u05d7\u05de\u05df: \u05db\u05de\u05d5\u05ea \u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05d5\u05d0\u05e4\u05ea \u05dc\u05d4\u05e9\u05d0\u05d9\u05e8 \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [168.7, "\u05db\u05e9\u05e4\u05d5\u05d8\u05e0\u05e6\u05d9\u05d0\u05dc \u05d4\u05e4\u05d7\u05de\u05df \u05e9\u05d5\u05d5\u05d4 \u05dc\u05e4\u05d7\u05de\u05df \u05e9\u05d1\u05e4\u05dc\u05d3\u05d4, \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05dc\u05d0 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05d5\u05dc\u05d0 \u05de\u05d5\u05e6\u05d9\u05d0\u05d4. \u05d0\u05dd \u05d4\u05d5\u05d0 \u05d2\u05d1\u05d5\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05d4\u05d9\u05d0 \u05de\u05d5\u05e1\u05d9\u05e4\u05d4 \u05e4\u05d7\u05de\u05df \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [178.5, "\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d7\u05d9\u05d9\u05e9\u05df \u05d7\u05de\u05e6\u05df \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d2\u05dd \u05dc\u05e4\u05d9 \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05d8\u05dc \u05e9\u05dc \u05d4\u05d2\u05d6."], [184.2, "\u05d7\u05dc\u05d5\u05e4\u05d4 \u05dc\u05d2\u05e0\u05e8\u05d8\u05d5\u05e8 \u05d4\u05d9\u05d0 \u05d7\u05e0\u05e7\u05df \u05d5\u05de\u05ea\u05e0\u05d5\u05dc. \u05d4\u05de\u05ea\u05e0\u05d5\u05dc \u05de\u05ea\u05e4\u05e8\u05e7 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d5\u05e0\u05d5\u05e6\u05e8\u05ea \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05d1\u05d4\u05e8\u05db\u05d1 \u05db\u05de\u05e2\u05d8 \u05d6\u05d4\u05d4."], [192.5, "\u05d5\u05d6\u05db\u05e8\u05d5 \u05d0\u05ea \u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea: \u05e4\u05d7\u05de\u05df \u05d7\u05d3 \u05d7\u05de\u05e6\u05e0\u05d9 \u05e8\u05e2\u05d9\u05dc, \u05d5\u05de\u05d9\u05de\u05df \u05d3\u05dc\u05d9\u05e7. \u05dc\u05db\u05df \u05d9\u05e9 \u05d1\u05e4\u05ea\u05d7\u05d9 \u05d4\u05ea\u05e0\u05d5\u05e8 \u05dc\u05d4\u05d1\u05d4 \u05e9\u05e9\u05d5\u05e8\u05e4\u05ea \u05d0\u05ea \u05d4\u05d2\u05d6, \u05d5\u05e9\u05d5\u05d8\u05e4\u05d9\u05dd \u05d1\u05d7\u05e0\u05e7\u05df \u05dc\u05e4\u05e0\u05d9 \u05e4\u05ea\u05d9\u05d7\u05d4."], [204.7, "\u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05e9\u05d5\u05d0\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8 \u05e2\u05d3 \u05dc\u05d7\u05e5 \u05e0\u05de\u05d5\u05da \u05de\u05d0\u05d5\u05d3, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05e1\u05d1\u05d9\u05d1\u05d5\u05ea \u05de\u05d0\u05d9\u05ea \u05e2\u05d3 \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05d1\u05e8."], [212.5, "\u05db\u05de\u05e2\u05d8 \u05d0\u05d9\u05df \u05d7\u05de\u05e6\u05df, \u05d5\u05dc\u05db\u05df \u05d0\u05d9\u05df \u05e7\u05e9\u05e7\u05e9\u05ea \u05d5\u05d0\u05d9\u05df \u05d4\u05e4\u05d7\u05ea\u05ea \u05e4\u05d7\u05de\u05df. \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d5\u05e6\u05d0\u05d9\u05dd \u05de\u05d1\u05e8\u05d9\u05e7\u05d9\u05dd \u05d5\u05e0\u05e7\u05d9\u05d9\u05dd."], [220.4, "\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd, \u05d4\u05d7\u05d5\u05dd \u05e2\u05d5\u05d1\u05e8 \u05e8\u05e7 \u05d1\u05e7\u05e8\u05d9\u05e0\u05d4, \u05e9\u05d4\u05d9\u05d0 \u05d0\u05d9\u05d8\u05d9\u05ea \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05e0\u05de\u05d5\u05db\u05d5\u05ea. \u05dc\u05db\u05df \u05d1\u05ea\u05d7\u05d9\u05dc\u05ea \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05d7\u05e0\u05e7\u05df, \u05d5\u05de\u05e1\u05d7\u05e8\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05de\u05d0\u05d5\u05d5\u05e8\u05e8."], [231.0, "\u05d0\u05ea \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d1\u05d2\u05d6: \u05d7\u05e0\u05e7\u05df \u05d1\u05dc\u05d7\u05e5 \u05e9\u05dc 2 \u05e2\u05d3 20 \u05d1\u05e8, \u05e9\u05de\u05d0\u05d5\u05d5\u05e8\u05e8 \u05d7\u05d6\u05e7 \u05de\u05d6\u05e8\u05d9\u05dd \u05d3\u05e8\u05da \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd."], [239.4, "\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d2\u05d6 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df, \u05d5\u05dc\u05db\u05df \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df. \u05d0\u05d1\u05dc \u05d4\u05d5\u05d0 \u05d2\u05dd \u05d0\u05d9\u05d8\u05d9 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05de\u05ea\u05d0\u05d9\u05dd \u05d1\u05e2\u05d9\u05e7\u05e8 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e2\u05dd \u05db\u05d5\u05e9\u05e8 \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4."], [249.3, "\u05d1\u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05d2\u05d1\u05d5\u05d4 \u05de\u05d3\u05d9, \u05d9\u05e1\u05d5\u05d3\u05d5\u05ea \u05db\u05de\u05d5 \u05db\u05e8\u05d5\u05dd \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05ea\u05d0\u05d3\u05d5\u05ea \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7. \u05dc\u05db\u05df \u05e2\u05d5\u05d1\u05d3\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05dc\u05d7\u05e5 \u05d7\u05dc\u05e7\u05d9 \u05e9\u05dc \u05d0\u05e8\u05d2\u05d5\u05df \u05d0\u05d5 \u05d7\u05e0\u05e7\u05df."], [258.7, "\u05ea\u05e0\u05d5\u05e8\u05d9 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d9\u05e7\u05e8\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8, \u05d0\u05d1\u05dc \u05d4\u05dd \u05d4\u05d1\u05d7\u05d9\u05e8\u05d4 \u05d4\u05de\u05d5\u05d1\u05d9\u05dc\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05dc\u05e0\u05d9\u05e8\u05d5\u05e1\u05d8\u05d4, \u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05dc\u05ea\u05e2\u05d5\u05e4\u05d4."], [268.2, "\u05d1\u05e9\u05d9\u05d8\u05d4 \u05d4\u05d5\u05d5\u05ea\u05d9\u05e7\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d8\u05d5\u05d1\u05dc\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05dc\u05d7 \u05de\u05d5\u05ea\u05da. \u05d1\u05de\u05dc\u05d7\u05d9\u05dd \u05e0\u05d9\u05d8\u05e8\u05dc\u05d9\u05d9\u05dd, \u05e2\u05dc \u05d1\u05e1\u05d9\u05e1 \u05db\u05dc\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd, \u05de\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e7\u05e9\u05d9\u05d4."], [277.5, "\u05d4\u05de\u05dc\u05d7 \u05de\u05d5\u05dc\u05d9\u05da \u05d7\u05d5\u05dd \u05d9\u05e9\u05d9\u05e8\u05d5\u05ea \u05dc\u05d7\u05dc\u05e7, \u05d5\u05dc\u05db\u05df \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05de\u05d4\u05d9\u05e8 \u05d5\u05d0\u05d7\u05d9\u05d3 \u05de\u05d0\u05d5\u05d3. \u05d4\u05d7\u05dc\u05e7 \u05d2\u05dd \u05e6\u05e3 \u05d7\u05dc\u05e7\u05d9\u05ea, \u05d5\u05db\u05da \u05d4\u05d5\u05d0 \u05e4\u05d7\u05d5\u05ea \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05de\u05d4\u05de\u05e9\u05e7\u05dc \u05e9\u05dc \u05e2\u05e6\u05de\u05d5."], [288.0, "\u05d0\u05d1\u05dc \u05d4\u05de\u05dc\u05d7 \u05de\u05ea\u05d7\u05de\u05e6\u05df \u05e2\u05dd \u05d4\u05d6\u05de\u05df \u05d5\u05de\u05ea\u05d7\u05d9\u05dc \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05e4\u05d7\u05de\u05df \u05de\u05d4\u05e4\u05dc\u05d3\u05d4. \u05dc\u05db\u05df \u05de\u05d8\u05e4\u05dc\u05d9\u05dd \u05d1\u05d0\u05de\u05d1\u05d8 \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2 \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5."], [296.1, "\u05d4\u05d1\u05d8\u05d9\u05d7\u05d5\u05ea \u05db\u05d0\u05df \u05e7\u05e8\u05d9\u05d8\u05d9\u05ea: \u05d7\u05dc\u05e7 \u05e8\u05d8\u05d5\u05d1 \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05dc\u05d7 \u05de\u05d5\u05ea\u05da \u05d2\u05d5\u05e8\u05dd \u05dc\u05d4\u05ea\u05d6\u05d4 \u05de\u05e1\u05d5\u05db\u05e0\u05ea. \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05e8\u05e7 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d9\u05d1\u05e9\u05d9\u05dd \u05d5\u05d7\u05de\u05d9\u05dd."], [305.1, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05d5\u05d8\u05e4\u05d9\u05dd \u05d0\u05ea \u05d4\u05de\u05dc\u05d7 \u05de\u05db\u05dc \u05d4\u05d7\u05d5\u05e8\u05d9\u05dd. \u05d2\u05dd \u05d4\u05e4\u05d9\u05e0\u05d5\u05d9 \u05e9\u05dc \u05de\u05dc\u05d7 \u05de\u05e9\u05d5\u05de\u05e9 \u05d9\u05e7\u05e8, \u05d5\u05dc\u05db\u05df \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05d1\u05d0\u05de\u05d1\u05d8\u05d9\u05dd \u05d4\u05d5\u05dc\u05da \u05d5\u05e4\u05d5\u05d7\u05ea."], [314.9, "\u05d2\u05dd \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d4\u05d8\u05d5\u05d1 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d0 \u05d9\u05e2\u05d6\u05d5\u05e8, \u05d0\u05dd \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e1\u05d5\u05d3\u05e8\u05d9\u05dd \u05dc\u05d0 \u05e0\u05db\u05d5\u05df."], [319.5, "\u05de\u05e9\u05d0\u05d9\u05e8\u05d9\u05dd \u05de\u05e8\u05d5\u05d5\u05d7 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05db\u05d3\u05d9 \u05e9\u05d4\u05d7\u05d5\u05dd \u05d5\u05d4\u05d2\u05d6 \u05d9\u05d2\u05d9\u05e2\u05d5 \u05dc\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd. \u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd \u05de\u05d3\u05d9 \u05de\u05ea\u05d7\u05de\u05de\u05d9\u05dd \u05dc\u05d0\u05d8 \u05d5\u05d1\u05d0\u05d5\u05e4\u05df \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3."], [329.1, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05ea\u05d5\u05dc\u05d9\u05dd \u05d0\u05e0\u05db\u05d9\u05ea \u05d0\u05d5 \u05ea\u05d5\u05de\u05db\u05d9\u05dd \u05d1\u05db\u05de\u05d4 \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea. \u05d1\u05d7\u05d5\u05dd, \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05dc\u05e9\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05e9\u05ea\u05dc\u05d5\u05d9 \u05e8\u05e7 \u05d1\u05e7\u05e6\u05d5\u05d5\u05ea \u05d9\u05ea\u05db\u05d5\u05e4\u05e3."], [338.8, "\u05dc\u05d0 \u05de\u05e2\u05e8\u05d1\u05d1\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d4 \u05de\u05e0\u05d4 \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05d5\u05e2\u05d1\u05d9\u05dd \u05de\u05d0\u05d5\u05d3. \u05d4\u05dd \u05de\u05d2\u05d9\u05e2\u05d9\u05dd \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d1\u05d6\u05de\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd \u05de\u05d0\u05d5\u05d3."], [346.4, "\u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05d4\u05d7\u05d6\u05e7\u05d4 \u05e1\u05d5\u05e4\u05e8\u05d9\u05dd \u05de\u05d4\u05e8\u05d2\u05e2 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5 \u05d4\u05d2\u05d9\u05e2 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05dc\u05d0 \u05de\u05d4\u05e8\u05d2\u05e2 \u05e9\u05d4\u05ea\u05e0\u05d5\u05e8 \u05d4\u05d2\u05d9\u05e2. \u05dc\u05db\u05df \u05de\u05d7\u05d1\u05e8\u05d9\u05dd \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc \u05dc\u05d7\u05dc\u05e7 \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e0\u05d4."], [357.0, "\u05de\u05e0\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05de\u05d3\u05d9 \u05d4\u05d9\u05d0 \u05d8\u05e2\u05d5\u05ea \u05e0\u05e4\u05d5\u05e6\u05d4: \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05e8\u05db\u05d6 \u05dc\u05d0 \u05de\u05e1\u05e4\u05d9\u05e7\u05d9\u05dd \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4, \u05d5\u05e9\u05de\u05df \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05ea\u05d7\u05de\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05d3\u05d9."], [366.2, "\u05d7\u05d9\u05de\u05d5\u05dd \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8 \u05d1\u05dc\u05d9 \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05de\u05e9\u05d0\u05d9\u05e8 \u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05e4\u05d7\u05de\u05df, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05e0\u05db\u05e9\u05dc \u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea."], [373.7, "\u05d7\u05d9\u05d9\u05e9\u05df \u05d7\u05de\u05e6\u05df \u05e9\u05dc\u05d0 \u05e2\u05d1\u05e8 \u05db\u05d9\u05d5\u05dc \u05d2\u05d5\u05e8\u05dd \u05dc\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05dc\u05d4\u05d5\u05e1\u05d9\u05e3 \u05d0\u05d5 \u05dc\u05d4\u05d5\u05e6\u05d9\u05d0 \u05e4\u05d7\u05de\u05df, \u05d1\u05dc\u05d9 \u05e9\u05de\u05d9\u05e9\u05d4\u05d5 \u05e9\u05dd \u05dc\u05d1."], [380.8, "\u05d3\u05dc\u05d9\u05e4\u05d4 \u05e7\u05d8\u05e0\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05de\u05db\u05e0\u05d9\u05e1\u05d4 \u05d0\u05d5\u05d5\u05d9\u05e8, \u05d5\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e6\u05d1\u05e2 \u05e9\u05dc \u05d7\u05de\u05e6\u05d5\u05df."], [387.1, "\u05e9\u05d0\u05e8\u05d9\u05d5\u05ea \u05de\u05dc\u05d7 \u05d1\u05d7\u05d5\u05e8\u05d9\u05dd \u05d5\u05d1\u05d4\u05d1\u05e8\u05d2\u05d5\u05ea \u05d2\u05d5\u05e8\u05de\u05d5\u05ea \u05dc\u05e7\u05d5\u05e8\u05d5\u05d6\u05d9\u05d4, \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05d1\u05d5\u05e2\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc."], [393.2, "\u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e6\u05e4\u05d5\u05e4\u05d9\u05dd \u05d0\u05d5 \u05de\u05e0\u05d4 \u05d2\u05d3\u05d5\u05dc\u05d4 \u05de\u05d3\u05d9 \u05e0\u05d5\u05ea\u05e0\u05d9\u05dd \u05e7\u05e9\u05d9\u05d5\u05ea \u05e9\u05d5\u05e0\u05d4 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05de\u05e8\u05db\u05d6 \u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05d1\u05e9\u05d5\u05dc\u05d9\u05d9\u05dd."], [401.3, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05ea\u05e0\u05d5\u05e8 \u05e2\u05dd \u05d0\u05d5\u05d5\u05d9\u05e8\u05d4, \u05d5\u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05e2\u05dd \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05d2\u05d6 \u05d1\u05dc\u05d7\u05e5 \u05d2\u05d1\u05d5\u05d4."], [408.7, "\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea \u05d3\u05d5\u05e8\u05e9\u05ea \u05d2\u05e0\u05e8\u05d8\u05d5\u05e8 \u05d0\u05d5 \u05d2\u05d6\u05d9\u05dd, \u05d7\u05d9\u05d9\u05e9\u05e0\u05d9\u05dd, \u05db\u05d9\u05d5\u05dc \u05d5\u05d1\u05e7\u05e8\u05d4 \u05e7\u05d1\u05d5\u05e2\u05d4."], [414.7, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d0\u05d5 \u05d0\u05e8\u05d5\u05db\u05d9\u05dd \u05ea\u05d5\u05e4\u05e1\u05d9\u05dd \u05ea\u05e0\u05d5\u05e8 \u05e9\u05dc\u05dd, \u05d0\u05d5 \u05d3\u05d5\u05e8\u05e9\u05d9\u05dd \u05ea\u05e0\u05d5\u05e8 \u05d1\u05d5\u05e8 \u05d5\u05de\u05ea\u05e7\u05e0\u05d9 \u05ea\u05dc\u05d9\u05d9\u05d4."], [421.6, "\u05d5\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d7\u05d5\u05e1\u05da \u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d5\u05d7\u05dc\u05e7\u05d9\u05dd \u05e4\u05e1\u05d5\u05dc\u05d9\u05dd, \u05d5\u05d1\u05e1\u05da \u05d4\u05db\u05d5\u05dc \u05d9\u05db\u05d5\u05dc \u05dc\u05e6\u05d0\u05ea \u05d6\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8."], [430.6, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d4\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d7\u05e9\u05d5\u05d1\u05d4 \u05db\u05de\u05d5 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4. \u05d0\u05d5\u05d5\u05d9\u05e8 \u05d9\u05d5\u05e6\u05e8 \u05e7\u05e9\u05e7\u05e9\u05ea \u05d5\u05de\u05d5\u05e6\u05d9\u05d0 \u05e4\u05d7\u05de\u05df \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [439.1, "\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05de\u05d1\u05d5\u05e7\u05e8\u05ea \u05e9\u05d5\u05de\u05e8\u05ea \u05e2\u05dc \u05d4\u05e4\u05d7\u05de\u05df \u05d1\u05e2\u05d6\u05e8\u05ea \u05e4\u05d5\u05d8\u05e0\u05e6\u05d9\u05d0\u05dc \u05e4\u05d7\u05de\u05df \u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05d5\u05d0\u05e7\u05d5\u05dd \u05e0\u05d5\u05ea\u05df \u05d7\u05dc\u05e7\u05d9\u05dd \u05e0\u05e7\u05d9\u05d9\u05dd \u05d5\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d3\u05d9\u05df \u05d1\u05d2\u05d6."], [448.3, "\u05d0\u05de\u05d1\u05d8 \u05de\u05dc\u05d7 \u05de\u05d7\u05de\u05dd \u05de\u05d4\u05e8 \u05d5\u05d0\u05d7\u05d9\u05d3, \u05d5\u05e1\u05d9\u05d3\u05d5\u05e8 \u05e0\u05db\u05d5\u05df \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05e7\u05d5\u05d1\u05e2 \u05d0\u05dd \u05db\u05d5\u05dc\u05dd \u05d9\u05e7\u05d1\u05dc\u05d5 \u05d0\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d8\u05d9\u05e4\u05d5\u05dc."], [455.4, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd, \u05d5\u05e2\u05dc \u05d0\u05d9\u05da \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05dc\u05e7 \u05e9\u05d9\u05e2\u05d1\u05d5\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05e9\u05dc\u05d5\u05dd."]]};
window.MH_TR["ch21"]={"t": "\u05e2\u05d9\u05d5\u05d5\u05ea, \u05e1\u05d3\u05e7\u05d9\u05dd \u05d5\u05ea\u05db\u05e0\u05d5\u05df \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd", "l": [[5.0, "\u05d7\u05dc\u05e7 \u05e0\u05db\u05e0\u05e1 \u05dc\u05ea\u05e0\u05d5\u05e8 \u05d9\u05e9\u05e8 \u05d5\u05de\u05d3\u05d5\u05d9\u05e7, \u05d5\u05d9\u05d5\u05e6\u05d0 \u05e2\u05e7\u05d5\u05dd, \u05d0\u05d5 \u05d2\u05e8\u05d5\u05e2 \u05de\u05d6\u05d4, \u05e1\u05d3\u05d5\u05e7. \u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05d1\u05d9\u05df \u05dc\u05de\u05d4 \u05d6\u05d4 \u05e7\u05d5\u05e8\u05d4."], [14.1, "\u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd \u05d4\u05dd \u05d4\u05e1\u05d9\u05d1\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05e4\u05e1\u05d9\u05dc\u05ea \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d5\u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05dd \u05e0\u05e7\u05d1\u05e2 \u05e2\u05d5\u05d3 \u05d1\u05e9\u05d5\u05dc\u05d7\u05df \u05d4\u05ea\u05db\u05e0\u05d5\u05df."], [22.7, "\u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d0\u05ea \u05e6\u05d5\u05e8\u05d5\u05ea \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea, \u05d0\u05ea \u05e1\u05d3\u05e7\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05d0\u05d9\u05da \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d7\u05dc\u05e7 \u05d5\u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05de\u05e7\u05d8\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05d9\u05db\u05d5\u05df."], [32.1, "\u05d9\u05e9 \u05e9\u05e0\u05d9 \u05de\u05e7\u05d5\u05e8\u05d5\u05ea \u05dc\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d1\u05db\u05d9\u05d1\u05d5\u05d9. \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd: \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d5\u05de\u05ea\u05db\u05d5\u05d5\u05e6\u05d9\u05dd, \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05dc\u05d9\u05d1\u05d4 \u05e2\u05d3\u05d9\u05d9\u05df \u05d7\u05de\u05d4."], [42.7, "\u05d4\u05e9\u05e0\u05d9 \u05d4\u05d5\u05d0 \u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05ea\u05de\u05e8\u05d4: \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05ea\u05d5\u05e4\u05e1 \u05e0\u05e4\u05d7 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05d5\u05d4\u05d5\u05d0 \u05e0\u05d5\u05e6\u05e8 \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d5\u05d1\u05dc\u05d9\u05d1\u05d4 \u05d1\u05d6\u05de\u05e0\u05d9\u05dd \u05e9\u05d5\u05e0\u05d9\u05dd."], [52.2, "\u05db\u05e9\u05e1\u05db\u05d5\u05dd \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e2\u05d5\u05d1\u05e8 \u05d0\u05ea \u05d2\u05d1\u05d5\u05dc \u05d4\u05db\u05e0\u05d9\u05e2\u05d4 \u05e9\u05dc \u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d7\u05dd, \u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea. \u05db\u05e9\u05d4\u05d5\u05d0 \u05e2\u05d5\u05d1\u05e8 \u05d0\u05ea \u05d4\u05d7\u05d5\u05d6\u05e7 \u05e9\u05dc \u05d4\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05e0\u05d5\u05e6\u05e8 \u05e1\u05d3\u05e7."], [61.5, "\u05d2\u05dd \u05d4\u05e2\u05d1\u05e8 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05e9\u05e4\u05d9\u05e2. \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05e9\u05e0\u05e9\u05d0\u05e8\u05d5 \u05de\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3, \u05de\u05d4\u05d9\u05e9\u05d5\u05e8 \u05d0\u05d5 \u05de\u05d4\u05e8\u05d9\u05ea\u05d5\u05da \u05de\u05e9\u05ea\u05d7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d7\u05d5\u05dd, \u05d5\u05d4\u05d7\u05dc\u05e7 \u05d6\u05d6."], [71.2, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05db\u05d5\u05d7 \u05d4\u05de\u05e9\u05d9\u05db\u05d4: \u05d1\u05d7\u05d5\u05dd \u05d4\u05e4\u05dc\u05d3\u05d4 \u05d7\u05dc\u05e9\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05e9\u05dc\u05d0 \u05e0\u05ea\u05de\u05da \u05db\u05de\u05d5 \u05e9\u05e6\u05e8\u05d9\u05da \u05e4\u05e9\u05d5\u05d8 \u05e9\u05d5\u05e7\u05e2."], [79.5, "\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d4\u05d1\u05d7\u05d9\u05df \u05d1\u05d9\u05df \u05e9\u05e0\u05d9 \u05e1\u05d5\u05d2\u05d9\u05dd \u05e9\u05dc \u05e9\u05d9\u05e0\u05d5\u05d9: \u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05de\u05d9\u05d3\u05d4, \u05e9\u05d1\u05d5 \u05d4\u05d7\u05dc\u05e7 \u05db\u05d5\u05dc\u05d5 \u05d2\u05d3\u05dc \u05d0\u05d5 \u05e7\u05d8\u05df \u05de\u05e2\u05d8, \u05d5\u05e9\u05d9\u05e0\u05d5\u05d9 \u05d1\u05e6\u05d5\u05e8\u05d4, \u05e9\u05d1\u05d5 \u05d4\u05d5\u05d0 \u05de\u05ea\u05e2\u05e7\u05dd."], [90.4, "\u05e6\u05d9\u05e8 \u05d0\u05e8\u05d5\u05da \u05d5\u05d3\u05e7 \u05e0\u05d5\u05d8\u05d4 \u05dc\u05d4\u05ea\u05e2\u05e7\u05dd \u05db\u05de\u05d5 \u05d1\u05e0\u05e0\u05d4, \u05d1\u05de\u05d9\u05d5\u05d7\u05d3 \u05d0\u05dd \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05dc\u05d0 \u05d0\u05d7\u05d9\u05d3 \u05de\u05db\u05dc \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd."], [97.0, "\u05d8\u05d1\u05e2\u05ea \u05d0\u05d5 \u05e9\u05e8\u05d5\u05d5\u05dc \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05e6\u05d0\u05ea \u05d0\u05d5\u05d1\u05dc\u05d9\u05d9\u05dd, \u05d5\u05d4\u05e7\u05d5\u05d8\u05e8 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9 \u05de\u05e9\u05ea\u05e0\u05d4."], [102.3, "\u05dc\u05d5\u05d7 \u05d3\u05e7 \u05d5\u05e9\u05d8\u05d5\u05d7 \u05de\u05ea\u05e2\u05e7\u05dd \u05db\u05de\u05d5 \u05e6\u05dc\u05d7\u05ea, \u05db\u05d9 \u05e9\u05e0\u05d9 \u05d4\u05e6\u05d3\u05d3\u05d9\u05dd \u05e9\u05dc\u05d5 \u05dc\u05d0 \u05de\u05ea\u05e7\u05e8\u05e8\u05d9\u05dd \u05d1\u05d0\u05d5\u05ea\u05d5 \u05e7\u05e6\u05d1."], [108.9, "\u05d7\u05dc\u05e7 \u05dc\u05d0 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9, \u05dc\u05de\u05e9\u05dc \u05e2\u05dd \u05d7\u05e8\u05d9\u05e5 \u05dc\u05d0\u05d5\u05e8\u05da \u05e6\u05d3 \u05d0\u05d7\u05d3, \u05de\u05ea\u05db\u05d5\u05e4\u05e3 \u05d0\u05dc \u05d4\u05e6\u05d3 \u05e9\u05d1\u05d5 \u05d9\u05e9 \u05e4\u05d7\u05d5\u05ea \u05d7\u05d5\u05de\u05e8."], [115.8, "\u05d5\u05d7\u05dc\u05e7 \u05e2\u05dd \u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05dc\u05e6\u05d3 \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e2\u05d1\u05d9\u05dd \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05d1\u05de\u05e2\u05d1\u05e8 \u05d1\u05d9\u05e0\u05d9\u05d4\u05dd, \u05db\u05d9 \u05db\u05dc \u05d0\u05d6\u05d5\u05e8 \u05de\u05ea\u05e7\u05e8\u05e8 \u05d1\u05e7\u05e6\u05d1 \u05d0\u05d7\u05e8."], [123.7, "\u05d2\u05dd \u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05d5\u05e0\u05e7\u05d9 \u05de\u05e9\u05e0\u05d4 \u05de\u05e2\u05d8 \u05d0\u05ea \u05d4\u05de\u05d9\u05d3\u05d5\u05ea \u05d1\u05d4\u05e7\u05e9\u05d9\u05d4. \u05d4\u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df, \u05d0\u05d1\u05dc \u05d1\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05e7\u05d7\u05ea \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d7\u05e9\u05d1\u05d5\u05df."], [133.4, "\u05e1\u05d3\u05e7 \u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05ea\u05d7\u05d9\u05dc \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05e7\u05d5\u05dd \u05e9\u05d1\u05d5 \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05ea\u05e8\u05db\u05d6\u05d9\u05dd: \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4, \u05d7\u05d5\u05e8 \u05e7\u05e8\u05d5\u05d1 \u05dc\u05e9\u05e4\u05d4, \u05d7\u05e8\u05d9\u05e5 \u05d0\u05d5 \u05de\u05e2\u05d1\u05e8 \u05d7\u05d3 \u05d1\u05e2\u05d5\u05d1\u05d9."], [143.3, "\u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05e1\u05d1\u05d9\u05d1\u05d4 \u05e9\u05dc\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05d2\u05dd \u05de\u05e8\u05db\u05d6\u05ea \u05de\u05d0\u05de\u05e5 \u05d5\u05d2\u05dd \u05d4\u05d5\u05e4\u05db\u05ea \u05dc\u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8 \u05e8\u05d0\u05e9\u05d5\u05e0\u05d4."], [151.6, "\u05d4\u05e1\u05d9\u05db\u05d5\u05df \u05d2\u05d3\u05dc \u05e2\u05dd \u05e4\u05d7\u05de\u05df \u05d2\u05d1\u05d5\u05d4, \u05e2\u05dd \u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d2\u05e1\u05d9\u05dd \u05de\u05d7\u05d9\u05de\u05d5\u05dd \u05d9\u05ea\u05e8, \u05d5\u05e2\u05dd \u05d0\u05de\u05e6\u05e2\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05e8\u05d9\u05e3 \u05de\u05d3\u05d9, \u05dc\u05de\u05e9\u05dc \u05de\u05d9\u05dd \u05dc\u05e4\u05dc\u05d3\u05d4 \u05e9\u05e0\u05d5\u05e2\u05d3\u05d4 \u05dc\u05e9\u05de\u05df."], [161.9, "\u05e1\u05d3\u05e7 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d5\u05e4\u05d9\u05e2 \u05d2\u05dd \u05e9\u05e2\u05d5\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d0\u05dd \u05dc\u05d0 \u05de\u05e8\u05e4\u05d9\u05dd \u05de\u05d9\u05d3. \u05dc\u05db\u05df \u05de\u05db\u05e0\u05d9\u05e1\u05d9\u05dd \u05dc\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d1\u05e8\u05d2\u05e2 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05de\u05ea\u05e7\u05e8\u05e8 \u05de\u05e1\u05e4\u05d9\u05e7."], [170.4, "\u05d0\u05d9\u05da \u05de\u05d6\u05d4\u05d9\u05dd \u05e1\u05d3\u05e7 \u05db\u05d9\u05d1\u05d5\u05d9? \u05d4\u05d5\u05d0 \u05e8\u05e5 \u05d1\u05e7\u05d5 \u05db\u05de\u05e2\u05d8 \u05d9\u05e9\u05e8 \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05dc\u05db\u05d9\u05d5\u05d5\u05df \u05d4\u05de\u05e8\u05db\u05d6, \u05d5\u05d0\u05d9\u05df \u05dc\u05d9\u05d3\u05d5 \u05d4\u05e4\u05d7\u05ea\u05ea \u05e4\u05d7\u05de\u05df."], [178.8, "\u05d0\u05dd \u05d9\u05e9 \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05d3\u05e7 \u05d4\u05e4\u05d7\u05ea\u05ea \u05e4\u05d7\u05de\u05df, \u05d4\u05d5\u05d0 \u05d4\u05d9\u05d4 \u05e7\u05d9\u05d9\u05dd \u05db\u05d1\u05e8 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05dc\u05de\u05e9\u05dc \u05de\u05d4\u05d7\u05d9\u05e9\u05d5\u05dc. \u05d0\u05dd \u05d9\u05e9 \u05d1\u05d5 \u05e7\u05e9\u05e7\u05e9\u05ea, \u05d4\u05d5\u05d0 \u05e0\u05e4\u05ea\u05d7 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4."], [189.0, "\u05d5\u05d9\u05e9 \u05d2\u05dd \u05e1\u05d3\u05e7\u05d9 \u05d4\u05e9\u05d7\u05d6\u05d4: \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d2\u05e8\u05e1\u05d9\u05d1\u05d9\u05ea \u05e9\u05dc \u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05de\u05d7\u05de\u05de\u05ea \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7, \u05d5\u05d9\u05d5\u05e6\u05e8\u05ea \u05e8\u05e9\u05ea \u05e9\u05dc \u05e1\u05d3\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd."], [198.2, "\u05de\u05d5\u05e0\u05e2\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05d0\u05d1\u05df \u05d7\u05d3\u05d4, \u05d1\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d8\u05d5\u05d1, \u05d5\u05d1\u05d4\u05d5\u05e8\u05d3\u05d4 \u05e9\u05dc \u05de\u05e2\u05d8 \u05d7\u05d5\u05de\u05e8 \u05d1\u05db\u05dc \u05de\u05e2\u05d1\u05e8. \u05de\u05d2\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d1\u05ea\u05d7\u05e8\u05d9\u05d8 \u05d1\u05d7\u05d5\u05de\u05e6\u05d4 \u05d0\u05d5 \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d2\u05e0\u05d8\u05d9\u05ea."], [208.4, "\u05d4\u05db\u05dc\u05dc \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d1\u05ea\u05db\u05e0\u05d5\u05df: \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05e0\u05d3\u05d9\u05d1\u05d9\u05dd \u05d1\u05de\u05e7\u05d5\u05dd \u05e4\u05d9\u05e0\u05d5\u05ea \u05d7\u05d3\u05d5\u05ea, \u05d1\u05db\u05dc \u05de\u05e7\u05d5\u05dd \u05e9\u05d0\u05e4\u05e9\u05e8."], [214.8, "\u05d4\u05db\u05dc\u05dc \u05d4\u05e9\u05e0\u05d9: \u05e2\u05d5\u05d1\u05d9 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3 \u05db\u05db\u05dc \u05d4\u05d0\u05e4\u05e9\u05e8, \u05d5\u05de\u05e2\u05d1\u05e8 \u05d4\u05d3\u05e8\u05d2\u05ea\u05d9 \u05d1\u05d9\u05df \u05d7\u05dc\u05e7\u05d9\u05dd \u05d3\u05e7\u05d9\u05dd \u05dc\u05e2\u05d1\u05d9\u05dd."], [222.3, "\u05d7\u05dc\u05e7 \u05e1\u05d9\u05de\u05d8\u05e8\u05d9 \u05de\u05ea\u05e2\u05d5\u05d5\u05ea \u05e4\u05d7\u05d5\u05ea. \u05d0\u05dd \u05d9\u05e9 \u05d7\u05e8\u05d9\u05e5 \u05d1\u05e6\u05d3 \u05d0\u05d7\u05d3, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d0\u05d6\u05df \u05d0\u05d5\u05ea\u05d5 \u05d1\u05d7\u05e8\u05d9\u05e5 \u05d0\u05d5 \u05d1\u05d7\u05d5\u05e8 \u05d1\u05e6\u05d3 \u05d4\u05e9\u05e0\u05d9."], [230.6, "\u05d7\u05d5\u05e8\u05d9\u05dd \u05de\u05e8\u05d7\u05d9\u05e7\u05d9\u05dd \u05de\u05d4\u05e9\u05e4\u05d4 \u05d5\u05de\u05d7\u05d5\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd. \u05d7\u05d5\u05e8 \u05e2\u05d5\u05d1\u05e8 \u05e2\u05d3\u05d9\u05e3 \u05e2\u05dc \u05d7\u05d5\u05e8 \u05e2\u05d9\u05d5\u05d5\u05e8, \u05e9\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d5\u05e9\u05de\u05df \u05db\u05d9\u05d1\u05d5\u05d9 \u05e0\u05dc\u05db\u05d3\u05d9\u05dd \u05d1\u05ea\u05d7\u05ea\u05d9\u05ea\u05d5."], [240.4, "\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dd \u05d3\u05e4\u05e0\u05d5\u05ea \u05d3\u05e7\u05d5\u05ea \u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05db\u05d5\u05e9\u05e8 \u05d4\u05ea\u05e7\u05e9\u05d5\u05ea \u05d2\u05d1\u05d5\u05d4, \u05e9\u05de\u05ea\u05e7\u05e9\u05d4 \u05d2\u05dd \u05db\u05e9\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e2\u05d3\u05d9\u05df, \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05d2\u05d6."], [249.0, "\u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d1\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05d4\u05de\u05d3\u05d5\u05d9\u05e7\u05d9\u05dd, \u05d5\u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05d0\u05e1\u05d5\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea, \u05db\u05de\u05d5 \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea."], [257.0, "\u05d5\u05db\u05d3\u05d0\u05d9 \u05dc\u05d3\u05d1\u05e8 \u05e2\u05dd \u05de\u05d9 \u05e9\u05e2\u05d5\u05e9\u05d4 \u05d0\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05db\u05d1\u05e8 \u05d1\u05e9\u05dc\u05d1 \u05d4\u05ea\u05db\u05e0\u05d5\u05df. \u05d4\u05d5\u05d0 \u05d9\u05d5\u05d3\u05e2 \u05d0\u05d9\u05da \u05d4\u05d7\u05dc\u05e7 \u05d9\u05ea\u05e0\u05d4\u05d2 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d1\u05d6\u05de\u05df \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [265.5, "\u05e1\u05d3\u05e8 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05d8\u05d9\u05e4\u05d5\u05e1\u05d9 \u05dc\u05d7\u05dc\u05e7 \u05de\u05d3\u05d5\u05d9\u05e7: \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d2\u05e1, \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05e2\u05d9\u05d1\u05d5\u05d3 \u05db\u05de\u05e2\u05d8 \u05e1\u05d5\u05e4\u05d9, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05d4\u05e9\u05d7\u05d6\u05d4."], [276.4, "\u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05d2\u05e1 \u05de\u05e9\u05d7\u05e8\u05e8\u05ea \u05d0\u05ea \u05d4\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05de\u05d4\u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05d5\u05dc\u05de\u05d9 \u05d5\u05de\u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e9\u05d1\u05d1\u05d9, \u05dc\u05e4\u05e0\u05d9 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05de\u05d2\u05d9\u05e2 \u05dc\u05de\u05d9\u05d3\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea."], [286.7, "\u05db\u05e9\u05d0\u05e4\u05e9\u05e8, \u05de\u05e7\u05e9\u05d9\u05dd \u05e8\u05e7 \u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05e9\u05e6\u05e8\u05d9\u05da, \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8. \u05db\u05da \u05d4\u05d7\u05d5\u05dd \u05de\u05e7\u05d5\u05de\u05d9, \u05d5\u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8."], [295.9, "\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d0\u05d9\u05df \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05db\u05dc\u05dc, \u05d5\u05dc\u05db\u05df \u05d4\u05e2\u05d9\u05d5\u05d5\u05ea \u05e7\u05d8\u05df \u05de\u05d0\u05d5\u05d3, \u05d5\u05dc\u05e2\u05d9\u05ea\u05d9\u05dd \u05e7\u05e8\u05d5\u05d1\u05d5\u05ea \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d7\u05e8\u05d9\u05d4."], [303.6, "\u05d1\u05d6\u05de\u05df \u05d4\u05db\u05d9\u05d1\u05d5\u05d9, \u05d7\u05dc\u05e7 \u05d0\u05e8\u05d5\u05da \u05e0\u05db\u05e0\u05e1 \u05dc\u05e9\u05de\u05df \u05d0\u05e0\u05db\u05d9\u05ea, \u05d5\u05d7\u05dc\u05e7 \u05e9\u05d8\u05d5\u05d7 \u05e0\u05db\u05e0\u05e1 \u05d1\u05e6\u05d3 \u05d4\u05e6\u05e8 \u05e9\u05dc\u05d5, \u05db\u05d3\u05d9 \u05e9\u05d9\u05ea\u05e7\u05e8\u05e8 \u05d1\u05d0\u05d5\u05e4\u05df \u05e9\u05d5\u05d5\u05d4."], [312.3, "\u05d7\u05d5\u05e8\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e1\u05d5\u05ea\u05de\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e4\u05e7\u05e7\u05d9\u05dd \u05d0\u05d5 \u05d1\u05d7\u05d5\u05de\u05e8 \u05d1\u05d9\u05d3\u05d5\u05d3, \u05db\u05d3\u05d9 \u05e9\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05e1\u05d1\u05d9\u05d1\u05dd \u05d9\u05d4\u05d9\u05d4 \u05e2\u05d3\u05d9\u05df \u05d9\u05d5\u05ea\u05e8."], [320.0, "\u05d8\u05d1\u05e2\u05d5\u05ea \u05d5\u05d2\u05dc\u05d2\u05dc\u05d9 \u05e9\u05d9\u05e0\u05d9\u05d9\u05dd \u05de\u05db\u05d1\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05ea\u05d5\u05da \u05de\u05db\u05d1\u05e9 \u05e2\u05dd \u05ea\u05d1\u05e0\u05d9\u05ea, \u05e9\u05de\u05d7\u05d6\u05d9\u05e7\u05d4 \u05d0\u05ea \u05d4\u05e6\u05d5\u05e8\u05d4 \u05d1\u05d6\u05de\u05df \u05d4\u05db\u05d9\u05d1\u05d5\u05d9."], [327.1, "\u05d7\u05dc\u05e7 \u05e9\u05d4\u05ea\u05e2\u05e7\u05dd \u05de\u05d9\u05d9\u05e9\u05e8\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d5\u05e2\u05d3\u05d9\u05e3 \u05db\u05e9\u05d4\u05d5\u05d0 \u05e2\u05d3\u05d9\u05d9\u05df \u05d7\u05dd. \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05dc\u05d0 \u05e0\u05d5\u05e6\u05e8\u05d5 \u05e1\u05d3\u05e7\u05d9\u05dd."], [336.5, "\u05ea\u05db\u05e0\u05d5\u05df \u05d1\u05dc\u05d9 \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05e9\u05d0\u05d9\u05e8 \u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05e9\u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d1\u05d9\u05d0 \u05dc\u05de\u05d9\u05d3\u05d4."], [342.0, "\u05d7\u05dc\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05e2\u05d3 \u05d4\u05e1\u05d5\u05e3 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05d1\u05dc\u05d9 \u05d4\u05e8\u05e4\u05d9\u05d9\u05ea \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d6\u05d6 \u05d5\u05d9\u05d5\u05e6\u05d0 \u05de\u05d4\u05d8\u05d5\u05dc\u05e8\u05e0\u05e1."], [349.1, "\u05d4\u05e9\u05d9\u05dc\u05d5\u05d1 \u05e9\u05dc \u05e4\u05d9\u05e0\u05d4 \u05d7\u05d3\u05d4 \u05e2\u05dd \u05db\u05d9\u05d1\u05d5\u05d9 \u05d7\u05e8\u05d9\u05e3 \u05d4\u05d5\u05d0 \u05d4\u05de\u05ea\u05db\u05d5\u05df \u05d4\u05e7\u05dc\u05d0\u05e1\u05d9 \u05dc\u05e1\u05d3\u05e7 \u05db\u05d9\u05d1\u05d5\u05d9."], [354.3, "\u05d7\u05dc\u05e7 \u05e9\u05d7\u05d9\u05db\u05d4 \u05dc\u05d9\u05dc\u05d4 \u05e9\u05dc\u05dd \u05d1\u05d9\u05df \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05dc\u05d4\u05e8\u05e4\u05d9\u05d4 \u05d9\u05db\u05d5\u05dc \u05dc\u05d4\u05d9\u05e1\u05d3\u05e7 \u05e2\u05dc \u05d4\u05de\u05d3\u05e3."], [359.5, "\u05d5\u05d9\u05d9\u05e9\u05d5\u05e8 \u05d1\u05db\u05d5\u05d7 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e7\u05e9\u05d4 \u05d5\u05e7\u05e8 \u05de\u05e1\u05ea\u05d9\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d1\u05e9\u05d1\u05e8."], [364.9, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05ea\u05d5\u05e1\u05e4\u05ea \u05d7\u05d5\u05de\u05e8 \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05e4\u05d9\u05e8\u05d5\u05e9\u05d4 \u05d6\u05de\u05df \u05d4\u05e9\u05d7\u05d6\u05d4, \u05d5\u05d7\u05dc\u05e7 \u05de\u05d5\u05e7\u05e9\u05d4 \u05e0\u05e9\u05d7\u05d6 \u05dc\u05d0\u05d8 \u05d5\u05d1\u05d6\u05d4\u05d9\u05e8\u05d5\u05ea."], [373.8, "\u05d2\u05dd \u05d9\u05d9\u05e9\u05d5\u05e8, \u05de\u05db\u05d1\u05e9\u05d9 \u05db\u05d9\u05d1\u05d5\u05d9 \u05d5\u05ea\u05d1\u05e0\u05d9\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e2\u05d1\u05d5\u05d3\u05d4 \u05d9\u05d3\u05e0\u05d9\u05ea \u05d5\u05e6\u05d9\u05d5\u05d3 \u05de\u05d9\u05d5\u05d7\u05d3."], [379.8, "\u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05e0\u05e4\u05e1\u05dc\u05d5 \u05d1\u05d2\u05dc\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea \u05d0\u05d5 \u05e1\u05d3\u05e7 \u05e2\u05d5\u05dc\u05d9\u05dd \u05d0\u05ea \u05db\u05dc \u05de\u05d4 \u05e9\u05d4\u05d5\u05e9\u05e7\u05e2 \u05d1\u05d4\u05dd \u05e2\u05d3 \u05d0\u05d5\u05ea\u05d5 \u05e9\u05dc\u05d1."], [386.0, "\u05d5\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05e8\u05d3\u05d9\u05d5\u05e1 \u05d2\u05d3\u05d5\u05dc \u05d9\u05d5\u05ea\u05e8 \u05d0\u05d5 \u05d3\u05d5\u05e4\u05df \u05d0\u05d7\u05d9\u05d3\u05d4 \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05e2\u05d5\u05dc\u05d9\u05dd \u05db\u05dc\u05d5\u05dd \u05d1\u05ea\u05db\u05e0\u05d5\u05df, \u05d5\u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d4\u05e8\u05d1\u05d4 \u05db\u05e1\u05e3 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8."], [394.8, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd \u05e0\u05d5\u05e6\u05e8\u05d9\u05dd \u05de\u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05ea\u05e8\u05de\u05d9\u05d9\u05dd \u05d5\u05de\u05de\u05d0\u05de\u05e6\u05d9 \u05d4\u05ea\u05de\u05e8\u05d4, \u05d5\u05de\u05ea\u05e8\u05db\u05d6\u05d9\u05dd \u05d1\u05e4\u05d9\u05e0\u05d5\u05ea, \u05d1\u05d7\u05d5\u05e8\u05d9\u05dd \u05d5\u05d1\u05de\u05e2\u05d1\u05e8\u05d9 \u05e2\u05d5\u05d1\u05d9."], [404.6, "\u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd \u05e0\u05d3\u05d9\u05d1\u05d9\u05dd, \u05e2\u05d5\u05d1\u05d9 \u05d0\u05d7\u05d9\u05d3 \u05d5\u05e1\u05d9\u05de\u05d8\u05e8\u05d9\u05d4 \u05d4\u05dd \u05d4\u05d3\u05e8\u05da \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e7\u05d8\u05d9\u05df \u05d0\u05d5\u05ea\u05dd."], [410.6, "\u05e1\u05d3\u05e8 \u05e4\u05e2\u05d5\u05dc\u05d5\u05ea \u05e0\u05db\u05d5\u05df, \u05ea\u05d5\u05e1\u05e4\u05ea \u05dc\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4 \u05de\u05d9\u05d3 \u05d0\u05d7\u05e8\u05d9 \u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05de\u05e9\u05dc\u05d9\u05de\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05de\u05d5\u05e0\u05d4."], [417.0, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05dc \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05d1\u05e7\u05e8\u05d4: \u05d0\u05d9\u05da \u05de\u05d5\u05d5\u05d3\u05d0\u05d9\u05dd \u05e9\u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d1\u05d0\u05de\u05ea \u05d4\u05e6\u05dc\u05d9\u05d7."]]};
window.MH_TR["ch22"]={"t": "\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05d1\u05e7\u05e8\u05d4", "l": [[5.0, "\u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d7\u05dc\u05e7 \u05e0\u05e8\u05d0\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05db\u05de\u05d5 \u05dc\u05e4\u05e0\u05d9. \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05d0\u05d5\u05ea \u05d1\u05e2\u05d9\u05df \u05d0\u05dd \u05d4\u05d5\u05d0 \u05e7\u05e9\u05d4, \u05d0\u05dd \u05d4\u05e9\u05db\u05d1\u05d4 \u05e2\u05de\u05d5\u05e7\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7, \u05d0\u05d5 \u05d0\u05dd \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d4\u05d9\u05d4 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d4\u05e0\u05db\u05d5\u05e0\u05d4."], [15.9, "\u05dc\u05db\u05df \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd: \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5, \u05d0\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05d4\u05e2\u05d3 \u05e9\u05e2\u05d1\u05e8\u05d5 \u05d0\u05d9\u05ea\u05d5 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da, \u05d5\u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8."], [23.0, "\u05e0\u05db\u05d9\u05e8 \u05d0\u05ea \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d0\u05ea \u05de\u05d3\u05d9\u05d3\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4, \u05d0\u05ea \u05d4\u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4, \u05d0\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05d4\u05e2\u05d3, \u05d5\u05d0\u05ea \u05d4\u05d1\u05e7\u05e8\u05d4 \u05e2\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8 \u05dc\u05e4\u05d9 AMS 2750."], [34.9, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05d9\u05d0 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8. \u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05d7\u05d5\u05d3\u05df \u05dc\u05ea\u05d5\u05da \u05d4\u05d7\u05d5\u05de\u05e8 \u05d1\u05db\u05d5\u05d7 \u05d9\u05d3\u05d5\u05e2, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e7\u05e2."], [43.0, "\u05d1\u05e9\u05d9\u05d8\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc, \u05d7\u05e8\u05d5\u05d8 \u05d9\u05d4\u05dc\u05d5\u05dd \u05e0\u05dc\u05d7\u05e5 \u05d1\u05e9\u05e0\u05d9 \u05e9\u05dc\u05d1\u05d9\u05dd, \u05d5\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05de\u05d5\u05d3\u05d3\u05ea \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05d7\u05d3\u05d9\u05e8\u05d4. \u05d6\u05d5 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d9\u05d0 \u05d4\u05e0\u05e4\u05d5\u05e6\u05d4 \u05d1\u05e8\u05e6\u05e4\u05ea \u05d4\u05d9\u05d9\u05e6\u05d5\u05e8."], [53.5, "\u05e1\u05e7\u05d0\u05dc\u05ea C \u05e9\u05dc \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05de\u05d5\u05e7\u05e9\u05d5\u05ea. \u05dc\u05d7\u05d5\u05de\u05e8\u05d9\u05dd \u05e8\u05db\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8 \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05db\u05d3\u05d5\u05e8 \u05d5\u05d1\u05e1\u05e7\u05d0\u05dc\u05d4 B."], [61.2, "\u05d1\u05e9\u05d9\u05d8\u05ea \u05d1\u05e8\u05d9\u05e0\u05dc, \u05db\u05d3\u05d5\u05e8 \u05d2\u05d3\u05d5\u05dc \u05de\u05e9\u05d0\u05d9\u05e8 \u05e9\u05e7\u05e2 \u05e8\u05d7\u05d1, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05d8\u05e8 \u05e9\u05dc\u05d5. \u05d4\u05e9\u05e7\u05e2 \u05d4\u05d2\u05d3\u05d5\u05dc \u05de\u05de\u05e6\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4, \u05d5\u05dc\u05db\u05df \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05ea\u05d0\u05d9\u05de\u05d4 \u05dc\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7 \u05d5\u05dc\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e8\u05d5\u05db\u05db\u05d9\u05dd."], [74.3, "\u05d1\u05e9\u05d9\u05d8\u05ea \u05d5\u05d9\u05e7\u05e8\u05e1, \u05e4\u05d9\u05e8\u05de\u05d9\u05d3\u05ea \u05d9\u05d4\u05dc\u05d5\u05dd \u05de\u05e9\u05d0\u05d9\u05e8\u05d4 \u05e9\u05e7\u05e2 \u05d1\u05e6\u05d5\u05e8\u05ea \u05e8\u05d9\u05d1\u05d5\u05e2, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d0\u05ea \u05d4\u05d0\u05dc\u05db\u05e1\u05d5\u05e0\u05d9\u05dd \u05e9\u05dc\u05d5 \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4. \u05d4\u05e1\u05e7\u05d0\u05dc\u05d4 \u05d0\u05d7\u05ea \u05dc\u05db\u05dc \u05d8\u05d5\u05d5\u05d7 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea."], [84.8, "\u05db\u05d3\u05d9 \u05e9\u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05ea\u05d4\u05d9\u05d4 \u05e0\u05db\u05d5\u05e0\u05d4, \u05de\u05d5\u05e8\u05d9\u05d3\u05d9\u05dd \u05e7\u05d5\u05d3\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05e7\u05e9\u05ea \u05d5\u05d0\u05ea \u05d4\u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05d4\u05e4\u05d7\u05de\u05df, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05d9\u05e9\u05e8 \u05d5\u05e0\u05e7\u05d9."], [93.3, "\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05dc\u05e4\u05d7\u05d5\u05ea \u05e4\u05d9 \u05e2\u05e9\u05e8\u05d4 \u05de\u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05e7\u05e2, \u05d0\u05d7\u05e8\u05ea \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e9\u05de\u05ea\u05d7\u05ea \u05de\u05e9\u05e4\u05d9\u05e2 \u05e2\u05dc \u05d4\u05de\u05d3\u05d9\u05d3\u05d4. \u05d5\u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05de\u05e2\u05d5\u05d2\u05dc \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05ea\u05d9\u05e7\u05d5\u05df \u05dc\u05e4\u05d9 \u05d8\u05d1\u05dc\u05d4."], [104.3, "\u05d0\u05ea \u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2 \u05e2\u05dc \u05d0\u05d1\u05df \u05db\u05d9\u05d5\u05dc. \u05d5\u05d8\u05d1\u05dc\u05d0\u05d5\u05ea \u05d4\u05de\u05e8\u05d4 \u05d1\u05d9\u05df \u05d4\u05e1\u05e7\u05d0\u05dc\u05d5\u05ea \u05d4\u05df \u05e8\u05e7 \u05e7\u05d9\u05e8\u05d5\u05d1."], [111.6, "\u05d1\u05e9\u05db\u05d1\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05d3\u05e7\u05d4, \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e8\u05d2\u05d9\u05dc\u05d4 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d3\u05e8\u05da \u05d4\u05e9\u05db\u05d1\u05d4 \u05d5\u05de\u05d5\u05d3\u05d3\u05ea \u05d2\u05dd \u05d0\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4. \u05dc\u05db\u05df \u05de\u05e9\u05ea\u05de\u05e9\u05d9\u05dd \u05d1\u05de\u05d9\u05e7\u05e8\u05d5-\u05e7\u05e9\u05d9\u05d5\u05ea."], [120.6, "\u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7, \u05de\u05dc\u05d8\u05e9\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05ea\u05da, \u05d5\u05dc\u05d5\u05d7\u05e6\u05d9\u05dd \u05e9\u05d5\u05e8\u05d4 \u05e9\u05dc \u05e9\u05e7\u05e2\u05d9\u05dd \u05e7\u05d8\u05e0\u05d9\u05dd \u05d1\u05db\u05d5\u05d7 \u05e9\u05dc \u05d2\u05e8\u05de\u05d9\u05dd, \u05de\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05e4\u05e0\u05d9\u05de\u05d4."], [129.1, "\u05de\u05db\u05dc \u05e9\u05e7\u05e2 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05e2\u05e8\u05da, \u05d5\u05de\u05e9\u05e8\u05d8\u05d8\u05d9\u05dd \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e9\u05dc \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05e4\u05d9 \u05d4\u05e2\u05d5\u05de\u05e7."], [134.8, "\u05dc\u05e4\u05d9 ISO 18203, \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d4\u05e2\u05d5\u05de\u05e7 \u05d4\u05d0\u05e4\u05e7\u05d8\u05d9\u05d1\u05d9 \u05e0\u05de\u05d3\u05d3 \u05e2\u05d3 550 \u05d5\u05d9\u05e7\u05e8\u05e1."], [143.0, "\u05d1\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d4\u05d1\u05d4, \u05e2\u05d3 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05d5\u05e8\u05d3\u05ea \u05dc-80 \u05d0\u05d7\u05d5\u05d6 \u05de\u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d4\u05de\u05d9\u05e0\u05d9\u05de\u05dc\u05d9\u05ea \u05d1\u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7."], [151.6, "\u05d5\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4, \u05e2\u05d3 \u05d4\u05e0\u05e7\u05d5\u05d3\u05d4 \u05e9\u05d1\u05d4 \u05d9\u05e9 \u05e2\u05d3\u05d9\u05d9\u05df 50 \u05d5\u05d9\u05e7\u05e8\u05e1 \u05de\u05e2\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea \u05d4\u05dc\u05d9\u05d1\u05d4."], [157.7, "\u05d6\u05d5 \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d4\u05d5\u05e8\u05e1\u05ea: \u05d4\u05d7\u05dc\u05e7 \u05e9\u05e0\u05d1\u05d3\u05e7 \u05e0\u05d7\u05ea\u05da. \u05dc\u05db\u05df \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dc \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05e2\u05d3, \u05d5\u05e2\u05dc \u05d6\u05d4 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05d5\u05d3 \u05de\u05e2\u05d8."], [167.0, "\u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4 \u05d4\u05d9\u05d0 \u05d4\u05e1\u05ea\u05db\u05dc\u05d5\u05ea \u05e2\u05dc \u05d4\u05de\u05d1\u05e0\u05d4 \u05e2\u05e6\u05de\u05d5. \u05d7\u05d5\u05ea\u05db\u05d9\u05dd, \u05d9\u05d5\u05e6\u05e7\u05d9\u05dd \u05d1\u05e9\u05e8\u05e3, \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd \u05d5\u05de\u05dc\u05d8\u05e9\u05d9\u05dd \u05e2\u05d3 \u05de\u05e8\u05d0\u05d4 \u05e9\u05dc \u05d1\u05e8\u05e7."], [175.7, "\u05d0\u05d7\u05e8 \u05db\u05da \u05e6\u05d5\u05e8\u05d1\u05d9\u05dd \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7 \u05d1\u05d7\u05d5\u05de\u05e6\u05d4 \u05e2\u05d3\u05d9\u05e0\u05d4, \u05dc\u05de\u05e9\u05dc \u05e0\u05d9\u05d8\u05dc, \u05d5\u05d4\u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d1\u05d9\u05df \u05d4\u05e4\u05d0\u05d6\u05d5\u05ea \u05e0\u05d7\u05e9\u05e4\u05d9\u05dd."], [183.4, "\u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e1\u05e7\u05d5\u05e4 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d0\u05dd \u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8, \u05db\u05de\u05d4 \u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8 \u05e9\u05d9\u05d5\u05e8\u05d9 \u05e0\u05e9\u05d0\u05e8, \u05d0\u05d9\u05da \u05de\u05e4\u05d5\u05d6\u05e8\u05d9\u05dd \u05d4\u05e7\u05e8\u05d1\u05d9\u05d3\u05d9\u05dd \u05d5\u05de\u05d4 \u05d2\u05d5\u05d3\u05dc \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd."], [191.9, "\u05e8\u05d5\u05d0\u05d9\u05dd \u05d2\u05dd \u05e4\u05d2\u05de\u05d9\u05dd: \u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05e4\u05d7\u05de\u05df, \u05e9\u05db\u05d1\u05d4 \u05dc\u05d1\u05e0\u05d4 \u05e2\u05d1\u05d4 \u05de\u05d3\u05d9 \u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4, \u05d0\u05d5 \u05d7\u05de\u05e6\u05d5\u05df \u05dc\u05d0\u05d5\u05e8\u05da \u05d2\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d2\u05e8\u05e2\u05d9\u05e0\u05d9\u05dd \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4."], [201.4, "\u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d0\u05ea \u05de\u05d4 \u05e9\u05e8\u05d5\u05d0\u05d9\u05dd \u05dc\u05ea\u05de\u05d5\u05e0\u05d5\u05ea \u05d9\u05d9\u05d7\u05d5\u05e1 \u05d1\u05ea\u05e7\u05df \u05d0\u05d5 \u05d1\u05de\u05e4\u05e8\u05d8, \u05d5\u05de\u05ea\u05e2\u05d3\u05d9\u05dd \u05d1\u05e6\u05d9\u05dc\u05d5\u05dd."], [207.3, "\u05d4\u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4 \u05e2\u05d5\u05e0\u05d4 \u05e2\u05dc \u05e9\u05d0\u05dc\u05d4 \u05e9\u05d4\u05e7\u05e9\u05d9\u05d5\u05ea \u05dc\u05d0 \u05e2\u05d5\u05e0\u05d4 \u05e2\u05dc\u05d9\u05d4: \u05dc\u05de\u05d4. \u05e9\u05e0\u05d9 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e2\u05dd \u05d0\u05d5\u05ea\u05d4 \u05e7\u05e9\u05d9\u05d5\u05ea \u05d9\u05db\u05d5\u05dc\u05d9\u05dd \u05dc\u05d4\u05d9\u05d5\u05ea \u05e2\u05dd \u05de\u05d1\u05e0\u05d4 \u05e9\u05d5\u05e0\u05d4 \u05dc\u05d2\u05de\u05e8\u05d9."], [217.7, "\u05d3\u05d2\u05d9\u05de\u05ea \u05e2\u05d3 \u05d4\u05d9\u05d0 \u05d7\u05ea\u05d9\u05db\u05d4 \u05e7\u05d8\u05e0\u05d4, \u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05d5\u05de\u05e8 \u05d5\u05de\u05d0\u05d5\u05ea\u05d4 \u05de\u05e0\u05ea \u05d9\u05d9\u05e6\u05d5\u05e8 \u05db\u05de\u05d5 \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd, \u05e9\u05e2\u05d5\u05d1\u05e8\u05ea \u05d0\u05d9\u05ea\u05dd \u05d0\u05ea \u05db\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [225.8, "\u05de\u05e0\u05d9\u05d7\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d1\u05ea\u05d5\u05da \u05d4\u05de\u05e0\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05d1\u05de\u05e7\u05d5\u05dd \u05d4\u05d1\u05e2\u05d9\u05d9\u05ea\u05d9 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05dc\u05de\u05e9\u05dc \u05d1\u05de\u05e8\u05db\u05d6 \u05d4\u05e1\u05dc, \u05e9\u05e9\u05dd \u05d4\u05d7\u05d9\u05de\u05d5\u05dd \u05d5\u05d4\u05db\u05d9\u05d1\u05d5\u05d9 \u05d0\u05d9\u05d8\u05d9\u05d9\u05dd \u05d9\u05d5\u05ea\u05e8."], [235.0, "\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05ea\u05db\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e2\u05dc\u05d9\u05d4: \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea, \u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05de\u05ea\u05d9\u05d7\u05d4 \u05d5\u05d4\u05dc\u05de\u05d4."], [243.1, "\u05d7\u05e9\u05d5\u05d1 \u05e9\u05d4\u05e2\u05d5\u05d1\u05d9 \u05e9\u05dc\u05d4 \u05d9\u05d4\u05d9\u05d4 \u05d3\u05d5\u05de\u05d4 \u05dc\u05e2\u05d5\u05d1\u05d9 \u05d4\u05d7\u05dc\u05e7. \u05d3\u05d2\u05d9\u05de\u05d4 \u05d3\u05e7\u05d4 \u05de\u05ea\u05e7\u05e8\u05e8\u05ea \u05de\u05d4\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05ea\u05d9\u05ea\u05df \u05ea\u05d5\u05e6\u05d0\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05d4\u05d7\u05dc\u05e7 \u05e2\u05e6\u05de\u05d5."], [252.2, "\u05db\u05dc \u05d3\u05d2\u05d9\u05de\u05d4 \u05de\u05e1\u05d5\u05de\u05e0\u05ea, \u05db\u05da \u05e9\u05d0\u05e4\u05e9\u05e8 \u05dc\u05e7\u05e9\u05e8 \u05d0\u05d5\u05ea\u05d4 \u05dc\u05de\u05e0\u05d4, \u05dc\u05ea\u05e0\u05d5\u05e8 \u05d5\u05dc\u05ea\u05d0\u05e8\u05d9\u05da. \u05d6\u05d4 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e2\u05e7\u05d9\u05d1\u05d5\u05ea \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [261.0, "\u05d4\u05d7\u05dc\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05d1\u05e7\u05e8\u05d4 \u05e2\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8. \u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4 \u05e2\u05d5\u05e9\u05d9\u05dd \u05d0\u05d5\u05ea\u05d4 \u05dc\u05e4\u05d9 \u05d4\u05de\u05e4\u05e8\u05d8 AMS 2750, \u05e9\u05e2\u05d5\u05e1\u05e7 \u05d1\u05de\u05d3\u05d9\u05d3\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [272.0, "\u05db\u05dc \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc \u05d5\u05de\u05db\u05e9\u05d9\u05e8 \u05de\u05d3\u05d9\u05d3\u05d4 \u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05db\u05d9\u05d5\u05dc, \u05d5\u05dc\u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc\u05d9\u05dd \u05d9\u05e9 \u05de\u05d2\u05d1\u05dc\u05d4 \u05e2\u05dc \u05de\u05e1\u05e4\u05e8 \u05d4\u05e9\u05d9\u05de\u05d5\u05e9\u05d9\u05dd \u05d0\u05d5 \u05e2\u05dc \u05d6\u05de\u05df \u05d4\u05e9\u05d9\u05de\u05d5\u05e9."], [280.4, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d4\u05de\u05e2\u05e8\u05db\u05ea, SAT, \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d0\u05ea \u05de\u05d4 \u05e9\u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05e8\u05d0\u05d4 \u05dc\u05de\u05d3\u05d9\u05d3\u05d4 \u05e9\u05dc \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc \u05d9\u05d9\u05d7\u05d5\u05e1, \u05d1\u05d0\u05d5\u05ea\u05d4 \u05e0\u05e7\u05d5\u05d3\u05d4."], [288.7, "\u05e1\u05e7\u05e8 \u05d4\u05d0\u05d7\u05d9\u05d3\u05d5\u05ea, TUS, \u05d1\u05d5\u05d3\u05e7 \u05d0\u05dd \u05db\u05dc \u05e0\u05e4\u05d7 \u05d4\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d1\u05d0\u05de\u05ea \u05d1\u05d0\u05d5\u05ea\u05d4 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4. \u05de\u05e4\u05d6\u05e8\u05d9\u05dd \u05d1\u05d5 \u05d4\u05e8\u05d1\u05d4 \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc\u05d9\u05dd, \u05d5\u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05dc\u05d0\u05d5\u05e8\u05da \u05d6\u05de\u05df."], [299.8, "\u05dc\u05e4\u05d9 \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d4\u05e1\u05e7\u05e8, \u05d4\u05ea\u05e0\u05d5\u05e8 \u05de\u05e7\u05d1\u05dc \u05d3\u05e8\u05d2\u05d4: \u05de\u05d3\u05e8\u05d2\u05d4 1, \u05e2\u05dd \u05e1\u05d8\u05d9\u05d9\u05d4 \u05e9\u05dc \u05e2\u05d3 3 \u05de\u05e2\u05dc\u05d5\u05ea \u05dc\u05db\u05dc \u05db\u05d9\u05d5\u05d5\u05df, \u05d5\u05e2\u05d3 \u05d3\u05e8\u05d2\u05d4 6, \u05e2\u05dd \u05e2\u05d3 28 \u05de\u05e2\u05dc\u05d5\u05ea."], [311.5, "\u05d4\u05de\u05e4\u05e8\u05d8 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d0\u05d5 \u05e9\u05dc \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e7\u05d5\u05d1\u05e2 \u05d0\u05d9\u05d6\u05d5 \u05d3\u05e8\u05d2\u05d4 \u05e0\u05d3\u05e8\u05e9\u05ea."], [316.8, "\u05d2\u05dd \u05e1\u05d5\u05d2 \u05d4\u05de\u05db\u05e9\u05d5\u05e8 \u05d1\u05ea\u05e0\u05d5\u05e8 \u05de\u05d5\u05d2\u05d3\u05e8, \u05de-A \u05d5\u05e2\u05d3 E: \u05db\u05de\u05d4 \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc\u05d9\u05dd \u05d9\u05e9, \u05d5\u05de\u05d4 \u05e0\u05e8\u05e9\u05dd. \u05ea\u05d3\u05d9\u05e8\u05d5\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e0\u05e7\u05d1\u05e2\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d3\u05e8\u05d2\u05d4 \u05d5\u05dc\u05e4\u05d9 \u05e1\u05d5\u05d2 \u05d4\u05de\u05db\u05e9\u05d5\u05e8."], [328.0, "\u05d5\u05db\u05dc \u05d4\u05e8\u05d9\u05e9\u05d5\u05de\u05d9\u05dd \u05e0\u05e9\u05de\u05e8\u05d9\u05dd: \u05d2\u05e8\u05e3 \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e9\u05dc \u05db\u05dc \u05de\u05e0\u05d4, \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d4\u05db\u05d9\u05d5\u05dc \u05d5\u05d4\u05e1\u05e7\u05e8\u05d9\u05dd. \u05de\u05d1\u05e7\u05e8 \u05d9\u05db\u05d5\u05dc \u05dc\u05d1\u05e7\u05e9 \u05d0\u05d5\u05ea\u05dd \u05d2\u05dd \u05d0\u05d7\u05e8\u05d9 \u05e9\u05e0\u05d9\u05dd."], [337.5, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05dc \u05e7\u05e9\u05e7\u05e9\u05ea \u05d0\u05d5 \u05e2\u05dc \u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05e4\u05d7\u05de\u05df \u05e0\u05d5\u05ea\u05e0\u05ea \u05e2\u05e8\u05da \u05e0\u05de\u05d5\u05da, \u05d5\u05d7\u05dc\u05e7 \u05d8\u05d5\u05d1 \u05e0\u05e4\u05e1\u05dc."], [345.3, "\u05d1\u05d3\u05d9\u05e7\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05e2\u05dc \u05d7\u05dc\u05e7 \u05d3\u05e7 \u05de\u05d3\u05d9 \u05e0\u05d5\u05ea\u05e0\u05ea \u05e2\u05e8\u05da \u05e9\u05d2\u05d5\u05d9, \u05d1\u05d2\u05dc\u05dc \u05d4\u05e9\u05d5\u05dc\u05d7\u05df \u05e9\u05de\u05ea\u05d7\u05ea."], [351.2, "\u05d3\u05d2\u05d9\u05de\u05ea \u05e2\u05d3 \u05d3\u05e7\u05d4 \u05de\u05d3\u05d9 \u05e2\u05d5\u05d1\u05e8\u05ea \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4, \u05d1\u05d6\u05de\u05df \u05e9\u05d4\u05d7\u05dc\u05e7 \u05d4\u05e2\u05d1\u05d4 \u05e2\u05e6\u05de\u05d5 \u05dc\u05d0 \u05d4\u05ea\u05e7\u05e9\u05d4 \u05de\u05e1\u05e4\u05d9\u05e7."], [357.6, "\u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc \u05e9\u05e2\u05d1\u05e8 \u05d0\u05ea \u05d6\u05de\u05df \u05d4\u05e9\u05d9\u05de\u05d5\u05e9 \u05e9\u05dc\u05d5 \u05e1\u05d5\u05d8\u05d4, \u05d5\u05d4\u05ea\u05e0\u05d5\u05e8 \u05e2\u05d5\u05d1\u05d3 \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d7\u05e8\u05ea \u05de\u05de\u05d4 \u05e9\u05de\u05d5\u05e6\u05d2."], [364.1, "\u05d5\u05d1\u05dc\u05d9 \u05e8\u05d9\u05e9\u05d5\u05dd \u05e9\u05dc \u05d4\u05de\u05e0\u05d4, \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d4\u05d5\u05db\u05d9\u05d7 \u05e9\u05d4\u05d7\u05dc\u05e7 \u05e2\u05d1\u05e8 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e0\u05db\u05d5\u05df."], [370.0, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05d3\u05d5\u05e8\u05e9\u05d5\u05ea \u05d3\u05d2\u05d9\u05de\u05d5\u05ea, \u05d7\u05d9\u05ea\u05d5\u05da \u05d5\u05d4\u05db\u05e0\u05d4 \u05d1\u05de\u05e2\u05d1\u05d3\u05d4."], [375.8, "\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5-\u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4 \u05dc\u05d5\u05e7\u05d7\u05d9\u05dd \u05e9\u05e2\u05d5\u05ea \u05e9\u05dc \u05e2\u05d1\u05d5\u05d3\u05d4 \u05de\u05e7\u05e6\u05d5\u05e2\u05d9\u05ea."], [380.8, "\u05e2\u05de\u05d9\u05d3\u05d4 \u05d1-AMS 2750 \u05d3\u05d5\u05e8\u05e9\u05ea \u05db\u05d9\u05d5\u05dc\u05d9\u05dd \u05d5\u05e1\u05e7\u05e8\u05d9\u05dd \u05ea\u05db\u05d5\u05e4\u05d9\u05dd, \u05ea\u05e8\u05de\u05d5\u05e7\u05e4\u05dc\u05d9\u05dd \u05d7\u05d3\u05e9\u05d9\u05dd, \u05de\u05db\u05e9\u05d5\u05e8 \u05d5\u05ea\u05d9\u05e2\u05d5\u05d3."], [389.7, "\u05d5\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d1\u05d3\u05d9\u05e7\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05e2\u05db\u05e9\u05d9\u05d5 \u05d7\u05d5\u05e1\u05db\u05ea \u05d7\u05dc\u05e7 \u05e4\u05e1\u05d5\u05dc \u05e9\u05de\u05ea\u05d2\u05dc\u05d4 \u05e8\u05e7 \u05d0\u05e6\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7."], [395.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d1\u05e9\u05d9\u05d8\u05d5\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc, \u05d1\u05e8\u05d9\u05e0\u05dc \u05d0\u05d5 \u05d5\u05d9\u05e7\u05e8\u05e1, \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9 \u05d5\u05d1\u05e2\u05d5\u05d1\u05d9 \u05de\u05e1\u05e4\u05d9\u05e7."], [403.8, "\u05e2\u05d5\u05de\u05e7 \u05e9\u05db\u05d1\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd \u05d1\u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05de\u05d9\u05e7\u05e8\u05d5-\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d5\u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05e8\u05d5\u05d0\u05d9\u05dd \u05d1\u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4, \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05e2\u05dc \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05e2\u05d3."], [412.3, "\u05d5\u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8 \u05e2\u05e6\u05de\u05d5 \u05de\u05d1\u05e7\u05e8\u05d9\u05dd \u05d1\u05db\u05d9\u05d5\u05dc\u05d9\u05dd, \u05d1\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d3\u05d9\u05d5\u05e7 \u05d5\u05d1\u05e1\u05e7\u05e8\u05d9 \u05d0\u05d7\u05d9\u05d3\u05d5\u05ea."], [417.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d1\u05d0 \u05e0\u05d3\u05d1\u05e8 \u05e2\u05dc \u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05e9\u05e8\u05d8\u05d5\u05d8: \u05d0\u05d9\u05da \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05e0\u05db\u05d5\u05df \u05d0\u05ea \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd."]]};
window.MH_TR["ch23"]={"t": "\u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05d5\u05e9\u05e8\u05d8\u05d5\u05d8", "l": [[5.0, "\u05db\u05dc \u05de\u05d4 \u05e9\u05dc\u05de\u05d3\u05e0\u05d5 \u05d1\u05e7\u05d5\u05e8\u05e1 \u05e6\u05e8\u05d9\u05da \u05d1\u05e1\u05d5\u05e3 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05dc\u05d3\u05e3 \u05d0\u05d7\u05d3: \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8. \u05de\u05de\u05e0\u05d5 \u05d4\u05de\u05e4\u05e2\u05dc, \u05d4\u05e1\u05e4\u05e7 \u05d5\u05de\u05e2\u05d1\u05d3\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d9\u05d5\u05d3\u05e2\u05d9\u05dd \u05de\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05e0\u05d3\u05e8\u05e9."], [15.8, "\u05e9\u05e8\u05d8\u05d5\u05d8 \u05e2\u05dd \u05d4\u05e2\u05e8\u05d4 \u05db\u05de\u05d5 \"\u05dc\u05d4\u05e7\u05e9\u05d5\u05ea\" \u05db\u05de\u05e2\u05d8 \u05dc\u05d0 \u05d0\u05d5\u05de\u05e8 \u05db\u05dc\u05d5\u05dd: \u05dc\u05d0\u05d9\u05d6\u05d5 \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d1\u05d0\u05d9\u05d6\u05d4 \u05e2\u05d5\u05de\u05e7, \u05d0\u05d9\u05e4\u05d4 \u05de\u05d5\u05d3\u05d3\u05d9\u05dd, \u05d5\u05dc\u05e4\u05d9 \u05d0\u05d9\u05d6\u05d4 \u05de\u05e4\u05e8\u05d8?"], [25.5, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d6\u05d4 \u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05da \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d3\u05e8\u05d9\u05e9\u05ea \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8, \u05d0\u05d9\u05dc\u05d5 \u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05de\u05e4\u05e0\u05d9\u05dd \u05d0\u05dc\u05d9\u05d4\u05dd, \u05d0\u05d9\u05d6\u05d5 \u05ea\u05e2\u05d5\u05d3\u05d4 \u05de\u05e7\u05d1\u05dc\u05d9\u05dd, \u05d5\u05de\u05d4 \u05d6\u05d4 Nadcap."], [35.9, "\u05d4\u05ea\u05e7\u05df \u05d4\u05d1\u05d9\u05e0\u05dc\u05d0\u05d5\u05de\u05d9 \u05dc\u05e0\u05d5\u05e9\u05d0 \u05d4\u05d5\u05d0 ISO 15787. \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05d9\u05da \u05de\u05e6\u05d9\u05d2\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d0\u05ea \u05d4\u05de\u05e6\u05d1 \u05d4\u05e1\u05d5\u05e4\u05d9 \u05e9\u05dc \u05d7\u05dc\u05e7 \u05e4\u05dc\u05d3\u05d4 \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd."], [47.3, "\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1: \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4, \u05d5\u05dc\u05d0 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da. \u05dc\u05d0 \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea \u05d5\u05d6\u05de\u05e0\u05d9\u05dd, \u05d0\u05dc\u05d0 \u05de\u05d4 \u05d4\u05d7\u05dc\u05e7 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05d1\u05e1\u05d5\u05e3."], [56.9, "\u05e7\u05d5\u05d3\u05dd \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05de\u05e6\u05d1 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05d1\u05de\u05d9\u05dc\u05d9\u05dd, \u05dc\u05e4\u05d9 \u05d4\u05e1\u05d3\u05e8 \u05e9\u05d1\u05d5 \u05d4\u05d5\u05d0 \u05e0\u05e2\u05e9\u05d4. \u05dc\u05de\u05e9\u05dc: \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4, \u05d0\u05d5 \u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."], [67.9, "\u05d0\u05d7\u05e8 \u05db\u05da \u05d0\u05ea \u05d4\u05e7\u05e9\u05d9\u05d5\u05ea, \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d0\u05dd \u05d9\u05e9, \u05d5\u05d0\u05ea \u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4. \u05d0\u05ea \u05db\u05dc \u05d0\u05dc\u05d4 \u05de\u05e8\u05db\u05d6\u05d9\u05dd \u05dc\u05d9\u05d3 \u05d8\u05d1\u05dc\u05ea \u05d4\u05db\u05d5\u05ea\u05e8\u05ea."], [77.0, "\u05d5\u05d0\u05dd \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e2\u05d5\u05d3 \u05de\u05e9\u05d7\u05d9\u05d6\u05d9\u05dd, \u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d2\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d5\u05d2\u05dd \u05d0\u05d7\u05e8\u05d9\u05d4, \u05db\u05d9 \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05de\u05d5\u05e8\u05d9\u05d3\u05d4 \u05d7\u05dc\u05e7 \u05de\u05d4\u05e9\u05db\u05d1\u05d4."], [86.2, "\u05dc\u05e4\u05d9 \u05d4\u05ea\u05e7\u05df, \u05dc\u05db\u05dc \u05e2\u05e8\u05da \u05e7\u05e9\u05d9\u05d5\u05ea \u05d7\u05d9\u05d9\u05d1\u05ea \u05dc\u05d4\u05d9\u05d5\u05ea \u05e1\u05d1\u05d5\u05dc\u05ea. \u05db\u05d5\u05ea\u05d1\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc, 60 \u05e4\u05dc\u05d5\u05e1 4 HRC, \u05db\u05dc\u05d5\u05de\u05e8 \u05d1\u05d9\u05df 60 \u05dc-64."], [97.9, "\u05d0\u05ea \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea \u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05e8\u05d7\u05d1\u05d4 \u05db\u05db\u05dc \u05e9\u05d4\u05ea\u05e4\u05e7\u05d5\u05d3 \u05e9\u05dc \u05d4\u05d7\u05dc\u05e7 \u05de\u05d0\u05e4\u05e9\u05e8. \u05e1\u05d1\u05d5\u05dc\u05ea \u05e6\u05e8\u05d4 \u05de\u05d3\u05d9 \u05de\u05e7\u05e9\u05d4 \u05e2\u05dc \u05d4\u05e1\u05e4\u05e7, \u05d5\u05de\u05d9\u05d9\u05e7\u05e8\u05ea."], [106.6, "\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05e7\u05e9\u05d9\u05d5\u05ea \u05d2\u05dd \u05d1\u05e9\u05d9\u05d8\u05ea \u05d5\u05d9\u05e7\u05e8\u05e1 \u05d0\u05d5 \u05d1\u05e8\u05d9\u05e0\u05dc, \u05d5\u05d0\u05d6 \u05de\u05e6\u05d9\u05d9\u05e0\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05db\u05d5\u05d7 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d4."], [113.2, "\u05dc\u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d9\u05e9 \u05e7\u05d9\u05e6\u05d5\u05e8 \u05dc\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da: \u05dc\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 CHD, \u05dc\u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d0\u05d5 \u05d1\u05dc\u05d4\u05d1\u05d4 SHD, \u05d5\u05dc\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 NHD."], [125.6, "\u05d2\u05dd \u05d4\u05e2\u05d5\u05de\u05e7 \u05de\u05e7\u05d1\u05dc \u05e1\u05d1\u05d5\u05dc\u05ea: \u05dc\u05de\u05e9\u05dc, CHD 0.8 \u05e4\u05dc\u05d5\u05e1 0.4, \u05db\u05dc\u05d5\u05de\u05e8 \u05d1\u05d9\u05df 0.8 \u05dc-1.2 \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8."], [137.4, "\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05e2\u05d5\u05d1\u05d9 \u05d4\u05e9\u05db\u05d1\u05d4 \u05d4\u05dc\u05d1\u05e0\u05d4, \u05d1\u05de\u05d9\u05e7\u05e8\u05d5\u05e0\u05d9\u05dd, \u05dc\u05de\u05e9\u05dc 10 \u05e2\u05d3 20."], [144.9, "\u05d5\u05d0\u05ea \u05e0\u05e7\u05d5\u05d3\u05ea \u05d4\u05de\u05d3\u05d9\u05d3\u05d4 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e1\u05de\u05dc \u05de\u05d9\u05d5\u05d7\u05d3, \u05e2\u05dd \u05de\u05e1\u05e4\u05e8, \u05db\u05d3\u05d9 \u05e9\u05db\u05dc \u05de\u05d9 \u05e9\u05d1\u05d5\u05d3\u05e7 \u05d9\u05de\u05d3\u05d5\u05d3 \u05d1\u05d0\u05d5\u05ea\u05d5 \u05de\u05e7\u05d5\u05dd."], [153.0, "\u05d4\u05e8\u05d1\u05d4 \u05e4\u05e2\u05de\u05d9\u05dd \u05e8\u05e7 \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05e9\u05d8\u05d7\u05d9\u05dd \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d4: \u05de\u05e1\u05dc\u05d5\u05dc \u05e9\u05dc \u05de\u05e1\u05d1, \u05e9\u05d9\u05e0\u05d9 \u05d2\u05dc\u05d2\u05dc, \u05d0\u05d5 \u05d0\u05d6\u05d5\u05e8 \u05d0\u05d8\u05d9\u05de\u05d4."], [160.7, "\u05d0\u05ea \u05d4\u05d0\u05d6\u05d5\u05e8 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05e7\u05d5 \u05e0\u05e7\u05d5\u05d3\u05d4 \u05e2\u05d1\u05d4, \u05d5\u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05dc\u05d5 \u05de\u05d9\u05d3\u05d5\u05ea."], [165.0, "\u05e7\u05d5 \u05de\u05e7\u05d5\u05d5\u05e7\u05d5 \u05e2\u05d1\u05d4 \u05d0\u05d5\u05de\u05e8: \u05de\u05d5\u05ea\u05e8 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05db\u05d0\u05df, \u05d0\u05d1\u05dc \u05dc\u05d0 \u05d7\u05d5\u05d1\u05d4. \u05d5\u05e7\u05d5 \u05de\u05e0\u05d5\u05e7\u05d3 \u05e2\u05d1\u05d4 \u05d0\u05d5\u05de\u05e8: \u05d0\u05e1\u05d5\u05e8."], [173.2, "\u05d6\u05d4 \u05d7\u05e9\u05d5\u05d1 \u05de\u05d0\u05d5\u05d3 \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05d5\u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4. \u05d4\u05d1\u05e8\u05d2\u05d5\u05ea, \u05dc\u05de\u05e9\u05dc, \u05e6\u05e8\u05d9\u05db\u05d5\u05ea \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d5\u05ea."], [180.4, "\u05d5\u05d0\u05d6 \u05de\u05db\u05e1\u05d9\u05dd \u05d0\u05d5\u05ea\u05df \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d0\u05d5 \u05d1\u05de\u05e9\u05d7\u05d4 \u05de\u05d9\u05d5\u05d7\u05d3\u05ea, \u05db\u05d3\u05d9 \u05e9\u05d4\u05e4\u05d7\u05de\u05df \u05d0\u05d5 \u05d4\u05d7\u05e0\u05e7\u05df \u05dc\u05d0 \u05d9\u05d9\u05db\u05e0\u05e1\u05d5."], [188.0, "\u05d1\u05dc\u05d9 \u05d4\u05e1\u05d9\u05de\u05d5\u05df \u05d4\u05d6\u05d4, \u05d4\u05e1\u05e4\u05e7 \u05d9\u05e7\u05e9\u05d4 \u05d0\u05ea \u05db\u05dc \u05d4\u05d7\u05dc\u05e7, \u05d0\u05d5 \u05d9\u05e0\u05d7\u05e9."], [193.7, "\u05d1\u05ea\u05e2\u05e9\u05d9\u05d9\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d4\u05d1\u05d9\u05d8\u05d7\u05d5\u05df, \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8 \u05de\u05e4\u05e0\u05d4 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc \u05dc\u05de\u05e4\u05e8\u05d8, \u05d5\u05dc\u05d0 \u05de\u05e4\u05e8\u05d8 \u05d0\u05ea \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05e2\u05e6\u05de\u05d5."], [201.8, "\u05dc\u05e4\u05dc\u05d3\u05d5\u05ea, \u05d4\u05de\u05e4\u05e8\u05d8 \u05d4\u05d1\u05e1\u05d9\u05e1\u05d9 \u05d4\u05d5\u05d0 AMS 2759. \u05d4\u05d5\u05d0 \u05e7\u05d5\u05d1\u05e2 \u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05d5\u05d9\u05e9 \u05dc\u05d5 \u05de\u05e4\u05e8\u05d8\u05d9 \u05de\u05e9\u05e0\u05d4 \u05dc\u05db\u05dc \u05de\u05e9\u05e4\u05d7\u05d4 \u05d5\u05dc\u05db\u05dc \u05ea\u05d4\u05dc\u05d9\u05da."], [213.5, "\u05dc\u05de\u05e9\u05dc, \u05dc\u05e4\u05dc\u05d3\u05d5\u05ea \u05e4\u05d7\u05de\u05df \u05d5\u05e1\u05d2\u05e1\u05d5\u05d2\u05ea \u05e0\u05de\u05d5\u05db\u05d4 AMS 2759/1, \u05dc\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 AMS 2759/7, \u05d5\u05dc\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 AMS 2759/6."], [226.4, "\u05dc\u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd \u05d9\u05e9 \u05de\u05e4\u05e8\u05d8 \u05e0\u05e4\u05e8\u05d3, AMS 2770, \u05d5\u05dc\u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd AMS 2801. \u05d5\u05e2\u05dc \u05d4\u05ea\u05e0\u05d5\u05e8 \u05e2\u05e6\u05de\u05d5 \u05d7\u05dc AMS 2750, \u05e9\u05d4\u05db\u05e8\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 \u05d4\u05e7\u05d5\u05d3\u05dd."], [241.3, "\u05d4\u05de\u05e4\u05e8\u05d8 \u05e7\u05d5\u05d1\u05e2 \u05d0\u05ea \u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d5\u05ea, \u05d0\u05ea \u05d4\u05d6\u05de\u05e0\u05d9\u05dd, \u05d0\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05d0\u05ea \u05d4\u05ea\u05d9\u05e2\u05d5\u05d3. \u05d5\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05de\u05d5\u05e1\u05d9\u05e4\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5 \u05de\u05e4\u05e8\u05d8\u05d9\u05dd \u05de\u05e9\u05dc\u05d4\u05dd, \u05e9\u05d2\u05d5\u05d1\u05e8\u05d9\u05dd \u05e2\u05dc\u05d9\u05d5."], [251.3, "\u05d7\u05e9\u05d5\u05d1 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d2\u05dd \u05d0\u05ea \u05d4\u05de\u05d4\u05d3\u05d5\u05e8\u05d4. \u05d4\u05d0\u05d5\u05ea \u05e9\u05d1\u05e1\u05d5\u05e3 \u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e4\u05e8\u05d8 \u05de\u05e1\u05de\u05e0\u05ea \u05de\u05d4\u05d3\u05d5\u05e8\u05d4, \u05d5\u05d4\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea \u05de\u05e9\u05ea\u05e0\u05d5\u05ea \u05d1\u05d9\u05df \u05de\u05d4\u05d3\u05d5\u05e8\u05d5\u05ea."], [260.4, "\u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da \u05d4\u05e1\u05e4\u05e7 \u05e9\u05d5\u05dc\u05d7 \u05ea\u05e2\u05d5\u05d3\u05d4. \u05d4\u05d9\u05d0 \u05d4\u05e7\u05e9\u05e8 \u05d4\u05d9\u05d7\u05d9\u05d3 \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7 \u05e9\u05e7\u05d9\u05d1\u05dc\u05ea\u05dd \u05dc\u05d1\u05d9\u05df \u05de\u05d4 \u05e9\u05e7\u05e8\u05d4 \u05d1\u05ea\u05e0\u05d5\u05e8."], [268.3, "\u05ea\u05e2\u05d5\u05d3\u05d4 \u05d8\u05d5\u05d1\u05d4 \u05db\u05d5\u05dc\u05dc\u05ea \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05d7\u05dc\u05e7 \u05d5\u05d0\u05ea \u05d4\u05db\u05de\u05d5\u05ea, \u05d0\u05ea \u05de\u05e1\u05e4\u05e8 \u05d4\u05de\u05e0\u05d4, \u05d0\u05ea \u05d4\u05de\u05e4\u05e8\u05d8 \u05d5\u05d4\u05de\u05d4\u05d3\u05d5\u05e8\u05d4, \u05d0\u05ea \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d5\u05d7\u05ea\u05d9\u05de\u05d4."], [278.3, "\u05dc\u05d7\u05d5\u05de\u05e8 \u05d4\u05d2\u05dc\u05dd \u05d9\u05e9 \u05ea\u05e7\u05df \u05d0\u05d9\u05e8\u05d5\u05e4\u05d9 \u05dc\u05e1\u05d5\u05d2\u05d9 \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea, EN 10204. \u05d1\u05ea\u05e2\u05d5\u05d3\u05d4 2.2 \u05d4\u05d9\u05e6\u05e8\u05df \u05de\u05e6\u05e8\u05e3 \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05db\u05dc\u05dc\u05d9\u05d5\u05ea, \u05e9\u05dc\u05d0 \u05e0\u05d1\u05d3\u05e7\u05d5 \u05d3\u05d5\u05d5\u05e7\u05d0 \u05e2\u05dc \u05d4\u05de\u05e9\u05dc\u05d5\u05d7 \u05e9\u05dc\u05db\u05dd."], [291.6, "\u05d1\u05ea\u05e2\u05d5\u05d3\u05d4 3.1 \u05d4\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05e0\u05de\u05d3\u05d3\u05d5 \u05e2\u05dc \u05d4\u05de\u05e0\u05d4 \u05e9\u05e1\u05d5\u05e4\u05e7\u05d4, \u05d5\u05e0\u05e6\u05d9\u05d2 \u05d1\u05e7\u05e8\u05d4 \u05e9\u05dc \u05d4\u05d9\u05e6\u05e8\u05df, \u05e9\u05d0\u05d9\u05e0\u05d5 \u05ea\u05dc\u05d5\u05d9 \u05d1\u05d9\u05d9\u05e6\u05d5\u05e8, \u05d7\u05d5\u05ea\u05dd \u05e2\u05dc\u05d9\u05d4\u05df."], [300.8, "\u05d5\u05d1\u05ea\u05e2\u05d5\u05d3\u05d4 3.2 \u05d7\u05d5\u05ea\u05dd \u05d2\u05dd \u05d1\u05d5\u05d3\u05e7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05d0\u05d5 \u05e0\u05e6\u05d9\u05d2 \u05e9\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7. \u05d4\u05d9\u05d0 \u05d4\u05d0\u05de\u05d9\u05e0\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8, \u05d5\u05d2\u05dd \u05d4\u05d9\u05e7\u05e8\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8."], [310.4, "\u05d1\u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05e7\u05d1\u05dc\u05d4 \u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05e2\u05d5\u05d3\u05d4 \u05dc\u05e9\u05e8\u05d8\u05d5\u05d8: \u05d0\u05d5\u05ea\u05d5 \u05de\u05e4\u05e8\u05d8, \u05d0\u05d5\u05ea\u05d4 \u05de\u05d4\u05d3\u05d5\u05e8\u05d4, \u05d5\u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d1\u05ea\u05d5\u05da \u05d4\u05e1\u05d1\u05d5\u05dc\u05ea."], [318.8, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05ea\u05d4\u05dc\u05d9\u05da \u05de\u05d9\u05d5\u05d7\u05d3: \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d1\u05d3\u05d5\u05e7 \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d1\u05de\u05dc\u05d5\u05d0\u05d4 \u05e2\u05dc \u05d4\u05d7\u05dc\u05e7 \u05d4\u05de\u05d5\u05d2\u05de\u05e8 \u05d1\u05dc\u05d9 \u05dc\u05d4\u05e8\u05d5\u05e1 \u05d0\u05d5\u05ea\u05d5."], [326.3, "\u05dc\u05db\u05df \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05dc\u05d0 \u05de\u05e1\u05ea\u05e4\u05e7\u05d9\u05dd \u05d1\u05d1\u05d3\u05d9\u05e7\u05d4 \u05d1\u05e1\u05d5\u05e3. \u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e1\u05e4\u05e7 \u05e2\u05e6\u05de\u05d5: \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8\u05d9\u05dd, \u05d0\u05ea \u05d4\u05e0\u05d4\u05dc\u05d9\u05dd, \u05d0\u05ea \u05d4\u05d4\u05d3\u05e8\u05db\u05d4 \u05d5\u05d0\u05ea \u05d4\u05e8\u05d9\u05e9\u05d5\u05de\u05d9\u05dd."], [336.0, "Nadcap \u05d4\u05d9\u05d0 \u05ea\u05d5\u05db\u05e0\u05d9\u05ea \u05d4\u05e1\u05de\u05db\u05d4 \u05de\u05e9\u05d5\u05ea\u05e4\u05ea \u05dc\u05d7\u05d1\u05e8\u05d5\u05ea \u05d4\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d4\u05d1\u05d9\u05d8\u05d7\u05d5\u05df \u05d4\u05d2\u05d3\u05d5\u05dc\u05d5\u05ea. \u05de\u05e0\u05d4\u05dc \u05d0\u05d5\u05ea\u05d4 \u05d0\u05e8\u05d2\u05d5\u05df \u05d1\u05e9\u05dd PRI."], [344.6, "\u05de\u05d1\u05e7\u05e8 \u05de\u05d5\u05de\u05d7\u05d4 \u05de\u05d2\u05d9\u05e2 \u05dc\u05e1\u05e4\u05e7 \u05dc\u05db\u05de\u05d4 \u05d9\u05de\u05d9\u05dd, \u05d5\u05e2\u05d5\u05d1\u05e8 \u05e2\u05dc \u05e8\u05e9\u05d9\u05de\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05de\u05e4\u05d5\u05e8\u05d8\u05d5\u05ea \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05d5\u05dc\u05de\u05d3\u05d9\u05d3\u05ea \u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [352.3, "\u05db\u05dc \u05d0\u05d9 \u05d4\u05ea\u05d0\u05de\u05d4 \u05d3\u05d5\u05e8\u05e9\u05ea \u05ea\u05d9\u05e7\u05d5\u05df \u05d5\u05e0\u05d9\u05ea\u05d5\u05d7 \u05e9\u05dc \u05e9\u05d5\u05e8\u05e9 \u05d4\u05d1\u05e2\u05d9\u05d4, \u05d5\u05e8\u05e7 \u05d0\u05d6 \u05e0\u05d9\u05ea\u05e0\u05ea \u05d4\u05d4\u05e1\u05de\u05db\u05d4. \u05d5\u05d4\u05d9\u05d0 \u05de\u05ea\u05d7\u05d3\u05e9\u05ea \u05d1\u05d1\u05d9\u05e7\u05d5\u05e8\u05d5\u05ea \u05d7\u05d5\u05d6\u05e8\u05d5\u05ea."], [361.4, "\u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e8\u05d1\u05d9\u05dd \u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05d5\u05d1\u05d1\u05d9\u05d8\u05d7\u05d5\u05df \u05de\u05d7\u05d9\u05d9\u05d1\u05d9\u05dd \u05e1\u05e4\u05e7 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e2\u05dd \u05d4\u05e1\u05de\u05db\u05ea Nadcap. \u05d1\u05dc\u05d9 \u05d6\u05d4, \u05d4\u05e1\u05e4\u05e7 \u05e4\u05e9\u05d5\u05d8 \u05dc\u05d0 \u05d1\u05e8\u05e9\u05d9\u05de\u05d4."], [370.7, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05d4\u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05d4\u05e0\u05e4\u05d5\u05e6\u05d5\u05ea \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."], [374.0, "\u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05dc\u05d9 \u05e1\u05d1\u05d5\u05dc\u05ea, \u05d0\u05d5 \u05e1\u05d1\u05d5\u05dc\u05ea \u05e9\u05dc \u05e9\u05ea\u05d9 \u05d9\u05d7\u05d9\u05d3\u05d5\u05ea \u05e8\u05d5\u05e7\u05d5\u05d5\u05dc \u05d1\u05dc\u05d1\u05d3, \u05e9\u05e7\u05e9\u05d4 \u05de\u05d0\u05d5\u05d3 \u05dc\u05e2\u05de\u05d5\u05d3 \u05d1\u05d4 \u05d1\u05d0\u05d5\u05e4\u05df \u05e7\u05d1\u05d5\u05e2."], [381.2, "\u05e2\u05d5\u05de\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d1\u05dc\u05d9 \u05dc\u05e6\u05d9\u05d9\u05df \u05d0\u05dd \u05d4\u05d5\u05d0 \u05dc\u05e4\u05e0\u05d9 \u05d4\u05d4\u05e9\u05d7\u05d6\u05d4 \u05d0\u05d5 \u05d0\u05d7\u05e8\u05d9\u05d4."], [385.7, "\u05d3\u05e8\u05d9\u05e9\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05dc \u05de\u05e9\u05d8\u05d7 \u05e9\u05d4\u05de\u05db\u05d5\u05e0\u05d4 \u05dc\u05d0 \u05d9\u05db\u05d5\u05dc\u05d4 \u05dc\u05d4\u05d2\u05d9\u05e2 \u05d0\u05dc\u05d9\u05d5, \u05d0\u05d5 \u05e2\u05dc \u05d3\u05d5\u05e4\u05df \u05d3\u05e7\u05d4 \u05de\u05d3\u05d9 \u05dc\u05de\u05d3\u05d9\u05d3\u05d4."], [392.1, "\u05d5\u05d4\u05e4\u05e0\u05d9\u05d4 \u05dc\u05de\u05e4\u05e8\u05d8 \u05d1\u05dc\u05d9 \u05de\u05d4\u05d3\u05d5\u05e8\u05d4, \u05d0\u05d5 \u05dc\u05de\u05e4\u05e8\u05d8 \u05e9\u05dc\u05d0 \u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05d7\u05d5\u05de\u05e8."], [398.4, "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8? \u05e1\u05d1\u05d5\u05dc\u05d5\u05ea \u05d4\u05d3\u05d5\u05e7\u05d5\u05ea \u05e9\u05dc \u05e7\u05e9\u05d9\u05d5\u05ea \u05d5\u05e9\u05dc \u05e2\u05d5\u05de\u05e7 \u05de\u05d7\u05d9\u05d9\u05d1\u05d5\u05ea \u05d1\u05e7\u05e8\u05d4 \u05e6\u05de\u05d5\u05d3\u05d4, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d2\u05d5\u05e8\u05de\u05d5\u05ea \u05dc\u05e4\u05e1\u05d9\u05dc\u05d5\u05ea."], [406.6, "\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e0\u05d5\u05e1\u05e4\u05d5\u05ea, \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05e2\u05d3 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05de\u05d5\u05e1\u05d9\u05e4\u05d5\u05ea \u05d6\u05de\u05df \u05d5\u05e2\u05d1\u05d5\u05d3\u05d4."], [412.4, "\u05ea\u05e2\u05d5\u05d3\u05d4 3.2 \u05d3\u05d5\u05e8\u05e9\u05ea \u05d1\u05d5\u05d3\u05e7 \u05d7\u05d9\u05e6\u05d5\u05e0\u05d9, \u05d5\u05e1\u05e4\u05e7 \u05e2\u05dd \u05d4\u05e1\u05de\u05db\u05ea Nadcap \u05d2\u05d5\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d4\u05d5\u05d0 \u05e0\u05d5\u05e9\u05d0 \u05d1\u05e2\u05dc\u05d5\u05d9\u05d5\u05ea \u05e9\u05dc \u05db\u05dc \u05d4\u05de\u05e2\u05e8\u05db\u05ea."], [421.6, "\u05d5\u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05e9\u05e8\u05d8\u05d5\u05d8 \u05d1\u05e8\u05d5\u05e8 \u05d7\u05d5\u05e1\u05da \u05e9\u05d0\u05dc\u05d5\u05ea, \u05d8\u05e2\u05d5\u05d9\u05d5\u05ea \u05d5\u05e4\u05e1\u05d9\u05dc\u05d5\u05ea. \u05d6\u05d5 \u05d4\u05d4\u05e9\u05e7\u05e2\u05d4 \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05d1\u05e4\u05e8\u05d5\u05d9\u05e7\u05d8."], [429.9, "\u05dc\u05e1\u05d9\u05db\u05d5\u05dd: \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8 \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05ea\u05d5\u05e6\u05d0\u05d4 \u05d4\u05e1\u05d5\u05e4\u05d9\u05ea, \u05dc\u05e4\u05d9 ISO 15787: \u05de\u05e6\u05d1 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc, \u05e7\u05e9\u05d9\u05d5\u05ea \u05e2\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea, \u05e2\u05d5\u05de\u05e7 \u05e9\u05db\u05d1\u05d4 \u05d5\u05e0\u05e7\u05d5\u05d3\u05d5\u05ea \u05de\u05d3\u05d9\u05d3\u05d4."], [442.9, "\u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05e7\u05d5\u05de\u05d9 \u05de\u05e1\u05de\u05e0\u05d9\u05dd \u05d1\u05e7\u05d5\u05d5\u05d9\u05dd, \u05d5\u05d1\u05ea\u05e2\u05d5\u05e4\u05d4 \u05de\u05e4\u05e0\u05d9\u05dd \u05dc\u05de\u05e4\u05e8\u05d8\u05d9 AMS \u05e2\u05dd \u05de\u05d4\u05d3\u05d5\u05e8\u05d4."], [449.3, "\u05d4\u05ea\u05e2\u05d5\u05d3\u05d4 \u05de\u05d7\u05d1\u05e8\u05ea \u05d1\u05d9\u05df \u05d4\u05d7\u05dc\u05e7 \u05dc\u05ea\u05d4\u05dc\u05d9\u05da, \u05d5\u05d4\u05e1\u05de\u05db\u05ea Nadcap \u05de\u05d1\u05d8\u05d9\u05d7\u05d4 \u05e9\u05d4\u05e1\u05e4\u05e7 \u05e2\u05e6\u05de\u05d5 \u05e2\u05d5\u05de\u05d3 \u05d1\u05d3\u05e8\u05d9\u05e9\u05d5\u05ea."], [457.4, "\u05d1\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05e0\u05e1\u05db\u05dd \u05d0\u05ea \u05d4\u05e7\u05d5\u05e8\u05e1 \u05db\u05d5\u05dc\u05d5, \u05d5\u05e0\u05e8\u05d0\u05d4 \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05d5\u05d0\u05d9\u05da \u05d7\u05d5\u05e1\u05db\u05d9\u05dd."]]};
window.MH_TR["ch24"]={"t": "\u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd", "l": [[5.0, "\u05d4\u05d2\u05e2\u05e0\u05d5 \u05dc\u05e4\u05e8\u05e7 \u05d4\u05d0\u05d7\u05e8\u05d5\u05df \u05d1\u05e7\u05d5\u05e8\u05e1. \u05d5\u05e0\u05e1\u05d9\u05d9\u05dd \u05d1\u05e9\u05d0\u05dc\u05d4 \u05e9\u05db\u05dc \u05de\u05d9 \u05e9\u05de\u05d6\u05de\u05d9\u05df \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05e9\u05d5\u05d0\u05dc: \u05dc\u05de\u05d4 \u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4 \u05db\u05de\u05d5 \u05e9\u05d6\u05d4 \u05e2\u05d5\u05dc\u05d4?"], [13.1, "\u05d4\u05de\u05d7\u05d9\u05e8 \u05e9\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05dc\u05d0 \u05e0\u05e7\u05d1\u05e2 \u05e8\u05e7 \u05dc\u05e4\u05d9 \u05d4\u05de\u05e9\u05e7\u05dc. \u05d4\u05d5\u05d0 \u05e0\u05e7\u05d1\u05e2 \u05dc\u05e4\u05d9 \u05d6\u05de\u05df \u05d1\u05ea\u05e0\u05d5\u05e8, \u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3\u05d9\u05d9\u05dd, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05ea\u05d9\u05e2\u05d5\u05d3."], [21.6, "\u05e0\u05e8\u05d0\u05d4 \u05d0\u05d9\u05da \u05e1\u05e4\u05e7\u05d9\u05dd \u05de\u05ea\u05de\u05d7\u05e8\u05d9\u05dd, \u05de\u05d4 \u05de\u05d9\u05d9\u05e7\u05e8, \u05d0\u05d9\u05da \u05d7\u05d5\u05e1\u05db\u05d9\u05dd \u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05d5\u05d1\u05e8\u05db\u05e9, \u05d5\u05d1\u05e1\u05d5\u05e3 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05d9\u05d7\u05d3 \u05e2\u05dc \u05db\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1."], [30.3, "\u05e1\u05e4\u05e7\u05d9\u05dd \u05de\u05ea\u05de\u05d7\u05e8\u05d9\u05dd \u05d1\u05e9\u05dc\u05d5\u05e9 \u05d3\u05e8\u05db\u05d9\u05dd: \u05dc\u05e4\u05d9 \u05e7\u05d9\u05dc\u05d5, \u05dc\u05e4\u05d9 \u05d7\u05dc\u05e7, \u05d0\u05d5 \u05dc\u05e4\u05d9 \u05de\u05d7\u05d6\u05d5\u05e8 \u05ea\u05e0\u05d5\u05e8 \u05e9\u05dc\u05dd, \u05db\u05e9\u05d4\u05ea\u05e0\u05d5\u05e8 \u05e2\u05d5\u05d1\u05d3 \u05e8\u05e7 \u05d1\u05e9\u05d1\u05d9\u05dc\u05db\u05dd."], [39.2, "\u05db\u05de\u05e2\u05d8 \u05ea\u05de\u05d9\u05d3 \u05d9\u05e9 \u05d2\u05dd \u05de\u05d7\u05d9\u05e8 \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd \u05dc\u05d4\u05d6\u05de\u05e0\u05d4. \u05dc\u05db\u05df \u05d7\u05dc\u05e7 \u05d0\u05d7\u05d3 \u05e7\u05d8\u05df \u05d9\u05db\u05d5\u05dc \u05dc\u05e2\u05dc\u05d5\u05ea \u05db\u05de\u05d5 \u05e2\u05e9\u05e8\u05d4."], [45.8, "\u05d4\u05ea\u05e0\u05d5\u05e8 \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3 \u05dc\u05db\u05dc \u05e9\u05e2\u05d4 \u05e9\u05d4\u05d5\u05d0 \u05e4\u05d5\u05e2\u05dc, \u05de\u05dc\u05d0 \u05d0\u05d5 \u05e8\u05d9\u05e7. \u05dc\u05db\u05df \u05d4\u05e1\u05e4\u05e7 \u05de\u05e2\u05d3\u05d9\u05e3 \u05dc\u05de\u05dc\u05d0 \u05d0\u05d5\u05ea\u05d5, \u05d5\u05de\u05e9\u05dc\u05d1 \u05d7\u05dc\u05e7\u05d9\u05dd \u05e9\u05dc \u05db\u05de\u05d4 \u05dc\u05e7\u05d5\u05d7\u05d5\u05ea \u05e9\u05e2\u05d5\u05d1\u05e8\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05ea\u05d4\u05dc\u05d9\u05da."], [56.7, "\u05d7\u05dc\u05e7 \u05e9\u05d3\u05d5\u05e8\u05e9 \u05de\u05d7\u05d6\u05d5\u05e8 \u05de\u05d9\u05d5\u05d7\u05d3, \u05d1\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d0\u05d5 \u05d1\u05d0\u05d5\u05d5\u05d9\u05e8\u05d4 \u05e9\u05d0\u05e3 \u05d0\u05d7\u05d3 \u05d0\u05d7\u05e8 \u05dc\u05d0 \u05e6\u05e8\u05d9\u05da, \u05de\u05e9\u05dc\u05dd \u05e2\u05dc \u05db\u05dc \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05dc\u05d1\u05d3."], [65.0, "\u05dc\u05d3\u05d5\u05d2\u05de\u05d4, \u05d7\u05dc\u05e7 \u05e9\u05dc \u05e2\u05e9\u05e8\u05d4 \u05e7\u05d9\u05dc\u05d5 \u05e9\u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05e0\u05d4 \u05de\u05e9\u05d5\u05ea\u05e4\u05ea \u05e2\u05dd \u05d7\u05dc\u05e7\u05d9\u05dd \u05d0\u05d7\u05e8\u05d9\u05dd \u05d6\u05d5\u05dc \u05d1\u05d4\u05e8\u05d1\u05d4 \u05de\u05d0\u05d5\u05ea\u05d5 \u05d7\u05dc\u05e7 \u05d1\u05de\u05d7\u05d6\u05d5\u05e8 \u05de\u05e9\u05dc\u05d5."], [73.2, "\u05d5\u05e9\u05d9\u05de\u05d5 \u05dc\u05d1: \u05d7\u05dc\u05e7\u05d9\u05dd \u05d2\u05d3\u05d5\u05dc\u05d9\u05dd \u05d5\u05de\u05e1\u05d5\u05d1\u05db\u05d9\u05dd \u05ea\u05d5\u05e4\u05e1\u05d9\u05dd \u05de\u05e7\u05d5\u05dd \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d2\u05dd \u05db\u05e9\u05d4\u05de\u05e9\u05e7\u05dc \u05e9\u05dc\u05d4\u05dd \u05e7\u05d8\u05df."], [80.4, "\u05d4\u05d2\u05d5\u05e8\u05dd \u05d4\u05e8\u05d0\u05e9\u05d5\u05df \u05d4\u05d5\u05d0 \u05d4\u05d6\u05de\u05df \u05d1\u05ea\u05e0\u05d5\u05e8. \u05e0\u05e8\u05de\u05d5\u05dc \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4 \u05e4\u05e9\u05d5\u05d8\u05d4 \u05d4\u05dd \u05de\u05d7\u05d6\u05d5\u05e8\u05d9\u05dd \u05e7\u05e6\u05e8\u05d9\u05dd \u05d9\u05d7\u05e1\u05d9\u05ea. \u05e8\u05d9\u05db\u05d5\u05da \u05de\u05dc\u05d0 \u05d0\u05e8\u05d5\u05da \u05d9\u05d5\u05ea\u05e8, \u05db\u05d9 \u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05d1\u05ea\u05d5\u05da \u05d4\u05ea\u05e0\u05d5\u05e8 \u05d0\u05d9\u05d8\u05d9."], [91.6, "\u05ea\u05e0\u05d5\u05e8 \u05d5\u05d0\u05e7\u05d5\u05dd \u05d4\u05d5\u05d0 \u05e6\u05d9\u05d5\u05d3 \u05d9\u05e7\u05e8, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05d4\u05de\u05d7\u05d6\u05d5\u05e8 \u05d1\u05d5 \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8 \u05d1\u05d3\u05e8\u05da \u05db\u05dc\u05dc. \u05de\u05e6\u05d3 \u05e9\u05e0\u05d9, \u05d4\u05d5\u05d0 \u05d7\u05d5\u05e1\u05da \u05e0\u05d9\u05e7\u05d5\u05d9 \u05d5\u05e0\u05d5\u05ea\u05df \u05de\u05e9\u05d8\u05d7 \u05e0\u05e7\u05d9."], [101.5, "\u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05d4\u05e2\u05d5\u05de\u05e7 \u05d2\u05d3\u05dc \u05dc\u05e4\u05d9 \u05d4\u05e9\u05d5\u05e8\u05e9 \u05e9\u05dc \u05d4\u05d6\u05de\u05df. \u05db\u05dc\u05d5\u05de\u05e8, \u05db\u05d3\u05d9 \u05dc\u05d4\u05db\u05e4\u05d9\u05dc \u05d0\u05ea \u05e2\u05d5\u05de\u05e7 \u05d4\u05e9\u05db\u05d1\u05d4 \u05e6\u05e8\u05d9\u05da \u05d1\u05e2\u05e8\u05da \u05e4\u05d9 \u05d0\u05e8\u05d1\u05e2\u05d4 \u05d6\u05de\u05df."], [110.8, "\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05d2\u05d1\u05d5\u05d4\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05e6\u05d5\u05e8\u05db\u05ea \u05d9\u05d5\u05ea\u05e8 \u05d0\u05e0\u05e8\u05d2\u05d9\u05d4 \u05d5\u05e9\u05d5\u05d7\u05e7\u05ea \u05d0\u05ea \u05d4\u05ea\u05e0\u05d5\u05e8. \u05dc\u05db\u05df \u05d4\u05e7\u05e9\u05d9\u05d4 \u05e9\u05dc \u05e4\u05dc\u05d3\u05d4 \u05de\u05d4\u05d9\u05e8\u05d4, \u05e1\u05d1\u05d9\u05d1 1,200 \u05de\u05e2\u05dc\u05d5\u05ea, \u05d9\u05e7\u05e8\u05d4 \u05d9\u05d5\u05ea\u05e8."], [121.6, "\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4 \u05d1\u05d2\u05d6 \u05e0\u05de\u05e9\u05db\u05ea \u05e2\u05e9\u05e8\u05d5\u05ea \u05e9\u05e2\u05d5\u05ea, \u05d5\u05dc\u05db\u05df \u05d2\u05dd \u05d4\u05d9\u05d0 \u05d9\u05e7\u05e8\u05d4, \u05dc\u05de\u05e8\u05d5\u05ea \u05e9\u05d4\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4 \u05e0\u05de\u05d5\u05db\u05d4."], [128.3, "\u05db\u05dc \u05e9\u05dc\u05d1 \u05e0\u05d5\u05e1\u05e3 \u05d4\u05d5\u05d0 \u05de\u05d7\u05d6\u05d5\u05e8 \u05e0\u05d5\u05e1\u05e3: \u05d4\u05e8\u05e4\u05d9\u05d4 \u05db\u05e4\u05d5\u05dc\u05d4 \u05d0\u05d5 \u05de\u05e9\u05d5\u05dc\u05e9\u05ea, \u05e7\u05d9\u05e8\u05d5\u05e8 \u05e2\u05de\u05d5\u05e7, \u05d0\u05d5 \u05e9\u05d7\u05e8\u05d5\u05e8 \u05de\u05d0\u05de\u05e6\u05d9\u05dd \u05dc\u05e4\u05e0\u05d9 \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d4\u05e1\u05d5\u05e4\u05d9."], [137.8, "\u05d5\u05d7\u05dc\u05e7 \u05e2\u05d1\u05d4 \u05e6\u05e8\u05d9\u05da \u05d9\u05d5\u05ea\u05e8 \u05d6\u05de\u05df, \u05e2\u05d3 \u05e9\u05d2\u05dd \u05d4\u05dc\u05d9\u05d1\u05d4 \u05de\u05d2\u05d9\u05e2\u05d4 \u05dc\u05d8\u05de\u05e4\u05e8\u05d8\u05d5\u05e8\u05d4."], [143.3, "\u05d7\u05dc\u05e7 \u05d2\u05d3\u05d5\u05dc \u05de\u05d4\u05e2\u05dc\u05d5\u05ea \u05d1\u05db\u05dc\u05dc \u05dc\u05d0 \u05d1\u05ea\u05e0\u05d5\u05e8, \u05d0\u05dc\u05d0 \u05d1\u05e2\u05d1\u05d5\u05d3\u05d4 \u05e9\u05de\u05e1\u05d1\u05d9\u05d1."], [147.8, "\u05dc\u05e4\u05e0\u05d9 \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc \u05e9\u05d5\u05d8\u05e4\u05d9\u05dd \u05e9\u05de\u05df \u05d5\u05dc\u05db\u05dc\u05d5\u05da. \u05d5\u05d0\u05d7\u05e8\u05d9\u05d5 \u05de\u05e0\u05e7\u05d9\u05dd \u05d0\u05ea \u05d4\u05e7\u05e9\u05e7\u05e9\u05ea, \u05d1\u05d4\u05ea\u05d6\u05d4 \u05d0\u05d5 \u05d1\u05db\u05d9\u05de\u05d9\u05e7\u05dc\u05d9\u05dd."], [155.7, "\u05d0\u05ea \u05d4\u05d7\u05dc\u05e7\u05d9\u05dd \u05de\u05e2\u05de\u05d9\u05e1\u05d9\u05dd \u05e2\u05dc \u05de\u05ea\u05e7\u05e0\u05d9\u05dd, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05ea\u05d5\u05dc\u05d9\u05dd \u05d0\u05d5\u05ea\u05dd \u05d0\u05d7\u05d3 \u05d0\u05d7\u05d3 \u05db\u05d3\u05d9 \u05dc\u05de\u05e0\u05d5\u05e2 \u05e2\u05d9\u05d5\u05d5\u05ea. \u05d6\u05d5 \u05e2\u05d1\u05d5\u05d3\u05ea \u05d9\u05d3\u05d9\u05d9\u05dd."], [163.6, "\u05d0\u05d6\u05d5\u05e8\u05d9\u05dd \u05e9\u05e6\u05e8\u05d9\u05db\u05d9\u05dd \u05dc\u05d4\u05d9\u05e9\u05d0\u05e8 \u05e8\u05db\u05d9\u05dd \u05de\u05db\u05e1\u05d9\u05dd \u05d1\u05e6\u05d9\u05e4\u05d5\u05d9 \u05e0\u05d7\u05d5\u05e9\u05ea \u05d0\u05d5 \u05d1\u05de\u05e9\u05d7\u05d4, \u05d5\u05de\u05e1\u05d9\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05db\u05d9\u05e1\u05d5\u05d9 \u05d0\u05d7\u05e8 \u05db\u05da."], [170.7, "\u05d7\u05dc\u05e7 \u05e9\u05d4\u05ea\u05e2\u05d5\u05d5\u05ea \u05e6\u05e8\u05d9\u05da \u05d2\u05dd \u05d9\u05d9\u05e9\u05d5\u05e8, \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d4\u05e8\u05e4\u05d9\u05d4 \u05e0\u05d5\u05e1\u05e4\u05ea \u05d0\u05d7\u05e8\u05d9 \u05d4\u05d9\u05d9\u05e9\u05d5\u05e8."], [176.3, "\u05d5\u05d0\u05d7\u05e8\u05d9 \u05d4\u05d4\u05e7\u05e9\u05d9\u05d4, \u05db\u05dc \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d0\u05d9\u05d8\u05d9 \u05d5\u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8: \u05d4\u05e9\u05d7\u05d6\u05d4 \u05d1\u05de\u05e7\u05d5\u05dd \u05db\u05e8\u05e1\u05d5\u05dd, \u05d5\u05d4\u05db\u05dc\u05d9\u05dd \u05e0\u05e9\u05d7\u05e7\u05d9\u05dd \u05de\u05d4\u05e8."], [185.4, "\u05d2\u05dd \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05d4\u05ea\u05d9\u05e2\u05d5\u05d3 \u05d4\u05dd \u05d7\u05dc\u05e7 \u05de\u05d4\u05de\u05d7\u05d9\u05e8: \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea, \u05d3\u05d2\u05d9\u05de\u05d5\u05ea \u05e2\u05d3, \u05de\u05d8\u05dc\u05d5\u05d2\u05e8\u05e4\u05d9\u05d4 \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea."], [193.1, "\u05e1\u05e4\u05e7 \u05e9\u05e2\u05d5\u05d1\u05d3 \u05dc\u05e4\u05d9 AMS 2750 \u05d5\u05de\u05d7\u05d6\u05d9\u05e7 \u05d4\u05e1\u05de\u05db\u05ea Nadcap \u05de\u05e9\u05dc\u05dd \u05e2\u05dc \u05db\u05d9\u05d5\u05dc\u05d9\u05dd, \u05e1\u05e7\u05e8\u05d9\u05dd \u05d5\u05d1\u05d9\u05e7\u05d5\u05e8\u05d5\u05ea, \u05d5\u05d6\u05d4 \u05e0\u05db\u05e0\u05e1 \u05dc\u05de\u05d7\u05d9\u05e8."], [202.7, "\u05dc\u05db\u05df \u05dc\u05d0 \u05db\u05d3\u05d0\u05d9 \u05dc\u05d3\u05e8\u05d5\u05e9 \u05ea\u05e2\u05d5\u05d3\u05d4 3.2 \u05d5\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d4\u05d5\u05e8\u05e1\u05d5\u05ea \u05e2\u05dc \u05d7\u05dc\u05e7 \u05e9\u05dc\u05d0 \u05e6\u05e8\u05d9\u05da \u05d0\u05d5\u05ea\u05df."], [209.2, "\u05d0\u05d1\u05dc \u05db\u05e9\u05d4\u05d7\u05dc\u05e7 \u05e7\u05e8\u05d9\u05d8\u05d9, \u05d0\u05dc\u05d4 \u05d1\u05d3\u05d9\u05d5\u05e7 \u05d4\u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05e9\u05d0\u05e1\u05d5\u05e8 \u05dc\u05d7\u05e1\u05d5\u05da \u05d1\u05d4\u05df."], [214.5, "\u05d4\u05d3\u05e8\u05da \u05d4\u05d6\u05d5\u05dc\u05d4 \u05d1\u05d9\u05d5\u05ea\u05e8 \u05dc\u05d7\u05e1\u05d5\u05da \u05d4\u05d9\u05d0 \u05d1\u05e9\u05dc\u05d1 \u05d4\u05ea\u05db\u05e0\u05d5\u05df."], [218.1, "\u05d0\u05dd \u05e6\u05e8\u05d9\u05da \u05e7\u05e9\u05d9\u05d5\u05ea \u05d1\u05d9\u05e0\u05d5\u05e0\u05d9\u05ea, \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05dc\u05e7\u05e0\u05d5\u05ea \u05e4\u05dc\u05d3\u05d4 \u05de\u05d5\u05e7\u05e9\u05d9\u05ea \u05de\u05e8\u05d0\u05e9, \u05db\u05de\u05d5 4140 \u05d1\u05e2\u05e8\u05da 28 \u05e2\u05d3 32 HRC, \u05d5\u05dc\u05d5\u05d5\u05ea\u05e8 \u05e2\u05dc \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd \u05d1\u05db\u05dc\u05dc."], [230.7, "\u05d0\u05dd \u05e8\u05e7 \u05de\u05e9\u05d8\u05d7 \u05d0\u05d7\u05d3 \u05e6\u05e8\u05d9\u05da \u05dc\u05d4\u05d9\u05d5\u05ea \u05e7\u05e9\u05d4, \u05d4\u05e7\u05e9\u05d9\u05d4 \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05e9\u05dc \u05d4\u05d0\u05d6\u05d5\u05e8 \u05d4\u05d6\u05d4 \u05d6\u05d5\u05dc\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4 \u05e9\u05dc \u05db\u05dc \u05d4\u05d7\u05dc\u05e7."], [239.0, "\u05e4\u05dc\u05d3\u05d4 \u05e2\u05dd \u05db\u05d5\u05e9\u05e8 \u05d4\u05e7\u05e9\u05d9\u05d4 \u05de\u05ea\u05d0\u05d9\u05dd \u05de\u05d0\u05e4\u05e9\u05e8\u05ea \u05db\u05d9\u05d1\u05d5\u05d9 \u05d1\u05e9\u05de\u05df \u05d0\u05d5 \u05d1\u05d2\u05d6 \u05d1\u05de\u05e7\u05d5\u05dd \u05d1\u05de\u05d9\u05dd, \u05e2\u05dd \u05e4\u05d7\u05d5\u05ea \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e4\u05d7\u05d5\u05ea \u05e4\u05e1\u05d9\u05dc\u05d5\u05ea."], [247.2, "\u05e7\u05d5\u05d1\u05e2\u05d9\u05dd \u05e1\u05d1\u05d5\u05dc\u05ea \u05e7\u05e9\u05d9\u05d5\u05ea \u05e8\u05d7\u05d1\u05d4 \u05db\u05db\u05dc \u05d4\u05d0\u05e4\u05e9\u05e8, \u05d5\u05e2\u05d5\u05de\u05e7 \u05e9\u05db\u05d1\u05d4 \u05e8\u05e7 \u05db\u05de\u05d4 \u05e9\u05d4\u05ea\u05e4\u05e7\u05d5\u05d3 \u05d3\u05d5\u05e8\u05e9. \u05db\u05dc \u05e2\u05e9\u05d9\u05e8\u05d9\u05ea \u05de\u05d9\u05dc\u05d9\u05de\u05d8\u05e8 \u05e9\u05dc \u05e2\u05d5\u05de\u05e7 \u05e2\u05d5\u05dc\u05d4 \u05d6\u05de\u05df \u05ea\u05e0\u05d5\u05e8."], [257.2, "\u05d5\u05d1\u05d5\u05d7\u05e8\u05d9\u05dd \u05ea\u05d4\u05dc\u05d9\u05da \u05e9\u05d4\u05e1\u05e4\u05e7\u05d9\u05dd \u05d4\u05de\u05e7\u05d5\u05de\u05d9\u05d9\u05dd \u05de\u05db\u05d9\u05e8\u05d9\u05dd \u05d4\u05d9\u05d8\u05d1. \u05ea\u05d4\u05dc\u05d9\u05da \u05e0\u05d3\u05d9\u05e8 \u05d9\u05e7\u05e8 \u05d9\u05d5\u05ea\u05e8, \u05d5\u05d2\u05dd \u05e7\u05e9\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05dc\u05de\u05e6\u05d5\u05d0 \u05dc\u05d5 \u05e1\u05e4\u05e7."], [265.6, "\u05d5\u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05ea \u05d4\u05d7\u05dc\u05e7 \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd, \u05db\u05de\u05d5 \u05e9\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d1\u05e4\u05e8\u05e7 21: \u05e2\u05d5\u05d1\u05d9 \u05d0\u05d7\u05d9\u05d3, \u05e8\u05d3\u05d9\u05d5\u05e1\u05d9\u05dd, \u05d5\u05ea\u05d5\u05e1\u05e4\u05ea \u05e2\u05d9\u05d1\u05d5\u05d3 \u05d1\u05de\u05e7\u05d5\u05de\u05d5\u05ea \u05d4\u05e0\u05db\u05d5\u05e0\u05d9\u05dd."], [275.6, "\u05d2\u05dd \u05d1\u05e8\u05db\u05e9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05d7\u05e1\u05d5\u05da."], [277.8, "\u05de\u05d0\u05d7\u05d3\u05d9\u05dd \u05d4\u05d6\u05de\u05e0\u05d5\u05ea \u05e7\u05d8\u05e0\u05d5\u05ea \u05dc\u05de\u05e0\u05d4 \u05d0\u05d7\u05ea, \u05db\u05d3\u05d9 \u05dc\u05d0 \u05dc\u05e9\u05dc\u05dd \u05e9\u05d5\u05d1 \u05d5\u05e9\u05d5\u05d1 \u05de\u05d7\u05d9\u05e8 \u05de\u05d9\u05e0\u05d9\u05de\u05d5\u05dd."], [283.0, "\u05de\u05d3\u05d1\u05e8\u05d9\u05dd \u05e2\u05dd \u05d4\u05e1\u05e4\u05e7 \u05dc\u05e4\u05e0\u05d9 \u05e9\u05e1\u05d5\u05d2\u05e8\u05d9\u05dd \u05d0\u05ea \u05d4\u05e9\u05e8\u05d8\u05d5\u05d8. \u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05e9\u05d9\u05e0\u05d5\u05d9 \u05e7\u05d8\u05df \u05de\u05d0\u05e4\u05e9\u05e8 \u05dc\u05d5 \u05dc\u05d4\u05e9\u05ea\u05de\u05e9 \u05d1\u05de\u05d7\u05d6\u05d5\u05e8 \u05e1\u05d8\u05e0\u05d3\u05e8\u05d8\u05d9 \u05e9\u05db\u05d1\u05e8 \u05e8\u05e5 \u05d0\u05e6\u05dc\u05d5."], [291.4, "\u05de\u05e9\u05d5\u05d5\u05d9\u05dd \u05d4\u05e6\u05e2\u05d5\u05ea \u05de\u05d7\u05d9\u05e8 \u05e2\u05dc \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e1\u05d9\u05e1: \u05d0\u05d5\u05ea\u05d5 \u05de\u05e4\u05e8\u05d8, \u05d0\u05d5\u05ea\u05df \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d0\u05d5\u05ea\u05df \u05ea\u05e2\u05d5\u05d3\u05d5\u05ea, \u05d5\u05d0\u05d5\u05ea\u05d5 \u05d6\u05de\u05df \u05d0\u05e1\u05e4\u05e7\u05d4."], [299.0, "\u05d5\u05de\u05d1\u05e7\u05e9\u05d9\u05dd \u05d4\u05e6\u05e2\u05d4 \u05e9\u05db\u05d5\u05dc\u05dc\u05ea \u05d4\u05db\u05d5\u05dc: \u05e0\u05d9\u05e7\u05d5\u05d9, \u05d9\u05d9\u05e9\u05d5\u05e8, \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea \u05d5\u05ea\u05e2\u05d5\u05d3\u05d5\u05ea, \u05db\u05d3\u05d9 \u05e9\u05dc\u05d0 \u05d9\u05d5\u05e4\u05d9\u05e2\u05d5 \u05ea\u05d5\u05e1\u05e4\u05d5\u05ea \u05d1\u05d7\u05e9\u05d1\u05d5\u05e0\u05d9\u05ea."], [307.0, "\u05d5\u05d6\u05d5\u05db\u05e8\u05d9\u05dd \u05d2\u05dd \u05d0\u05ea \u05d4\u05d4\u05d5\u05d1\u05dc\u05d4 \u05d5\u05d0\u05ea \u05d4\u05d6\u05de\u05df: \u05d7\u05dc\u05e7 \u05e9\u05de\u05d7\u05db\u05d4 \u05e9\u05d1\u05d5\u05e2 \u05dc\u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05e2\u05db\u05d1 \u05d0\u05ea \u05db\u05dc \u05d4\u05e4\u05e8\u05d5\u05d9\u05e7\u05d8."], [314.7, "\u05d5\u05de\u05d4 \u05d9\u05e7\u05e8 \u05d1\u05d0\u05de\u05ea? \u05e4\u05e1\u05d9\u05dc\u05d4 \u05d1\u05e1\u05d5\u05e3 \u05d4\u05ea\u05d4\u05dc\u05d9\u05da."], [318.3, "\u05db\u05e9\u05d7\u05dc\u05e7 \u05e0\u05e4\u05e1\u05dc \u05d0\u05d7\u05e8\u05d9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05d4\u05d7\u05d5\u05dd, \u05db\u05d1\u05e8 \u05e9\u05d9\u05dc\u05de\u05e0\u05d5 \u05e2\u05dc \u05d4\u05d7\u05d5\u05de\u05e8, \u05e2\u05dc \u05d4\u05e2\u05d9\u05d1\u05d5\u05d3 \u05d5\u05e2\u05dc \u05d4\u05d8\u05d9\u05e4\u05d5\u05dc. \u05d5\u05dc\u05e4\u05e2\u05de\u05d9\u05dd \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05ea\u05e7\u05df."], [326.8, "\u05d5\u05d7\u05dc\u05e7 \u05e9\u05e0\u05db\u05e9\u05dc \u05d0\u05e6\u05dc \u05d4\u05dc\u05e7\u05d5\u05d7, \u05d1\u05d2\u05dc\u05dc \u05e9\u05db\u05d1\u05d4 \u05e8\u05d3\u05d5\u05d3\u05d4 \u05d0\u05d5 \u05e1\u05d3\u05e7, \u05e2\u05d5\u05dc\u05d4 \u05d4\u05e8\u05d1\u05d4 \u05d9\u05d5\u05ea\u05e8 \u05de\u05db\u05dc \u05d1\u05d3\u05d9\u05e7\u05d4 \u05e9\u05d7\u05e1\u05db\u05e0\u05d5."], [334.3, "\u05d5\u05d2\u05dd \u05d4\u05d6\u05de\u05df \u05e2\u05d5\u05dc\u05d4 \u05db\u05e1\u05e3: \u05d7\u05dc\u05e7 \u05e9\u05e0\u05e4\u05e1\u05dc \u05e2\u05d5\u05d1\u05e8 \u05e9\u05d5\u05d1 \u05d0\u05ea \u05db\u05dc \u05d4\u05e9\u05e8\u05e9\u05e8\u05ea, \u05d5\u05d4\u05e4\u05e8\u05d5\u05d9\u05e7\u05d8 \u05de\u05d7\u05db\u05d4."], [341.4, "\u05d5\u05e2\u05db\u05e9\u05d9\u05d5, \u05d1\u05d5\u05d0\u05d5 \u05e0\u05e2\u05d1\u05d5\u05e8 \u05e2\u05dc \u05db\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1."], [344.4, "\u05d4\u05ea\u05d7\u05dc\u05e0\u05d5 \u05d1\u05d1\u05e1\u05d9\u05e1: \u05de\u05d1\u05e0\u05d4 \u05d4\u05d1\u05e8\u05d6\u05dc, \u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05ea \u05d1\u05e8\u05d6\u05dc \u05e4\u05d7\u05de\u05df, \u05d5\u05d3\u05d9\u05d0\u05d2\u05e8\u05de\u05d5\u05ea \u05d4\u05d6\u05de\u05df \u05d5\u05d4\u05e7\u05d9\u05e8\u05d5\u05e8 \u05e9\u05de\u05e1\u05d1\u05d9\u05e8\u05d5\u05ea \u05de\u05ea\u05d9 \u05e0\u05d5\u05e6\u05e8 \u05de\u05e8\u05d8\u05e0\u05d6\u05d9\u05d8."], [353.5, "\u05e8\u05d0\u05d9\u05e0\u05d5 \u05d0\u05d9\u05da \u05de\u05e8\u05db\u05db\u05d9\u05dd, \u05de\u05e0\u05e8\u05de\u05dc\u05d9\u05dd \u05d5\u05de\u05e9\u05d7\u05e8\u05e8\u05d9\u05dd \u05de\u05d0\u05de\u05e6\u05d9\u05dd, \u05d5\u05d0\u05d9\u05da \u05de\u05e7\u05e9\u05d9\u05dd: \u05d7\u05d9\u05de\u05d5\u05dd \u05dc\u05d0\u05d5\u05e1\u05d8\u05e0\u05d9\u05d8, \u05db\u05d9\u05d1\u05d5\u05d9, \u05d5\u05d4\u05e8\u05e4\u05d9\u05d4."], [362.8, "\u05dc\u05de\u05d3\u05e0\u05d5 \u05dc\u05d4\u05e7\u05e9\u05d5\u05ea \u05e8\u05e7 \u05d0\u05ea \u05e4\u05e0\u05d9 \u05d4\u05e9\u05d8\u05d7: \u05d1\u05d0\u05d9\u05e0\u05d3\u05d5\u05e7\u05e6\u05d9\u05d4 \u05d5\u05d1\u05dc\u05d4\u05d1\u05d4, \u05d1\u05e6\u05de\u05e0\u05d8\u05e6\u05d9\u05d4, \u05d1\u05e0\u05d9\u05d8\u05e8\u05d9\u05d3\u05e6\u05d9\u05d4, \u05d1\u05dc\u05d9\u05d9\u05d6\u05e8 \u05d5\u05d1\u05d1\u05d5\u05e8\u05d9\u05d3\u05d9\u05e0\u05d2."], [372.2, "\u05e2\u05d1\u05e8\u05e0\u05d5 \u05e2\u05dc \u05de\u05e9\u05e4\u05d7\u05d5\u05ea \u05d4\u05d7\u05d5\u05de\u05e8\u05d9\u05dd: \u05e4\u05dc\u05d3\u05d5\u05ea \u05db\u05dc\u05d9\u05dd, \u05e4\u05dc\u05d3\u05d5\u05ea \u05d0\u05dc \u05d7\u05dc\u05d3, \u05d0\u05dc\u05d5\u05de\u05d9\u05e0\u05d9\u05d5\u05dd, \u05d8\u05d9\u05d8\u05e0\u05d9\u05d5\u05dd, \u05e0\u05d7\u05d5\u05e9\u05ea \u05d1\u05e8\u05d9\u05dc\u05d9\u05d5\u05dd, \u05e1\u05d2\u05e1\u05d5\u05d2\u05d5\u05ea \u05e2\u05dc \u05d5\u05d1\u05e8\u05d6\u05dc \u05d9\u05e6\u05d5\u05e7."], [382.8, "\u05d5\u05e8\u05d0\u05d9\u05e0\u05d5 \u05e9\u05db\u05dc \u05d7\u05d5\u05de\u05e8 \u05d3\u05d5\u05e8\u05e9 \u05d8\u05d9\u05e4\u05d5\u05dc \u05de\u05e9\u05dc\u05d5, \u05d5\u05e9\u05d0\u05d9\u05df \u05de\u05ea\u05db\u05d5\u05df \u05d0\u05d7\u05d3 \u05e9\u05de\u05ea\u05d0\u05d9\u05dd \u05dc\u05db\u05dc \u05d4\u05de\u05ea\u05db\u05d5\u05ea."], [389.0, "\u05d5\u05d1\u05d7\u05dc\u05e7 \u05d4\u05de\u05e2\u05e9\u05d9 \u05d3\u05d9\u05d1\u05e8\u05e0\u05d5 \u05e2\u05dc \u05ea\u05e0\u05d5\u05e8\u05d9\u05dd \u05d5\u05d0\u05d5\u05d5\u05d9\u05e8\u05d5\u05ea, \u05e2\u05dc \u05e2\u05d9\u05d5\u05d5\u05ea \u05d5\u05e1\u05d3\u05e7\u05d9\u05dd, \u05e2\u05dc \u05d1\u05d3\u05d9\u05e7\u05d5\u05ea, \u05d5\u05e2\u05dc \u05d0\u05d9\u05da \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05ea \u05d4\u05d3\u05e8\u05d9\u05e9\u05d4 \u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."], [397.9, "\u05d4\u05de\u05e1\u05e8 \u05d4\u05de\u05e8\u05db\u05d6\u05d9 \u05e9\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1: \u05d8\u05d9\u05e4\u05d5\u05dc \u05d7\u05d5\u05dd \u05de\u05e9\u05e0\u05d4 \u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05e4\u05e0\u05d9\u05de\u05d9, \u05d5\u05d0\u05ea \u05d4\u05de\u05d1\u05e0\u05d4 \u05d4\u05d6\u05d4 \u05d0\u05d9 \u05d0\u05e4\u05e9\u05e8 \u05dc\u05e8\u05d0\u05d5\u05ea \u05d1\u05e2\u05d9\u05df."], [406.0, "\u05dc\u05db\u05df \u05de\u05ea\u05db\u05e0\u05e0\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05de\u05e8\u05d0\u05e9, \u05db\u05d5\u05ea\u05d1\u05d9\u05dd \u05d0\u05d5\u05ea\u05d5 \u05d1\u05e8\u05d5\u05e8, \u05d5\u05d1\u05d5\u05d3\u05e7\u05d9\u05dd \u05e9\u05d4\u05d5\u05d0 \u05d1\u05d0\u05de\u05ea \u05e7\u05e8\u05d4."], [412.1, "\u05ea\u05d5\u05d3\u05d4 \u05e9\u05d4\u05d9\u05d9\u05ea\u05dd \u05d0\u05d9\u05ea\u05e0\u05d5 \u05dc\u05d0\u05d5\u05e8\u05da \u05db\u05dc \u05d4\u05e7\u05d5\u05e8\u05e1. \u05d1\u05d4\u05e6\u05dc\u05d7\u05d4 \u05d1\u05de\u05e4\u05e2\u05dc, \u05d1\u05ea\u05db\u05e0\u05d5\u05df \u05d5\u05d1\u05e9\u05e8\u05d8\u05d5\u05d8."]]};
